INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vitorsilva/saberloop/landing-page-marketing', 'community', 'vitorsilva', 'saberloop', 'vitorsilva/saberloop', 'landing-page-marketing', 0, 0, 59, '2026-03-08T01:57:15.304Z', '2026-03-08T02:01:57.693Z', '97a15d22f3c14015cdcb1a239bdfc99c976c58ea91af90e95f92a95871682b31', '{"id":"vitorsilva/saberloop/landing-page-marketing","name":"landing-page-marketing","description":{"en":"The landing-page-marketing skill automates the workflow for updating Saberloop landing pages, capturing marketing assets, and deploying with standardized processes. It benefits developers and marketers by consolidating screenshot capture, image processing, HTML updates, and deployment.","zh":"landing-page-marketing AI エージェント是一种自动化工作流程的工具，用于更新 Saberloop 登陆页面和捕获营销资产","ja":"landing-page-marketing AI エージェントは、Saberloop ランディングページの更新とマーケティング資産の取得を自動化するツールです","ko":"landing-page-marketing AI 에이전트는 Saberloop 랜딩 페이지를 자동화하고 마케팅 자산을 캡처하는 개발자용 도구입니다","es":"Landing-page-marketing es una habilidad que automatiza el flujo de trabajo para actualizar la página de destino de Saberloop y capturar assets de marketing, utilizando tecnologías como PWA y procesamiento de imágenes","fr":"Landing-page-marketing est une compétence qui automatise le flux de travail pour mettre à jour la page de destination de Saberloop et capturer les ressources de marketing, en utilisant des technologies comme PWA et traitement d''images","de":"Landing-page-marketing ist eine Fähigkeit, die den Workflow zum Aktualisieren der Zielseite von Saberloop und Erfassen von Marketing-Ressourcen automatisiert, unter Verwendung von Technologien wie PWA und Bildverarbeitung","pt":"A ferramenta de landing page marketing automática consolida captura de screenshots, processamento de imagens, atualizações de HTML e deploy em um processo padrão","ru":"Инструмент автоматического маркетинга landing page консолидирует захват скриншотов, обработку изображений, обновления HTML и развертывание в стандартизированный процесс","ar":"أداة التسويق التلقيمي لصفحة الهبوط تدمج التقاط لقطات الشاشة ومعالجة الصور وتحديثات HTML والنشر في عملية معيارية"},"seo":{"title":{"en":"Landing-Page-Marketing: Automated Workflow Setup Guide | ...","zh":"landing-page-marketing_SETUP GUIDE - AIエージェント","ja":"landing-page-marketing ベストプラクティス - AIエージェント","ko":"landing-page-marketing 설정 가이드 - AI 에이전트","es":"Guía de configuración de landing-page-marketing con AI","fr":"Guide de mise en place de landing-page-marketing avec IA","de":"Einrichtungsleitfaden für landing-page-marketing mit KI","pt":"Guia de Configuração de Landing Page Marketing com Ferram...","ru":"Настройка маркетинга landing page с помощью ИИ Агентов","ar":"دليل إعداد صفحة الهبوط التسويقية باستخدام أدوات الذكاء ال..."},"description":{"en":"Discover how to streamline landing page updates with AI-powered automation. Learn to capture marketing assets and deploy with ease. Get started now!","zh":"利用 landing-page-marketing AI エージェント自动化工作流程，更新 Saberloop 登陆页面和捕获营销资产","ja":"landing-page-marketing AI エージェントを使用して Saberloop ランディングページを更新し、マーケティング資産を取得する","ko":"landing-page-marketing AI 에이전트를 사용하여 Saberloop 랜딩 페이지를 자동화하고 마케팅 자산을 캡처하는 방법","es":"Automatice su workflow de marketing con landing-page-marketing, una herramienta de IA para actualizar páginas de destino y capturar assets de marketing","fr":"Automatisez votre flux de travail de marketing avec landing-page-marketing, un outil IA pour mettre à jour les pages de destination et capturer les ressource...","de":"Automatisieren Sie Ihren Marketing-Workflow mit landing-page-marketing, einem KI-Tool zum Aktualisieren von Zielseiten und Erfassen von Marketing-Ressourcen","pt":"Aprenda a automatizar o fluxo de trabalho de marketing de landing page com nossa ferramenta de IA, incluindo captura de screenshots e atualizações de HTML","ru":"Автоматизируйте рабочий процесс маркетинга landing page с помощью нашей ИИ-функции, включая захват скриншотов и обновления HTML","ar":"تعلم كيفية تلقيم تدفق العمل للتسويق لصفحة الهبوط باستخدام أداة الذكاء الاصطناعي لدينا، بما في ذلك التقاط لقطات الشاشة وتحديثات HTML"},"definition":{"en":"Landing-page-marketing is a skill that automates the complete workflow for updating landing pages, capturing marketing assets, and deploying with standardized processes, utilizing technologies like HTML and PWA.","zh":"landing-page-marketing 是一种利用 AI エージェント自动化工作流程的技术，用于更新登陆页面和捕获营销资产","ja":"landing-page-marketing は、AI エージェントを使用してランディングページを更新し、マーケティング資産を取得する技術です","ko":"landing-page-marketing 은 AI 에이전트를 사용하여 랜딩 페이지를 자동화하고 마케팅 자산을 캡처하는 기술입니다","es":"Landing-page-marketing es una herramienta de IA que automatiza la actualización de páginas de destino y la captura de assets de marketing","fr":"Landing-page-marketing est un outil IA qui automatise la mise à jour des pages de destination et la capture des ressources de marketing","de":"Landing-page-marketing ist ein KI-Tool, das die Aktualisierung von Zielseiten und das Erfassen von Marketing-Ressourcen automatisiert","pt":"O que é landing page marketing? É um processo automatizado que atualiza a página de destino e captura ativos de marketing","ru":"Что такое маркетинг landing page? Это автоматизированный процесс, который обновляет целевую страницу и захватывает маркетинговые активы","ar":"ما هو تسويق صفحة الهبوط؟ إنه عملية تلقيمية تحديث صفحة الوجهة والتقاط الأصول التسويقية"},"features":{"en":["Consolidates screenshot capture, image processing, HTML updates, and deployment into a standardized process","Utilizes PWA (Progressive Web App) with offline support for seamless user experience","Updates index.html and app/ endpoints for Saberloop landing page","Supports staging environment with app-staging/ endpoint","Automates workflow using AI-powered automation"],"zh":["自动化 Saberloop 登陆页面更新","捕获营销资产","支持 PWA 和离线模式","HTML 更新和部署","截图捕获和图像处理"],"ja":["Saberloop ランディングページの自動更新","マーケティング資産の取得","PWA とオフラインモードのサポート","HTML 更新とデプロイ","スクリーンショットの取得と画像処理"],"ko":["Saberloop 랜딩 페이지 자동화","마케팅 자산 캡처","PWA 및 오프라인 모드 지원","HTML 업데이트 및 배포","스크린샷 캡처 및 이미지 처리"],"es":["Automatización del flujo de trabajo de marketing","Actualización de la página de destino de Saberloop","Captura de assets de marketing","Utilización de tecnologías PWA y procesamiento de imágenes","Despliegue de aplicaciones web progresivas (PWA)","Soporte offline para aplicaciones web"],"fr":["Automatisation du flux de travail de marketing","Mise à jour de la page de destination de Saberloop","Capture des ressources de marketing","Utilisation de technologies PWA et traitement d''images","Déploiement d''applications web progresives (PWA)","Prise en charge hors ligne pour les applications web"],"de":["Automatisierung des Marketing-Workflows","Aktualisierung der Zielseite von Saberloop","Erfassung von Marketing-Ressourcen","Verwendung von Technologien PWA und Bildverarbeitung","Bereitstellung von progressiven Webanwendungen (PWA)","Unterstützung von Offline-Modus für Webanwendungen"],"pt":["Consolidação de captura de screenshots e processamento de imagens","Atualizações de HTML e deploy automatizados","Suporte a PWA com funcionalidade offline","Arquitetura de landing page personalizada","Integração com aplicativos de IA para geração de perguntas"],"ru":["Консолидация захвата скриншотов и обработки изображений","Автоматические обновления HTML и развертывание","Поддержка PWA с функциональностью offline","Пользовательская архитектура landing page","Интеграция с ИИ-приложениями для генерации вопросов"],"ar":["دمج التقاط لقطات الشاشة ومعالجة الصور","تحديثات HTML وتوزيع تلقيمي","دعم PWA بالوظائف بدون اتصال","هيكل صفحة الهبوط المخصص","التكامل مع تطبيقات الذكاء الاصطناعي لتوليد الأسئلة"]},"keywords":{"en":["how to use landing-page-marketing","what is landing-page-marketing","landing-page-marketing alternative","landing-page-marketing vs manual updates","landing-page-marketing install","landing-page-marketing setup guide","automated landing page updates","PWA landing page marketing","AI-powered marketing automation"],"zh":["landing-page-marketing","AI エージェント","Saberloop","PWA","HTML 更新","截图捕获","图像处理","自动化工作流程"],"ja":["landing-page-marketing","AI エージェント","Saberloop","PWA","HTML 更新","スクリーンショットの取得","画像処理","自動化ワークフロー"],"ko":["landing-page-marketing","AI 에이전트","Saberloop","PWA","HTML 업데이트","스크린샷 캡처","이미지 처리","자동화 워크플로"],"es":["landing-page-marketing","herramientas de IA para marketing","automatización de marketing","páginas de destino","assets de marketing","PWA","procesamiento de imágenes","despliegue de aplicaciones web"],"fr":["landing-page-marketing","outils IA pour le marketing","automatisation du marketing","pages de destination","ressources de marketing","PWA","traitement d''images","déploiement d''applications web"],"de":["landing-page-marketing","KI-Tools für Marketing","Automatisierung von Marketing","Zielseiten","Marketing-Ressourcen","PWA","Bildverarbeitung","Bereitstellung von Webanwendungen"],"pt":["landing page marketing","ferramentas de IA para marketing","automatização de marketing","captura de screenshots","processamento de imagens","PWA com suporte offline","desenvolvimento de landing page"],"ru":["маркетинг landing page","ИИ инструменты для маркетинга","автоматизация маркетинга","захват скриншотов","обработка изображений","PWA с поддержкой offline","разработка landing page"],"ar":["تسويق صفحة الهبوط","أدوات الذكاء الاصطناعي للتسويق","تلقيم التسويق","التقاط لقطات الشاشة","معالجة الصور","PWA بدعم بدون اتصال","تنمية صفحة الهبوط"]}},"owner":"vitorsilva","repo":"saberloop","repoPath":"vitorsilva/saberloop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.304Z","topics":[],"category":"community","skillMd":{"name":"landing-page-marketing","description":"Automate landing page updates and marketing asset capture following established patterns","version":"1.0.0","bodyPreview":"# Landing Page Marketing Skill\n\n## Overview\n\nThis skill automates the complete workflow for updating the Saberloop landing page and capturing marketing assets. It consolidates screenshot capture, image processing, HTML updates, and deployment into a standardized process.\n\n## Landing Page Architecture\n\n```\nsaberloop.com/\n├── index.html          # Landing page (from ./landing/)\n├── app/                # PWA application\n├── app-staging/        # Staging PWA\n└── [other endpoints]\n\n./landing/\n├── ind","body":"# Landing Page Marketing Skill\n\n## Overview\n\nThis skill automates the complete workflow for updating the Saberloop landing page and capturing marketing assets. It consolidates screenshot capture, image processing, HTML updates, and deployment into a standardized process.\n\n## Landing Page Architecture\n\n```\nsaberloop.com/\n├── index.html          # Landing page (from ./landing/)\n├── app/                # PWA application\n├── app-staging/        # Staging PWA\n└── [other endpoints]\n\n./landing/\n├── index.html          # Main landing page HTML\n├── images/             # Landing page images (304x584 for mobile screenshots)\n│   ├── demo.webm\n│   ├── landing-*.png\n│   └── party-demo.webm\n└── [deployed to root]\n```\n\n## When to Use This Skill\n\nUse this skill when ANY of these are true:\n- [ ] Adding a new feature to showcase on landing page\n- [ ] Updating marketing copy or CTAs\n- [ ] Capturing new app screenshots\n- [ ] Creating demo videos\n- [ ] Refreshing existing screenshots after UI changes\n- [ ] Deploying landing page updates\n\n## Landing Page Sections\n\n| Section | Location (lines) | Purpose |\n|---------|------------------|---------|\n| Hero | ~668-694 | Main headline, video demo, primary CTAs |\n| Features | ~697-733 | Feature cards grid (6-7 cards) |\n| Party Mode | ~736-759 | Dedicated party mode section |\n| How It Works | ~762-788 | 4-step process explanation |\n| Screenshots | ~791-803 | App screenshot gallery |\n| Share Section | ~806-819 | Social sharing preview |\n| CTA | ~822-848 | Final call-to-action columns |\n| Footer | ~851-862 | Links and copyright |\n\n## Complete Workflow\n\n### Phase 1: Screenshot Capture\n\n#### Step 1.1: Create Capture Script\n\n**File:** `tests/e2e/capture-[feature]-screenshots.spec.js`\n\n```javascript\nimport { test, expect } from ''@playwright/test'';\nimport { setupAuthenticatedState, clearSessions } from ''./helpers.js'';\n\nconst MOBILE_VIEWPORT = { width: 375, height: 667 };\nconst SCREENSHOT_DIR = ''landing/images'';\n\ntest.use({ viewport: MOBILE_VIEWPORT });\n\ntest.describe(''Capture [Feature] Screenshots'', () => {\n\n  test(''[Feature] screenshot'', async ({ page }) => {\n    // Setup authenticated state if needed\n    await setupAuthenticatedState(page);\n    await clearSessions(page);\n    await page.reload();\n    await page.waitForSelector(''[data-testid=\"welcome-heading\"]'', { timeout: 10000 });\n\n    // Navigate to the screen to capture\n    await page.goto(''/#/[route]'');\n    await page.waitForTimeout(500);\n\n    // Setup the UI state (scroll, open modals, etc.)\n    // ...\n\n    // Capture screenshot\n    await page.screenshot({\n      path: `${SCREENSHOT_DIR}/landing-[feature-name].png`,\n      fullPage: false\n    });\n\n    console.log(''✓ Captured: [Feature] screenshot'');\n  });\n\n});\n```\n\n#### Step 1.2: Run Capture Script\n\n```bash\n# Run with visible browser\nnpx playwright test tests/e2e/capture-[feature]-screenshots.spec.js --headed\n\n# Or run all capture scripts\nnpm run test:e2e:capture\n```\n\n#### Step 1.3: Process Images\n\n```bash\n# Resize to landing page dimensions (304x584)\n# Option 1: Using Sharp CLI\nnpx sharp-cli landing/images/landing-[feature].png -o landing/images/landing-[feature].png resize 304 584\n\n# Option 2: Using ImageMagick\nconvert landing/images/landing-[feature].png -resize 304x584 landing/images/landing-[feature].png\n\n# Verify file size (should be <50KB for fast loading)\nls -la landing/images/landing-[feature].png\n```\n\n### Phase 2: HTML Updates\n\n#### Step 2.1: Add Feature Card\n\n**Location:** Features grid in `landing/index.html` (~line 700)\n\n```html\n<!-- Add after existing feature cards -->\n<div class=\"feature-card\">\n    <div class=\"feature-icon\">[EMOJI]</div>\n    <h3>[Feature Name]</h3>\n    <p>[Short description - 1-2 sentences]</p>\n</div>\n```\n\n**Available emojis for consistency:**\n- 🧠 AI/Learning\n- 🌍 Languages/Global\n- 🎓 Education/Levels\n- 📱 Mobile/Offline\n- 🔒 Privacy/Security\n- 🎉 Social/Party\n- 🤖 AI Models/Tech\n- ⚡ Performance\n- 💰 Pricing/Value\n\n#### Step 2.2: Update CTA Section\n\n**Location:** CTA columns in `landing/index.html` (~line 822)\n\n```html\n<div class=\"cta-column\">\n    <h3>[Column Title]</h3>\n    <ul>\n        <li>[Benefit 1]</li>\n        <li>[Benefit 2]</li>\n        <li>[Benefit 3]</li>\n        <li>[Benefit 4]</li>\n    </ul>\n    <a href=\"[URL]\" class=\"btn btn-secondary\" data-track=\"[tracking_id]\">[Button Text]</a>\n</div>\n```\n\n#### Step 2.3: Add Screenshot to Gallery\n\n**Location:** Screenshots grid in `landing/index.html` (~line 794)\n\n```html\n<img src=\"images/landing-[feature].png\"\n     alt=\"[Descriptive alt text]\"\n     width=\"304\" height=\"584\"\n     loading=\"lazy\">\n```\n\n#### Step 2.4: Update Structured Data\n\n**Location:** JSON-LD in `<head>` (~line 52)\n\n```json\n{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"SoftwareApplication\",\n    \"name\": \"Saberloop\",\n    \"description\": \"[Updated description including new feature]\",\n    \"featureList\": [\n        \"AI-powered quiz generation\",\n        \"[New feature description]\",\n        \"Multi-language support\",\n        \"Offline mode\",\n        \"Party Mode multiplayer\"\n    ]\n}\n```\n\n### Phase 3: Testing\n\n#### Step 3.1: Local Preview\n\n```bash\n# Serve landing page locally\nnpx serve landing -p 8080\n\n# Or use Python\ncd landing && python -m http.server 8080\n```\n\n#### Step 3.2: Responsive Testing\n\nTest at these breakpoints:\n- Mobile: 375px (primary)\n- Tablet: 768px\n- Desktop: 1200px+\n\n```bash\n# Use Playwright for responsive screenshots\nnpx playwright test tests/e2e/capture-landing-responsive.spec.js\n```\n\n### Phase 4: Deployment\n\n#### Step 4.1: Deploy to Staging\n\n```bash\n# Build and deploy to staging first\nnpm run deploy:landing -- --staging\n\n# Staging URL: https://saberloop.com/staging/ (if configured)\n# Or test via: https://saberloop.com/app-staging/\n```\n\n#### Step 4.2: Verify Staging\n\nChecklist:\n- [ ] All images load correctly\n- [ ] Feature cards display properly\n- [ ] CTA buttons work\n- [ ] Mobile layout is correct\n- [ ] No console errors\n- [ ] Tracking events fire (check GA)\n\n#### Step 4.3: Deploy to Production\n\n```bash\n# Deploy landing page to production\nnpm run deploy:landing\n\n# Production URL: https://saberloop.com/\n```\n\n#### Step 4.4: Post-Deploy Verification\n\n```bash\n# Clear CDN cache if needed (depends on hosting)\n# Verify in incognito/private browsing\n# Test on actual mobile device\n```\n\n## Templates\n\n### Feature Card Template\n\n```html\n<div class=\"feature-card\">\n    <div class=\"feature-icon\">🤖</div>\n    <h3>Feature Name</h3>\n    <p>Brief description of the feature benefit to users. Keep it to 1-2 sentences.</p>\n</div>\n```\n\n### Hero Button Template\n\n```html\n<a href=\"/app/\" class=\"btn btn-primary\" data-track=\"[tracking_id]\">\n    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\">\n        <!-- SVG path here -->\n    </svg>\n    Button Text\n</a>\n```\n\n### Screenshot Capture Script Template\n\n```javascript\nimport { test, expect } from ''@playwright/test'';\nimport { setupAuthenticatedState, clearSessions } from ''./helpers.js'';\n\nconst MOBILE_VIEWPORT = { width: 375, height: 667 };\nconst SCREENSHOT_DIR = ''landing/images'';\n\ntest.use({ viewport: MOBILE_VIEWPORT });\n\ntest.describe(''Capture Screenshots for Landing Page'', () => {\n\n  test.beforeEach(async ({ page }) => {\n    await setupAuthenticatedState(page);\n    await clearSessions(page);\n    await page.reload();\n    await page.waitForSelector(''[data-testid=\"welcome-heading\"]'', { timeout: 10000 });\n  });\n\n  test(''Screenshot 1: [Description]'', async ({ page }) => {\n    await page.goto(''/#/[route]'');\n    await page.waitForTimeout(500);\n\n    // Setup UI state...\n\n    await page.screenshot({\n      path: `${SCREENSHOT_DIR}/landing-[name].png`,\n      fullPage: false\n    });\n    console.log(''✓ Captured: [Description]'');\n  });\n\n});\n```\n\n## CSS Reference\n\n### Feature Card Styles\n\n```css\n.feature-card {\n    background: var(--background-light);  /* #252542 */\n    padding: 32px;\n    border-radius: 20px;\n    text-align: center;\n}\n\n.feature-icon {\n    font-size: 3rem;\n    margin-bottom: 16px;\n}\n\n.feature-card h3 {\n    font-size: 1.25rem;\n    margin-bottom: 12px;\n}\n\n.feature-card p {\n    color: var(--text-muted);  /* #a0a0b0 */\n    font-size: 0.95rem;\n}\n```\n\n### Button Styles\n\n```css\n.btn {\n    padding: 16px 32px;\n    border-radius: 50px;\n    font-weight: 600;\n    font-size: 1rem;\n    text-decoration: none;\n}\n\n.btn-primary {\n    background: var(--primary);  /* #FF6B35 */\n    color: white;\n}\n\n.btn-secondary {\n    background: var(--background-light);\n    color: var(--text);\n    border: 2px solid var(--background-light);\n}\n```\n\n### Color Variables\n\n```css\n:root {\n    --primary: #FF6B35;\n    --primary-dark: #e55a2b;\n    --background: #1a1a2e;\n    --background-light: #252542;\n    --text: #ffffff;\n    --text-muted: #a0a0b0;\n}\n```\n\n## Tracking Events\n\nAll clickable elements should have `data-track` attribute:\n\n```html\n<a href=\"/app/\" data-track=\"web_app_hero\">Try in Browser</a>\n```\n\nEvents are automatically tracked via the script at the bottom of the landing page:\n\n```javascript\ndocument.addEventListener(''click'', function(e) {\n    const trackable = e.target.closest(''[data-track]'');\n    if (trackable && typeof gtag === ''function'') {\n        gtag(''event'', trackable.dataset.track, {\n            ''event_category'': ''engagement'',\n            ''event_label'': trackable.dataset.track\n        });\n    }\n});\n```\n\n## Image Specifications\n\n| Type | Dimensions | Format | Max Size | Location |\n|------|------------|--------|----------|----------|\n| App Screenshot | 304x584 | PNG | 50KB | `landing/images/` |\n| Demo Video | 375x667 | WebM | 500KB | `landing/images/` |\n| Hero Video | 300x600 | WebM | 500KB | `landing/images/` |\n\n## Deployment Commands\n\n```bash\n# Landing page only\nnpm run deploy:landing\n\n# With staging flag (if configured)\nnpm run deploy:landing -- --staging\n\n# Full app + landing\nnpm run deploy && npm run deploy:landing\n```\n\n## Troubleshooting\n\n### Images Not Loading\n1. Check file path is correct (relative to landing/index.html)\n2. Verify file was uploaded (FTP deployment)\n3. Clear browser cache\n4. Check file permissions on server\n\n### Layout Issues\n1. Test at all breakpoints (375, 768, 1200)\n2. Check CSS grid/flexbox rules\n3. Verify image dimensions match expected\n4. Check for overflow issues\n\n### Tracking Not Working\n1. Verify `data-track` attribute exists\n2. Check GA is loaded (no ad blockers)\n3. Verify gtag function is available\n4. Check browser console for errors\n\n## Integration with Other Skills\n\nThis skill integrates with:\n- **testing-suite-management** - For E2E capture scripts\n- **cicd-pipeline-management** - For deployment workflows\n- **documentation-generation** - For marketing docs\n\n## References\n\n### Developer Guides\n- [E2E Testing Guide](../../../docs/developer-guide/E2E_TESTING.md)\n- [Deployment Guide](../../../docs/architecture/DEPLOYMENT.md)\n- [Staging Deployment](../../../docs/developer-guide/STAGING_DEPLOYMENT.md)\n\n### Existing Capture Scripts\n- `tests/e2e/capture-landing-assets.spec.js`\n- `tests/e2e/capture-playstore-screenshots.spec.js`\n- `tests/e2e/capture-party-demo.spec.js`\n\n### Previous Landing Updates\n- [Epic 6: Party Mode Update](../../../docs/learning/epic06_sharing/LANDING_PAGE_PARTY_UPDATE.md)\n- [Epic 11 Phase 6: Multi-Provider](../../../docs/learning/epic11_llm_support/PHASE6_MARKETING_UPDATE.md)\n\n---\n\n**Version:** 1.0.0\n**Last Updated:** 2026-01-23\n**Compatible with:** Saberloop v2.0.0+\n"},"lastSynced":"2026-03-08T02:01:57.693Z","agentAnalysis":{"suitability":{"en":"Perfect for Marketing Agents needing automated landing page updates and HTML deployment capabilities.","zh":"非常适合需要自动更新着陆页和HTML部署能力的营销代理。","ja":"マーケティングエージェントがランディングページの自動更新とHTMLのデプロイ機能を必要とする場合に最適です。","ko":"자동화된 랜딩 페이지 업데이트 및 HTML 배포 기능이 필요한 마케팅 에이전트에게 적합합니다.","es":"Perfecto para agentes de marketing que necesitan actualizaciones de página de aterrizaje automatizadas y capacidades de implementación de HTML.","fr":"Parfait pour les agents marketing ayant besoin de mises à jour de page d''atterrissage automatisées et de capacités de déploiement HTML.","de":"Perfekt für Marketingagenten, die automatisierte Updates für Landingpages und HTML-Bereitstellungsfunktionen benötigen.","pt":"Perfeito para Agentes de Marketing que necessitam de atualizações de página de destino automatizadas e capacidades de implantação de HTML.","ru":"Идеально для Маркетинговых Агентов, которым требуются автоматизированные обновления целевой страницы и возможности развертывания HTML.","ar":"مثالي لوكلاء التسويق الذين يحتاجون إلى تحديثات صفحة الهبوط الآلية وقدرات النشر HTML."},"recommendation":{"en":"Empowers agents to consolidate screenshot capture, image processing, and HTML updates into a standardized process using Saberloop landing pages, streamlining marketing asset deployment via protocols like HTTP and HTML.","zh":"赋予代理人将截图捕获、图像处理和HTML更新整合到使用Saberloop着陆页的标准化过程中，通过HTTP和HTML等协议简化营销资产的部署。","ja":"Saberloopのランディングページを使用して、スクリーンショットのキャプチャ、画像処理、HTMLの更新を標準化されたプロセスに統合し、マーケティング資産のデプロイをHTTPやHTMLなどのプロトコルで簡素化します。","ko":"에이전트가 Saberloop 랜딩 페이지를 사용하여 스크린샷 캡처, 이미지 처리 및 HTML 업데이트를 표준화된 프로세스로 통합하여 HTTP 및 HTML과 같은 프로토콜을 통해 마케팅 자산 배포를 간소화할 수 있습니다.","es":"Permite a los agentes consolidar la captura de pantallas, el procesamiento de imágenes y las actualizaciones de HTML en un proceso estandarizado utilizando páginas de aterrizaje de Saberloop, simplificando la implementación de activos de marketing a través de protocolos como HTTP y HTML.","fr":"Permet aux agents de consolider la capture d''écran, le traitement d''images et les mises à jour HTML dans un processus standardisé en utilisant les pages d''atterrissage Saberloop, simplifiant le déploiement d''actifs marketing via des protocoles tels que HTTP et HTML.","de":"Ermöglicht es den Agenten, die Screenshot-Erfassung, die Bildverarbeitung und die HTML-Aktualisierungen in einem standardisierten Prozess mithilfe von Saberloop-Landingpages zu konsolidieren, wodurch die Bereitstellung von Marketing-Ressourcen über Protokolle wie HTTP und HTML gestreamt wird.","pt":"Habilita os agentes a consolidar a captura de tela, o processamento de imagem e as atualizações de HTML em um processo padronizado usando páginas de destino Saberloop, simplificando a implantação de ativos de marketing via protocolos como HTTP e HTML.","ru":"Наделяет агентов возможностью консолидировать захват экрана, обработку изображений и обновления HTML в стандартизированный процесс с использованием целевых страниц Saberloop, упрощая развертывание маркетинговых активов через протоколы seperti HTTP и HTML.","ar":"تمكين الوكلاء من توحيد التقاط الشاشة ومعالجة الصور وتحديث HTML في عملية معيارية باستخدام صفحات الهبوط Saberloop، وتبسيط نشر أصول التسويق عبر بروتوكولات مثل HTTP و HTML."},"useCases":{"en":["Automating Saberloop landing page updates with captured marketing assets","Generating standardized HTML templates for marketing campaigns","Deploying landing pages with optimized image processing and screenshot capture"],"zh":["使用捕获的营销资产自动更新Saberloop着陆页","为营销活动生成标准化的HTML模板","部署具有优化的图像处理和截图捕获的着陆页"],"ja":["キャプチャされたマーケティング資産を使用してSaberloopのランディングページを自動更新する","マーケティングキャンペーンのための標準化されたHTMLテンプレートを生成する","最適化された画像処理とスクリーンショットキャプチャを備えたランディングページをデプロイする"],"ko":["캡처한 마케팅 자산을 사용하여 Saberloop 랜딩 페이지를 자동으로 업데이트 하는 것","마케팅 캠페인에 대한 표준화된 HTML 템플릿을 생성하는 것","최적화된 이미지 처리 및 스크린샷 캡처를 갖춘 랜딩 페이지를 배포하는 것"],"es":["Automatizar las actualizaciones de la página de aterrizaje de Saberloop con activos de marketing capturados","Generar plantillas HTML estandarizadas para campañas de marketing","Implementar páginas de aterrizaje con procesamiento de imágenes optimizado y captura de pantalla"],"fr":["Automatiser les mises à jour de la page d''atterrissage Saberloop avec des actifs marketing capturés","Générer des modèles HTML standardisés pour des campagnes marketing","Déployer des pages d''atterrissage avec un traitement d''images optimisé et une capture d''écran"],"de":["Automatisieren von Saberloop-Landingpage-Aktualisierungen mit erfassten Marketing-Ressourcen","Erzeugen standardisierter HTML-Vorlagen für Marketing-Kampagnen","Bereitstellen von Landingpages mit optimierter Bildverarbeitung und Screenshot-Erfassung"],"pt":["Automatizar atualizações de páginas de destino Saberloop com ativos de marketing capturados","Gerar modelos de HTML padronizados para campanhas de marketing","Implantar páginas de destino com processamento de imagem otimizado e captura de tela"],"ru":["Автоматизировать обновления целевых страниц Saberloop с захваченными маркетинговыми активами","Генерировать стандартизированные шаблоны HTML для маркетинговых кампаний","Развертывать целевые страницы с оптимизированной обработкой изображений и захватом экрана"],"ar":["توفير تحديثات صفحة الهبوط Saberloop الآلية مع أصول التسويق الملتقطة","توليد قوالب HTML معيارية لحملات التسويق","نشر صفحات الهبوط مع معالجة الصور المُحسنة والتقاط الشاشة"]},"limitations":{"en":["Requires access to Saberloop landing page architecture","Limited to HTML updates and deployment","Dependent on standardized processes for marketing asset capture and processing"],"zh":["需要访问Saberloop着陆页架构","仅限HTML更新和部署","依赖于标准化的营销资产捕获和处理过程"],"ja":["Saberloopのランディングページアーキテクチャへのアクセスが必要","HTMLの更新とデプロイのみ","標準化されたマーケティング資産のキャプチャと処理プロセスに依存する"],"ko":["Saberloop 랜딩 페이지 아키텍처에 대한 액세스가 필요합니다.","HTML 업데이트 및 배포만 해당합니다.","표준화된 마케팅 자산 캡처 및 처리 프로세스에 의존합니다."],"es":["Requiere acceso a la arquitectura de la página de aterrizaje de Saberloop","Limitado a actualizaciones y despliegue de HTML","Dependiente de procesos estandarizados para la captura y el procesamiento de activos de marketing"],"fr":["Nécessite un accès à l''architecture de la page d''atterrissage Saberloop","Limité aux mises à jour et au déploiement HTML","Dépendant de processus standardisés pour la capture et le traitement d''actifs marketing"],"de":["Erfordert Zugriff auf die Architektur der Saberloop-Landingpage","Begrenzt auf HTML-Aktualisierungen und -Bereitstellung","Abhängig von standardisierten Prozessen für die Erfassung und Verarbeitung von Marketing-Ressourcen"],"pt":["Requer acesso à arquitetura de páginas de destino Saberloop","Limitado a atualizações e implantação de HTML","Dependente de processos padronizados para captura e processamento de ativos de marketing"],"ru":["Требует доступа к архитектуре целевых страниц Saberloop","Ограничен обновлениями и развертыванием HTML","Зависит от стандартизированных процессов для захвата и обработки маркетинговых активов"],"ar":["يتطلب الوصول إلى هندسة صفحات الهبوط Saberloop","محدود بتحديثات وتنصيب HTML","يعتمد على عمليات معيارية لالتقاط ومعالجة أصول التسويق"]},"version":4},"contentHash":"97a15d22f3c14015cdcb1a239bdfc99c976c58ea91af90e95f92a95871682b31","qualityScore":59}');
