INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jewbetcha/opentrace/coding-standards', 'coding-standards', 'jewbetcha', 'opentrace', 'community', 'coding-standards jewbetcha opentrace community The coding-standards skill provides universal coding standards applicable across all projects, focusing on code quality principles such as readability, KISS, and DRY. This skill benefits developers seeking to improve code maintainability and reusability. 代码标准是编写高质量代码的基础，包括代码可读性、简单性和重用性 コーディングスタンダードは、高品質のコードを書くための基礎です。コードの可読性、単純性、再利用性を重視します 코딩 표준은高品質의 코드를 작성하는 基礎입니다. 코드의 가독성, 단순성, 재사용성을 중시합니다 Estándares de codificación para proyectos de desarrollo de software, enfocados en principios de calidad de código como legibilidad y simplicidad Normes de codage pour les projets de développement de logiciels, axées sur les principes de qualité de code tels que la lisibilité et la simplicité Codierungsstandards für Software-Entwicklungsprojekte, die auf Code-Qualitätsprinzipien wie Lesbarkeit und Einfachheit basieren Padrões de codificação para melhorar a qualidade do código e aumentar a produtividade Стандарты кодирования для улучшения качества кода и повышения производительности معايير الترميز لتحسين جودة الشفرة وزيادة الإنتاجية how to use coding-standards coding-standards best practices coding-standards vs clean code coding-standards setup guide what is coding-standards coding-standards alternative coding-standards install coding-standards for AI agents coding-standards for developers coding-standards tutorial 代码标准 代码可读性 代码简单性 代码重用性 代码格式 自解释代码 代码注释 AI开发 代码质量 Enforces Readability First principle with clear variable and function names Applies KISS principle to avoid over-engineering and premature optimization Implements DRY principle to extract common code and reduce repetition Promotes self-documenting code over comments for better maintainability Encourages consistent formatting for improved code readability Coding-standards is a set of universal principles and best practices for writing clean, readable, and maintainable code, emphasizing simplicity, reusability, and self-documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pthm/soup/shader-debug', 'community', 'pthm', 'soup', 'pthm/soup', 'shader-debug', 0, 0, 59, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:15.607Z', '775f6fdd2001de2f716c8f9210c711d161404178eca75fd5b5ba7a3c97036670', '{"id":"pthm/soup/shader-debug","name":"shader-debug","description":{"en":"The shader-debug skill allows developers to debug GLSL fragment shaders by rendering them to PNG files, ideal for inspecting shader values and iterating on shader code. It benefits game developers and graphics programmers.","zh":"shader-debug是一个用于调试GLSL片段着色器的工具，通过渲染PNG文件来提供快速视觉反馈","ja":"Shader DebugはGLSLフラグメントシェーダーをデバッグするツールで、PNGファイルをレンダリングして迅速な視覚フィードバックを提供する","ko":"shader-debug는 GLSL 프래그먼트 셰이더를 디버깅하는 도구로 PNG 파일을 렌더링하여 빠른 시각적 피드백을 제공합니다","es":"Shader-debug es una herramienta para depurar shaders GLSL, permitiendo renderizarlos a archivos PNG para una inspección visual rápida","fr":"Shader-debug est un outil pour déboguer les shaders GLSL, permettant de les rendre sous forme de fichiers PNG pour une inspection visuelle rapide","de":"Shader-debug ist ein Tool zum Debuggen von GLSL-Shadern, das das Rendern in PNG-Dateien für eine schnelle visuelle Inspektion ermöglicht","pt":"A ferramenta shader-debug permite que desenvolvedores depurem shaders GLSL renderizando-os para arquivos PNG","ru":"Инструмент shader-debug позволяет разработчикам отлаживать шейдеры GLSL, отрисовывая их в файлы PNG","ar":"أداة فحص الشيدر تسمح للمطورين بفحص الشيدر GLSL عن طريق تقديمها إلى ملفات PNG"},"seo":{"title":{"en":"shader-debug: Debug GLSL Fragment Shaders | AI Agent Skill","zh":"shader-debug 设置指南：调试GLSL片段着色器","ja":"Shader Debug のベストプラクティス：GLSL フラグメント シェーダーのデバッグ","ko":"shader-debug 튜토리얼: GLSL 프래그먼트 셰이더 디버깅","es":"Guía de configuración de shader-debug para depuración de ...","fr":"Guide d''installation de shader-debug pour le débogage de ...","de":"Einrichtungsleitfaden für shader-debug zur Fehlersuche in...","pt":"Guia de Configuração do Shader Debug para Desenvolvedores","ru":"ИИ Агенты: Shader Debug Руководство по Настройке","ar":"إعداد أداة فحص الشيدر للمطورين"},"description":{"en":"Unlock efficient shader debugging with shader-debug! Render GLSL fragment shaders to PNG files and inspect values without running simulations. Get started now!","zh":"使用shader-debug调试GLSL片段着色器，快速获取视觉反馈，解决游戏开发中的着色器问题","ja":"Shader Debugを使用してGLSLフラグメントシェーダーをデバッグし、ゲーム開発でのシェーダーの問題を解決する","ko":"shader-debug를 사용하여 GLSL 프래그먼트 셰이더를 디버깅하고 게임 개발에서의 셰이더 문제를 해결하세요","es":"Aprende a depurar shaders GLSL con shader-debug, una herramienta de línea de comandos para renderizar shaders a archivos PNG","fr":"Découvrez comment déboguer les shaders GLSL avec shader-debug, un outil en ligne de commande pour rendre les shaders sous forme de fichiers PNG","de":"Erfahren Sie, wie Sie GLSL-Shader mit shader-debug debuggen, einem Kommandozeilen-Tool zum Rendern von Shadern in PNG-Dateien","pt":"Aprenda a depurar shaders GLSL com a ferramenta shader-debug e melhore a qualidade dos gráficos em seus jogos","ru":"Используйте ИИ Агенты для отладки шейдеров GLSL с помощью инструмента shader-debug и улучшите качество графики в ваших играх","ar":"تعلم كيفية فحص الشيدر GLSL باستخدام أداة فحص الشيدر و تحسين جودة الرسومات في ألعابك"},"definition":{"en":"shader-debug is a tool for debugging GLSL fragment shaders, enabling rendering to PNG files for visual inspection and feedback.","zh":"shader-debug是一种用于调试GLSL片段着色器的工具，通过渲染PNG文件来提供视觉反馈","ja":"Shader DebugはGLSLフラグメントシェーダーをデバッグするためのツールで、PNGファイルをレンダリングして視覚フィードバックを提供する","ko":"shader-debug는 GLSL 프래그먼트 셰이더를 디버깅하기 위한 도구로 PNG 파일을 렌더링하여 시각적 피드백을 제공하는 것입니다","es":"Shader-debug es una herramienta de depuración de shaders que utiliza la línea de comandos para renderizar shaders GLSL a archivos PNG","fr":"Shader-debug est un outil de débogage de shaders qui utilise la ligne de commande pour rendre les shaders GLSL sous forme de fichiers PNG","de":"Shader-debug ist ein Debugging-Tool für Shader, das die Kommandozeile nutzt, um GLSL-Shader in PNG-Dateien zu rendern","pt":"O shader-debug é uma ferramenta de depuração para shaders GLSL que renderiza o resultado para arquivos PNG","ru":"Shader-debug - это инструмент отладки для шейдеров GLSL, который отрисовывает результат в файлы PNG","ar":"فحص الشيدر هو أداة فحص للشيدر GLSL التي تقدم النتيجة إلى ملفات PNG"},"features":{"en":["Renders GLSL fragment shaders to PNG files for visual debugging","Supports quick visual feedback via command-line interface using Go","Enables inspection of shader values without running simulations","Facilitates debugging of coordinate systems, UV mapping, and color output","Utilizes the `go run` command for easy execution, with options like `-shader` and `-out`"],"zh":["调试GLSL片段着色器","渲染PNG文件以提供视觉反馈","支持快速迭代和视觉反馈","适用于游戏开发和着色器调试","使用Go语言编写"],"ja":["GLSLフラグメントシェーダーのデバッグ","PNGファイルのレンダリングによる視覚フィードバック","迅速なイテレーションと視覚フィードバックのサポート","ゲーム開発とシェーダーデバッグに適している","Go言語で書かれている"],"ko":["GLSL 프래그먼트 셰이더 디버깅","PNG 파일 렌더링을 통한 시각적 피드백","빠른 반복과 시각적 피드백 지원","게임 개발과 셰이더 디버깅에 적합","Go 언어로 작성됨"],"es":["Renderizado de shaders GLSL a archivos PNG","Depuración de shaders sin necesidad de ejecutar la simulación","Inspección visual rápida de valores de shader","Soporte para coordenadas, mapeo UV y salida de color"],"fr":["Rendu de shaders GLSL sous forme de fichiers PNG","Débogage de shaders sans exécuter la simulation","Inspection visuelle rapide des valeurs de shader","Prise en charge des coordonnées, du mapeo UV et de la sortie de couleur"],"de":["Rendern von GLSL-Shadern in PNG-Dateien","Fehlersuche in Shadern ohne Simulationsausführung","Schnelle visuelle Inspektion von Shader-Werten","Unterstützung für Koordinaten, UV-Mapping und Farbausgabe"],"pt":["Depuração de shaders GLSL","Renderização para arquivos PNG","Verificação de saída de shader","Inspeção de valores de shader sem simulação","Iteração rápida em código de shader"],"ru":["Отладка шейдеров GLSL","Отрисовка в файлы PNG","Проверка вывода шейдера","Осмотр значений шейдера без симуляции","Быстрая итерация кода шейдера"],"ar":["فحص الشيدر GLSL","تقديم إلى ملفات PNG","فحص إخراج الشيدر","تفتيش قيم الشيدر دون محاكاة","تكرار سريع في كود الشيدر"]},"keywords":{"en":["how to use shader-debug","shader-debug setup guide","GLSL fragment shader debugging","shader-debug alternative","shader-debug vs renderdoc","debugging GLSL shaders","shader-debug install","what is shader-debug","shader-debug tutorial"],"zh":["shader-debug","GLSL","片段着色器","调试工具","PNG渲染","游戏开发","着色器调试","Go语言"],"ja":["Shader Debug","GLSL","フラグメントシェーダー","デバッグツール","PNGレンダリング","ゲーム開発","シェーダーデバッグ","Go言語"],"ko":["shader-debug","GLSL","프래그먼트 셰이더","디버깅 도구","PNG 렌더링","게임 개발","셰이더 디버깅","Go 언어"],"es":["shader-debug","depuración de shaders","GLSL","renderizado de shaders","herramientas de línea de comandos","inspección visual de shaders","debugging de shaders","shader-debug para desarrolladores"],"fr":["shader-debug","débogage de shaders","GLSL","rendu de shaders","outils en ligne de commande","inspection visuelle de shaders","débogage de shaders","shader-debug pour les développeurs"],"de":["shader-debug","Fehlersuche in Shadern","GLSL","Rendern von Shadern","Kommandozeilen-Tools","visuelle Inspektion von Shadern","Debugging von Shadern","shader-debug für Entwickler"],"pt":["shader debug","depuração de shader","GLSL","renderização para PNG","desenvolvimento de jogos","ferramentas de desenvolvimento","otimização de gráficos"],"ru":["ИИ Агенты","shader debug","отладка шейдеров","GLSL","отрисовка в файлы PNG","разработка игр","инструменты разработки","оптимизация графики"],"ar":["أدوات الذكاء الاصطناعي","فحص الشيدر","فحص الشيدر GLSL","GLSL","تقديم إلى ملفات PNG","تطوير الألعاب","أدوات التطوير","تحسين الرسومات"]}},"owner":"pthm","repo":"soup","repoPath":"pthm/soup","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"shader-debug","description":"This skill should be used when debugging GLSL shaders, when shader output looks wrong, when the user mentions shader not working, debug shader, test shader, or when troubleshooting GPU rendering issues in this project.","version":"1.0.0","bodyPreview":"# Shader Debug Skill\n\nDebug GLSL fragment shaders by rendering them to PNG files.\n\n## When to Use\n\n- Shader output doesn''t look right in the game\n- Need to inspect shader values without running the simulation\n- Iterating on shader code and want quick visual feedback\n- Debugging coordinate systems, UV mapping, or color output\n\n## Tool Location\n\n```\ncmd/shaderdebug/main.go\n```\n\n## Basic Usage\n\n```bash\n# Render a shader to PNG\ngo run ./cmd/shaderdebug -shader shaders/resource.fs -out /tmp/debug.png","body":"# Shader Debug Skill\n\nDebug GLSL fragment shaders by rendering them to PNG files.\n\n## When to Use\n\n- Shader output doesn''t look right in the game\n- Need to inspect shader values without running the simulation\n- Iterating on shader code and want quick visual feedback\n- Debugging coordinate systems, UV mapping, or color output\n\n## Tool Location\n\n```\ncmd/shaderdebug/main.go\n```\n\n## Basic Usage\n\n```bash\n# Render a shader to PNG\ngo run ./cmd/shaderdebug -shader shaders/resource.fs -out /tmp/debug.png\n\n# View the result\nopen /tmp/debug.png  # macOS\n```\n\n## Flags\n\n| Flag | Default | Description |\n|------|---------|-------------|\n| `-shader` | `shaders/resource.fs` | Fragment shader path |\n| `-out` | `debug.png` | Output PNG path |\n| `-width` | 512 | Render width |\n| `-height` | 512 | Render height |\n\n## Shader Requirements\n\nThe shader must accept these uniforms (automatically set by the tool):\n- `uniform float time;` - Set to 0.0\n- `uniform vec2 resolution;` - Set to (width, height)\n\nStandard inputs available:\n- `in vec2 fragTexCoord;` - UV coordinates (0,0 at top-left, 1,1 at bottom-right after flip)\n\n## Debugging Workflow\n\n### 1. Create a minimal test shader\n\n```glsl\n#version 330\nin vec2 fragTexCoord;\nout vec4 finalColor;\nuniform vec2 resolution;\n\nvoid main() {\n    // Output UV as color to verify coordinates\n    finalColor = vec4(fragTexCoord.x, fragTexCoord.y, 0.0, 1.0);\n}\n```\n\n### 2. Test the pipeline\n\n```bash\ngo run ./cmd/shaderdebug -shader shaders/debug_test.fs -out /tmp/uv.png\n```\n\nExpected: Gradient from black (top-left) to yellow (bottom-right).\n\n### 3. Isolate the problem\n\nAdd intermediate outputs:\n```glsl\n// Debug: output distance as brightness\nfloat dist = length(uv - center);\nfinalColor = vec4(vec3(dist), 1.0);\n```\n\n### 4. Use the Read tool to view results\n\n```\nRead /tmp/debug.png\n```\n\nThe assistant can view PNG files directly and describe what it sees.\n\n## Common Issues\n\n### Shader appears all black\n- Check if values are in valid range [0, 1]\n- Verify uniforms are being set correctly\n- Test with debug_test.fs to verify pipeline works\n\n### Coordinates seem wrong\n- fragTexCoord has (0,0) at top-left after image flip\n- For world coordinates: `vec2 worldPos = fragTexCoord * resolution;`\n- Remember toroidal wrapping if simulating torus\n\n### Values too dark/bright\n- Normalize values to [0, 1] range\n- Use `clamp()` to prevent overflow\n- Check math for division by zero\n\n## Pre-made Debug Shaders\n\n| Shader | Purpose |\n|--------|---------|\n| `shaders/debug_test.fs` | UV coordinates as colors |\n| `shaders/debug_circle.fs` | Single circle at center |\n| `shaders/debug_dist.fs` | Distance from center |\n\n## Example: Debug Resource Field\n\n```bash\n# Test resource shader at game resolution\ngo run ./cmd/shaderdebug \\\n  -shader shaders/resource.fs \\\n  -out /tmp/resource.png \\\n  -width 1280 -height 720\n\n# Check the output\nopen /tmp/resource.png\n```\n\nIf hotspots aren''t visible:\n1. Check radius values (might be too small relative to resolution)\n2. Verify UV vs world coordinate usage\n3. Test with a simple single-hotspot shader first\n"},"lastSynced":"2026-03-08T02:04:15.607Z","agentAnalysis":{"suitability":{"en":"Perfect for Graphics Agents needing advanced shader debugging capabilities for GLSL fragment shaders.","zh":"适合需要高级着色器调试功能的图形代理，特别是用于GLSL片段着色器的调试。","ja":"GLSLフラグメントシェーダーの高度なシェーダー デバッグ機能を必要とするグラフィックス エージェントに最適です。","ko":"GLSL 조각 셰이더에 대한 고급 셰이더 디버깅 기능을 필요로 하는 그래픽 에이전트에 적합합니다.","es":"Perfecto para agentes gráficos que necesitan capacidades de depuración de sombreadores avanzadas para sombreadores de fragmentos GLSL.","fr":"Parfait pour les agents graphiques nécessitant des capacités de débogage de shaders avancées pour les shaders de fragments GLSL.","de":"Perfekt für Grafikagenten, die erweiterte Shader-Debugging-Funktionen für GLSL-Fragment-Shader benötigen.","pt":"Perfeito para Agentes Gráficos que necessitam de capacidades avançadas de depuração de sombreamento para sombreamentos de fragmentos GLSL.","ru":"Идеально подходит для Графических Агентов, требующих расширенных возможностей отладки шейдеров для фрагментных шейдеров GLSL.","ar":"مثالي للوكلاء الرسوميين الذين يحتاجون إلى قدرات متقدمة لتصحيح أخطاء الشيدر لشيدرات القطع GLSL."},"recommendation":{"en":"Empowers agents to debug GLSL fragment shaders by rendering them to PNG files, providing quick visual feedback and facilitating iteration on shader code, ideal for inspecting shader values, debugging coordinate systems, UV mapping, or color output using GLSL.","zh":"赋予代理调试GLSL片段着色器的能力，通过将其渲染为PNG文件，提供快速的视觉反馈，并促进着色器代码的迭代，适合检查着色器值、调试坐标系、UV映射或使用GLSL的颜色输出。","ja":"GLSLフラグメントシェーダーをPNGファイルにレンダリングすることで、エージェントにシェーダーのデバッグ機能を提供し、迅速な視覚的なフィードバックを提供し、シェーダーコードの反復処理を容易にし、シェーダーの値の検査、座標系のデバッグ、UVマッピング、またはGLSLを使用した色の出力を可能にします。","ko":"에이전트가 GLSL 조각 셰이더를 디버깅할 수 있도록 해주며, 이를 PNG 파일로 렌더링하여 빠른 시각적 피드백을 제공하고 셰이더 코드의 반복을 촉진하여 셰이더 값 검사, 좌표계 디버깅, UV 매핑 또는 GLSL을 사용한 색상 출력에 이상적입니다.","es":"Habilita a los agentes a depurar sombreadores de fragmentos GLSL al renderizarlos a archivos PNG, proporcionando una retroalimentación visual rápida y facilitando la iteración en el código de sombreador, ideal para inspeccionar valores de sombreador, depurar sistemas de coordenadas, mapeo UV o salida de color utilizando GLSL.","fr":"Permet aux agents de déboguer les shaders de fragments GLSL en les rendant dans des fichiers PNG, fournissant une rétroaction visuelle rapide et facilitant l''itération sur le code de shader, idéal pour inspecter les valeurs de shader, déboguer les systèmes de coordonnées, le mappage UV ou la sortie de couleur en utilisant GLSL.","de":"Ermöglicht es den Agenten, GLSL-Fragment-Shader zu debuggen, indem sie diese in PNG-Dateien rendern, wodurch eine schnelle visuelle Rückmeldung bereitgestellt und die Iteration über den Shader-Code erleichtert wird, ideal zum Überprüfen von Shader-Werten, Debuggen von Koordinatensystemen, UV-Mapping oder Farbausgabe unter Verwendung von GLSL.","pt":"Habilita os agentes a depurar sombreamentos de fragmentos GLSL renderizando-os para arquivos PNG, fornecendo feedback visual rápido e facilitando a iteração no código do sombreamento, ideal para inspecionar valores de sombreamento, depurar sistemas de coordenadas, mapeamento UV ou saída de cor usando GLSL.","ru":"Наделяет агентов возможностью отлаживать фрагментные шейдеры GLSL, отрисовывая их в файлы PNG, обеспечивая быструю визуальную обратную связь и облегчая итерацию кода шейдера, идеально подходит для инспекции значений шейдера, отладки систем координат, отображения UV или цветного вывода с помощью GLSL.","ar":"يمنح الوكلاء القدرة على تصحيح أخطاء شيدر القطع GLSL عن طريق تحويلها إلى ملفات PNG، مما يوفر ملاحظات بصرية سريعة ويهيئ التكرار في код الشيدر، مثالي لتفحص قيم الشيدر، تصحيح أخطاء أنظمة الإحداثيات، تعيين UV أو إخراج اللون باستخدام GLSL."},"useCases":{"en":["Debugging shader output discrepancies","Inspecting shader values without simulation","Iterating on shader code for rapid visual feedback","Debugging coordinate systems and UV mapping"],"zh":["调试着色器输出差异","无需模拟即可检查着色器值","迭代着色器代码以获得快速的视觉反馈","调试坐标系和UV映射"],"ja":["シェーダーの出力の不一致をデバッグする","シミュレーションを実行せずにシェーダーの値を確認する","シェーダーコードを反復処理して迅速な視覚的なフィードバックを得る","座標系とUVマッピングをデバッグする"],"ko":["셰이더 출력 불일치를 디버깅하는 것","시ミュ레이션 없이 셰이더 값을 검사하는 것","셰이더 코드를 반복 처리하여 빠른 시각적 피드백을 얻는 것","좌표계와 UV 매핑을 디버깅하는 것"],"es":["Depuración de discrepancias en la salida del sombreador","Inspección de valores de sombreador sin simulación","Iteración en el código de sombreador para una retroalimentación visual rápida","Depuración de sistemas de coordenadas y mapeo UV"],"fr":["Débogage des disparités de sortie de shader","Inspection des valeurs de shader sans simulation","Itération sur le code de shader pour une rétroaction visuelle rapide","Débogage des systèmes de coordonnées et du mappage UV"],"de":["Debuggen von Unstimmigkeiten in der Shader-Ausgabe","Überprüfen von Shader-Werten ohne Simulation","Iterieren über den Shader-Code für eine schnelle visuelle Rückmeldung","Debuggen von Koordinatensystemen und UV-Mapping"],"pt":["Depuração de discrepâncias de saída de sombreamento","Inspecionar valores de sombreamento sem simulação","Iterar no código de sombreamento para feedback visual rápido","Depurar sistemas de coordenadas e mapeamento UV"],"ru":["Отладка несоответствий вывода шейдера","Проверка значений шейдера без симуляции","Итерация кода шейдера для быстрой визуальной обратной связи","Отладка систем координат и отображения UV"],"ar":["تصحيح أخطاء اختلافات إخراج الشيدر","تفحص قيم الشيدر دون محاكاة","تكرار في код الشيدر لتعليقات بصرية سريعة","تصحيح أخطاء أنظمة الإحداثيات وتعيين UV"]},"limitations":{"en":["Requires Go runtime environment","Limited to GLSL fragment shaders","Output is PNG files only"],"zh":["需要Go运行时环境","仅限GLSL片段着色器","输出仅为PNG文件"],"ja":["Goランタイム環境が必要","GLSLフラグメントシェーダーのみ","出力はPNGファイルのみ"],"ko":["Go 런타임 환경이 필요","GLSL 조각 셰이더만 해당","출력은 PNG 파일만"],"es":["Requiere entorno de ejecución Go","Limitado a sombreadores de fragmentos GLSL","La salida es solo archivos PNG"],"fr":["Nécessite un environnement d''exécution Go","Limité aux shaders de fragments GLSL","La sortie est uniquement des fichiers PNG"],"de":["Benötigt eine Go-Laufzeitumgebung","Begrenzt auf GLSL-Fragment-Shader","Die Ausgabe besteht nur aus PNG-Dateien"],"pt":["Exige ambiente de execução Go","Limitado a sombreamentos de fragmentos GLSL","Saída é apenas arquivos PNG"],"ru":["Требует среды выполнения Go","Ограничен фрагментными шейдерами GLSL","Вывод только в файлах PNG"],"ar":["يتطلب بيئة تشغيل Go","محدود بشيدرات القطع GLSL","الإخراج هو ملفات PNG فقط"]},"version":4},"contentHash":"775f6fdd2001de2f716c8f9210c711d161404178eca75fd5b5ba7a3c97036670","qualityScore":59}');
