INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pthm/soup/shader-debug', 'shader-debug', 'pthm', 'soup', 'community', 'shader-debug pthm soup community The shader-debug skill allows developers to debug GLSL fragment shaders by rendering them to PNG files, ideal for inspecting shader values and iterating on shader code. It benefits game developers and graphics programmers. shader-debug是一个用于调试GLSL片段着色器的工具，通过渲染PNG文件来提供快速视觉反馈 Shader DebugはGLSLフラグメントシェーダーをデバッグするツールで、PNGファイルをレンダリングして迅速な視覚フィードバックを提供する shader-debug는 GLSL 프래그먼트 셰이더를 디버깅하는 도구로 PNG 파일을 렌더링하여 빠른 시각적 피드백을 제공합니다 Shader-debug es una herramienta para depurar shaders GLSL, permitiendo renderizarlos a archivos PNG para una inspección visual rápida Shader-debug est un outil pour déboguer les shaders GLSL, permettant de les rendre sous forme de fichiers PNG pour une inspection visuelle rapide Shader-debug ist ein Tool zum Debuggen von GLSL-Shadern, das das Rendern in PNG-Dateien für eine schnelle visuelle Inspektion ermöglicht A ferramenta shader-debug permite que desenvolvedores depurem shaders GLSL renderizando-os para arquivos PNG Инструмент shader-debug позволяет разработчикам отлаживать шейдеры GLSL, отрисовывая их в файлы PNG أداة فحص الشيدر تسمح للمطورين بفحص الشيدر GLSL عن طريق تقديمها إلى ملفات PNG how to use shader-debug shader-debug setup guide GLSL fragment shader debugging shader-debug alternative shader-debug vs renderdoc debugging GLSL shaders shader-debug install what is shader-debug shader-debug tutorial shader-debug GLSL 片段着色器 调试工具 PNG渲染 游戏开发 着色器调试 Go语言 Renders GLSL fragment shaders to PNG files for visual debugging Supports quick visual feedback via command-line interface using Go Enables inspection of shader values without running simulations Facilitates debugging of coordinate systems, UV mapping, and color output Utilizes the `go run` command for easy execution, with options like `-shader` and `-out` shader-debug is a tool for debugging GLSL fragment shaders, enabling rendering to PNG files for visual inspection and feedback.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zubayer0077/Claude-Multi-Agent-Research-System-Skill/multi-agent-researcher', 'community', 'zubayer0077', 'Claude-Multi-Agent-Research-System-Skill', 'zubayer0077/Claude-Multi-Agent-Research-System-Skill', 'multi-agent-researcher', 0, 0, 59, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:15.650Z', 'c6ccf8b31eb436ebba19c2b88d6168915a7e2f627f686b37799d44cdc91f184b', '{"id":"zubayer0077/Claude-Multi-Agent-Research-System-Skill/multi-agent-researcher","name":"multi-agent-researcher","description":{"en":"The multi-agent-researcher skill transforms complex research questions into comprehensive reports by decomposing topics and synthesizing findings. It benefits researchers and developers seeking structured investigations and seamless workflow planning.","zh":"多智能体研究协调器通过分解复杂研究问题、并行执行和审计，生成综合报告","ja":"マルチエージェント研究コーディネーターは、複雑な研究問題を分解し、並列実行と監査を実行して包括的な報告書を生成する","ko":"멀티 에이전트 리서치 코디네이터는 복잡한 연구 문제를 분해하고 병렬 실행과 감사를 통해 포괄적인 보고서를 생성합니다","es":"El multi-agent-researcher permite investigaciones paralelas y estructuradas, descomponiendo temas complejos en subtemas enfocados","fr":"Le multi-agent-researcher permet des recherches parallèles et structurées, en décomposant des sujets complexes en sous-sujets ciblés","de":"Der multi-agent-researcher ermöglicht parallele und strukturierte Recherchen, indem komplexe Themen in fokussierte Subthemen zerlegt werden","pt":"O multi-agent-researcher é uma ferramenta que transforma questões de pesquisa complexas em relatórios abrangentes com execução paralela e auditorias","ru":"ИИ Агенты multi-agent-researcher преобразуют сложные исследовательские вопросы в комплексные отчеты с параллельным выполнением и аудитами","ar":"يحول multi-agent-researcher أسئلة البحث المعقدة إلى تقارير شاملة مع التنفيذ الموازي والتدقيق"},"seo":{"title":{"en":"multi-agent-researcher: Parallel Execution Setup Guide | ...","zh":"多智能体研究协调器设置指南","ja":"マルチエージェント研究コーディネーター ベストプラクティス","ko":"멀티 에이전트 리서치 코디네이터 구축 가이드","es":"Guía de configuración de multi-agent-researcher para inve...","fr":"Guide de mise en place de multi-agent-researcher pour rec...","de":"Einrichtungsleitfaden für multi-agent-researcher zur para...","pt":"Guia de Configuração do multi-agent-researcher para Pesqu...","ru":"Настройка ИИ Агентов: multi-agent-researcher для Параллел...","ar":"دليل إعداد multi-agent-researcher لأبحاث متوازية"},"description":{"en":"Unlock efficient research workflows with multi-agent-researcher. Discover how to decompose topics, spawn researcher agents, and synthesize findings. Get star...","zh":"使用多智能体研究协调器，通过并行执行和审计，实现高效、结构化的调查和无缝的工作流计划","ja":"マルチエージェント研究コーディネーターを使用して、並列実行と監査により効率的で構造化された調査とシームレスなワークフロープランニングを実現する","ko":"멀티 에이전트 리서치 코디네이터를 사용하여 병렬 실행과 감사를 통해 효율적이고 구조화된 조사와 무縫의 워크플로우 계획을 구현합니다","es":"Aprende a utilizar multi-agent-researcher para investigaciones estructuradas y planificación de flujos de trabajo","fr":"Découvrez comment utiliser multi-agent-researcher pour des recherches structurées et une planification de flux de travail","de":"Erfahren Sie, wie Sie multi-agent-researcher für strukturierte Recherchen und Workflow-Planung einsetzen","pt":"Aprenda a configurar o multi-agent-researcher para pesquisas eficientes e estruturadas com execução paralela e auditorias","ru":"Узнайте, как настроить ИИ Агенты multi-agent-researcher для эффективных и структурированных исследований с параллельным выполнением и аудитами","ar":"تعرف على كيفية إعداد multi-agent-researcher لأبحاث كفؤة ومرتبة مع التنفيذ الموازي والتدقيق"},"definition":{"en":"multi-agent-researcher is a skill that orchestrates multi-agent research with parallel execution and audits for efficient investigations and workflow planning.","zh":"多智能体研究协调器是一种AI工具，用于协调多个研究代理以执行并行研究","ja":"マルチエージェント研究コーディネーターは、複数の研究エージェントを並列研究のために調整するAIエージェントの一種です","ko":"멀티 에이전트 리서치 코디네이터는 병렬 연구를 위해 여러 연구 에이전트를 조정하는 AI 도구의 일종입니다","es":"Un multi-agent-researcher es una herramienta de investigación que coordina agentes especializados para investigaciones paralelas","fr":"Un multi-agent-researcher est un outil de recherche qui coordonne des agents spécialisés pour des recherches parallèles","de":"Ein multi-agent-researcher ist ein Recherche-Tool, das spezialisierte Agenten für parallele Recherchen koordiniert","pt":"O multi-agent-researcher é uma ferramenta de pesquisa que divide tópicos amplos em subtemas focados e executa pesquisas paralelas","ru":"ИИ Агенты multi-agent-researcher - это исследовательский инструмент, который разбивает широкие темы на фокусированные подсубъекты и выполняет параллельные исследования","ar":"multi-agent-researcher هو أداة بحث تقسم الموضوعات الواسعة إلى مواضيع فرعية محددة وتقوم بأبحاث موازية"},"features":{"en":["Decomposes broad topics into 2-4 focused subtopics","Spawns specialized researcher agents in parallel for efficient research","Synthesizes findings into cohesive final reports","Saves structured outputs for reference and future use","Auto-invoke capability for search and discovery tasks","Supports seamless workflow planning and execution"],"zh":["并行执行研究任务","审计和结构化输出","分解复杂研究问题","生成综合报告","支持多个研究代理","实现无缝的工作流计划"],"ja":["並列実行による研究タスク","監査と構造化出力","複雑な研究問題の分解","包括的な報告書の生成","複数の研究エージェントのサポート","シームレスなワークフロープランニング"],"ko":["병렬 실행 연구 태스크","감사 및 구조화 출력","복잡한 연구 문제의 분해","포괄적인 보고서 생성","複数의 연구 에이전트 지원","무縫의 워크플로우 계획"],"es":["Descomposición de temas complejos en 2-4 subtemas enfocados","Ejecución paralela de agentes de investigación especializados","Síntesis de hallazgos en informes finales cohesivos","Guardar salidas estructuradas para referencia","Planificación de flujos de trabajo para investigaciones eficientes"],"fr":["Décomposition de sujets complexes en 2-4 sous-sujets ciblés","Exécution parallèle d''agents de recherche spécialisés","Synthèse de résultats en rapports finals cohérents","Enregistrement de sorties structurées pour référence","Planification de flux de travail pour des recherches efficaces"],"de":["Zerlegung komplexer Themen in 2-4 fokussierte Subthemen","Parallele Ausführung spezialisierter Recherche-Agenten","Synthese von Ergebnissen in kohärenten Endberichten","Speichern von strukturierten Ausgaben für Referenz","Workflow-Planung für effiziente Recherchen"],"pt":["Decomposição de tópicos amplos em subtemas focados","Execução paralela de pesquisas com auditorias","Síntese de resultados em relatórios abrangentes","Salvar saídas estruturadas para referência","Suporte a pesquisas paralelas com spawns de agentes especializados"],"ru":["Разбиение широких тем на фокусированные подсубъекты","Параллельное выполнение исследований с аудитами","Синтез результатов в комплексные отчеты","Сохранение структурированных выходных данных для справки","Поддержка параллельных исследований с вызовом специализированных агентов"],"ar":["تقسيم الموضوعات الواسعة إلى مواضيع فرعية محددة","التنفيذ الموازي لأبحاث مع التدقيق","دمج النتائج في تقارير شاملة","حفظ الإخراج المنظم للREFERENCE","دعم الأبحاث الموازية مع استدعاء وكلاء متخصصين"]},"keywords":{"en":["how to use multi-agent-researcher","what is multi-agent-researcher","multi-agent-researcher alternative","multi-agent-researcher vs other research tools","multi-agent-researcher install","multi-agent-researcher setup guide","parallel execution in research","structured research workflows","research agent automation"],"zh":["多智能体研究协调器","AI工具","并行执行","审计和结构化输出","研究代理","综合报告","工作流计划","研究问题分解"],"ja":["マルチエージェント研究コーディネーター","AIエージェント","並列実行","監査と構造化出力","研究エージェント","包括的な報告書","ワークフロープランニング","研究問題分解"],"ko":["멀티 에이전트 리서치 코디네이터","AI 도구","병렬 실행","감사 및 구조화 출력","연구 에이전트","포괄적인 보고서","워크플로우 계획","연구 문제 분해"],"es":["herramientas de investigación","agentes de investigación","investigación paralela","planificación de flujos de trabajo","informes de investigación","recherche estructurada","desarrollo de software","tecnologías de investigación"],"fr":["outils de recherche","agents de recherche","recherche parallèle","planification de flux de travail","rapports de recherche","recherche structurée","développement de logiciels","technologies de recherche"],"de":["Recherche-Tools","Recherche-Agenten","parallele Recherche","Workflow-Planung","Recherche-Berichte","strukturierte Recherche","Software-Entwicklung","Recherche-Technologien"],"pt":["multi-agent-researcher","pesquisa paralela","auditorias de pesquisa","relatórios abrangentes","pesquisa eficiente","ferramentas de pesquisa","agentes de pesquisa","pesquisa estruturada"],"ru":["ИИ Агенты","multi-agent-researcher","параллельное выполнение исследований","аудиты исследований","комплексные отчеты","эффективные исследования","инструменты исследования","агенты исследования","структурированные исследования"],"ar":["multi-agent-researcher","أبحاث موازية","تدقيق أبحاث","تقارير شاملة","أبحاث كفؤة","أدوات بحث","وكلاء بحث","أبحاث منظمة","أدوات إبحاث إصطناعية"]}},"owner":"zubayer0077","repo":"Claude-Multi-Agent-Research-System-Skill","repoPath":"zubayer0077/Claude-Multi-Agent-Research-System-Skill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"multi-agent-researcher","description":"Conduct comprehensive research on any topic by coordinating 2-4 specialized researcher agents in parallel, then synthesizing findings into a detailed report via mandatory report-writer agent delegation","version":"2.1.2","bodyPreview":"# Multi-Agent Research Coordinator\n\n## Purpose\n\nTransform complex research questions into comprehensive reports by:\n1. Decomposing broad topics into 2-4 focused subtopics\n2. Spawning specialized researcher agents in parallel\n3. Synthesizing findings into cohesive final report\n4. Saving structured outputs for reference\n\n## When to Use\n\nAuto-invoke when user asks:\n- **Search/Discovery**: \"Search what is [topic]\", \"Find information about [subject]\", \"Look up [technology]\", \"Discover [patterns]\"\n- *","body":"# Multi-Agent Research Coordinator\n\n## Purpose\n\nTransform complex research questions into comprehensive reports by:\n1. Decomposing broad topics into 2-4 focused subtopics\n2. Spawning specialized researcher agents in parallel\n3. Synthesizing findings into cohesive final report\n4. Saving structured outputs for reference\n\n## When to Use\n\nAuto-invoke when user asks:\n- **Search/Discovery**: \"Search what is [topic]\", \"Find information about [subject]\", \"Look up [technology]\", \"Discover [patterns]\"\n- **Investigation**: \"Research [topic]\", \"Investigate [subject]\", \"Analyze [phenomenon]\", \"Study [field]\", \"Explore [domain]\"\n- **Collection**: \"Gather information about [subject]\", \"Collect data on [topic]\", \"Compile resources for [area]\"\n- **Learning**: \"Learn about [subject]\", \"Tell me about [topic]\", \"Dig into [technology]\", \"Delve into [concept]\"\n- **Contextual**: \"What are the latest developments in [field]?\", \"Comprehensive analysis of [topic]\", \"Deep dive into [subject]\", \"State of the art in [domain]\", \"Best practices for [area]\"\n\nDo NOT invoke for:\n- Simple factual questions (\"What is the capital of France?\")\n- Decision evaluation (\"Should I use X or Y?\")\n- Code-related tasks (\"Debug this function\", \"Write a script\")\n\n## Orchestration Workflow\n\n### Phase 1: Query Analysis & Decomposition\n\n**Step 1.1: Understand the Research Question**\nAnalyze user''s query to identify core topic, scope, and intent.\n\n**Step 1.2: Decompose into Subtopics**\nBreak topic into 2-4 focused subtopics that are:\n- Mutually exclusive (minimal overlap)\n- Collectively exhaustive (cover whole topic)\n- Independently researchable\n- Together provide comprehensive coverage\n\n**Decomposition Patterns:**\n\n**Temporal**: Past → Current → Future\n**Categorical**: Category 1, 2, 3\n**Stakeholder**: Technical → Business → Policy → User\n**Problem-Solution**: Problem → Solutions → Gaps → Future\n**Geographic**: Region A → Region B → Comparison\n\n**Step 1.3: Create Research Plan**\nUse TodoWrite to track:\n```\n- [ ] Decompose query into subtopics\n- [ ] Spawn researcher 1: [subtopic]\n- [ ] Spawn researcher 2: [subtopic]\n- [ ] Spawn researcher 3: [subtopic]\n- [ ] Synthesize findings\n- [ ] Save final report\n```\n\n---\n\n### Phase 2: Parallel Research Execution\n\n**Step 2.1: Spawn Researcher Agents in Parallel**\n\nFor each subtopic, create a Task tool call with:\n```\nsubagent_type: \"researcher\"\ndescription: \"Research {subtopic name}\"\nprompt: \"Research the following subtopic in depth:\n\n**Subtopic**: {Subtopic name}\n**Context**: Part of research on ''{original topic}''\n**Focus**: {Specific guidance}\n\nConduct thorough web research, gather authoritative sources, extract key findings, and save results to files/research_notes/{subtopic-slug}.md\"\n```\n\n**Critical**: Spawn ALL researchers in parallel (multiple Task calls in same message), not sequentially.\n\n**Step 2.2: Monitor Completion**\nUpdate TodoWrite as researchers complete.\n\n**Step 2.3: Verify All Complete**\nUse Glob to confirm all files exist: `files/research_notes/*.md`\n\n---\n\n### Phase 3: Synthesis & Report Generation\n\n**⚠️ CRITICAL: ARCHITECTURAL ENFORCEMENT ACTIVE ⚠️**\n\n**YOU DO NOT HAVE WRITE TOOL ACCESS** when this skill is active. The `allowed-tools` frontmatter explicitly EXCLUDES the Write tool to enforce proper workflow delegation.\n\n**YOU CANNOT**:\n- ❌ Write synthesis reports yourself\n- ❌ Create files in files/reports/ directory\n- ❌ Bypass the report-writer agent\n\n**YOU MUST**:\n- ✅ Spawn report-writer agent via Task tool\n- ✅ Delegate all synthesis and report writing to the agent\n- ✅ Read the completed report and deliver to user\n\n---\n\n**Step 3.1: Verify Research Completion**\n\n1. Use Glob to confirm all research notes exist: `files/research_notes/*.md`\n2. Verify count matches number of spawned researchers\n3. If any missing: investigate and complete before synthesis\n\n**Step 3.2: Spawn Report-Writer Agent (MANDATORY)**\n\n**This is the ONLY synthesis approach** - there is no \"Option A\" or \"Option B\". You MUST use the report-writer agent because you lack Write tool permissions.\n\n```\nTask:\nsubagent_type: \"report-writer\"\ndescription: \"Synthesize research findings into comprehensive report\"\nprompt: \"Synthesize research into comprehensive report:\n\n**Original Question**: {user query}\n**Subtopics Researched**: {list all subtopics}\n**Notes Location**: files/research_notes/\n\n## Your Tasks:\n1. Read ALL research notes from files/research_notes/\n2. Identify themes, patterns, and contradictions across notes\n3. Synthesize findings into cohesive narrative\n4. Cite sources from research notes\n5. Add cross-cutting insights beyond individual notes\n6. Save comprehensive report to files/reports/{topic-slug}_{timestamp}.md\n\n## Report Structure:\n- Executive Summary\n- Key Findings (with evidence from research notes)\n- Detailed Analysis by subtopic\n- Cross-Cutting Themes\n- Contradictions and Debates\n- Gaps and Limitations\n- Source Bibliography\n\nUse the timestamp format: $(date +\\\"%Y%m%d-%H%M%S\\\") for the filename.\"\n```\n\n**Step 3.3: Monitor Agent Completion**\n\nAfter spawning report-writer agent, wait for completion. The agent will:\n- Read all research notes\n- Synthesize findings\n- Write comprehensive report to files/reports/\n- Return completion message with file path\n\n---\n\n### Phase 4: Deliver Results\n\n**Step 4.1: Create User Summary**\n```markdown\n# Research Complete: {Topic}\n\nComprehensive research completed with {N} specialized researchers.\n\n## Key Findings\n1. {Finding 1}\n2. {Finding 2}\n3. {Finding 3}\n\n## Research Scope\n{N} subtopics investigated:\n- {Subtopic 1}\n- {Subtopic 2}\n- {Subtopic 3}\n\n## Files Generated\n**Research Notes**: `files/research_notes/`\n- {file1}.md\n- {file2}.md\n- {file3}.md\n\n**Final Report**: `files/reports/{filename}.md`\n\n## Next Steps\n{Optional suggestions}\n```\n\n**Step 4.2: Update TodoWrite**\nMark all items complete.\n\n---\n\n## Best Practices\n\n### Good Decomposition\n✅ 2-4 subtopics (sweet spot: 3)\n✅ Distinct but related\n✅ Comprehensive coverage\n✅ Independently researchable\n\n❌ Too many (>5)\n❌ Too few (1)\n❌ Significant overlap\n❌ Too narrow or too broad\n\n### Parallel Execution\n- Always spawn researchers simultaneously\n- Never sequential unless dependent\n- Provide context to each researcher\n- Reasonable scope (10-15 min each)\n\n### Synthesis Quality\n- Read ALL notes\n- Find connections across subtopics\n- Note contradictions explicitly\n- Cite sources\n- Add insights beyond individual notes\n\n---\n\n## Error Handling\n\n**Researcher Fails**: Try replacement, proceed with others, note gap\n**No Results Found**: Accept partial, note limitation\n**Contradictory Findings**: Document all perspectives explicitly\n**Unclear Query**: Ask clarifying questions first\n\n---\n\n## Examples\n\n**Query**: \"Research quantum error correction\"\n**Decomposition**:\n1. Theoretical foundations\n2. Hardware implementations\n3. Commercial viability\n**Researchers**: 3 parallel\n**Synthesis**: report-writer agent (MANDATORY)\n\n**Query**: \"Investigate cryptocurrency market 2025\"\n**Decomposition**:\n1. Market metrics & players\n2. Regulatory landscape\n3. Technology evolution\n4. Institutional trends\n**Researchers**: 4 parallel\n**Synthesis**: report-writer agent (MANDATORY)\n\n---\n\n**Remember**: Quality depends on good decomposition, thorough researchers, insightful synthesis, and clear user communication.\n"},"lastSynced":"2026-03-08T02:04:15.650Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents requiring advanced topic decomposition and report synthesis capabilities.","zh":"适合需要高级主题分解和报告综合能力的研究代理。","ja":"高度なトピック分解とレポート合成機能を必要とする研究エージェントに適しています。","ko":"고급 주제 분해 및 보고서 합성 기능을 필요로 하는 연구 에이전트에 적합합니다.","es":"Ideal para agentes de investigación que requieren descomposición de temas avanzada y capacidad de síntesis de informes.","fr":"Idéal pour les agents de recherche nécessitant une décomposition de sujets avancée et des capacités de synthèse de rapports.","de":"Ideal für Forschungsagenten, die eine erweiterte Themendekomposition und Berichtssynthesefähigkeiten erfordern.","pt":"Ideal para Agentes de Pesquisa que exigem decomposição avançada de tópicos e capacidades de síntese de relatórios.","ru":"Идеально подходит для агентов-исследователей, требующих продвинутого разложения тем и возможностей синтеза отчетов.","ar":"مثالي للوكلاء البحثيين الذين يتطلبون تحليل المواضيع المتقدم و khảليات إعداد التقارير."},"recommendation":{"en":"Empowers agents to transform complex research questions into comprehensive reports by decomposing topics, spawning specialized researcher agents, and synthesizing findings using parallel processing and structured output formatting, leveraging keywords like search, discovery, and workflow planning.","zh":"使代理能够通过分解主题、生成专用研究代理和使用并行处理和结构化输出格式合成发现来将复杂的研究问题转化为综合报告，利用诸如搜索、发现和工作流规划等关键词。","ja":"エージェントが複雑な研究問題を包括的なレポートに変換できるようにし、トピックを分解し、専門の研究者エージェントを生成し、並列処理と構造化出力形式を使用して発見を合成し、検索、発見、ワークフロー計画などのキーワードを利用します。","ko":"에이전트가 복잡한 연구 문제를 포괄적인 보고서로 변환할 수 있도록 하며, 주제를 분해하고 전문 연구자 에이전트를 생성하고 병렬 처리와 구조화된 출력 형식을 사용하여 발견을 합성하며, 검색, 발견, 워크플로 계획 등의 키워드를 활용합니다.","es":"Habilita a los agentes a transformar preguntas de investigación complejas en informes completos al descomponer temas, generar agentes de investigador especializados y sintetizar hallazgos utilizando procesamiento paralelo y formato de salida estructurado, aprovechando palabras clave como búsqueda, descubrimiento y planificación de flujo de trabajo.","fr":"Permet aux agents de transformer des questions de recherche complexes en rapports complets en décomposant les sujets, en générant des agents de recherche spécialisés et en synthétisant les résultats en utilisant un traitement parallèle et un format de sortie structuré, en exploitant des mots clés comme recherche, découverte et planification de workflow.","de":"Ermächtigt Agenten, komplexe Forschungsfragen in umfassende Berichte umzuwandeln, indem sie Themen in Teilthemen zerlegen, spezialisierte Forscheragenten spawnen und Ergebnisse mithilfe von parallelem Verarbeiten und strukturiertem Ausgabeformat synthetisieren, indem sie Schlüsselwörter wie Suche, Entdeckung und Workflow-Planung nutzen.","pt":"Habilita os agentes a transformar questões de pesquisa complexas em relatórios abrangentes, decompondo tópicos, gerando agentes de pesquisador especializados e sintetizando descobertas usando processamento paralelo e formatação de saída estruturada, aproveitando palavras-chave como busca, descoberta e planejamento de fluxo de trabalho.","ru":"Наделяет агентов возможностью преобразовывать сложные исследовательские вопросы в комплексные отчеты, разлагая темы, генерируя специализированных агентов-исследователей и синтезируя результаты с использованием параллельной обработки и структурированного форматирования вывода, используя ключевые слова như поиск, открытие и планирование рабочего процесса.","ar":"يمنح الوكلاء القدرة على تحويل الأسئلة البحثية المعقدة إلى تقارير شاملة من خلال تحليل المواضيع وتوليد وكلاء باحثين متخصصين ودمج النتائج باستخدام المعالجة الموازية وتحديد تنسيق الإخراج الهيكلي، واستخدام كلمات مفتاحية مثل البحث والاكتشاف وتخطيط سير العمل."},"useCases":{"en":["Decomposing broad research topics into focused subtopics","Automating the synthesis of findings into cohesive final reports","Generating structured outputs for seamless reference and workflow planning"],"zh":["将广泛的研究主题分解为焦点子主题","自动将发现合成为连贯的最终报告","生成结构化输出以实现无缝参考和工作流规划"],"ja":["広範な研究トピックを焦点を当てたサブトピックに分解する","発見を一貫した最終レポートに自動的に合成する","構造化された出力を生成して参照とワークフロー計画を円滑に行う"],"ko":["광범위한 연구 주제를 집중된 하위 주제로 분해하는 것","발견을 일관된 최종 보고서로 자동으로 합성하는 것","구조화된 출력을 생성하여 참조 및 워크플로 계획을 원활하게进行하는 것"],"es":["Descomponer temas de investigación amplios en subtemas enfocados","Automatizar la síntesis de hallazgos en informes finales cohesivos","Generar salidas estructuradas para una referencia y planificación de flujo de trabajo sin problemas"],"fr":["Décomposer des sujets de recherche larges en sous-sujets ciblés","Automatiser la synthèse des résultats en rapports finals cohérents","Générer des sorties structurées pour une référence et une planification de workflow sans problème"],"de":["Breite Forschungsthemen in fokussierte Teilthemen zerlegen","Die Synthese von Ergebnissen in kohärente Endberichte automatisieren","Strukturierte Ausgaben für eine nahtlose Referenz und Workflow-Planung generieren"],"pt":["Decompor tópicos de pesquisa amplos em subtemas focados","Automatizar a síntese de descobertas em relatórios finais coesos","Gerar saídas estruturadas para referência e planejamento de fluxo de trabalho sem interrupções"],"ru":["Разложение широких исследовательских тем на сосредоточенные подсубъекты","Автоматизация синтеза результатов в связные окончательные отчеты","Генерация структурированных выводов для бесперебойной ссылки и планирования рабочего процесса"],"ar":["تحليل المواضيع البحثية الواسعة إلى مواضيع محددة","تأتمة دمج النتائج في تقارير نهائية متسقة","توليد مخرجات هيكلية للاستشهاد وتخطيط سير العمل دون انقطاع"]},"limitations":{"en":["Requires user input for initial research questions","Limited to text-based research and reporting"],"zh":["需要用户输入初始研究问题","仅限于基于文本的研究和报告"],"ja":["初期の研究問題に対するユーザー入力が必要","テキストベースの研究とレポートに限定される"],"ko":["초기 연구 문제에 대한 사용자 입력이 필요","텍스트 기반 연구 및 보고서로 제한됨"],"es":["Requiere la entrada del usuario para las preguntas de investigación iniciales","Limitado a la investigación y la informática basadas en texto"],"fr":["Nécessite une entrée utilisateur pour les questions de recherche initiales","Limité à la recherche et à la rédaction de rapports basés sur du texte"],"de":["Benutzerinput für die anfänglichen Forschungsfragen erfordert","Begrenzt auf textbasierte Forschung und Berichterstellung"],"pt":["Exige entrada do usuário para questões de pesquisa iniciais","Limitado à pesquisa e relatórios baseados em texto"],"ru":["Требует ввода пользователя для начальных исследовательских вопросов","Ограничен текстовой исследовательской и отчетностью"],"ar":["يتطلب إدخال المستخدم للأسئلة البحثية الأولية","محدود بالبحث والتقرير القائم على النص"]},"version":4},"contentHash":"c6ccf8b31eb436ebba19c2b88d6168915a7e2f627f686b37799d44cdc91f184b","qualityScore":59}');
