INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('benbjohnson/litestream-skills/litestream', 'litestream', 'benbjohnson', 'litestream-skills', 'community', 'litestream benbjohnson litestream-skills community litestream is a disaster recovery tool for SQLite, benefiting AI assistant developers by providing continuous database replication. It monitors the SQLite Write-Ahead Log, converting changes to immutable LTX files. Litestream 是一个为 SQLite 提供灾难恢复功能的工具，通过监控 WAL 并转换为 LTX 文件来实现数据库的连续复制 Litestream は SQLite 用のディザスタリカバリーツールで、WAL を監視し、LTX ファイルに変換してデータベースの連続複製を実現します Litestream은 SQLite 재해 복구 도구로 WAL 모니터링 및 LTX 파일 변환을 통해 데이터베이스의 연속 복제를 제공합니다 Litestream es una herramienta de recuperación de desastres para SQLite que replica continuamente los cambios en la base de datos a almacenamiento en la nube Litestream est un outil de récupération de données pour SQLite qui réplique en continu les modifications de la base de données vers un stockage cloud Litestream ist ein Tool für die Notfallwiederherstellung von SQLite, das kontinuierlich Änderungen an der Datenbank auf Cloud-Speicher überträgt O Litestream é uma ferramenta de recuperação de desastres para o SQLite que replica continuamente as alterações do banco de dados para o armazenamento em nuvem Litestream - это инструмент восстановления после сбоев для SQLite, который непрерывно реплицирует изменения базы данных в облачное хранилище Litestream هو أداة لاستعادة البيانات بعد الكارثة ل SQLite التي تتكرر باستمرار لتغييرات قاعدة البيانات إلى التخزين السحابي how to use litestream litestream alternative litestream setup guide what is litestream litestream vs database replication tools litestream install for AI assistants SQLite disaster recovery LTX file format WAL monitoring interval Litestream SQLite 灾难恢复 WAL 监控 LTX 文件转换 云存储上传 AI 工具 AIエージェント WAL Monitoring: watches SQLite Write-Ahead Log for changes at configurable intervals LTX File generation: converts database page changes to immutable files Cloud storage upload: seamlessly uploads LTX files to chosen storage backend Configurable intervals: allows for customizable monitoring intervals, defaulting to 1s Immutable LTX files: ensures database page changes are never modified litestream is a background process that replicates SQLite database changes to cloud storage, ensuring data integrity and disaster recovery');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('riedel28/article-space/fsd-check', 'community', 'riedel28', 'article-space', 'riedel28/article-space', 'fsd-check', 0, 0, 59, '2026-03-08T01:57:15.463Z', '2026-03-08T02:09:19.090Z', '306bdcf443d2aaa88b3055d15b9bf5415379e9dc31bc56b9c9b0a3ca7ba80ba9', '{"id":"riedel28/article-space/fsd-check","name":"fsd-check","description":{"en":"The fsd-check AI Agent Skill validates React and TypeScript projects for strict compliance with Feature-Sliced Design (FSD) architecture. It is designed for developers and teams adopting FSD to maintain clean, scalable code structure.","zh":"FSD-check 是一个现代博客平台，使用 React、TypeScript 和 Mantine 构建。它遵循严格的 FSD 方法论，包括层次结构、规则和检查","ja":"FSD-check は、React、TypeScript、Mantine を使用して構築されたモダンなブログプラットフォームです。厳格な FSD 方法論に従い、層階構造、ルール、チェックを含みます","ko":"FSD-check는 React, TypeScript, Mantine을 사용하여 구축된 최신 블로그 플랫폼입니다. 엄격한 FSD 방법론을 따르며 계층 구조, 규칙 및 검사를 포함합니다","es":"fsd-check es una herramienta de verificación de diseño de características para proyectos React y TypeScript, que sigue la metodología de Feature-Sliced Design","fr":"fsd-check est un outil de vérification de conception de fonctionnalités pour les projets React et TypeScript, qui suit la méthodologie de Feature-Sliced Design","de":"fsd-check ist ein Werkzeug zur Überprüfung von Feature-Sliced-Design für React- und TypeScript-Projekte, das der Feature-Sliced-Design-Methode folgt","pt":"O FSD-Check é uma ferramenta que valida a conformidade do design de recursos em plataformas de blog modernas construídas com React, TypeScript e Mantine","ru":"FSD-Check - это инструмент, который проверяет соответствие дизайна функций в современных платформах блогов, построенных на React, TypeScript и Mantine с помощью ИИ Агентов","ar":"FSD-Check هو أداة للتحقق من امتثال مكونات التصميم في منصات التدوين الحديثة مبنية على React و TypeScript و Mantine باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"fsd-check: FSD Architecture Compliance Checker | AI Agent...","zh":"FSD-check 设置指南：React 和 TypeScript 的现代博客平台","ja":"FSD-check のベストプラクティス：React、TypeScript、Mantine を使用したモダンなブロ...","ko":"FSD-check 설치 가이드: React, TypeScript, Mantine을 사용한 최신 블로그 플랫폼","es":"Guía de configuración de fsd-check: Herramienta de verifi...","fr":"Guide de configuration de fsd-check : Outil de vérificati...","de":"Konfigurationsleitfaden für fsd-check: Werkzeug zur Überp...","pt":"FSD-Check: Guia de Configuração para Arquitetura de Desig...","ru":"FSD-Check: Руководство по настройке для ИИ Агентов и пров...","ar":"FSD-Check: دليل الإعداد للتحقق من مكونات التصميم مع أدوات..."},"description":{"en":"Automatically validate your React & TypeScript codebase against Feature-Sliced Design (FSD) principles. Enforces layer hierarchy, prevents cross-imports, and...","zh":"了解 FSD-check 的工作原理，包括 FSD 层次结构、规则和检查。使用 React、TypeScript 和 Mantine 构建现代博客平台","ja":"FSD-check の仕組みを学ぶ：FSD 層階構造、ルール、チェック。React、TypeScript、Mantine を使用したモダンなブログプラットフォームの構築","ko":"FSD-check의 작동 원리를 알아보세요. FSD 계층 구조, 규칙 및 검사 포함. React, TypeScript, Mantine을 사용한 최신 블로그 플랫폼 구축","es":"Aprende a configurar fsd-check, una herramienta de verificación de diseño de características para proyectos React y TypeScript, y mejora la organización de t...","fr":"Découvrez comment configurer fsd-check, un outil de vérification de conception de fonctionnalités pour les projets React et TypeScript, et améliorez l''organi...","de":"Erfahren Sie, wie Sie fsd-check konfigurieren, ein Werkzeug zur Überprüfung von Feature-Sliced-Design für React- und TypeScript-Projekte, und verbessern Sie ...","pt":"Aprenda a configurar o FSD-Check para validar a conformidade do design de recursos em sua plataforma de blog moderna com React e TypeScript","ru":"Узнайте, как настроить FSD-Check для проверки соответствия дизайна функций в вашей современной платформе блогов на React и TypeScript с помощью ИИ Агентов","ar":"تعلم كيفية 설정 FSD-Check للتحقق من امتثال مكونات التصميم في منصتك التدوينية الحديثة مع React و TypeScript باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"fsd-check is an AI Agent Skill that automates validation of a codebase''s adherence to Feature-Sliced Design principles. It checks layer import hierarchy, enforces public API usage via `index.ts`, and mandates absolute imports with the `@/*` alias.","zh":"FSD-check 是一个用于验证 Feature-Sliced Design 合规性的工具，用于检查代码库中的 FSD 层次结构和规则","ja":"FSD-check は、Feature-Sliced Design の準拠性を検証するためのツールであり、コードベース内の FSD 層階構造とルールをチェックします","ko":"FSD-check는 기능 슬라이스 설계 규칙을 준수하는지 확인하는 도구로 코드베이스 내의 FSD 계층 구조 및 규칙을 검사합니다","es":"fsd-check es una herramienta de verificación de diseño de características que valida la conformidad con la metodología de Feature-Sliced Design","fr":"fsd-check est un outil de vérification de conception de fonctionnalités qui valide la conformité à la méthodologie de Feature-Sliced Design","de":"fsd-check ist ein Werkzeug zur Überprüfung von Feature-Sliced-Design, das die Konformität mit der Feature-Sliced-Design-Methode überprüft","pt":"O FSD-Check é uma ferramenta de verificação de conformidade de design de recursos que segue a metodologia FSD","ru":"FSD-Check - это инструмент проверки соответствия дизайна функций, следующий методологии FSD для ИИ Агентов","ar":"FSD-Check هو أداة للتحقق من امتثال مكونات التصميم التي تتبع منهجية FSD لأدوات الذكاء الاصطناعي"},"features":{"en":["Validates FSD layer hierarchy (app → pages → widgets → features → entities → shared)","Enforces that layers can only import from layers below them","Prevents cross-imports within the same layer (e.g., features cannot import other features)","Mandates that all imports must go through a public API (`index.ts`)","Checks for the use of absolute imports with the `@/*` alias"],"zh":["基于 React、TypeScript 和 Mantine 的现代博客平台","遵循严格的 FSD 方法论，包括层次结构和规则","支持绝对导入和公共 API","检查 FSD 层次结构和规则的合规性","使用 @/* 别名进行导入"],"ja":["React、TypeScript、Mantine を使用したモダンなブログプラットフォーム","厳格な FSD 方法論に従い、層階構造とルールを含みます","絶対インポートとパブリック API をサポート","FSD 層階構造とルールの準拠性をチェック","インポートに @/* エイリアスを使用"],"ko":["React, TypeScript, Mantine을 사용한 최신 블로그 플랫폼","엄격한 FSD 방법론을 따르며 계층 구조 및 규칙을 포함","절대 가져오기 및 공용 API 지원","FSD 계층 구조 및 규칙의 규준을 검사","가져오기에 @/* 별칭 사용"],"es":["Validación de la jerarquía de capas de Feature-Sliced Design","Verificación de las reglas de importación de capas","Uso de imports absolutos con el alias @/*","Compatibilidad con proyectos React y TypeScript","Seguimiento de la metodología de Feature-Sliced Design"],"fr":["Validation de la hiérarchie de couches de Feature-Sliced Design","Vérification des règles d''importation de couches","Utilisation d''imports absolus avec l''alias @/*","Compatibilité avec les projets React et TypeScript","Suivi de la méthodologie de Feature-Sliced Design"],"de":["Validierung der Hierarchie von Feature-Sliced-Design-Schichten","Überprüfung der Importregeln für Schichten","Verwendung von absoluten Imports mit dem Alias @/*","Kompatibilität mit React- und TypeScript-Projekten","Verfolgung der Feature-Sliced-Design-Methode"],"pt":["Validação da conformidade do design de recursos com a metodologia FSD","Verificação da hierarquia de camadas do projeto","Implantação de regras de importação para garantir a integridade do design","Uso de imports absolutos com alias @/*","Compatibilidade com React, TypeScript e Mantine"],"ru":["Проверка соответствия дизайна функций методологии FSD для ИИ Агентов","Проверка иерархии слоев проекта","Внедрение правил импорта для обеспечения целостности дизайна","Использование абсолютных импортов с алиасом @/*","Совместимость с React, TypeScript и Mantine"],"ar":["التحقق من امتثال مكونات التصميم مع منهجية FSD لأدوات الذكاء الاصطناعي","التحقق من هرمية الطبقات للمشروع","تنفيذ قواعد الاستيراد لضمان سلامة التصميم","استخدام الاستيراد المطلق مع 별 @/*","التوافق مع React و TypeScript و Mantine"]},"keywords":{"en":["fsd-check setup guide","how to use fsd-check","what is fsd-check","fsd-check vs eslint","fsd-check install","Feature-Sliced Design checker","fsd architecture validation","fsd-check layer import rules"],"zh":["FSD-check","React","TypeScript","Mantine","现代博客平台","FSD 方法论","层次结构","规则","检查","AIエージェント"],"ja":["FSD-check","React","TypeScript","Mantine","モダンなブログプラットフォーム","FSD 方法論","層階構造","ルール","チェック","AIエージェント"],"ko":["FSD-check","React","TypeScript","Mantine","최신 블로그 플랫폼","FSD 방법론","계층 구조","규칙","검사","AI 도구"],"es":["fsd-check","Feature-Sliced Design","React","TypeScript","herramienta de verificación de diseño","validación de código","organización de código","metodología de desarrollo"],"fr":["fsd-check","Feature-Sliced Design","React","TypeScript","outil de vérification de conception","validation de code","organisation de code","méthodologie de développement"],"de":["fsd-check","Feature-Sliced Design","React","TypeScript","Werkzeug zur Überprüfung von Design","Code-Validierung","Code-Organisation","Entwicklungs-Methode"],"pt":["FSD-Check","design de recursos","metodologia FSD","React","TypeScript","Mantine","validação de conformidade","hierarquia de camadas","regras de importação"],"ru":["FSD-Check","дизайн функций","методология FSD","ИИ Агенты","React","TypeScript","Mantine","проверка соответствия","иерархия слоев","правила импорта"],"ar":["FSD-Check","مكونات التصميم","منهجية FSD","أدوات الذكاء الاصطناعي","React","TypeScript","Mantine","التحقق من امتثال","هرمية الطبقات","قواعد الاستيراد"]}},"owner":"riedel28","repo":"article-space","repoPath":"riedel28/article-space","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.463Z","topics":[],"category":"community","skillMd":{"name":"fsd-check","description":"Validate Feature-Sliced Design architecture compliance. Checks layer imports, public API usage, and cross-slice violations. Use when asked to check FSD, validate architecture, check imports, or FSD audit.","version":"1.0.0","bodyPreview":"# FSD Architecture Checker\n\nValidates Feature-Sliced Design compliance for this codebase.\n\n## FSD Layer Hierarchy\n\nThe project follows strict FSD methodology:\n\n```\napp → pages → widgets → features → entities → shared\n```\n\n**Rules:**\n\n- Layers can ONLY import from layers below them\n- No cross-imports within the same layer (features cannot import other features)\n- All imports must go through public API (`index.ts`)\n- Use absolute imports with `@/*` alias\n\n## Checks Performed\n\n### 1. Layer Import V","body":"# FSD Architecture Checker\n\nValidates Feature-Sliced Design compliance for this codebase.\n\n## FSD Layer Hierarchy\n\nThe project follows strict FSD methodology:\n\n```\napp → pages → widgets → features → entities → shared\n```\n\n**Rules:**\n\n- Layers can ONLY import from layers below them\n- No cross-imports within the same layer (features cannot import other features)\n- All imports must go through public API (`index.ts`)\n- Use absolute imports with `@/*` alias\n\n## Checks Performed\n\n### 1. Layer Import Violations\n\nCheck that imports respect the hierarchy:\n\n- `app` can import: pages, widgets, features, entities, shared\n- `pages` can import: widgets, features, entities, shared\n- `widgets` can import: features, entities, shared\n- `features` can import: entities, shared\n- `entities` can import: shared, other entities (same layer allowed)\n- `shared` can only import: shared\n\n### 2. Public API Violations\n\nAll imports from `entities`, `features`, `pages`, `widgets` must go through `index.ts`\n\n```typescript\n// CORRECT\nimport { Article } from ''@/entities/Article'';\n\n// WRONG - bypasses public API\nimport { Article } from ''@/entities/Article/model/types'';\n```\n\n### 3. Cross-Slice Violations\n\nWithin the same layer, slices should not import each other directly:\n\n```typescript\n// In features/AuthByUsername - WRONG\nimport { something } from ''@/features/AnotherFeature'';\n```\n\n### 4. Missing Public API\n\nCheck if slices have proper `index.ts` exports.\n\n## How to Run Checks\n\n### Option A: Run ESLint FSD Rules\n\n```bash\nnpx eslint \"src/**/*.{ts,tsx}\" --rule ''ulbi-tv-plugin/layer-imports: error'' --rule ''ulbi-tv-plugin/public-api-imports: error'' --rule ''ulbi-tv-plugin/path-checker: error''\n```\n\n### Option B: Manual Analysis\n\n1. Use Grep to find problematic import patterns\n2. Check specific layers or slices\n\n## Analysis Workflow\n\nWhen user invokes `/fsd-check`:\n\n1. **If argument provided** (e.g., `/fsd-check features`):\n   - Focus analysis on that specific layer or path\n   - Run targeted checks\n\n2. **If no argument**:\n   - Ask user what to check: full codebase, specific layer, or specific slice\n   - Or run quick overview of all layers\n\n3. **For each check**:\n   - Search for violation patterns using Grep\n   - Report findings in format: `file:line - violation description`\n\n4. **Output summary**:\n   - Total violations by category\n   - Most problematic files/slices\n   - Suggested fixes\n\n## Common Violation Patterns to Search\n\n### Layer violations (Grep patterns)\n\n```\n# Features importing from pages/widgets\npath: src/features/\npattern: from [''\"]@/(pages|widgets)/\n\n# Entities importing from features/pages/widgets\npath: src/entities/\npattern: from [''\"]@/(features|pages|widgets)/\n\n# Shared importing from any other layer\npath: src/shared/\npattern: from [''\"]@/(entities|features|pages|widgets|app)/\n```\n\n### Public API violations\n\n```\n# Deep imports into slices (more than 2 segments after @/)\npattern: from [''\"]@/(entities|features|pages|widgets)/[^''\"]+/[^''\"]+\n```\n\n### Cross-slice violations\n\n```\n# Feature importing another feature (check current file path vs import)\n# This requires analyzing file location context\n```\n\n## Output Format\n\nReport findings as:\n\n```\n## FSD Violations Found\n\n### Layer Import Violations (X found)\n- `src/features/Auth/ui/LoginForm.tsx:15` - features cannot import from widgets\n- `src/entities/User/model/slice.ts:3` - entities cannot import from features\n\n### Public API Violations (X found)\n- `src/widgets/Sidebar/ui/Sidebar.tsx:8` - import should be `@/entities/User` not `@/entities/User/model/types`\n\n### Cross-Slice Violations (X found)\n- `src/features/Auth/ui/Form.tsx:12` - feature should not import from another feature\n\n### Summary\n- Total: X violations\n- Critical: X (layer violations)\n- Fixable: X (public API - has autofix via ESLint)\n```\n\n## Quick Commands\n\nFor the user''s reference:\n\n```bash\n# Run all FSD ESLint rules\nnpm run lint:ts -- --rule ''ulbi-tv-plugin/layer-imports: error''\n\n# Check specific layer\nnpx eslint \"src/features/**/*.{ts,tsx}\" --rule ''ulbi-tv-plugin/layer-imports: error''\n\n# Auto-fix public API imports\nnpx eslint \"src/**/*.{ts,tsx}\" --rule ''ulbi-tv-plugin/public-api-imports: error'' --fix\n```\n"},"lastSynced":"2026-03-08T02:09:19.090Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing strict Feature-Sliced Design compliance validation in React and TypeScript projects.","zh":"非常适合需要严格的 Feature-Sliced Design 合规性验证的代码审查代理，尤其是在使用 React 和 TypeScript 的项目中。","ja":"React および TypeScript プロジェクトで厳格な Feature-Sliced Design コンプライアンス検証を必要とするコードレビュー エージェントに最適です。","ko":"React와 TypeScript 프로젝트에서 엄격한 Feature-Sliced Design 규정 준수 검증이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Ideal para agentes de revisión de código que necesitan una validación estricta del cumplimiento de Feature-Sliced Design en proyectos React y TypeScript.","fr":"Parfait pour les agents de revue de code nécessitant une validation stricte de la conformité au Feature-Sliced Design dans les projets React et TypeScript.","de":"Perfekt für Code Review Agents, die eine strenge Validierung der Einhaltung von Feature-Sliced Design in React- und TypeScript-Projekten benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de validação estrita de conformidade com o Design Dividido em Recursos em projetos React e TypeScript.","ru":"Идеально для агентов код-ревью, которым необходима строгая проверка соответствия дизайну, разделенному на функции, в проектах React и TypeScript.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى التحقق الصارم من الامتثال لتصميم المقاطع الميزة في مشاريع React و TypeScript."},"recommendation":{"en":"Empowers agents to enforce a clean, scalable code structure by validating strict FSD methodology, including layer import hierarchy and absolute imports with @/* alias, ensuring compliance with rules such as layers only importing from layers below them and no cross-imports within the same layer.","zh":"赋予代理人强制执行干净、可扩展的代码结构的能力，通过验证严格的 FSD 方法论，包括层次导入层级和使用 @/* 别名的绝对导入，确保遵守诸如层次只能从下层导入和同一层内不允许交叉导入等规则。","ja":"React および TypeScript プロジェクトで厳格な Feature-Sliced Design コンプライアンス検証を必要とするコードレビュー エージェントに最適です。エージェントは、厳格な FSD 方法論を検証することで、クリーンでスケーラブルなコード構造を強制実行できます。検証対象には、レイヤー間のインポート階層や @/* エイリアスを使用した絶対インポートなどがあり、同一レイヤー内でのクロスインポートは禁止されます。","ko":"에이전트가 깨끗하고 확장 가능한 코드 구조를 강제 적용할 수 있도록 해줍니다. 이는 엄격한 FSD 방법론을 검증하여 규칙을 준수하도록 합니다. 규칙에는 같은 레이어 내에서 교차 가져오기를 하지 않도록 하는 것과 레이어가 아래 레이어에서만 가져오도록 하는 것이 포함됩니다.","es":"Permite a los agentes imponer una estructura de código limpia y escalable validando la metodología FSD estricta, incluyendo la jerarquía de importación de capas y las importaciones absolutas con el alias @/*, asegurando el cumplimiento de reglas como que las capas solo importen desde capas inferiores y que no haya importaciones cruzadas dentro de la misma capa.","fr":"Permet aux agents d''imposer une structure de code propre et évolutive en validant la méthodologie FSD stricte, y compris la hiérarchie d''importation des couches et les importations absolues avec l''alias @/*, garantissant le respect de règles telles que les couches n''importent que depuis des couches inférieures et aucune importation croisée au sein de la même couche.","de":"Ermöglicht es Agents, eine saubere, skalierbare Codestruktur durchzusetzen, indem sie die strenge FSD-Methodologie validieren, einschließlich der Ebenen-Import-Hierarchie und absoluter Importe mit dem @/*-Alias, und so die Einhaltung von Regeln sicherstellen, wie dass Ebenen nur von untergeordneten Ebenen importieren und es keine Querimporte innerhalb derselben Ebene gibt.","pt":"Habilita os agentes a impor uma estrutura de código limpa e escalável, validando a metodologia FSD estrita, incluindo a hierarquia de importação de camadas e imports absolutos com alias @/*, garantindo o cumprimento de regras como camadas que importam apenas de camadas abaixo delas e sem importações cruzadas dentro da mesma camada.","ru":"Наделяет агентов возможностью обеспечить чистую и масштабируемую структуру кода, проверяя строгую методологию FSD, включая иерархию импорта слоев и абсолютные импорты с псевдонимом @/*, обеспечивая соблюдение правил, таких как слои, импортирующие только из слоев ниже них, и отсутствие перекрестных импортов внутри одного и того же слоя.","ar":"يمنح الوكيل khảية فرض هيكل رمز نظيف ومرن، من خلال التحقق من منهجية FSD الصارمة، بما في ذلك هرمية استيراد الطبقات والاستيرادات المطلقة مع 별 @/*، مما يضمن امتثال القواعد مثل الطبقات التي تستورد فقط من الطبقات أدناها وبدون استيرادات متقاطعة داخل نفس الطبقة."},"useCases":{"en":["Validating Feature-Sliced Design architecture in React projects","Enforcing strict layer import hierarchy in TypeScript codebases","Debugging cross-import issues within the same layer"],"zh":["在 React 项目中验证 Feature-Sliced Design 架构","在 TypeScript 代码库中强制执行严格的层次导入层级","调试同一层内的交叉导入问题"],"ja":["React プロジェクトでの Feature-Sliced Design アーキテクチャの検証","TypeScript コードベースでの厳格なレイヤーインポート階層の適用","同一レイヤー内のクロスインポートの問題のデバッグ"],"ko":["React 프로젝트에서 Feature-Sliced Design 아키텍처를 검증하는 것","TypeScript 코드베이스에서 엄격한 레이어 가져오기 계층을 적용하는 것","同じ 레이어 내의 교차 가져오기 문제를 디버깅하는 것"],"es":["Validación de la arquitectura Feature-Sliced Design en proyectos React","Aplicación de una jerarquía de importación de capas estricta en bases de código TypeScript","Depuración de problemas de importaciones cruzadas dentro de la misma capa"],"fr":["Validation de l''architecture Feature-Sliced Design dans les projets React","Application d''une hiérarchie d''importation de couches stricte dans les codebases TypeScript","Débogage des problèmes d''importation croisée au sein de la même couche"],"de":["Validierung der Feature-Sliced Design-Architektur in React-Projekten","Durchsetzung einer strengen Ebenen-Import-Hierarchie in TypeScript-Codebasen","Debugging von Querimportproblemen innerhalb derselben Ebene"],"pt":["Validar a arquitetura de Design Dividido em Recursos em projetos React","Impor uma hierarquia de importação de camadas estrita em codebases TypeScript","Depurar problemas de importação cruzada dentro da mesma camada"],"ru":["Проверка архитектуры дизайна, разделенного на функции, в проектах React","Внедрение строгой иерархии импорта слоев в кодовые базы TypeScript","Отладка перекрестных импортов внутри одного и того же слоя"],"ar":["التحقق من بنية تصميم المقاطع الميزة في مشاريع React","فرض هرمية استيراد الطبقات الصارمة في قواعد الكود TypeScript","تصحيح مشاكل الاستيراد المتقاطع داخل نفس الطبقة"]},"limitations":{"en":["Requires React and TypeScript project setup","Limited to Feature-Sliced Design architecture validation"],"zh":["需要 React 和 TypeScript 项目环境","仅限于 Feature-Sliced Design 架构验证"],"ja":["React および TypeScript プロジェクトのセットアップが必要","Feature-Sliced Design アーキテクチャの検証のみに限定される"],"ko":["React와 TypeScript 프로젝트 환경이 필요함","Feature-Sliced Design 아키텍처 검증에만 제한됨"],"es":["Requiere una configuración de proyecto React y TypeScript","Limitado a la validación de la arquitectura Feature-Sliced Design"],"fr":["Nécessite une configuration de projet React et TypeScript","Limité à la validation de l''architecture Feature-Sliced Design"],"de":["Erfordert eine React- und TypeScript-Projekteinrichtung","Beschränkt auf die Validierung der Feature-Sliced Design-Architektur"],"pt":["Exige configuração de projeto React e TypeScript","Limitado à validação da arquitetura de Design Dividido em Recursos"],"ru":["Требует настройки проекта React и TypeScript","Ограничен проверкой архитектуры дизайна, разделенного на функции"],"ar":["يتطلب إعداد مشروع React و TypeScript","محدود بالتحقق من بنية تصميم المقاطع الميزة"]},"version":4},"contentHash":"306bdcf443d2aaa88b3055d15b9bf5415379e9dc31bc56b9c9b0a3ca7ba80ba9","qualityScore":59}');
