INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('damianpoole/Loadstone/loadstone-cli', 'loadstone-cli', 'damianpoole', 'Loadstone', 'community', 'loadstone-cli damianpoole Loadstone community The loadstone-cli skill retrieves RuneScape 3 Wiki and RuneMetrics data, returning it in a structured JSON format for easy consumption. It benefits developers and AI agents seeking RS3 data. Loadstone CLI Skill 是一个用于操作 Loadstone CLI 的工具，提供 RS3 Wiki 数据和 RuneMetrics 信息的结构化 JSON 输出 Loadstone CLI Skill は、Loadstone CLI を操作して RS3 Wiki データと RuneMetrics 情報を取得し、構造化 JSON 出力を提供する Loadstone CLI 스킬은 Loadstone CLI를操作하여 RS3 Wiki 데이터와 RuneMetrics 정보를 구조화된 JSON 출력으로 제공하는 도구입니다 loadstone-cli es una herramienta de línea de comandos para obtener datos de la Wiki de RuneScape 3 y RuneMetrics. Proporciona salida JSON estructurada para consumo de LLM loadstone-cli est un outil en ligne de commande pour récupérer des données à partir de la Wiki de RuneScape 3 et de RuneMetrics. Il fournit une sortie JSON structurée pour la consommation de LLM loadstone-cli ist ein Kommandozeilen-Tool zum Abrufen von Daten aus der RuneScape 3-Wiki und RuneMetrics. Es liefert strukturierte JSON-Ausgaben für den Verzehr von LLM O Loadstone CLI é uma ferramenta para operar a CLI e retornar dados em formato JSON Loadstone CLI - это инструмент для работы с CLI и возврата данных в формате JSON أداة Loadstone CLI هي أداة لتشغيل واجهة سطر الأوامر و إرجاع البيانات بформات JSON how to use loadstone-cli loadstone-cli setup guide RuneScape 3 Wiki data retrieval RuneMetrics profile info loadstone-cli alternative loadstone-cli vs other CLI tools install loadstone-cli loadstone-cli JSON output RuneScape data processing Loadstone CLI RS3 Wiki RuneMetrics AI 工具 结构化 JSON 输出 Loadstone CLI 命令 用户友好的数据格式 Operates the Loadstone CLI to retrieve RS3 Wiki data, including pages, categories, and tables Fetches RuneMetrics profile and quest information Provides structured JSON output for LLM consumption Supports the use of --json for preferred output format Enables users to run and interpret Loadstone CLI commands loadstone-cli is a command-line interface skill for retrieving and processing RuneScape 3 Wiki and RuneMetrics data in a user-friendly format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('timothyfroehlich/PinPoint-SkillEval/Writing Skills', 'community', 'timothyfroehlich', 'PinPoint-SkillEval', 'timothyfroehlich/PinPoint-SkillEval', 'Writing Skills', 0, 0, 59, '2026-03-08T01:57:15.603Z', '2026-03-08T02:13:08.325Z', '619d4c8603e6e54afa478ae8bd485658986a81dcbc1e927fe9e8cfa9ce666416', '{"id":"timothyfroehlich/PinPoint-SkillEval/Writing Skills","name":"Writing Skills","description":{"en":"Writing Skills applies Test-Driven Development to process documentation, allowing developers to edit skills directly in their project''s codebase. This skill benefits developers by providing a structured approach to documentation.","zh":"Writing Skills 是一种基于测试驱动的文档开发技术，通过测试案例和压力场景来开发和完善文档","ja":"Writing Skills は、テスト駆動開発によって文書化を開発し、改善する技術です","ko":"Writing Skills는 테스트 주도 개발을 통해 문서화를 개발하고 개선하는 기술입니다","es":"Writing Skills es un enfoque de desarrollo dirigido por pruebas aplicado a la documentación de procesos, almacenado en `.gemini/skills/`","fr":"Les compétences d''écriture sont une approche de développement dirigée par des tests appliquée à la documentation de processus, stockée dans `.gemini/skills/`","de":"Writing Skills ist ein testgetriebener Ansatz für die Prozessdokumentation, der in `.gemini/skills/` gespeichert wird","pt":"As habilidades de escrita aplicam o Test-Driven Development à documentação de processos, armazenadas em `.gemini/skills/` ou `~/.gemini/skills/`","ru":"Навыки написания применяют Test-Driven Development к документации процессов, хранящейся в `.gemini/skills/` или `~/.gemini/skills/`","ar":"المهارات الكتابية تطبق التطوير القائم على الاختبار على توثيق العمليات، المخزنة في `.gemini/skills/` أو `~/.gemini/skills/`"},"seo":{"title":{"en":"Writing Skills: Test-Driven Documentation Setup Guide | A...","zh":"Writing Skills 设置指南 - 基于测试驱动的文档开发","ja":"Writing Skills セットアップガイド - テスト駆動開発による文書化","ko":"Writing Skills 설정 가이드 - 테스트 주도 개발을 통한 문서화","es":"Guía de configuración de Writing Skills para agentes de i...","fr":"Guide de mise en place des compétences d''écriture pour le...","de":"Einrichtungsleitfaden für Writing Skills in KI-Agenten","pt":"Guia de Configuração de Habilidades de Escrita para Ferra...","ru":"Настройка Навыков Написания для ИИ Агентов","ar":"دليل إعداد مهارات الكتابة لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient documentation with Writing Skills. Learn how to apply Test-Driven Development to your process documentation and streamline your workflow today!","zh":"了解 Writing Skills 的核心原则和工作流程，掌握测试驱动的文档开发技术","ja":"Writing Skills の中核となる原則とワークフローを学び、テスト駆動の文書化技術をマスター","ko":"Writing Skills의 핵심 원칙과 워크플로우를 익히고 테스트 주도 문서화 기술을.master","es":"Aprende a configurar Writing Skills para agentes de inteligencia artificial y mejora la documentación de tus proyectos","fr":"Découvrez comment configurer les compétences d''écriture pour les outils d''intelligence artificielle et améliorez la documentation de vos projets","de":"Erfahren Sie, wie Sie Writing Skills für KI-Agenten einrichten und die Dokumentation Ihrer Projekte verbessern","pt":"Aprenda a configurar habilidades de escrita para ferramentas de IA com Test-Driven Development e documentação de processos","ru":"Узнайте, как настроить навыки написания для ИИ агентов с помощью Test-Driven Development и документации процессов","ar":"تعلم كيفية إعداد مهارات الكتابة لأدوات الذكاء الاصطناعي باستخدام التطوير القائم على الاختبار وتوثيق العمليات"},"definition":{"en":"Writing Skills is a Test-Driven Development approach to process documentation, stored in .gemini/skills/ or ~/.gemini/skills/, enabling developers to write and refine skills through test cases and refactoring.","zh":"Writing Skills 是一种将测试驱动开发应用于文档开发的技术","ja":"Writing Skills は、テスト駆動開発を文書化に適用した技術です","ko":"Writing Skills는 테스트 주도 개발을 문서화에 적용한 기술입니다","es":"Writing Skills es una técnica de desarrollo que aplica pruebas dirigidas a la documentación de procesos","fr":"Les compétences d''écriture sont une technique de développement qui applique des tests dirigés à la documentation de processus","de":"Writing Skills ist eine Entwicklungstechnik, die Test-Driven Development auf die Prozessdokumentation anwendet","pt":"Habilidades de escrita são capacidades de documentação de processos baseadas em Test-Driven Development","ru":"Навыки написания - это способности документации процессов на основе Test-Driven Development","ar":"المهارات الكتابية هي قدرات توثيق العمليات القائمة على التطوير القائم على الاختبار"},"features":{"en":["Applies Test-Driven Development to process documentation","Stores skills in .gemini/skills/ (project-local) or ~/.gemini/skills/ (user-global)","Allows editing skills directly in the project''s codebase","Supports writing test cases with subagents and pressure scenarios","Enables refactoring to close loopholes and improve documentation"],"zh":["基于测试驱动的文档开发","使用压力场景和子代理进行测试","支持项目本地和用户全局的技能存储","编辑技能直接在项目代码库中","支持测试案例的开发和完善"],"ja":["テスト駆動開発による文書化","プレッシャーシナリオとサブエージェントを使用したテスト","プロジェクトローカルとユーザーグローバルのスキルストレージをサポート","スキルを直接プロジェクトコードベースで編集","テストケースの開発と改善をサポート"],"ko":["테스트 주도 개발을 통한 문서화","압력 시나리오와 서브 에이전트를 사용한 테스트","프로젝트 로컬과 사용자 全球의 스킬 저장을 지원","스킬을 직접 프로젝트 코드베이스에서 편집","테스트 케이스의 개발과 개선을 지원"],"es":["Almacenamiento de habilidades en `.gemini/skills/`","Edición directa de habilidades en el código del proyecto","Creación de casos de prueba con subagentes","Refactorización para cerrar brechas en la documentación"],"fr":["Stockage des compétences dans `.gemini/skills/`","Édition directe des compétences dans le code du projet","Création de cas de test avec des sous-agents","Réfactorisation pour fermer les lacunes dans la documentation"],"de":["Speicherung von Fähigkeiten in `.gemini/skills/`","Direkte Bearbeitung von Fähigkeiten im Projektcode","Erstellung von Testfällen mit Subagenten","Refactorierung, um Lücken in der Dokumentation zu schließen"],"pt":["Armazenamento de habilidades em `.gemini/skills/` ou `~/.gemini/skills/`","Desenvolvimento de testes e casos de pressão com subagentes","Edição direta de habilidades no código da projeto","Refinamento de habilidades para fechar lacunas","Integração com Test-Driven Development"],"ru":["Хранение навыков в `.gemini/skills/` или `~/.gemini/skills/`","Разработка тестов и сценариев давления с субагентами","Прямое редактирование навыков в коде проекта","Уточнение навыков для закрытия лазеек","Интеграция с Test-Driven Development"],"ar":["تخزين المهارات في `.gemini/skills/` أو `~/.gemini/skills/`","تطوير الاختبارات وحالات الضغط مع الوكلاء الفرعيين","التحرير المباشر للمهارات في код المشروع","تحسين المهارات لإغلاق الثغرات","التكامل مع التطوير القائم على الاختبار"]},"keywords":{"en":["how to use Writing Skills","Writing Skills setup guide","Test-Driven Development for documentation","Writing Skills vs traditional documentation methods","what is Writing Skills","Writing Skills install","Writing Skills alternative","Writing Skills for AI agents","Writing Skills best practices"],"zh":["Writing Skills","测试驱动开发","文档开发","AIエージェント","压力场景","子代理","项目本地","用户全局"],"ja":["Writing Skills","テスト駆動開発","文書化","AIエージェント","プレッシャーシナリオ","サブエージェント","プロジェクトローカル","ユーザーグローバル"],"ko":["Writing Skills","테스트 주도 개발","문서화","AI 에이전트","압력 시나리오","서브 에이전트","프로젝트 로컬","사용자 全球"],"es":["Writing Skills","agentes de inteligencia artificial","desarrollo dirigido por pruebas","documentación de procesos","Gemini","subagentes","refactorización"],"fr":["compétences d''écriture","outils d''intelligence artificielle","développement dirigé par des tests","documentation de processus","Gemini","sous-agents","réfactorisation"],"de":["Writing Skills","KI-Agenten","Test-Driven Development","Prozessdokumentation","Gemini","Subagenten","Refactorierung"],"pt":["habilidades de escrita","ferramentas de IA","Test-Driven Development","documentação de processos","desenvolvimento de software","IA","_machine learning_","processos de escrita","guias de configuração"],"ru":["навыки написания","ИИ агенты","Test-Driven Development","документация процессов","разработка программного обеспечения","ИИ","машиное обучение","процессы написания","руководства по настройке"],"ar":["المهارات الكتابية","أدوات الذكاء الاصطناعي","التطوير القائم على الاختبار","توثيق العمليات","تطوير البرمجيات","الذكاء الاصطناعي","التعلم الآلي","عمليات الكتابة","دلائل الإعداد"]}},"owner":"timothyfroehlich","repo":"PinPoint-SkillEval","repoPath":"timothyfroehlich/PinPoint-SkillEval","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.603Z","topics":[],"category":"community","skillMd":{"name":"Writing Skills","description":"TDD for process documentation - test with subagents before writing, iterate until bulletproof","version":"1.0.0","bodyPreview":"# Writing Skills\n\n## Overview\n\n**Writing skills IS Test-Driven Development applied to process documentation.**\n\n**Skills are stored in `.gemini/skills/` (project-local) or `~/.gemini/skills/` (user-global).** You edit skills directly in the project''s codebase.\n\nYou write test cases (pressure scenarios with subagents), watch them fail (baseline behavior), write the skill (documentation), watch tests pass (agents comply), and refactor (close loopholes).\n\n**Core principle:** If you didn''t watch an","body":"# Writing Skills\n\n## Overview\n\n**Writing skills IS Test-Driven Development applied to process documentation.**\n\n**Skills are stored in `.gemini/skills/` (project-local) or `~/.gemini/skills/` (user-global).** You edit skills directly in the project''s codebase.\n\nYou write test cases (pressure scenarios with subagents), watch them fail (baseline behavior), write the skill (documentation), watch tests pass (agents comply), and refactor (close loopholes).\n\n**Core principle:** If you didn''t watch an agent fail without the skill, you don''t know if the skill teaches the right thing.\n\nSee `skills/testing/test-driven-development` for the fundamental RED-GREEN-REFACTOR cycle. This skill adapts TDD to documentation.\n\n## What is a Skill?\n\nA **skill** is a reference guide for proven techniques, patterns, or tools. Skills help future Agent instances find and apply effective approaches.\n\n**Skills are:** Reusable techniques, patterns, tools, reference guides\n\n**Skills are NOT:** Narratives about how you solved a problem once\n\n## When to Create a Skill\n\n**Create when:**\n\n- Technique wasn''t intuitively obvious to you\n- You''d reference this again across projects\n- Pattern applies broadly (not project-specific)\n- Others would benefit\n\n**Don''t create for:**\n\n- One-off solutions\n- Standard practices well-documented elsewhere\n- Project-specific conventions (put in `GEMINI.md`)\n\n## When to Use This Skill\n\n**Situations:**\n\n- When you discover a technique, pattern, or tool worth documenting for reuse.\n- When editing existing skills.\n- When asked to modify skill documentation.\n- When you''ve written a skill and need to verify it works before deploying.\n\n## TDD Mapping for Skills\n\n| TDD Concept             | Skill Creation                                   |\n| ----------------------- | ------------------------------------------------ |\n| **Test case**           | Pressure scenario with subagent                  |\n| **Production code**     | Skill document (SKILL.md)                        |\n| **Test fails (RED)**    | Agent violates rule without skill (baseline)     |\n| **Test passes (GREEN)** | Agent complies with skill present                |\n| **Refactor**            | Close loopholes while maintaining compliance     |\n| **Write test first**    | Run baseline scenario BEFORE writing skill       |\n| **Watch it fail**       | Document exact rationalizations agent uses       |\n| **Minimal code**        | Write skill addressing those specific violations |\n| **Watch it pass**       | Verify agent now complies                        |\n| **Refactor cycle**      | Find new rationalizations → plug → re-verify     |\n\nThe entire skill creation process follows RED-GREEN-REFACTOR.\n\n## Skill Types\n\n### Technique\n\nConcrete method with steps to follow (condition-based-waiting, root-cause-tracing)\n\n### Pattern\n\nWay of thinking about problems (flatten-with-flags, test-invariants)\n\n### Reference\n\nAPI docs, syntax guides, tool documentation\n\n## Directory Structure\n\n**All skills are stored in `.gemini/skills/`:**\n\n```\n.gemini/skills/\n  skill-name/\n    SKILL.md              # Main reference (required)\n    supporting-file.*     # Only if needed\n```\n\n**Flat namespace** - all skills in one searchable location\n\n**Separate files for:**\n\n1. **Heavy reference** (100+ lines) - API docs, comprehensive syntax\n2. **Reusable tools** - Scripts, utilities, templates\n\n**Keep inline:**\n\n- Principles and concepts\n- Code patterns (< 50 lines)\n- Everything else\n\n## SKILL.md Structure\n\n```markdown\n---\nname: Human-Readable Name\ndescription: One-line summary of what this does (ASO-critical)\nversion: 1.0.0\n---\n\n# Skill Name\n\n## Overview\n\nWhat is this? Core principle in 1-2 sentences.\n\n## When to Use\n\n[Small inline flowchart IF decision non-obvious]\n\nBullet list with SYMPTOMS and use cases\nWhen NOT to use\n\n## Core Pattern (for techniques/patterns)\n\nBefore/after code comparison\n\n## Quick Reference\n\nTable or bullets for scanning common operations\n\n## Implementation\n\nInline code for simple patterns\nLink to file for heavy reference or reusable tools\n\n## Common Mistakes\n\nWhat goes wrong + fixes\n\n## Real-World Impact (optional)\n\nConcrete results\n```\n\n## Agent Search Optimization (ASO)\n\n**Critical for discovery:** Future Agents need to FIND your skill.\n\n### 1. Rich Description\n\nInclude SYMPTOMS and key keywords in the `description` field, as this is the primary discovery mechanism:\n\n```yaml\n# ❌ BAD: Too abstract\ndescription: For async testing\n\n# ✅ GOOD: Symptoms and context\ndescription: Fix flaky async tests using condition-based waiting. Handles timeouts, race conditions, and CI failures.\n```\n\n### 2. Keyword Coverage\n\nUse words an Agent would search for:\n\n- Error messages: \"Hook timed out\", \"ENOTEMPTY\", \"race condition\"\n- Symptoms: \"flaky\", \"hanging\", \"zombie\", \"pollution\"\n- Synonyms: \"timeout/hang/freeze\", \"cleanup/teardown/afterEach\"\n- Tools: Actual commands, library names, file types\n\n### 3. Descriptive Naming\n\n**Use active voice, verb-first:**\n\n- ✅ `creating-skills` not `skill-creation`\n- ✅ `testing-skills-with-subagents` not `subagent-skill-testing`\n\n### 4. Token Efficiency (Critical)\n\n**Problem:** Skills are loaded into the Agent''s context. Every token counts.\n\n**Target word counts:**\n\n- Getting-started workflows: <150 words each\n- Other skills: <500 words (be concise)\n\n**Techniques:**\n\n**Move details to tool help:**\n\n```bash\n# ✅ GOOD: Reference --help\nnpm run test -- --help\n```\n\n**Use cross-references:**\n\n```markdown\n# ✅ GOOD: Reference other skill\n\nAlways use subagents. See `skills/getting-started` for workflow.\n```\n\n**Eliminate redundancy:**\n\n- Don''t repeat what''s in cross-referenced skills\n- Don''t explain what''s obvious from context\n\n**Name by what you DO or core insight:**\n\n- ✅ `condition-based-waiting` > `async-test-helpers`\n- ✅ `using-skills` not `skill-usage`\n- ✅ `flatten-with-flags` > `data-structure-refactoring`\n- ✅ `root-cause-tracing` > `debugging-techniques`\n\n**Gerunds (-ing) work well for processes:**\n\n- `creating-skills`, `testing-skills`, `debugging-with-logs`\n\n### 4. Content Repetition\n\nMention key concepts in the description, overview, and section headers to increase Grep hits.\n\n### 5. Cross-Referencing Other Skills\n\nUse path format relative to the skills root:\n\n- ✅ Good: `skills/testing/test-driven-development`\n\n## Flowchart Usage\n\n```dot\ndigraph when_flowchart {\n    \"Need to show information?\" [shape=diamond];\n    \"Decision where I might go wrong?\" [shape=diamond];\n    \"Use markdown\" [shape=box];\n    \"Small inline flowchart\" [shape=box];\n\n    \"Need to show information?\" -> \"Decision where I might go wrong?\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Small inline flowchart\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Use markdown\" [label=\"no\"];\n}\n```\n\n**Use flowcharts ONLY for:**\n\n- Non-obvious decision points\n- Process loops where you might stop too early\n\nSee `docs/ui-patterns/graphviz-conventions.dot` for graphviz style rules.\n\n## Code Examples\n\n**One excellent example beats many mediocre ones.**\n\n**Good example:**\n\n- Complete and runnable\n- Well-commented explaining WHY\n- From real scenario\n- Shows pattern clearly\n\n## The Iron Law (Same as TDD)\n\n```\nNO SKILL WITHOUT A FAILING TEST FIRST\n```\n\nThis applies to NEW skills AND EDITS to existing skills.\n\nWrite skill before testing? Delete it. Start over.\nEdit skill without testing? Same violation.\n\n**No exceptions:**\n\n- Not for \"simple additions\"\n- Not for \"just adding a section\"\n- Not for \"documentation updates\"\n- Delete means delete\n\nSee `skills/testing/test-driven-development` for why this matters.\n\n## Testing All Skill Types\n\n### Discipline-Enforcing Skills\n\n**Test with:** Pressure scenarios (time + sunk cost + exhaustion). Identify rationalizations and add counters.\n\n### Technique Skills\n\n**Test with:** Application scenarios. Can the Agent apply the technique to new scenarios?\n\n### Pattern Skills\n\n**Test with:** Recognition scenarios. Does the Agent know when pattern applies?\n\n### Reference Skills\n\n**Test with:** Retrieval scenarios. Can the Agent find and use the right info?\n\n## Common Rationalizations for Skipping Testing\n\n| Excuse                     | Reality                                        |\n| -------------------------- | ---------------------------------------------- |\n| \"Skill is obviously clear\" | Clear to you ≠ clear to other agents. Test it. |\n| \"Testing is overkill\"      | Untested skills have issues. Always.           |\n| \"I''m confident it''s good\"  | Overconfidence guarantees issues. Test anyway. |\n\n## Bulletproofing Skills Against Rationalization\n\n### Close Every Loophole Explicitly\n\nForbid specific workarounds:\n\n```markdown\nWrite code before test? Delete it. Start over.\n**No exceptions:** Don''t keep it as \"reference\". Delete means delete.\n```\n\n### Build Rationalization Table\n\nCapture excuses from baseline testing and provide counters.\n\n### Create Red Flags List\n\n```markdown\n## Red Flags - STOP and Start Over\n\n- Code before test\n- \"I already manually tested it\"\n- \"It''s about spirit not ritual\"\n```\n\n## RED-GREEN-REFACTOR for Skills\n\n### RED: Write Failing Test (Baseline)\n\nRun scenario with subagent WITHOUT the skill. Document baseline behavior and rationalizations verbatim.\n\n### GREEN: Write Minimal Skill\n\nWrite skill addressing those specific failures. Verify Agent now complies.\n\n### REFACTOR: Close Loopholes\n\nAdd explicit counters for any new rationalizations found during testing.\n\n## STOP: Before Moving to Next Skill\n\n**After writing ANY skill, you MUST STOP and complete the verification process.**\n\n**Do NOT:**\n\n- Create multiple skills in batch without testing each.\n- Skip testing because \"batching is more efficient\".\n\n## Skill Creation Checklist\n\n- [ ] Create pressure scenarios\n- [ ] Run scenarios WITHOUT skill - document baseline behavior\n- [ ] Name describes what you DO\n- [ ] Frontmatter with rich description (primary discovery)\n- [ ] Address baseline failures\n- [ ] One excellent example\n- [ ] Run scenarios WITH skill - verify compliance\n- [ ] Identify NEW rationalizations and add explicit counters\n- [ ] Re-test until bulletproof\n\n## Discovery Workflow\n\nHow future Agents find your skill:\n\n1. **Encounter problem** (\"tests are flaky\")\n2. **Automatic Discovery** (Agent scans `.gemini/skills/` descriptions)\n3. **Finds SKILL.md** (rich description matches)\n4. **Scans overview** (is this relevant?)\n5. **Reads patterns** (quick reference table)\n\n## The Bottom Line\n\n**Creating skills IS TDD for process documentation.**\n\nSame Iron Law: No skill without failing test first.\nSame cycle: RED (baseline) → GREEN (write skill) → REFACTOR (close loopholes).\nSame benefits: Better quality, fewer surprises, bulletproof results.\n"},"lastSynced":"2026-03-08T02:13:08.325Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing structured documentation through Test-Driven Development","zh":"非常适合需要通过测试驱动开发进行结构化文档记录的开发者代理","ja":"テスト駆動開発を通じて構造化されたドキュメントが必要な開発者エージェントに最適","ko":"테스트 주도 개발을 통해 구조화된 문서가 필요한 개발자 에이전트에게 적합","es":"Perfecto para Agentes de Desarrollador que necesitan documentación estructurada a través del Desarrollo Dirigido por Pruebas","fr":"Parfait pour les Agents de Développeur ayant besoin d''une documentation structurée via le Développement Piloté par les Tests","de":"Perfekt für Entwickler-Agenten, die eine strukturierte Dokumentation durch Test-Driven Development benötigen","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de documentação estruturada por meio do Desenvolvimento Dirigido por Testes","ru":"Идеально для агентов-разработчиков, которым необходима структурированная документация через Разработку, управляемую тестами","ar":"مثالي لعميل المطور الذين يحتاجون إلى توثيق منظم من خلال التطوير الموجه بواسطة الاختبار"},"recommendation":{"en":"Empowers agents to edit skills directly in the project''s codebase using Test-Driven Development, providing a structured approach to documentation with pressure scenarios and subagents, and storing skills in .gemini/skills/ or ~/.gemini/skills/ directories","zh":"使代理能够直接在项目的代码库中使用测试驱动开发编辑技能，提供结构化的文档方法，包括压力场景和子代理，并将技能存储在 .gemini/skills/ 或 ~/.gemini/skills/ 目录中","ja":"エージェントがテスト駆動開発を使用してプロジェクトのコードベースでスキルを直接編集できるようにし、圧力シナリオやサブエージェントを含む構造化されたドキュメントへのアプローチを提供し、スキルを .gemini/skills/ または ~/.gemini/skills/ ディレクトリに保存する","ko":"에이전트가 테스트 주도 개발을 사용하여 프로젝트의 코드베이스에서 직접 스킬을 편집할 수 있도록 하여, 압력 시나리오와 서브 에이전트를 포함한 구조화된 문서화 방법을 제공하고, 스킬을 .gemini/skills/ 또는 ~/.gemini/skills/ 디렉토리에 저장","es":"Habilita a los agentes a editar habilidades directamente en el código base del proyecto utilizando Desarrollo Dirigido por Pruebas, proporcionando un enfoque estructurado para la documentación con escenarios de presión y subagentes, y almacenando habilidades en directorios .gemini/habilidades/ o ~/.gemini/habilidades/","fr":"Permet aux agents d''éditer des compétences directement dans le code base du projet en utilisant le Développement Piloté par les Tests, fournissant une approche structurée de la documentation avec des scénarios de pression et des sous-agents, et stockant les compétences dans les répertoires .gemini/compétences/ ou ~/.gemini/compétences/","de":"Ermächtigt Agenten, Fähigkeiten direkt im Codebase des Projekts zu bearbeiten, indem sie Test-Driven Development verwenden, und bietet einen strukturierten Ansatz für die Dokumentation mit Druckszenarien und Subagenten, und speichert Fähigkeiten in .gemini/Fähigkeiten/ oder ~/.gemini/Fähigkeiten/-Verzeichnissen","pt":"Habilita os agentes a editar habilidades diretamente na base de código do projeto usando Desenvolvimento Dirigido por Testes, fornecendo uma abordagem estruturada para documentação com cenários de pressão e subagentes, e armazenando habilidades nos diretórios .gemini/skills/ ou ~/.gemini/skills/","ru":"Наделяет агентов возможностью редактировать навыки напрямую в кодовой базе проекта, используя Разработку, управляемую тестами, обеспечивая структурированный подход к документации с помощью сценариев давления и субагентов, и хранение навыков в директориях .gemini/skills/ или ~/.gemini/skills/","ar":"يتمكن العميل من تحرير المهارات مباشرة في قاعدة رمز المشروع باستخدام التطوير الموجه بواسطة الاختبار، ويوفر نهجًا منظمًا للتدوين مع سيناريوهات الضغط والوكيلات الفرعية، وتخزين المهارات في المجلدات .gemini/skills/ أو ~/.gemini/skills/"},"useCases":{"en":["Automating documentation updates","Generating test cases for skills","Refactoring skills for compliance"],"zh":["自动化文档更新","为技能生成测试用例","重构技能以满足合规要求"],"ja":["ドキュメントの自動更新","スキルのテストケースを生成","スキルのリファクタリングによるコンプライアンス"],"ko":["문서 자동화 업데이트","스킬의 테스트 케이스를 생성","스킬의 리팩토링을 통한 컴플라이언스"],"es":["Automatizar actualizaciones de documentación","Generar casos de prueba para habilidades","Reestructurar habilidades para cumplimiento"],"fr":["Automatiser les mises à jour de la documentation","Générer des cas de test pour les compétences","Réorganiser les compétences pour la conformité"],"de":["Automatisierung von Dokumentenaktualisierungen","Generieren von Testfällen für Fähigkeiten","Umstrukturierung von Fähigkeiten für Compliance"],"pt":["Automatizar atualizações de documentação","Gerar casos de teste para habilidades","Reestruturar habilidades para cumprimento"],"ru":["Автоматизировать обновления документации","Генерировать тестовые случаи для навыков","Перестроить навыки для соблюдения"],"ar":["أتمتة تحديثات الوثائق","توليد الحالات الاختبارية للمهارات","إعادة هيكلة المهارات للامتثال"]},"limitations":{"en":["Requires access to project codebase","Limited to .gemini/skills/ or ~/.gemini/skills/ storage"],"zh":["需要访问项目代码库","仅限于 .gemini/skills/ 或 ~/.gemini/skills/ 存储"],"ja":["プロジェクトのコードベースへのアクセスが必要",".gemini/skills/ または ~/.gemini/skills/ への保存のみ"],"ko":["프로젝트 코드베이스에 대한 액세스가 필요",".gemini/skills/ 또는 ~/.gemini/skills/ 저장소만 제한"],"es":["Requiere acceso al código base del proyecto","Limitado al almacenamiento en .gemini/habilidades/ o ~/.gemini/habilidades/"],"fr":["Requiert un accès au code base du projet","Limité au stockage dans .gemini/compétences/ ou ~/.gemini/compétences/"],"de":["Benötigt Zugriff auf den Codebase des Projekts","Begrenzt auf .gemini/Fähigkeiten/ oder ~/.gemini/Fähigkeiten/-Speicher"],"pt":["Exige acesso à base de código do projeto","Limitado ao armazenamento em .gemini/skills/ ou ~/.gemini/skills/"],"ru":["Требует доступа к кодовой базе проекта","Ограничен хранением в .gemini/skills/ или ~/.gemini/skills/"],"ar":["يتطلب الوصول إلى قاعدة رمز المشروع","محدود بتخزين المجلدات .gemini/skills/ أو ~/.gemini/skills/"]},"version":4},"contentHash":"619d4c8603e6e54afa478ae8bd485658986a81dcbc1e927fe9e8cfa9ce666416","qualityScore":59}');
