INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('timothyfroehlich/PinPoint-SkillEval/Writing Skills', 'Writing Skills', 'timothyfroehlich', 'PinPoint-SkillEval', 'community', 'Writing Skills timothyfroehlich PinPoint-SkillEval community Writing Skills applies Test-Driven Development to process documentation, allowing developers to edit skills directly in their project''s codebase. This skill benefits developers by providing a structured approach to documentation. Writing Skills 是一种基于测试驱动的文档开发技术，通过测试案例和压力场景来开发和完善文档 Writing Skills は、テスト駆動開発によって文書化を開発し、改善する技術です Writing Skills는 테스트 주도 개발을 통해 문서화를 개발하고 개선하는 기술입니다 Writing Skills es un enfoque de desarrollo dirigido por pruebas aplicado a la documentación de procesos, almacenado en `.gemini/skills/` Les compétences d''écriture sont une approche de développement dirigée par des tests appliquée à la documentation de processus, stockée dans `.gemini/skills/` Writing Skills ist ein testgetriebener Ansatz für die Prozessdokumentation, der in `.gemini/skills/` gespeichert wird As habilidades de escrita aplicam o Test-Driven Development à documentação de processos, armazenadas em `.gemini/skills/` ou `~/.gemini/skills/` Навыки написания применяют Test-Driven Development к документации процессов, хранящейся в `.gemini/skills/` или `~/.gemini/skills/` المهارات الكتابية تطبق التطوير القائم على الاختبار على توثيق العمليات، المخزنة في `.gemini/skills/` أو `~/.gemini/skills/` how to use Writing Skills Writing Skills setup guide Test-Driven Development for documentation Writing Skills vs traditional documentation methods what is Writing Skills Writing Skills install Writing Skills alternative Writing Skills for AI agents Writing Skills best practices Writing Skills 测试驱动开发 文档开发 AIエージェント 压力场景 子代理 项目本地 用户全局 Applies Test-Driven Development to process documentation Stores skills in .gemini/skills/ (project-local) or ~/.gemini/skills/ (user-global) Allows editing skills directly in the project''s codebase Supports writing test cases with subagents and pressure scenarios Enables refactoring to close loopholes and improve documentation Writing Skills is a Test-Driven Development approach to process documentation, stored in .gemini/skills/ or ~/.gemini/skills/, enabling developers to write and refine skills through test cases and refactoring.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryanmr/vela-skills/vela-rulesets', 'community', 'ryanmr', 'vela-skills', 'ryanmr/vela-skills', 'vela-rulesets', 0, 0, 59, '2026-03-08T01:52:43Z', '2026-03-08T02:18:38.488Z', 'b121fdc8599959097c2ae31ba32193949f96550742619780910ea35f3290ef59', '{"id":"ryanmr/vela-skills/vela-rulesets","name":"vela-rulesets","description":{"en":"vela-rulesets enables developers to control build steps based on specific conditions. It benefits developers by allowing them to customize their build processes.","zh":"Vela rulesets 使您能够控制 Vela 构建过程中步骤的执行，通过使用 compile-time rules 和 runtime rules 来管理构建元数据","ja":"Vela rulesets を使用すると、compile-time rules と runtime rules を使用してビルドメタデータを管理し、Vela ビルドプロセス中的のステップの実行を制御できます","ko":"Vela rulesets를 사용하면 compile-time rules와 runtime rules를 사용하여 빌드 메타데이터를 관리하고 Vela 빌드 프로세스 중의 단계를 제어할 수 있습니다","es":"Vela-rulesets permite controlar los pasos de compilación en función de metadatos como rama, evento y cambios de ruta. Utiliza reglas de compilación y ejecución para personalizar tus flujos de trabajo","fr":"Les vela-rulesets permettent de contrôler les étapes de construction en fonction de métadonnées telles que la branche, l''événement et les modifications de chemin. Utilisez des règles de compilation et d''exécution pour personnaliser vos workflows","de":"Vela-rulesets ermöglicht die Steuerung von Schritten in einem Workflow auf der Grundlage von Metadaten wie Zweig, Ereignis und Pfadänderungen. Verwenden Sie Kompilierungs- und Ausführungsregeln, um Ihre Workflows anzupassen","pt":"O vela-rulesets permite controlar o fluxo de trabalho em um pipeline de build, usando regras de compilação e tempo de execução para gatear a execução de etapas","ru":"Vela-rulesets позволяет контролировать поток работы в конвейере сборки, используя правила компиляции и времени выполнения для ограничения выполнения шагов","ar":"يسمح vela-rulesets بمراقبة سير عمل البناء في أنبوب بناء، باستخدام قواعد مرحلة التجميع والتشغيل لتحديد تنفيذ الخطوات"},"seo":{"title":{"en":"vela-rulesets: Conditional Build Control Setup Guide | AI...","zh":"Vela Rulesets_SETUP GUIDE - AIエージェント","ja":"Vela Rulesets ベストプラクティス - AIエージェント","ko":"Vela Rulesets 설정 가이드 - AI 에이전트","es":"Guía de configuración de vela-rulesets para control de fl...","fr":"Configurer les vela-rulesets pour contrôler les workflows","de":"Einrichtungsleitfaden für vela-rulesets zur Steuerung von...","pt":"Guia de Configuração de vela-rulesets para Controle de Fl...","ru":"ИИ Агенты: Настройка vela-rulesets для Контроля Выполнени...","ar":"إعداد قواعد vela-rulesets لمراقبة سير عمل البناء"},"description":{"en":"Discover how to optimize your Vela builds with vela-rulesets. Learn to gate execution on branch, event, and path changes - get started now!","zh":"了解 Vela rulesets 的技术细节，掌握 compile-time rules 和 runtime rules 的区别，优化您的 Vela 构建过程","ja":"Vela rulesets の技術的詳細を学び、compile-time rules と runtime rules の違いを理解して、Vela ビルドプロセスを最適化する","ko":"Vela rulesets의 기술적 세부 사항을 배우고 compile-time rules와 runtime rules의 차이를 이해하여 Vela 빌드 프로세스를 최적화하십시오","es":"Aprende a utilizar vela-rulesets para controlar los pasos de compilación en función de metadatos como rama, evento y cambios de ruta","fr":"Découvrez comment utiliser les vela-rulesets pour contrôler les étapes de construction en fonction de métadonnées telles que la branche, l''événement et les m...","de":"Erfahren Sie, wie Sie vela-rulesets verwenden können, um die Schritte in einem Workflow auf der Grundlage von Metadaten wie Zweig, Ereignis und Pfadänderunge...","pt":"Aprenda a usar regras de compilação e tempo de execução para controlar o fluxo de trabalho em vela-rulesets. Descubra como otimizar seus pipelines com essas ...","ru":"Узнайте, как использовать правила компиляции и времени выполнения для контроля потока работы в vela-rulesets. Откройте для себя, как оптимизировать свои конв...","ar":"تعلم كيفية استخدام القواعد الخاصة بمرحلة التجميع والتشغيل لمراقبة سير عمل البناء في vela-rulesets. اكتشف كيفية تحسين أنابيبك باستخدام هذه النصائح"},"definition":{"en":"vela-rulesets is a feature that allows developers to use rulesets to control which steps run in a Vela build, based on conditions like branch, event, and path changes.","zh":"Vela rulesets 是一种用于控制 Vela 构建过程中步骤执行的规则系统","ja":"Vela rulesets は、Vela ビルドプロセス中的のステップの実行を制御するためのルールシステムです","ko":"Vela rulesets는 Vela 빌드 프로세스 중의 단계를 제어하기 위한 규칙 시스템입니다","es":"Vela-rulesets es una función que permite controlar los pasos de compilación en función de metadatos","fr":"Les vela-rulesets sont une fonctionnalité qui permet de contrôler les étapes de construction en fonction de métadonnées","de":"Vela-rulesets ist eine Funktion, die die Steuerung von Schritten in einem Workflow auf der Grundlage von Metadaten ermöglicht","pt":"Vela-rulesets é um recurso que permite controlar o fluxo de trabalho em um pipeline de build, usando regras para gatear a execução de etapas","ru":"Vela-rulesets - это функция, которая позволяет контролировать поток работы в конвейере сборки, используя правила для ограничения выполнения шагов","ar":"vela-rulesets هو ميزة تسمح بمراقبة سير عمل البناء في أنبوب بناء، باستخدام قواعد لتحديد تنفيذ الخطوات"},"features":{"en":["Attach a `ruleset:` block to any step to gate execution","Evaluate compile-time rules on the server before pipeline reaches the worker","Remove steps entirely that fail compile-time rules","Supports rules based on branch, event, path, comment, tag, target, repo, and label","Allows for conditional build control based on build metadata"],"zh":["支持 compile-time rules 和 runtime rules","可以根据分支、事件、路径、评论、标签、目标、仓库和标签等元数据控制步骤执行","步骤可以根据规则被移除或执行","支持多种规则类型，包括 branch、event、path、comment、tag、target、repo 和 label"],"ja":["compile-time rules と runtime rules をサポート","ブランチ、イベント、パス、コメント、ラベル、ターゲット、リポジトリ、ラベルなどのメタデータに基づいてステップの実行を制御","ステップはルールに基づいて削除または実行される","様々なルールタイプをサポート、包括 branch、event、path、comment、tag、target、repo、label"],"ko":["compile-time rules와 runtime rules를 지원","분기, 이벤트, 경로, 댓글, 레이블, 대상, 저장소 및 레이블 등의 메타데이터를 기반으로 단계 실행을 제어","단계는 규칙에 따라 제거 또는 실행","다양한 규칙 유형을 지원, 포함 branch, event, path, comment, tag, target, repo, label"],"es":["Reglas de compilación para evaluar metadatos como rama y evento","Reglas de ejecución para controlar los pasos de compilación","Compatibilidad con metadatos como cambios de ruta y etiquetas","Eliminación de pasos que no cumplen con las reglas de compilación","Personalización de flujos de trabajo con reglas de compilación y ejecución"],"fr":["Règles de compilation pour évaluer des métadonnées telles que la branche et l''événement","Règles d''exécution pour contrôler les étapes de construction","Compatibilité avec des métadonnées telles que les modifications de chemin et les libellés","Suppression des étapes qui ne respectent pas les règles de compilation","Personnalisation de workflows avec des règles de compilation et d''exécution"],"de":["Kompilierungsregeln für die Auswertung von Metadaten wie Zweig und Ereignis","Ausführungsregeln für die Steuerung von Schritten in einem Workflow","Unterstützung von Metadaten wie Pfadänderungen und Labels","Entfernung von Schritten, die die Kompilierungsregeln nicht erfüllen","Anpassung von Workflows mit Kompilierungs- und Ausführungsregeln"],"pt":["Regras de compilação para avaliar branches, eventos e caminhos","Regras de tempo de execução para avaliar status e metadados de build","Controle de fluxo de trabalho com base em regras de compilação e tempo de execução","Remoção de etapas que falham nas regras de compilação","Integração com pipelines de build para otimizar o fluxo de trabalho"],"ru":["Правила компиляции для оценки веток, событий и путей","Правила времени выполнения для оценки статуса и метаданных сборки","Контроль потока работы на основе правил компиляции и времени выполнения","Удаление шагов, которые не проходят правила компиляции","Интеграция с конвейерами сборки для оптимизации потока работы"],"ar":["قواعد مرحلة التجميع لتقييم الفروع والأحداث والمسارات","قواعد التشغيل لتقييم الحالة والبيانات الوصفية للبناء","مراقبة سير عمل البناء dựa على قواعد مرحلة التجميع والتشغيل","إزالة الخطوات التي تفشل في قواعد مرحلة التجميع","التكامل مع أنابيب البناء لتحسين سير العمل"]},"keywords":{"en":["how to use vela-rulesets","vela-rulesets setup guide","vela-rulesets vs github actions","what is vela-rulesets","vela-rulesets install","vela-rulesets conditional build control"],"zh":["Vela rulesets","AIエージェント","compile-time rules","runtime rules","Vela 构建过程","步骤执行控制","元数据管理"],"ja":["Vela rulesets","AIエージェント","compile-time rules","runtime rules","Vela ビルドプロセス","ステップの実行制御","メタデータ管理"],"ko":["Vela rulesets","AI 에이전트","compile-time rules","runtime rules","Vela 빌드 프로세스","단계 실행 제어","메타데이터 관리"],"es":["vela-rulesets","control de flujos de trabajo","reglas de compilación","reglas de ejecución","metadatos de compilación","personalización de workflows","herramientas de automatización de workflows","integración de vela-rulesets con herramientas de desarrollo"],"fr":["vela-rulesets","contrôle de workflows","règles de compilation","règles d''exécution","métadonnées de construction","personnalisation de workflows","outils d''automatisation de workflows","intégration de vela-rulesets avec des outils de développement"],"de":["vela-rulesets","Steuerung von Workflows","Kompilierungsregeln","Ausführungsregeln","Metadaten von Workflows","Anpassung von Workflows","Werkzeuge für die Automatisierung von Workflows","Integration von vela-rulesets mit Entwicklungstools"],"pt":["vela-rulesets","regras de compilação","regras de tempo de execução","controle de fluxo de trabalho","pipeline de build","otimização de fluxo de trabalho","desenvolvimento de software","ferramentas de build"],"ru":["vela-rulesets","правила компиляции","правила времени выполнения","контроль потока работы","конвейер сборки","оптимизация потока работы","разработка программного обеспечения","инструменты сборки"],"ar":["vela-rulesets","قواعد مرحلة التجميع","قواعد التشغيل","مراقبة سير عمل البناء","أنبوب بناء","تحسين سير العمل","تطوير البرمجيات","أدوات البناء"]}},"owner":"ryanmr","repo":"vela-skills","repoPath":"ryanmr/vela-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:52:43Z","topics":[],"category":"community","skillMd":{"name":"vela-rulesets","description":"Conditional step execution in Vela: rulesets, if/unless syntax, event scoping (push, pull_request:opened, tag, deployment), branch/path filtering, status rules, and the continue key.","version":"1.0","bodyPreview":"## Overview\n\nUse rulesets to control which steps run in a Vela build. Attach a `ruleset:` block to any step to gate execution on branch, event, path changes, status, and other build metadata.\n\nThere are two categories of rules, and understanding the difference is critical:\n\n- **Compile-time rules** (`branch`, `event`, `path`, `comment`, `tag`, `target`, `repo`, `label`): Evaluated on the server before the pipeline reaches the worker. Steps that fail compile-time rules are **removed entirely** fr","body":"## Overview\n\nUse rulesets to control which steps run in a Vela build. Attach a `ruleset:` block to any step to gate execution on branch, event, path changes, status, and other build metadata.\n\nThere are two categories of rules, and understanding the difference is critical:\n\n- **Compile-time rules** (`branch`, `event`, `path`, `comment`, `tag`, `target`, `repo`, `label`): Evaluated on the server before the pipeline reaches the worker. Steps that fail compile-time rules are **removed entirely** from the pipeline.\n- **Runtime rules** (`status`): Evaluated during execution on the worker. The step remains in the pipeline but may be skipped based on the build''s current status.\n\n## Rule Types\n\n### Compile-Time Rules\n\n| Rule       | Description                                  | Example Values                    |\n|------------|----------------------------------------------|-----------------------------------|\n| `branch`   | Branch name                                  | `main`, `release/*`              |\n| `event`    | Webhook event (with optional action)         | `push`, `pull_request:opened`    |\n| `path`     | Files changed in the commit                  | `src/**`, `*.go`, `README.md`    |\n| `tag`      | Git tag reference                            | `v1.*`, `release-*`             |\n| `target`   | Deployment or schedule target                | `production`, `staging`          |\n| `comment`  | PR comment body                              | `\"run build\"`                    |\n| `repo`     | Repository name                              | `myorg/myrepo`, `myorg/*`       |\n| `label`    | PR label                                     | `enhancement`, `bug`            |\n| `instance` | FQDN of the Vela server                      | `https://vela.example.com`      |\n\n### Runtime Rules\n\n| Rule     | Description                | Example Values          |\n|----------|----------------------------|-------------------------|\n| `status` | Current build status       | `success`, `failure`   |\n\n### Eval Rules\n\nThe `eval` key uses [expr](https://expr-lang.org/) expressions for complex conditions:\n\n```yaml\nruleset:\n  eval: \"VELA_BUILD_AUTHOR == ''Octocat''\"\n```\n\nEval can be combined with other rules -- all must pass for the step to run.\n\n## Operators and Matchers\n\n### Operator: `and` vs `or`\n\nBy default, all rules within a ruleset use **`and`** -- every rule must match:\n\n```yaml\nruleset:\n  branch: main\n  event: push\n  # Step runs only on push events to main\n```\n\nSwitch to `or` to run when **any** rule matches:\n\n```yaml\nruleset:\n  operator: or\n  branch: main\n  event: tag\n  # Step runs on any push to main OR any tag event\n```\n\n### Matcher: `filepath` vs `regexp`\n\nThe default matcher is `filepath` (glob-style). Switch to `regexp` for regex patterns:\n\n```yaml\nruleset:\n  matcher: regexp\n  branch: \"release-\\\\d+\"\n  # Matches release-1, release-42, etc.\n```\n\n## if / unless Syntax\n\nFor explicit control, use `if:` (run when all match) or `unless:` (skip when any match):\n\n```yaml\n# Run only on push to main\nruleset:\n  if:\n    branch: main\n    event: push\n```\n\n```yaml\n# Skip on pushes to main\nruleset:\n  unless:\n    branch: main\n    event: push\n```\n\nThe `if:`/`unless:` syntax is equivalent to the shorthand top-level rules but makes intent clearer. Use either style, but do not mix them in the same ruleset -- the compiler cannot resolve the ambiguity when both forms are present.\n\n## Event Scoping\n\nEvents support action scoping with `event:action` syntax:\n\n| Event          | Available Actions                                       |\n|----------------|---------------------------------------------------------|\n| `push`         | (no actions)                                            |\n| `pull_request` | `opened`, `synchronize`, `reopened`, `edited`, `labeled`, `unlabeled` |\n| `comment`      | `created`, `edited`                                     |\n| `deployment`   | `created`                                               |\n| `tag`          | (no actions)                                            |\n\nDefault expansions when no action is specified:\n\n- `pull_request` = `pull_request:opened` + `pull_request:synchronize` + `pull_request:reopened`\n- `comment` = `comment:created` + `comment:edited`\n- `deployment` = `deployment:created`\n\nUse wildcard for all actions: `pull_request*`\n\n```yaml\nruleset:\n  event: pull_request*  # all PR actions including edited, labeled, unlabeled\n```\n\n## The `continue` Key\n\nBy default, if a step fails, the entire build fails. Set `continue: true` to allow the build to continue past a failed step:\n\n```yaml\nsteps:\n  - name: lint\n    image: golangci/golangci-lint:v1-alpine\n    ruleset:\n      continue: true\n    commands:\n      - golangci-lint run\n```\n\nThis is useful for non-blocking checks like linting or optional notifications.\n\n## Compile-Time Pruning in Stages\n\nWhen using stages, compile-time rules can cause entire stages to be pruned if all steps within them are removed. \"Pruning\" means the stage is deleted from the compiled pipeline entirely -- it never reaches the worker and disappears from the `needs:` dependency graph, which can unblock stages that were waiting on it.\n\nSee the vela-stages skill for detailed examples of this behavior.\n\n## Examples\n\n### Example: Standard Branch + Event Gating\n\n```yaml\nsteps:\n  - name: test\n    image: golang:1.23-alpine\n    commands:\n      - go test ./...\n\n  - name: deploy\n    image: myorg/deployer:latest\n    ruleset:\n      event: push\n      branch: main\n    commands:\n      - ./deploy.sh\n```\n\n### Example: Path-Based Execution\n\n```yaml\nsteps:\n  - name: backend tests\n    image: golang:1.23-alpine\n    ruleset:\n      path: [\"backend/**\", \"go.mod\", \"go.sum\"]\n    commands:\n      - go test ./...\n\n  - name: frontend tests\n    image: node:22-alpine\n    ruleset:\n      path: [\"frontend/**\", \"package.json\"]\n    commands:\n      - npm test\n```\n\n### Example: Failure Notification\n\n```yaml\nsteps:\n  - name: test\n    image: golang:1.23-alpine\n    commands:\n      - go test ./...\n\n  - name: notify on failure\n    image: target/vela-slack:latest\n    ruleset:\n      status: failure\n      continue: true\n    parameters:\n      text: \"Build failed for ${VELA_REPO_FULL_NAME}\"\n```\n\n### Example: PR Label Gating\n\n```yaml\nsteps:\n  - name: deploy preview\n    image: myorg/deployer:latest\n    ruleset:\n      event: [\"pull_request:labeled\"]\n      label: [\"deploy-preview\"]\n    commands:\n      - ./deploy-preview.sh\n```\n\n### Example: Eval with Expr\n\n```yaml\nsteps:\n  - name: admin-only\n    image: alpine:3\n    ruleset:\n      eval: \"VELA_BUILD_AUTHOR == ''admin-user''\"\n    commands:\n      - echo \"running admin task\"\n\n  - name: prefix-match\n    image: alpine:3\n    ruleset:\n      eval: \"hasPrefix(VELA_BUILD_BRANCH, ''release/'')\"\n    commands:\n      - echo \"release branch detected\"\n```\n\n## Pitfalls\n\n- The `status` rule is evaluated at runtime on the worker, which means it survives compile-time pruning on its own. However, if a step also has compile-time rules (like `branch` or `event`) that do not match, the step is removed from the pipeline entirely before the worker ever sees it -- and the `status` rule never gets a chance to run. In stages, this can cascade: if all steps in a stage are pruned, the entire stage disappears from the dependency graph.\n- Plain `pull_request` expands to only three actions: `opened`, `synchronize`, and `reopened`. Actions like `edited`, `labeled`, and `unlabeled` are excluded. If you need a step to respond to all PR activity, use `pull_request*` with the wildcard to capture every action type.\n- The `path` rule compares against the list of changed files included in the webhook payload. Only `push` and `pull_request` events include this file change data. For other event types (like `tag` or `deployment`), the changed file list is empty, so `path` rules will never match.\n- The top-level rule syntax (e.g., `ruleset: branch: main`) and the explicit `if:`/`unless:` syntax are two ways of expressing the same thing. Mixing them in a single ruleset creates ambiguity the compiler cannot resolve. Choose one style per ruleset.\n- When using `matcher: regexp`, remember that YAML string parsing happens before the regex engine sees the pattern. A single backslash in YAML is an escape character, so regex patterns like `\\d+` need double-escaping: `\"release-\\\\d+\"`. Without the extra backslash, YAML consumes it and the regex receives `d+` instead.\n- The `continue: true` flag controls what happens after a step fails -- it tells Vela to proceed with the remaining steps rather than halting the build. It has no effect on whether the step runs in the first place; that is still governed entirely by the ruleset.\n\n## Quick Reference\n\n```yaml\nruleset:\n  # Compile-time rules\n  branch: [main, release/*]\n  event: [push, pull_request]\n  path: [\"src/**\", \"*.go\"]\n  tag: [v1.*]\n  target: [production]\n  comment: [\"run build\"]\n  repo: [\"myorg/*\"]\n  label: [enhancement]\n\n  # Runtime rules\n  status: [success, failure]\n\n  # Expr evaluation\n  eval: \"VELA_BUILD_AUTHOR == ''octocat''\"\n\n  # Controls\n  continue: true         # don''t fail build on step failure\n  operator: and          # and | or (default: and)\n  matcher: filepath      # filepath | regexp (default: filepath)\n\n  # Explicit form (alternative to top-level rules)\n  if:\n    branch: main\n    event: push\n  unless:\n    branch: main\n    event: push\n\n# Event action scoping\nevent: pull_request:opened\nevent: pull_request*          # wildcard for all actions\nevent: comment:created\nevent: deployment:created\n```\n"},"lastSynced":"2026-03-08T02:18:38.488Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing conditional build step control in Vela pipelines.","zh":"非常适合需要在 Vela 流水线中实现条件构建步骤控制的 DevOps Agents。","ja":"Vela パイプラインで条件付きビルド ステップ コントロールが必要な DevOps エージェントに最適です。","ko":"Vela 파이프라인에서 조건부 빌드 단계 제어가 필요한 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan control de paso de compilación condicional en tuberías de Vela.","fr":"Parfait pour les agents DevOps ayant besoin d''un contrôle de l''étape de build conditionnel dans les pipelines Vela.","de":"Perfekt für DevOps-Agents, die eine bedingte Build-Schrittsteuerung in Vela-Pipelines benötigen.","pt":"Perfeito para agentes DevOps que necessitam de controle de etapas de compilação condicional em pipelines Vela.","ru":"Идеально подходит для агентов DevOps, которым требуется условный контроль шагов сборки в конвейерах Vela.","ar":"مثالي لعميل DevOps الذي يحتاج إلى التحكم في خطوات البناء الشرطي في خطوط أنابيب Vela."},"recommendation":{"en":"Empowers agents to gate execution on branch, event, path changes, status, and other build metadata using compile-time rules and rulesets, enabling customized build processes with features like `branch`, `event`, and `path` conditions.","zh":"赋予代理人使用编译时规则和规则集根据分支、事件、路径更改、状态和其他构建元数据来控制执行的能力，使得可以使用 `branch`、`event` 和 `path` 条件等功能实现自定义的构建过程。","ja":"エージェントに、コンパイル時ルールとルールセットを使用してブランチ、イベント、パス変更、ステータス、および他のビルド メタデータに基づいて実行を制御する能力を付与し、`branch`、`event`、`path` 条件などの機能を使用してカスタマイズされたビルド プロセスを実現します。","ko":"에이전트에게 컴파일 타임 규칙과 규칙셋을 사용하여 분기, 이벤트, 경로 변경, 상태 및 기타 빌드 메타데이터를 기반으로 실행을 제어하는 기능을 부여하여 `branch`, `event`, `path` 조건 등과 같은 기능을 사용하여 사용자 지정 빌드 프로세스를 구현할 수 있습니다.","es":"Habilita a los agentes a controlar la ejecución en función de cambios en la rama, eventos, ruta, estado y otros metadatos de compilación utilizando reglas y conjuntos de reglas de tiempo de compilación, lo que permite procesos de compilación personalizados con características como condiciones de `branch`, `event` y `path`.","fr":"Permet aux agents de contrôler l''exécution en fonction de modifications de branche, d''événements, de chemin, de statut et d''autres métadonnées de build à l''aide de règles et de jeux de règles de temps de compilation, permettant ainsi des processus de build personnalisés avec des fonctionnalités comme les conditions `branch`, `event` et `path`.","de":"Ermächtigt Agents, die Ausführung basierend auf Änderungen an Zweig, Ereignis, Pfad, Status und anderen Build-Metadaten mit Kompilierzeitregeln und Regelsätzen zu steuern, wodurch benutzerdefinierte Buildprozesse mit Funktionen wie `branch`-, `event`- und `path`-Bedingungen ermöglicht werden.","pt":"Permite que os agentes controlem a execução com base em alterações de branch, evento, caminho, status e outros metadados de compilação usando regras e conjuntos de regras de tempo de compilação, permitindo processos de compilação personalizados com recursos como condições de `branch`, `event` e `path`.","ru":"Позволяет агентам управлять выполнением на основе изменений ветки, события, пути, статуса и других метаданных сборки с помощью правил и наборов правил времени компиляции, что позволяет создавать настраиваемые процессы сборки с функциями, такими как условия `branch`, `event` и `path`.","ar":"يمكن للعميل التحكم في التنفيذ بناءً على التغييرات في الفرع والحالة والمسار والحدث وغيرها من بيانات البناء باستخدام القواعد وقواعد التجميع في وقت التجميع، مما يسمح بعملية بناء مخصصة مع ميزات مثل حالات `branch` و `event` و `path`."},"useCases":{"en":["Controlling build steps based on specific conditions","Customizing build processes with rulesets","Gating execution on branch or event changes"],"zh":["基于特定条件控制构建步骤","使用规则集自定义构建过程","基于分支或事件更改来控制执行"],"ja":["特定の条件に基づいてビルド ステップを制御する","ルールセットを使用してビルド プロセスをカスタマイズする","ブランチまたはイベントの変更に基づいて実行を制御する"],"ko":["특정 조건에 따라 빌드 단계를 제어하는 것","규칙셋을 사용하여 빌드 프로세스를 사용자 지정하는 것","분기 또는 이벤트 변경에 따라 실행을 제어하는 것"],"es":["Controlar los pasos de compilación en función de condiciones específicas","Personalizar procesos de compilación con conjuntos de reglas","Controlar la ejecución en función de cambios en la rama o en el evento"],"fr":["Contrôler les étapes de build en fonction de conditions spécifiques","Personnaliser les processus de build avec des jeux de règles","Contrôler l''exécution en fonction de modifications de branche ou d''événements"],"de":["Build-Schritte basierend auf bestimmten Bedingungen steuern","Build-Prozesse mit Regelsätzen anpassen","Ausführung basierend auf Änderungen an Zweig oder Ereignis steuern"],"pt":["Controle de etapas de compilação com base em condições específicas","Personalização de processos de compilação com conjuntos de regras","Controle de execução com base em alterações de branch ou evento"],"ru":["Контроль шагов сборки на основе определенных условий","Настройка процессов сборки с помощью наборов правил","Контроль выполнения на основе изменений ветки или события"],"ar":["التحكم في خطوات البناء بناءً على شروط محددة","تخصيص عمليات البناء باستخدام مجموعات القواعد","التحكم في التنفيذ بناءً على التغييرات في الفرع أو الحدث"]},"limitations":{"en":["Requires Vela pipeline setup","Two categories of rules must be understood: compile-time and runtime rules"],"zh":["需要 Vela 流水线设置","必须理解两种类型的规则：编译时规则和运行时规则"],"ja":["Vela パイプラインの設定が必要","2 種類のルール、コンパイル時ルールとランタイム ルールを理解する必要がある"],"ko":["Vela 파이프ライン 설정이 필요","컴파일 타임 규칙과 런타임 규칙이라는 두 가지 유형의 규칙을 이해해야 함"],"es":["Requiere una configuración de tubería de Vela","Deben entenderse dos categorías de reglas: reglas de tiempo de compilación y reglas de tiempo de ejecución"],"fr":["Nécessite une configuration de pipeline Vela","Deux catégories de règles doivent être comprises : règles de temps de compilation et règles de temps d''exécution"],"de":["Benötigt eine Vela-Pipeline-Konfiguration","Zwei Kategorien von Regeln müssen verstanden werden: Kompilierzeitregeln und Laufzeitregeln"],"pt":["Requer configuração de pipeline Vela","Duas categorias de regras devem ser entendidas: regras de tempo de compilação e regras de tempo de execução"],"ru":["Требуется настройка конвейера Vela","Два типа правил должны быть поняты: правила времени компиляции и правила времени выполнения"],"ar":["يتطلب إعداد خط أنابيب Vela","يجب فهم فئتين من القواعد: قواعد وقت التجميع وقواعد وقت التنفيذ"]},"version":4},"contentHash":"b121fdc8599959097c2ae31ba32193949f96550742619780910ea35f3290ef59","qualityScore":59}');
