INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryanmr/vela-skills/vela-rulesets', 'vela-rulesets', 'ryanmr', 'vela-skills', 'community', 'vela-rulesets ryanmr vela-skills community vela-rulesets enables developers to control build steps based on specific conditions. It benefits developers by allowing them to customize their build processes. Vela rulesets 使您能够控制 Vela 构建过程中步骤的执行，通过使用 compile-time rules 和 runtime rules 来管理构建元数据 Vela rulesets を使用すると、compile-time rules と runtime rules を使用してビルドメタデータを管理し、Vela ビルドプロセス中的のステップの実行を制御できます Vela rulesets를 사용하면 compile-time rules와 runtime rules를 사용하여 빌드 메타데이터를 관리하고 Vela 빌드 프로세스 중의 단계를 제어할 수 있습니다 Vela-rulesets permite controlar los pasos de compilación en función de metadatos como rama, evento y cambios de ruta. Utiliza reglas de compilación y ejecución para personalizar tus flujos de trabajo Les vela-rulesets permettent de contrôler les étapes de construction en fonction de métadonnées telles que la branche, l''événement et les modifications de chemin. Utilisez des règles de compilation et d''exécution pour personnaliser vos workflows Vela-rulesets ermöglicht die Steuerung von Schritten in einem Workflow auf der Grundlage von Metadaten wie Zweig, Ereignis und Pfadänderungen. Verwenden Sie Kompilierungs- und Ausführungsregeln, um Ihre Workflows anzupassen O vela-rulesets permite controlar o fluxo de trabalho em um pipeline de build, usando regras de compilação e tempo de execução para gatear a execução de etapas Vela-rulesets позволяет контролировать поток работы в конвейере сборки, используя правила компиляции и времени выполнения для ограничения выполнения шагов يسمح vela-rulesets بمراقبة سير عمل البناء في أنبوب بناء، باستخدام قواعد مرحلة التجميع والتشغيل لتحديد تنفيذ الخطوات how to use vela-rulesets vela-rulesets setup guide vela-rulesets vs github actions what is vela-rulesets vela-rulesets install vela-rulesets conditional build control Vela rulesets AIエージェント compile-time rules runtime rules Vela 构建过程 步骤执行控制 元数据管理 Attach a `ruleset:` block to any step to gate execution Evaluate compile-time rules on the server before pipeline reaches the worker Remove steps entirely that fail compile-time rules Supports rules based on branch, event, path, comment, tag, target, repo, and label Allows for conditional build control based on build metadata vela-rulesets is a feature that allows developers to use rulesets to control which steps run in a Vela build, based on conditions like branch, event, and path changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('davidkimai/ralph-zero/prd', 'community', 'davidkimai', 'ralph-zero', 'davidkimai/ralph-zero', 'prd', 0, 0, 59, '2026-03-07T01:49:01.453Z', '2026-03-07T01:56:05.831Z', '83ea93fc1dd955868057bbd8fe2aa6c25a94f67fde40b749de1dce7a62410b2d', '{"id":"davidkimai/ralph-zero/prd","name":"prd","description":{"en":"The prd skill generates comprehensive Product Requirements Documents through an interactive question-and-answer workflow, ideal for autonomous development and planning new features.","zh":"PRD 生成技能通过交互式问答工作流自动创建综合的产品需求文档，优化自动化开发","ja":"PRD 作成スキルは、交互式の質問と回答のワークフローで包括的な製品要件文書を自動生成し、自動開発を最適化する","ko":"PRD 생성 스킬은 상호작용형 질문과 답변 작업 흐름을 통해 포괄적인 제품 요구 사항 문서를 자동 생성하여 자동화 개발을 최적화합니다","es":"El skill PRD permite a los agentes generar documentos de requisitos de producto estructurados a través de un flujo de trabajo interactivo","fr":"Le skill PRD permet aux agents de créer des documents de spécifications de produit complets via un workflow interactif","de":"Das PRD-Skill ermöglicht es Agenten, strukturierte Produktanforderungsdokumente durch einen interaktiven Workflow zu erstellen","pt":"O PRD é uma habilidade que gera documentos de requisitos de produto interativos e estruturados para desenvolvimento autônomo.","ru":"ИИ Агенты PRD - это habilidade, которая создает комплексные технические требования к продукту с помощью интерактивного рабочего процесса.","ar":"برد هو مهارة تقوم بتوليد مستندات متطلبات المنتج الشاملة والمنظمة من خلال سير عمل تفاعلي لتنمية مستقلة."},"seo":{"title":{"en":"prd: Interactive PRD Generation for AI Agents | AI Agent ...","zh":"PRD 生成技能设置指南 - 使用 Ralph Zero 实现自动化开发","ja":"PRD 作成スキルベストプラクティス - Ralph Zero で自動開発を実現","ko":"PRD 생성 스킬 설정 가이드 - Ralph Zero로 자동화 개발 구현","es":"Generación de PRD: Guía de Configuración para Agentes de ...","fr":"Création de PRD : Guide d''Installation pour les Outils d''...","d