INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('davidkimai/ralph-zero/prd', 'prd', 'davidkimai', 'ralph-zero', 'community', 'prd davidkimai ralph-zero community The prd skill generates comprehensive Product Requirements Documents through an interactive question-and-answer workflow, ideal for autonomous development and planning new features. PRD 生成技能通过交互式问答工作流自动创建综合的产品需求文档，优化自动化开发 PRD 作成スキルは、交互式の質問と回答のワークフローで包括的な製品要件文書を自動生成し、自動開発を最適化する PRD 생성 스킬은 상호작용형 질문과 답변 작업 흐름을 통해 포괄적인 제품 요구 사항 문서를 자동 생성하여 자동화 개발을 최적화합니다 El skill PRD permite a los agentes generar documentos de requisitos de producto estructurados a través de un flujo de trabajo interactivo Le skill PRD permet aux agents de créer des documents de spécifications de produit complets via un workflow interactif Das PRD-Skill ermöglicht es Agenten, strukturierte Produktanforderungsdokumente durch einen interaktiven Workflow zu erstellen O PRD é uma habilidade que gera documentos de requisitos de produto interativos e estruturados para desenvolvimento autônomo. ИИ Агенты PRD - это habilidade, которая создает комплексные технические требования к продукту с помощью интерактивного рабочего процесса. برد هو مهارة تقوم بتوليد مستندات متطلبات المنتج الشاملة والمنظمة من خلال سير عمل تفاعلي لتنمية مستقلة. how to use prd skill prd skill alternative prd setup guide what is prd skill prd vs ralph loop prd installation for ai agents generate product requirements document prd skill for autonomous development interactive prd generation PRD 生成技能 自动化开发 交互式问答工作流 产品需求文档 Ralph Zero AI 에이전트 自动化工具 Generates comprehensive Product Requirements Documents (PRDs) through an interactive question-and-answer workflow Follows a structured 5-step process for efficient PRD creation Optimized for autonomous development and planning new features Breaks down complex features into implementable stories Utilizes error handling, process scheduling, memory management, and feedback learning through Ralph Zero prd is a skill that generates comprehensive, structured Product Requirements Documents through an interactive workflow optimized for autonomous development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JohnMarkCapones/Aralify/coding-standards', 'community', 'JohnMarkCapones', 'Aralify', 'JohnMarkCapones/Aralify', 'coding-standards', 0, 0, 59, '2026-03-05T06:20:06.259Z', '2026-03-05T07:51:49.315Z', '4034db738c85d87eb3f94a12a5a662ac9b20005be028b0a9c69b914300508a31', '{"id":"JohnMarkCapones/Aralify/coding-standards","name":"coding-standards","description":{"zh":"Aralify是一个交互式编程教育平台，提供分层的编码挑战和跟踪进度功能","ja":"Aralifyはインタラクティブなプログラミング教育プラットフォームで、階層化されたコーディングチャレンジと進度トラッキング機能を提供","ko":"Aralify는 상호작용 프로그래밍 교육 플랫폼으로 계층화된 코딩 챌린지와 진행 상황 추적 기능을 제공","es":"Aralify es una plataforma de educación interactiva donde los aprendices resuelven desafíos de codificación reales con dificultades tiered","fr":"Aralify est une plateforme d''éducation interactive où les apprenants résolvent des défis de codage réels avec des difficultés tiered","de":"Aralify ist eine interaktive Bildungsplattform, auf der Lernende reale Codierherausforderungen mit gestuften Schwierigkeitsgraden lösen","pt":"Aralify é uma plataforma de educação de programação interativa que ajuda os desenvolvedores a melhorar suas habilidades de codificação","ru":"Aralify - это интерактивная платформа программной образователь, giúpая разработчикам улучшать свои навыки кодирования","ar":"Aralify هي منصة تعليم برمجة تفاعلية تساعد المطورين على تحسين مهاراتهم في البرمجة","en":"Aralify is an interactive programming education platform where learners solve real coding challenges with tiered difficulties (Easy/Medium/Hard), earn XP and achievements, and track their progress across web and mobile."},"seo":{"title":{"zh":"AI工具：编码标准和挑战平台","ja":"AIエージェント：コーディングスタンダードとチャレンジプラットフォーム","ko":"AI 에이전트: 코딩 표준 및 챌린지 플랫폼","es":"Herramientas de codificación estándar con Aralify","fr":"Outils de codage standard avec Aralify","de":"Codierstandards mit Aralify, einem KI-Tool","pt":"Ferramentas