INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JohnMarkCapones/Aralify/coding-standards', 'coding-standards', 'JohnMarkCapones', 'Aralify', 'community', 'coding-standards JohnMarkCapones Aralify community Aralify是一个交互式编程教育平台，提供分层的编码挑战和跟踪进度功能 Aralifyはインタラクティブなプログラミング教育プラットフォームで、階層化されたコーディングチャレンジと進度トラッキング機能を提供 Aralify는 상호작용 프로그래밍 교육 플랫폼으로 계층화된 코딩 챌린지와 진행 상황 추적 기능을 제공 Aralify es una plataforma de educación interactiva donde los aprendices resuelven desafíos de codificación reales con dificultades tiered Aralify est une plateforme d''éducation interactive où les apprenants résolvent des défis de codage réels avec des difficultés tiered Aralify ist eine interaktive Bildungsplattform, auf der Lernende reale Codierherausforderungen mit gestuften Schwierigkeitsgraden lösen Aralify é uma plataforma de educação de programação interativa que ajuda os desenvolvedores a melhorar suas habilidades de codificação Aralify - это интерактивная платформа программной образователь, giúpая разработчикам улучшать свои навыки кодирования Aralify هي منصة تعليم برمجة تفاعلية تساعد المطورين على تحسين مهاراتهم في البرمجة Aralify is an interactive programming education platform where learners solve real coding challenges with tiered difficulties (Easy/Medium/Hard), earn XP and achievements, and track their progress across web and mobile. 如何使用Aralify 什么是编码标准 Aralify替代品 Aralify安装 编码挑战平台 交互式编程教育 编码技能提高 Aralify is an interactive programming education platform where learners solve real coding challenges with tiered difficulties (Easy/Medium/Hard), earn XP and achievements, and track their progress across web and mobile.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('emavgl/oinkoin/translate', 'community', 'emavgl', 'oinkoin', 'emavgl/oinkoin', 'translate', 341, 34, 58, '2026-02-28T10:44:17Z', '2026-03-06T06:28:45.504Z', '621fd8a99d1624c29f890d040b231f8ae39fa681c7ea5792e04b343316dfa291', '{"id":"emavgl/oinkoin/translate","name":"translate","description":{"en":"The translate skill helps developers manage translations for the Oinkoin app by translating untranslated strings in locale JSON files. It benefits developers working on the Oinkoin project.","zh":"Translate功能用于Oinkoin_app的本地化，支持本地JSON文件的翻译","ja":"Translate機能はOinkoinアプリのローカライズをサポート，ローカルJSONファイルの翻訳を実現","ko":"Translate_기능은_Oinkoin앱_로컬라이제이션을_지원，로컬_JSON_파일_번역_구현","es":"La habilidad de traducir permite traducir cadenas no traducidas en archivos JSON de locale para la aplicación Oinkoin.","fr":"La compétence de traduction permet de traduire les chaînes non traduites dans les fichiers JSON de locale pour l''application Oinkoin.","de":"Die Übersetzungsfunktion ermöglicht das Übersetzen unübersetzter Zeichenfolgen in JSON-Dateien für die Oinkoin-App.","pt":"O translate é uma habilidade que traduz strings não traduzidas em arquivos JSON de locale para o aplicativo Oinkoin.","ru":"Перевод - это навык, который переводит не переведенные строки в файлах JSON локали для приложения Oinkoin.","ar":"الترجمة هي مهارة تترجم السلاسل غير المترجمة في ملفات JSON المحلية لتطبيق Oinkoin."},"seo":{"title":{"en":"translate: Locale JSON Translation Setup Guide | AI Agent...","zh":"Translate_setup_guide_for_Oinkoin_app","ja":"OinkoinアプリのTranslate機能セットアップガイド","ko":"Oinkoin앱_Translate_설정_가이드","es":"Guía de configuración de traducción para Oinkoin","fr":"Guide de configuration de traduction pour Oinkoin","de":"Translate-Setup-Anleitung für Oinkoin","pt":"Guia de Configuração do Translate: Ferramentas de Traduçã...","ru":"Настройка Перевода: Лучшие Практики для ИИ Агентов","ar":"دليل إعداد الترجمة: أدوات ترجمة متقدمة للوكلاء الذكيين"},"description":{"en":"Discover how to translate untranslated strings in Oinkoin''s locale JSON files with ease. Learn the /translate command and get started today!","zh":"使用Translate功能实现Oinkoin_app的本地化，AIエージェント工具简化开发流程","ja":"OinkoinアプリのローカライズをTranslate機能で実現，AIエージェントツールによる開発効率化","ko":"Oinkoin앱_로컬라이제이션을_Translate_기능으로_구현，AI_도구_개발_프로세스_최적화","es":"Aprende a traducir cadenas no traducidas en archivos JSON de locale para la aplicación Oinkoin con la herramienta de AI Agent","fr":"Découvrez comment traduire les chaînes non traduites dans les fichiers JSON de locale pour l''application Oinkoin avec l''outil d''AI Agent","de":"Erfahren Sie, wie Sie unübersetzte Zeichenfolgen in JSON-Dateien für die Oinkoin-App mit dem AI-Tool übersetzen","pt":"Aprenda a usar o translate para traduzir strings em arquivos JSON de locale para o aplicativo Oinkoin. Ferramentas de tradução de AI Agents.","ru":"Узнайте, как использовать перевод для перевода строк в файлах JSON локали для приложения Oinkoin. Инструменты ИИ Агентов.","ar":"تعرف على كيفية استخدام الترجمة لترجمة السلاسل في ملفات JSON المحلية لتطبيق Oinkoin. أدوات الوكلاء الذكيين."},"definition":{"en":"translate is a skill that automates translation of untranslated strings in locale JSON files for the Oinkoin app, using the /translate command.","zh":"Translate功能是Oinkoin_app的本地化工具，用于翻译本地JSON文件","ja":"Translate機能はOinkoinアプリのローカライズツール，ローカルJSONファイルの翻訳を実現","ko":"Translate_기능은_Oinkoin앱_로컬라이제이션_도구，로컬_JSON_파일_번역_을_구현","es":"La traducción es una habilidad de AI que traduce cadenas en archivos JSON de locale","fr":"La traduction est une compétence d''AI qui traduit les chaînes dans les fichiers JSON de locale","de":"Die Übersetzung ist eine Fähigkeit von AI, die Zeichenfolgen in JSON-Dateien für die Lokalisierung übersetzt","pt":"O que é translate? É uma habilidade que traduz strings em arquivos JSON de locale.","ru":"Что такое перевод? Это навык, который переводит строки в файлах JSON локали.","ar":"ما هي الترجمة؟ هي مهارة تترجم السلاسل في ملفات JSON المحلية."},"features":{"en":["Translates untranslated strings in locale JSON files using the /translate command","Supports translation of multiple locale files, including it.json, de.json, and pt-BR.json","Uses assets/locales/en-US.json as the source of truth for translations","Allows for translation of all locale files at once if no file is specified","Works with the Oinkoin app, a Flutter app for managing expenses"],"zh":["支持本地JSON文件的翻译","使用CLI命令/translate进行翻译","assets/locales/en-US.json作为翻译源","支持多语言本地化","自动化翻译流程","提高开发效率"],"ja":["ローカルJSONファイルの翻訳をサポート","CLIコマンド/translateを使用して翻訳","assets/locales/en-US.jsonを翻訳ソースとして使用","多言語ローカライズをサポート","翻訳プロセスを自動化","開発効率を向上"],"ko":["로컬_JSON_파일_번역_지원","CLI_명령어_/translate_사용_번역","assets/locales/en-US.json_번역_출처_사용","다중_언어_로컬라이제이션_지원","번역_프로세스_자동화","개발_효율_개선"],"es":["Traducción de cadenas no traducidas en archivos JSON de locale","Compatibilidad con múltiples archivos de locale (it.json, de.json, pt-BR.json)","Uso de assets/locales/en-US.json como fuente de verdad","Soporte para traducir todos los archivos de locale de una vez","Uso de la sintaxis /translate <locale-file> para traducir archivos individuales","Funciona sin conexión a Internet"],"fr":["Traduction de chaînes non traduites dans les fichiers JSON de locale","Compatibilité avec plusieurs fichiers de locale (it.json, de.json, pt-BR.json)","Utilisation de assets/locales/en-US.json comme source de vérité","Prise en charge de la traduction de tous les fichiers de locale en une seule fois","Utilisation de la syntaxe /translate <locale-file> pour traduire des fichiers individuels","Fonctionne sans connexion Internet"],"de":["Übersetzung unübersetzter Zeichenfolgen in JSON-Dateien für die Lokalisierung","Kompatibilität mit mehreren Lokalisierungsdateien (it.json, de.json, pt-BR.json)","Verwendung von assets/locales/en-US.json als Quelle der Wahrheit","Unterstützung für das Übersetzen aller Lokalisierungsdateien auf einmal","Verwendung der Syntax /translate <locale-file> zum Übersetzen einzelner Dateien","Funktioniert ohne Internetverbindung"],"pt":["Tradução de strings em arquivos JSON de locale","Suporte a múltiplos arquivos de locale","Uso de comandos CLI para traduzir strings","Integração com o aplicativo Oinkoin","Suporte a tradução de strings em diferentes idiomas"],"ru":["Перевод строк в файлах JSON локали","Поддержка нескольких файлов локали","Использование команд CLI для перевода строк","Интеграция с приложением Oinkoin","Поддержка перевода строк на разных языках"],"ar":["ترجمة السلاسل في ملفات JSON المحلية","دعم الملفات المحلية المتعددة","استخدام أوامر CLI لترجمة السلاسل","التكامل مع تطبيق Oinkoin","دعم ترجمة السلاسل بلغات مختلفة"]},"keywords":{"en":["how to use translate","what is translate","translate alternative","translate vs localization","translate install","translate setup guide","Oinkoin app translation","locale JSON translation","Flutter app translation"],"zh":["Oinkoin_app","Translate功能","本地化","AIエージェント","JSON文件翻译","CLI命令","自动化翻译","开发效率","多语言支持"],"ja":["Oinkoinアプリ","Translate機能","ローカライズ","AIエージェント","JSONファイル翻訳","CLIコマンド","自動化翻訳","開発効率","多言語サポート"],"ko":["Oinkoin앱","Translate_기능","로컬라이제이션","AI_도구","JSON_파일_번역","CLI_명령어","자동화_번역","개발_효율","다중_언어_지원"],"es":["herramientas de AI para desarrolladores","traducción de cadenas en archivos JSON","locale files","Oinkoin","traducción automática","desarrollo de aplicaciones móviles","flutter","AI Agent","herramientas de traducción"],"fr":["outils d''IA pour les développeurs","traduction de chaînes dans les fichiers JSON","fichiers de locale","Oinkoin","traduction automatique","développement d''applications mobiles","flutter","agent d''IA","outils de traduction"],"de":["AI-Tools für Entwickler","Übersetzung von Zeichenfolgen in JSON-Dateien","Lokalisierungsdateien","Oinkoin","automatische Übersetzung","Entwicklung von mobilen Anwendungen","flutter","AI-Agent","Übersetzungs-Tools"],"pt":["translate","AI Agents","ferramentas de tradução","tradução de strings","arquivos JSON de locale","Oinkoin","CLI","tradução automática"],"ru":["перевод","ИИ Агенты","инструменты перевода","перевод строк","файлы JSON локали","Oinkoin","CLI","автоматический перевод"],"ar":["ترجمة","الوكلاء الذكيين","أدوات الترجمة","ترجمة السلاسل","ملفات JSON المحلية","Oinkoin","CLI","ترجمة آلية"]}},"owner":"emavgl","repo":"oinkoin","repoPath":"emavgl/oinkoin","stars":341,"forks":34,"updatedAt":"2026-02-28T10:44:17Z","topics":[],"category":"community","skillMd":{"name":"translate","description":"Translates untranslated strings in a locale JSON file for the Oinkoin app. Use when the user wants to localise or update translations for a specific language, or says translate <locale>.","bodyPreview":"# Skill: translate\n\nTranslate untranslated strings in a locale JSON file for the Oinkoin app.\n\n## Usage\n```\n/translate <locale-file>\n```\nExample: `/translate assets/locales/it.json`\n\nIf no file is specified, address all the locale files\n\n---\n\n## How translations work in this project\n\n- All locale files live in `assets/locales/` (e.g. `it.json`, `de.json`, `pt-BR.json`).\n- `assets/locales/en-US.json` is the **source of truth**: every key AND its English value are listed there.\n- Every other local","body":"# Skill: translate\n\nTranslate untranslated strings in a locale JSON file for the Oinkoin app.\n\n## Usage\n```\n/translate <locale-file>\n```\nExample: `/translate assets/locales/it.json`\n\nIf no file is specified, address all the locale files\n\n---\n\n## How translations work in this project\n\n- All locale files live in `assets/locales/` (e.g. `it.json`, `de.json`, `pt-BR.json`).\n- `assets/locales/en-US.json` is the **source of truth**: every key AND its English value are listed there.\n- Every other locale file has the **same keys**. A string is **untranslated** when its value is identical to its key (i.e. it was never localised and still reads in English).\n- A string is **already translated** when its value differs from its key. **Never touch those.**\n\n## Step-by-step instructions\n\n### 0. Sync keys with the codebase (always run first)\nRun the sync script from the project root to ensure `en-US.json` is up-to-date and stale keys are removed from all locale files:\n```\npython3 scripts/update_en_strings.py\n```\nThis regenerates `en-US.json` from all `.i18n` strings found in `lib/`, and removes obsolete keys from every other locale file. Run it before translating so you are working against the current set of keys.\n\n### 1. Read the target locale file\nRead the full file specified by the user.\n\n### 2. Identify untranslated strings\nA string is untranslated when `value == key`. Collect every such entry.\n\nIf there are no untranslated strings, tell the user and stop.\n\n### 3. For each untranslated string — look up context before translating\nDo **not** guess from the key text alone. For each untranslated key:\n\n- Search the Dart source code (Grep in `lib/`) for the exact key string to find where it is used.\n- Look at the surrounding widget/function/page to understand the context (e.g. is it a button label, a dialog title, an error message, a settings toggle description?).\n- Only then choose the most natural, contextually appropriate translation for the target language.\n\n### 4. Write the translated strings\nEdit the locale file, replacing only the untranslated values. Keep every other entry byte-for-byte identical.\n\n### 5. Report what changed\nAfter editing, print a compact table of the strings you translated:\n\n| Key | Translation |\n|-----|-------------|\n| … | … |\n\n---\n\n## Important rules\n\n- **Never modify already-translated strings** (value ≠ key).\n- **Never change keys** — only values.\n- Preserve placeholders exactly as written: `%s`, `%d`, `%1$s`, etc.\n- Match the tone and terminology of the strings that ARE already translated in the same file — consistency matters more than literal accuracy.\n- For technical or brand terms (e.g. \"Oinkoin Pro\", \"PIN\", \"CSV\", \"JSON\") keep them untranslated.\n- If a string has no natural translation (e.g. it is already the correct word in the target language), it is fine to leave the value equal to the key — but note this in your report.\n- Process the **whole file** in one pass; do not ask for confirmation before each string.\n\n## Exceptions\n\nFor British english use en-GB.json - in this case, key and value will most of case matches. Consider all the strings as already translated and skip it.\n"},"lastSynced":"2026-03-06T06:28:45.504Z","agentAnalysis":{"suitability":{"en":"Ideal for Multilingual Agents requiring efficient locale file management and translation capabilities.","zh":"适合需要高效的本地化文件管理和翻译能力的多语言代理。","ja":"多言語エージェントが効率的なロケールファイル管理と翻訳機能を必要とする場合に適しています。","ko":"多언어 에이전트가 효율적인 로컬 파일 관리와 번역 기능을 필요로 할 때 적합합니다.","es":"Ideal para Agentes Multilingües que requieren una gestión eficiente de archivos de configuración regional y capacidades de traducción.","fr":"Idéal pour les agents multilingues nécessitant une gestion efficace des fichiers de configuration régionale et des capacités de traduction.","de":"Ideal für multilinguale Agenten, die eine effiziente Verwaltung von Gebietsdateien und Übersetzungsfunktionen erfordern.","pt":"Ideal para Agentes Multilíngues que requerem gestão eficiente de arquivos de localização e capacidades de tradução.","ru":"Идеально подходит для многоязычных агентов, требующих эффективного управления файлами локализации и возможностей перевода.","ar":"مثالي لعميل متعددة اللغات التي تتطلب إدارة كفؤة لملفات الموقع و قدرات الترجمة."},"recommendation":{"en":"Empowers agents to translate untranslated strings in locale JSON files, leveraging the source of truth in ''assets/locales/en-US.json'' and supporting multiple locales like ''it.json'', ''de.json'', and ''pt-BR.json'' through JSON file interactions.","zh":"赋予代理人翻译未翻译的字符串在本地JSON文件的能力，利用''assets/locales/en-US.json''的真实来源，并通过JSON文件交互支持多个本地化，如''it.json''、''de.json''和''pt-BR.json''。","ja":"エージェントに未翻訳の文字列をロケールJSONファイルで翻訳する能力を与え、''assets/locales/en-US.json''の真実の源を利用し、JSONファイルの相互作用を介して複数のロケール(''it.json''、''de.json''、''pt-BR.json''など)をサポートします。","ko":"에이전트가 로컬 JSON 파일의 번역되지 않은 문자열을 번역할 수 있는 기능을 부여하며, ''assets/locales/en-US.json''의 진실된 출처를 활용하고 JSON 파일 상호 작용을 통해 여러 로컬(''it.json'', ''de.json'', ''pt-BR.json'' 등)을 지원합니다.","es":"Habilita a los agentes a traducir cadenas no traducidas en archivos JSON de configuración regional, aprovechando la fuente de verdad en ''assets/locales/en-US.json'' y admitiendo varios locales como ''it.json'', ''de.json'' y ''pt-BR.json'' a través de interacciones con archivos JSON.","fr":"Permet aux agents de traduire les chaînes non traduites dans les fichiers JSON de configuration régionale, en exploitant la source de vérité dans ''assets/locales/en-US.json'' et en prenant en charge plusieurs paramètres régionaux tels que ''it.json'', ''de.json'' et ''pt-BR.json'' via des interactions avec des fichiers JSON.","de":"Ermächtigt Agenten, unübersetzte Zeichenfolgen in Gebiets-JSON-Dateien zu übersetzen, indem es die Quelle der Wahrheit in ''assets/locales/en-US.json'' nutzt und mehrere Gebiete wie ''it.json'', ''de.json'' und ''pt-BR.json'' über JSON-Datei-Interaktionen unterstützt.","pt":"Permite que os agentes traduzam cadeias de caracteres não traduzidas em arquivos JSON de localização, aproveitando a fonte de verdade em ''assets/locales/en-US.json'' e suportando vários locais como ''it.json'', ''de.json'' e ''pt-BR.json'' por meio de interações de arquivos JSON.","ru":"Позволяет агентам переводить не переведенные строки в файлах JSON локализации, используя источник истины в ''assets/locales/en-US.json'' и поддерживая несколько локалей, таких как ''it.json'', ''de.json'' и ''pt-BR.json'', через взаимодействие с файлами JSON.","ar":"يمكن للعميل ترجمة السلاسل غير المترجمة في ملفات JSON للموقع، واستخدام مصدر الحقيقة في ''assets/locales/en-US.json'' ودعم المواقع المتعددة مثل ''it.json'' و ''de.json'' و ''pt-BR.json'' من خلال التفاعل مع ملفات JSON."},"useCases":{"en":["Translating locale files for the Oinkoin app","Managing untranslated strings in JSON files","Updating ''assets/locales/'' directory with new translations"],"zh":["为Oinkoin应用程序翻译本地文件","在JSON文件中管理未翻译的字符串","使用新翻译更新''assets/locales/''目录"],"ja":["Oinkoinアプリのロケールファイルを翻訳する","JSONファイル内の未翻訳文字列を管理する","新しい翻訳で''assets/locales/''ディレクトリを更新する"],"ko":["Oinkoin 애플리케이션의 로컬 파일 번역","JSON 파일의 번역되지 않은 문자열 관리","새 번역으로 ''assets/locales/'' 디렉토리 업데이트"],"es":["Traducir archivos de configuración regional para la aplicación Oinkoin","Gestionar cadenas no traducidas en archivos JSON","Actualizar el directorio ''assets/locales/'' con nuevas traducciones"],"fr":["Traduire les fichiers de configuration régionale pour l''application Oinkoin","Gérer les chaînes non traduites dans les fichiers JSON","Mettre à jour le répertoire ''assets/locales/'' avec de nouvelles traductions"],"de":["Übersetzen von Gebietsdateien für die Oinkoin-App","Verwalten von unübersetzten Zeichenfolgen in JSON-Dateien","Aktualisieren des Verzeichnisses ''assets/locales/'' mit neuen Übersetzungen"],"pt":["Traduzir arquivos de localização para o aplicativo Oinkoin","Gerenciar cadeias de caracteres não traduzidas em arquivos JSON","Atualizar o diretório ''assets/locales/'' com novas traduções"],"ru":["Переводить файлы локализации для приложения Oinkoin","Управлять не переведенными строками в файлах JSON","Обновлять каталог ''assets/locales/'' с новыми переводами"],"ar":["ترجمة ملفات الموقع للتطبيق Oinkoin","إدارة السلاسل غير المترجمة في ملفات JSON","تحديث دليل ''assets/locales/'' بالترجمات الجديدة"]},"limitations":{"en":["Requires access to locale JSON files","Limited to JSON file format","Dependent on ''assets/locales/en-US.json'' as the source of truth"],"zh":["需要访问本地JSON文件","仅限于JSON文件格式","依赖''assets/locales/en-US.json''作为真实来源"],"ja":["ロケールJSONファイルへのアクセスが必要","JSONファイル形式のみに限定される","''assets/locales/en-US.json''を真実の源として依存する"],"ko":["로컬 JSON 파일에 대한 액세스가 필요","JSON 파일 형식만으로 제한","''assets/locales/en-US.json''를 진실된 출처로서 의존"],"es":["Requiere acceso a archivos JSON de configuración regional","Limitado al formato de archivo JSON","Dependiente de ''assets/locales/en-US.json'' como fuente de verdad"],"fr":["Nécessite un accès aux fichiers JSON de configuration régionale","Limité au format de fichier JSON","Dépendant de ''assets/locales/en-US.json'' comme source de vérité"],"de":["Erfordert Zugriff auf Gebiets-JSON-Dateien","Begrenzt auf JSON-Dateiformat","Abhängig von ''assets/locales/en-US.json'' als Quelle der Wahrheit"],"pt":["Requer acesso a arquivos JSON de localização","Limitado ao formato de arquivo JSON","Dependente de ''assets/locales/en-US.json'' como a fonte de verdade"],"ru":["Требует доступа к файлам JSON локализации","Ограничен форматом файла JSON","Зависит от ''assets/locales/en-US.json'' как от источника истины"],"ar":["يتطلب الوصول إلى ملفات JSON للموقع","محدود بتنسيق ملف JSON","يعتمد على ''assets/locales/en-US.json'' كمصدر للحقيقة"]},"version":4},"contentHash":"621fd8a99d1624c29f890d040b231f8ae39fa681c7ea5792e04b343316dfa291","qualityScore":58}');
