INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('emavgl/oinkoin/translate', 'translate', 'emavgl', 'oinkoin', 'community', 'translate emavgl oinkoin community The translate skill helps developers manage translations for the Oinkoin app by translating untranslated strings in locale JSON files. It benefits developers working on the Oinkoin project. Translate功能用于Oinkoin_app的本地化，支持本地JSON文件的翻译 Translate機能はOinkoinアプリのローカライズをサポート，ローカルJSONファイルの翻訳を実現 Translate_기능은_Oinkoin앱_로컬라이제이션을_지원，로컬_JSON_파일_번역_구현 La habilidad de traducir permite traducir cadenas no traducidas en archivos JSON de locale para la aplicación Oinkoin. La compétence de traduction permet de traduire les chaînes non traduites dans les fichiers JSON de locale pour l''application Oinkoin. Die Übersetzungsfunktion ermöglicht das Übersetzen unübersetzter Zeichenfolgen in JSON-Dateien für die Oinkoin-App. O translate é uma habilidade que traduz strings não traduzidas em arquivos JSON de locale para o aplicativo Oinkoin. Перевод - это навык, который переводит не переведенные строки в файлах JSON локали для приложения Oinkoin. الترجمة هي مهارة تترجم السلاسل غير المترجمة في ملفات JSON المحلية لتطبيق Oinkoin. how to use translate what is translate translate alternative translate vs localization translate install translate setup guide Oinkoin app translation locale JSON translation Flutter app translation Oinkoin_app Translate功能 本地化 AIエージェント JSON文件翻译 CLI命令 自动化翻译 开发效率 多语言支持 Translates untranslated strings in locale JSON files using the /translate command Supports translation of multiple locale files, including it.json, de.json, and pt-BR.json Uses assets/locales/en-US.json as the source of truth for translations Allows for translation of all locale files at once if no file is specified Works with the Oinkoin app, a Flutter app for managing expenses translate is a skill that automates translation of untranslated strings in locale JSON files for the Oinkoin app, using the /translate command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('satsigner/satsigner/native-data-fetching', 'community', 'satsigner', 'satsigner', 'satsigner/satsigner', 'native-data-fetching', 46, 22, 58, '2026-02-27T14:11:40Z', '2026-03-06T06:35:41.082Z', 'b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be', '{"id":"satsigner/satsigner/native-data-fetching","name":"native-data-fetching","description":{"en":"The native-data-fetching skill is designed for developers to manage UTXO and signing, ideal for implementing API requests and data fetching using React Query or SWR. It benefits developers working on Expo networking projects.","zh":"Native 数据抓取是一种用于 Expo Networking 的技能，提供了 UTXO Manager 和 Signer 的功能。","ja":"ネイティブデータフェッチングは、Expo Networking 用のスキルで、UTXO マネージャーとサイン機能を提供します。","ko":"네이티브 데이터 패칭은 Expo Networking용 스킬로 UTXO 매니저 및 서명기능을 제공합니다.","es":"Native-data-fetching es una habilidad para gestionar solicitudes de API y recuperación de datos en Expo. Utilízala para implementar API requests y depuración de red","fr":"Native-data-fetching est une compétence pour gérer les requêtes API et la récupération de données dans Expo. Utilisez-la pour mettre en œuvre des requêtes API et déboguer le réseau","de":"Native-data-fetching ist eine Fähigkeit zum Verwalten von API-Anfragen und Datenabruf in Expo. Verwenden Sie sie, um API-Anfragen und Netzwerksdebugging zu implementieren","pt":"O native-data-fetching é uma habilidade que permite requisições de API, busca de dados e caching em projetos de desenvolvimento, utilizando tecnologias como React Query e SWR","ru":"ИИ Агент native-data-fetching - это навык, который позволяет делать запросы API, извлекать данные и использовать кэширование в проектах разработки, используя технологии seperti React Query и SWR","ar":"native-data-fetching هو مهارة تسمح بطلبات API و استرجاع البيانات وتخزينها المؤقت في مشاريع البرمجة، باستخدام تقنيات مثل React Query و SWR"},"seo":{"title":{"en":"native-data-fetching: Expo Networking Setup Guide | AI Ag...","zh":"Native 数据抓取 Setup Guide - AIエージェント","ja":"ネイティブデータフェッチングベストプラクティス - AIエージェント","ko":"네이티브 데이터 패칭 설정 가이드 - AI 에이전트","es":"Guía de configuración de native-data-fetching para Expo N...","fr":"Guide de mise en place de native-data-fetching pour Expo ...","de":"Einrichtungsleitfaden für native-data-fetching bei Expo N...","pt":"Guia de Configuração de native-data-fetching para Desenvo...","ru":"ИИ Агент native-data-fetching: Руководство по Настройке","ar":"دليل إعداد native-data-fetching للبرمجة"},"description":{"en":"Discover how to use native-data-fetching for API requests, data fetching, and caching. Learn how to implement Expo networking with ease and optimize your wor...","zh":"了解 Native 数据抓取的技术细节，包括 React Query、SWR 和 Expo Networking。","ja":"ネイティブデータフェッチングの技術的な詳細について学びましょう。React Query、SWR、Expo Networking を含みます。","ko":"네이티브 데이터 패칭의 기술적 세부 정보를 알아보세요. React Query, SWR, Expo Networking 등을 포함합니다.","es":"Aprende a utilizar native-data-fetching para solicitudes de API, recuperación de datos y depuración de red en Expo","fr":"Découvrez comment utiliser native-data-fetching pour les requêtes API, la récupération de données et le débogage réseau dans Expo","de":"Erfahren Sie, wie Sie native-data-fetching für API-Anfragen, Datenabruf und Netzwerksdebugging in Expo verwenden","pt":"Aprenda a usar o native-data-fetching para requisições de API, busca de dados e caching em seus projetos de desenvolvimento","ru":"Узнайте, как использовать ИИ Агент native-data-fetching для запросов API, извлечения данных и кэширования в ваших проектах","ar":"تعرف على كيفية استخدام native-data-fetching لطلبات API واسترجاع البيانات وتخزينها المؤقت في مشاريعك"},"definition":{"en":"native-data-fetching is a skill that enables Expo networking for API requests, data fetching, caching, and network debugging, utilizing technologies like expo/fetch.","zh":"Native 数据抓取是一种用于实现 API 请求、数据抓取、缓存和网络调试的 Expo Networking 技术。","ja":"ネイティブデータフェッチングは、API リクエスト、データフェッチ、キャッシュ、ネットワーク デバッグを実現する Expo Networking 技術です。","ko":"네이티브 데이터 패칭은 API 요청, 데이터 패칭, 캐싱 및 네트워크 디버깅을 구현하는 Expo Networking 기술입니다.","es":"Native-data-fetching es una habilidad que permite gestionar solicitudes de API y recuperación de datos en Expo","fr":"Native-data-fetching est une compétence qui permet de gérer les requêtes API et la récupération de données dans Expo","de":"Native-data-fetching ist eine Fähigkeit, die das Verwalten von API-Anfragen und Datenabruf in Expo ermöglicht","pt":"O que é native-data-fetching? É uma habilidade que permite gerenciar requisições de API e busca de dados de forma eficiente","ru":"Что такое ИИ Агент native-data-fetching? Это навык, который позволяет эффективно управлять запросами API и извлечением данных","ar":"ما هو native-data-fetching؟ هو مهارة تسمح بإدارة طلبات API و استرجاع البيانات بفعالية"},"features":{"en":["Implements API requests using expo/fetch","Sets up data fetching with React Query or SWR","Handles caching strategies for optimized performance","Debugs network failures and handles offline scenarios","Manages authentication and token management","Configures API URLs and environment variables"],"zh":["支持 React Query 和 SWR","提供 UTXO Manager 和 Signer 功能","实现 API 请求和数据抓取","支持缓存策略和离线场景","支持认证和令牌管理"],"ja":["React Query と SWR をサポート","UTXO マネージャーとサイン機能を提供","API リクエストとデータフェッチを実現","キャッシュ戦略とオフラインシナリオをサポート","認証とトークン管理をサポート"],"ko":["React Query 및 SWR 지원","UTXO 매니저 및 서명기능 제공","API 요청 및 데이터 패칭 구현","캐싱 전략 및 오프라인 시나리오 지원","인증 및 토큰 관리 지원"],"es":["Implementación de solicitudes de API con expo/fetch","Configuración de recuperación de datos con React Query y SWR","Depuración de errores de red y caché","Gestión de autenticación y tokens","Configuración de URLs de API y variables de entorno"],"fr":["Mise en œuvre de requêtes API avec expo/fetch","Configuration de la récupération de données avec React Query et SWR","Débogage des erreurs de réseau et du cache","Gestion de l''authentification et des jetons","Configuration des URL d''API et des variables d''environnement"],"de":["Implementierung von API-Anfragen mit expo/fetch","Konfiguration von Datenabruf mit React Query und SWR","Fehlerbehebung bei Netzwerksfehlern und Cache","Verwaltung von Authentifizierung und Token","Konfiguration von API-URLs und Umgebungsvariablen"],"pt":["Suporte a requisições de API com expo/fetch","Integração com React Query e SWR para busca de dados","Caching e gerenciamento de dados offline","Autenticação e gerenciamento de tokens","Configuração de URLs de API e variáveis de ambiente"],"ru":["Поддержка запросов API с помощью expo/fetch","Интеграция с React Query и SWR для извлечения данных","Кэширование и управление данными в offline-режиме","Аутентификация и управление токенами","Настройка URL-адресов API и переменных среды"],"ar":["دعم طلبات API مع expo/fetch","التكامل مع React Query و SWR لاسترجاع البيانات","تخزين البيانات المؤقتة وإدارة البيانات في وضع عدم الاتصال","التحقق من هوية المستخدم وإدارة الرموز","تكوين عناوين URL ل API ومتغيرات البيئة"]},"keywords":{"en":["how to use native-data-fetching","native-data-fetching vs axios","native-data-fetching setup guide","what is native-data-fetching","native-data-fetching install","expo networking with native-data-fetching","native-data-fetching for React Query","native-data-fetching alternative","native-data-fetching and SWR","native-data-fetching for API requests"],"zh":["Native 数据抓取","Expo Networking","React Query","SWR","UTXO Manager","Signer","API 请求","数据抓取","缓存","网络调试"],"ja":["ネイティブデータフェッチング","Expo Networking","React Query","SWR","UTXO マネージャー","サイン","API リクエスト","データフェッチ","キャッシュ","ネットワーク デバッグ"],"ko":["네이티브 데이터 패칭","Expo Networking","React Query","SWR","UTXO 매니저","서명","API 요청","데이터 패칭","캐싱","네트워크 디버깅"],"es":["native-data-fetching","Expo Networking","solicitudes de API","recuperación de datos","depuración de red","React Query","SWR","autenticación","tokens"],"fr":["native-data-fetching","Expo Networking","requêtes API","récupération de données","débogage réseau","React Query","SWR","authentification","jetons"],"de":["native-data-fetching","Expo Networking","API-Anfragen","Datenabruf","Netzwerksdebugging","React Query","SWR","Authentifizierung","Token"],"pt":["native-data-fetching","requisições de API","busca de dados","caching","React Query","SWR","expo/fetch","autenticação","gerenciamento de tokens"],"ru":["ИИ Агент native-data-fetching","запросы API","извлечение данных","кэширование","React Query","SWR","expo/fetch","аутентификация","управление токенами"],"ar":["native-data-fetching","طلبات API","استرجاع البيانات","تخزين البيانات المؤقتة","React Query","SWR","expo/fetch","التحقق من هوية المستخدم","إدارة الرموز"]}},"owner":"satsigner","repo":"satsigner","repoPath":"satsigner/satsigner","stars":46,"forks":22,"updatedAt":"2026-02-27T14:11:40Z","topics":[],"category":"community","skillMd":{"name":"native-data-fetching","description":"Use when implementing or debugging ANY network request, API call, or data fetching. Covers fetch API, axios, React Query, SWR, error handling, caching strategies, offline support.","version":"1.0.0","bodyPreview":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## When to Use\n\nUse this router when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Debugging network failures\n- Implementing caching strategies\n- Handling offline scenarios\n- Authentication/token management\n- Configuring API URLs and environment variables\n\n## Preferences\n\n- Avoid axios, prefer expo/fetch\n\n## Common Issues &","body":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## When to Use\n\nUse this router when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Debugging network failures\n- Implementing caching strategies\n- Handling offline scenarios\n- Authentication/token management\n- Configuring API URLs and environment variables\n\n## Preferences\n\n- Avoid axios, prefer expo/fetch\n\n## Common Issues & Solutions\n\n### 1. Basic Fetch Usage\n\n**Simple GET request**:\n\n```tsx\nconst fetchUser = async (userId: string) => {\n  const response = await fetch(`https://api.example.com/users/${userId}`);\n\n  if (!response.ok) {\n    throw new Error(`HTTP error! status: ${response.status}`);\n  }\n\n  return response.json();\n};\n```\n\n**POST request with body**:\n\n```tsx\nconst createUser = async (userData: UserData) => {\n  const response = await fetch(\"https://api.example.com/users\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n      Authorization: `Bearer ${token}`,\n    },\n    body: JSON.stringify(userData),\n  });\n\n  if (!response.ok) {\n    const error = await response.json();\n    throw new Error(error.message);\n  }\n\n  return response.json();\n};\n```\n\n---\n\n### 2. React Query (TanStack Query)\n\n**Setup**:\n\n```tsx\n// app/_layout.tsx\nimport { QueryClient, QueryClientProvider } from \"@tanstack/react-query\";\n\nconst queryClient = new QueryClient({\n  defaultOptions: {\n    queries: {\n      staleTime: 1000 * 60 * 5, // 5 minutes\n      retry: 2,\n    },\n  },\n});\n\nexport default function RootLayout() {\n  return (\n    <QueryClientProvider client={queryClient}>\n      <Stack />\n    </QueryClientProvider>\n  );\n}\n```\n\n**Fetching data**:\n\n```tsx\nimport { useQuery } from \"@tanstack/react-query\";\n\nfunction UserProfile({ userId }: { userId: string }) {\n  const { data, isLoading, error, refetch } = useQuery({\n    queryKey: [\"user\", userId],\n    queryFn: () => fetchUser(userId),\n  });\n\n  if (isLoading) return <Loading />;\n  if (error) return <Error message={error.message} />;\n\n  return <Profile user={data} />;\n}\n```\n\n**Mutations**:\n\n```tsx\nimport { useMutation, useQueryClient } from \"@tanstack/react-query\";\n\nfunction CreateUserForm() {\n  const queryClient = useQueryClient();\n\n  const mutation = useMutation({\n    mutationFn: createUser,\n    onSuccess: () => {\n      // Invalidate and refetch\n      queryClient.invalidateQueries({ queryKey: [\"users\"] });\n    },\n  });\n\n  const handleSubmit = (data: UserData) => {\n    mutation.mutate(data);\n  };\n\n  return <Form onSubmit={handleSubmit} isLoading={mutation.isPending} />;\n}\n```\n\n---\n\n### 3. Error Handling\n\n**Comprehensive error handling**:\n\n```tsx\nclass ApiError extends Error {\n  constructor(message: string, public status: number, public code?: string) {\n    super(message);\n    this.name = \"ApiError\";\n  }\n}\n\nconst fetchWithErrorHandling = async (url: string, options?: RequestInit) => {\n  try {\n    const response = await fetch(url, options);\n\n    if (!response.ok) {\n      const error = await response.json().catch(() => ({}));\n      throw new ApiError(\n        error.message || \"Request failed\",\n        response.status,\n        error.code\n      );\n    }\n\n    return response.json();\n  } catch (error) {\n    if (error instanceof ApiError) {\n      throw error;\n    }\n    // Network error (no internet, timeout, etc.)\n    throw new ApiError(\"Network error\", 0, \"NETWORK_ERROR\");\n  }\n};\n```\n\n**Retry logic**:\n\n```tsx\nconst fetchWithRetry = async (\n  url: string,\n  options?: RequestInit,\n  retries = 3\n) => {\n  for (let i = 0; i < retries; i++) {\n    try {\n      return await fetchWithErrorHandling(url, options);\n    } catch (error) {\n      if (i === retries - 1) throw error;\n      // Exponential backoff\n      await new Promise((r) => setTimeout(r, Math.pow(2, i) * 1000));\n    }\n  }\n};\n```\n\n---\n\n### 4. Authentication\n\n**Token management**:\n\n```tsx\nimport * as SecureStore from \"expo-secure-store\";\n\nconst TOKEN_KEY = \"auth_token\";\n\nexport const auth = {\n  getToken: () => SecureStore.getItemAsync(TOKEN_KEY),\n  setToken: (token: string) => SecureStore.setItemAsync(TOKEN_KEY, token),\n  removeToken: () => SecureStore.deleteItemAsync(TOKEN_KEY),\n};\n\n// Authenticated fetch wrapper\nconst authFetch = async (url: string, options: RequestInit = {}) => {\n  const token = await auth.getToken();\n\n  return fetch(url, {\n    ...options,\n    headers: {\n      ...options.headers,\n      Authorization: token ? `Bearer ${token}` : \"\",\n    },\n  });\n};\n```\n\n**Token refresh**:\n\n```tsx\nlet isRefreshing = false;\nlet refreshPromise: Promise<string> | null = null;\n\nconst getValidToken = async (): Promise<string> => {\n  const token = await auth.getToken();\n\n  if (!token || isTokenExpired(token)) {\n    if (!isRefreshing) {\n      isRefreshing = true;\n      refreshPromise = refreshToken().finally(() => {\n        isRefreshing = false;\n        refreshPromise = null;\n      });\n    }\n    return refreshPromise!;\n  }\n\n  return token;\n};\n```\n\n---\n\n### 5. Offline Support\n\n**Check network status**:\n\n```tsx\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Hook for network status\nfunction useNetworkStatus() {\n  const [isOnline, setIsOnline] = useState(true);\n\n  useEffect(() => {\n    return NetInfo.addEventListener((state) => {\n      setIsOnline(state.isConnected ?? true);\n    });\n  }, []);\n\n  return isOnline;\n}\n```\n\n**Offline-first with React Query**:\n\n```tsx\nimport { onlineManager } from \"@tanstack/react-query\";\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Sync React Query with network status\nonlineManager.setEventListener((setOnline) => {\n  return NetInfo.addEventListener((state) => {\n    setOnline(state.isConnected ?? true);\n  });\n});\n\n// Queries will pause when offline and resume when online\n```\n\n---\n\n### 6. Environment Variables\n\n**Using environment variables for API configuration**:\n\nExpo supports environment variables with the `EXPO_PUBLIC_` prefix. These are inlined at build time and available in your JavaScript code.\n\n```tsx\n// .env\nEXPO_PUBLIC_API_URL=https://api.example.com\nEXPO_PUBLIC_API_VERSION=v1\n\n// Usage in code\nconst API_URL = process.env.EXPO_PUBLIC_API_URL;\n\nconst fetchUsers = async () => {\n  const response = await fetch(`${API_URL}/users`);\n  return response.json();\n};\n```\n\n**Environment-specific configuration**:\n\n```tsx\n// .env.development\nEXPO_PUBLIC_API_URL=http://localhost:3000\n\n// .env.production\nEXPO_PUBLIC_API_URL=https://api.production.com\n```\n\n**Creating an API client with environment config**:\n\n```tsx\n// api/client.ts\nconst BASE_URL = process.env.EXPO_PUBLIC_API_URL;\n\nif (!BASE_URL) {\n  throw new Error(\"EXPO_PUBLIC_API_URL is not defined\");\n}\n\nexport const apiClient = {\n  get: async <T,>(path: string): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`);\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n\n  post: async <T,>(path: string, body: unknown): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(body),\n    });\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n};\n```\n\n**Important notes**:\n\n- Only variables prefixed with `EXPO_PUBLIC_` are exposed to the client bundle\n- Never put secrets (API keys with write access, database passwords) in `EXPO_PUBLIC_` variables—they''re visible in the built app\n- Environment variables are inlined at **build time**, not runtime\n- Restart the dev server after changing `.env` files\n- For server-side secrets in API routes, use variables without the `EXPO_PUBLIC_` prefix\n\n**TypeScript support**:\n\n```tsx\n// types/env.d.ts\ndeclare global {\n  namespace NodeJS {\n    interface ProcessEnv {\n      EXPO_PUBLIC_API_URL: string;\n      EXPO_PUBLIC_API_VERSION?: string;\n    }\n  }\n}\n\nexport {};\n```\n\n---\n\n### 7. Request Cancellation\n\n**Cancel on unmount**:\n\n```tsx\nuseEffect(() => {\n  const controller = new AbortController();\n\n  fetch(url, { signal: controller.signal })\n    .then((response) => response.json())\n    .then(setData)\n    .catch((error) => {\n      if (error.name !== \"AbortError\") {\n        setError(error);\n      }\n    });\n\n  return () => controller.abort();\n}, [url]);\n```\n\n**With React Query** (automatic):\n\n```tsx\n// React Query automatically cancels requests when queries are invalidated\n// or components unmount\n```\n\n---\n\n## Decision Tree\n\n```\nUser asks about networking\n  |-- Basic fetch?\n  |   \\-- Use fetch API with error handling\n  |\n  |-- Need caching/state management?\n  |   |-- Complex app -> React Query (TanStack Query)\n  |   \\-- Simpler needs -> SWR or custom hooks\n  |\n  |-- Authentication?\n  |   |-- Token storage -> expo-secure-store\n  |   \\-- Token refresh -> Implement refresh flow\n  |\n  |-- Error handling?\n  |   |-- Network errors -> Check connectivity first\n  |   |-- HTTP errors -> Parse response, throw typed errors\n  |   \\-- Retries -> Exponential backoff\n  |\n  |-- Offline support?\n  |   |-- Check status -> NetInfo\n  |   \\-- Queue requests -> React Query persistence\n  |\n  |-- Environment/API config?\n  |   |-- Client-side URLs -> EXPO_PUBLIC_ prefix in .env\n  |   |-- Server secrets -> Non-prefixed env vars (API routes only)\n  |   \\-- Multiple environments -> .env.development, .env.production\n  |\n  \\-- Performance?\n      |-- Caching -> React Query with staleTime\n      |-- Deduplication -> React Query handles this\n      \\-- Cancellation -> AbortController or React Query\n```\n\n## Common Mistakes\n\n**Wrong: No error handling**\n\n```tsx\nconst data = await fetch(url).then((r) => r.json());\n```\n\n**Right: Check response status**\n\n```tsx\nconst response = await fetch(url);\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst data = await response.json();\n```\n\n**Wrong: Storing tokens in AsyncStorage**\n\n```tsx\nawait AsyncStorage.setItem(\"token\", token); // Not secure!\n```\n\n**Right: Use SecureStore for sensitive data**\n\n```tsx\nawait SecureStore.setItemAsync(\"token\", token);\n```\n\n## Example Invocations\n\nUser: \"How do I make API calls in React Native?\"\n-> Use fetch, wrap with error handling\n\nUser: \"Should I use React Query or SWR?\"\n-> React Query for complex apps, SWR for simpler needs\n\nUser: \"My app needs to work offline\"\n-> Use NetInfo for status, React Query persistence for caching\n\nUser: \"How do I handle authentication tokens?\"\n-> Store in expo-secure-store, implement refresh flow\n\nUser: \"API calls are slow\"\n-> Check caching strategy, use React Query staleTime\n\nUser: \"How do I configure different API URLs for dev and prod?\"\n-> Use EXPO*PUBLIC* env vars with .env.development and .env.production files\n\nUser: \"Where should I put my API key?\"\n-> Client-safe keys: EXPO*PUBLIC* in .env. Secret keys: non-prefixed env vars in API routes only\n"},"lastSynced":"2026-03-06T06:35:41.082Z","agentAnalysis":{"suitability":{"en":"Perfect for Expo Networking Agents needing efficient data fetching and caching capabilities.","zh":"非常适合需要高效数据获取和缓存能力的Expo网络代理。","ja":"Expoネットワーキングエージェントが効率的なデータ取得とキャッシュ機能を必要とする場合に最適です。","ko":"효율적인 데이터 가져오기 및 캐싱 기능이 필요한 Expo 네트워킹 에이전트에 적합합니다.","es":"Perfecto para Agentes de Red de Expo que necesitan capacidades de recolección y almacenamiento en caché de datos eficientes.","fr":"Parfait pour les agents de réseau Expo nécessitant des capacités de récupération et de mise en cache de données efficaces.","de":"Perfekt für Expo-Netzwerkagenten, die effiziente Datenabruf- und Cachefunktionen benötigen.","pt":"Perfeito para Agentes de Rede Expo que precisam de capacidades de busca e cache de dados eficientes.","ru":"Идеально подходит для агентов сети Expo, которым необходимы эффективные возможности получения и кэширования данных.","ar":"مثالي لأعضاء وكالات الشبكة التي تحتاج إلى قدرات استرجاع البيانات وتخزينها المؤقتة الفعالة."},"recommendation":{"en":"Empowers agents to handle API requests, implement caching strategies, and manage UTXO and signing using React Query or SWR, with a preference for expo/fetch over axios, enabling seamless data fetching and network debugging.","zh":"赋予代理处理API请求、实现缓存策略和使用React Query或SWR管理UTXO和签名的能力，优先使用expo/fetch而不是axios，从而实现无缝的数据获取和网络调试。","ja":"APIリクエストの処理、キャッシュ戦略の実装、React QueryまたはSWRを使用したUTXOと署名の管理をエージェントに可能にし、expo/fetchをaxiosより優先して無停止のデータ取得とネットワークデバッグを可能にします。","ko":"API 요청 처리, 캐싱 전략 구현 및 React Query 또는 SWR을 사용한 UTXO 및 서명의 관리를 에이전트에 가능하게 하며, axios보다 expo/fetch를 우선하여 무중단 데이터 가져오기 및 네트워크 디버깅을 가능하게 합니다.","es":"Habilita a los agentes a manejar solicitudes de API, implementar estrategias de caché y administrar UTXO y firma utilizando React Query o SWR, con preferencia por expo/fetch sobre axios, lo que permite una recuperación y depuración de red de datos sin problemas.","fr":"Permet aux agents de gérer les requêtes API, de mettre en œuvre des stratégies de mise en cache et de gérer UTXO et la signature en utilisant React Query ou SWR, avec une préférence pour expo/fetch plutôt que axios, permettant ainsi une récupération et un débogage de réseau de données sans heurts.","de":"Ermöglicht es Agenten, API-Anfragen zu verarbeiten, Cachestrategien zu implementieren und UTXO und Signierung mit React Query oder SWR zu verwalten, wobei expo/fetch bevorzugt wird, anstatt axios, was eine nahtlose Datenabruf und Netzwerksdebugging ermöglicht.","pt":"Habilita os agentes a lidar com solicitações de API, implementar estratégias de cache e gerenciar UTXO e assinatura usando React Query ou SWR, com preferência por expo/fetch em vez de axios, permitindo busca e depuração de rede sem problemas.","ru":"Наделяет агентов возможностью обрабатывать запросы API, реализовывать стратегии кэширования и управлять UTXO и подписью с помощью React Query или SWR, с предпочтением expo/fetch вместо axios, обеспечивая бесперебойную получение данных и отладку сети.","ar":"تمكّن الوكالات من التعامل مع طلبات API وتنفيذ استراتيجيات التخزين المؤقت وإدارة UTXO والتوقيع باستخدام React Query أو SWR، مع تفضيل expo/fetch على axios، وتمكين استرجاع البيانات وتحسين الشبكة بسلاسة."},"useCases":{"en":["Implementing API requests with environment variable configuration","Setting up data fetching and caching using React Query or SWR","Debugging network failures and handling offline scenarios","Managing authentication and token validation"],"zh":["使用环境变量配置实现API请求","使用React Query或SWR设置数据获取和缓存","调试网络故障和处理离线场景","管理身份验证和令牌验证"],"ja":["環境変数の設定を使用したAPIリクエストの実装","React QueryまたはSWRを使用したデータ取得とキャッシュの設定","ネットワーク障害のデバッグとオフラインシナリオの処理","認証とトークン検証の管理"],"ko":["환경 변수 구성으로 API 요청 구현","React Query 또는 SWR을 사용한 데이터 가져오기 및 캐싱 설정","네트워크 오류 디버깅 및 오프라인 시나리오 처리","인증 및 토큰 확인 관리"],"es":["Implementación de solicitudes de API con configuración de variables de entorno","Configuración de la recuperación y el almacenamiento en caché de datos utilizando React Query o SWR","Depuración de fallos de red y manejo de escenarios sin conexión","Administración de autenticación y validación de tokens"],"fr":["Mise en œuvre des requêtes API avec configuration de variables d''environnement","Configuration de la récupération et de la mise en cache de données en utilisant React Query ou SWR","Débogage des défaillances réseau et gestion des scénarios hors ligne","Gestion de l''authentification et de la validation des jetons"],"de":["Implementierung von API-Anfragen mit Umgebungsvariablenkonfiguration","Einrichtung der Datenabruf und Cachefunktionen mit React Query oder SWR","Fehlerbehebung bei Netzwerkausfällen und Handhabung von Offline-Szenarien","Verwaltung der Authentifizierung und Token-Validierung"],"pt":["Implementação de solicitações de API com configuração de variáveis de ambiente","Configuração de busca e cache de dados usando React Query ou SWR","Depuração de falhas de rede e tratamento de cenários offline","Gerenciamento de autenticação e validação de token"],"ru":["Реализация запросов API с настройкой переменных окружения","Настройка получения и кэширования данных с помощью React Query или SWR","Отладка сбоев сети и обработка офлайн-сценариев","Управление аутентификацией и проверкой токена"],"ar":["تنفيذ طلبات API مع تكوين متغيرات البيئة","تهيئة استرجاع البيانات وتخزينها المؤقت باستخدام React Query أو SWR","تصحيح عطال الشبكة ومعالجة السيناريوهات دون اتصال","إدارة المصادقة وتصديق العلامة"]},"limitations":{"en":["Requires Expo networking project setup","Prefer expo/fetch over axios for requests"],"zh":["需要Expo网络项目设置","优先使用expo/fetch而不是axios进行请求"],"ja":["Expoネットワーキングプロジェクトの設定が必要","リクエストにはaxiosよりもexpo/fetchを優先する"],"ko":["Expo 네트워킹 프로젝트 설정이 필요","요청时 expo/fetch를 axios보다 우선"],"es":["Requiere configuración de proyecto de red de Expo","Preferencia por expo/fetch sobre axios para solicitudes"],"fr":["Nécessite une configuration de projet de réseau Expo","Préférence pour expo/fetch plutôt que axios pour les requêtes"],"de":["Erfordert Expo-Netzwerkprojektsetup","Bevorzugt expo/fetch gegenüber axios für Anfragen"],"pt":["Exige configuração do projeto de rede Expo","Preferência por expo/fetch em vez de axios para solicitações"],"ru":["Требует настройки проекта сети Expo","Предпочтение expo/fetch вместо axios для запросов"],"ar":["يتطلب إعداد مشروع شبكة Expo","التفضيل لاستخدام expo/fetch بدلاً من axios لطلبات الشبكة"]},"version":4},"contentHash":"b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be","qualityScore":58}');
