INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vamseeachanta/workspace-hub/geotechnical-engineering', 'geotechnical-engineering', 'vamseeachanta', 'workspace-hub', 'community', 'geotechnical-engineering vamseeachanta workspace-hub community 一个用于管理多个GitHub仓库的集中管理系统，具有模块化组织功能 複数のGitHubリポジトリを管理するための集中管理システムで、モジュラー化された組織機能を備えています 여러 개의 깃허브 리포지토리를 관리하기 위한集中 관리 시스템으로, 모듈화된 조직 기능을 제공 Nuestro sistema de gestión centralizado para múltiples repositorios de GitHub ofrece una organización modular para ingenieros geotécnicos Notre système de gestion centralisé pour plusieurs dépôts GitHub propose une organisation modulaire pour les ingénieurs géotechniques Unser zentrales Managementsystem für mehrere GitHub-Repositorys bietet eine modulare Organisation für Geotechnik-Ingenieure O geotechnical-engineering é uma solução de gestão centralizada para múltiplos repositórios GitHub com organização modular Геотехническая инженерия - это централизованная система управления для нескольких репозиториев GitHub с модульной организацией الهندسة الجيوتكنيكية هي نظام إدارة مركزي لمستودعات GitHub المتعددة مع تنظيم معماري A centralized management system for multiple GitHub repositories with modular organization AI智能代理 GitHub仓库管理 模块化组织 集中管理 多用户协作 仓库监控 自定义工作流 如何使用AI智能代理 AI智能代理安装指南 A centralized management system for multiple GitHub repositories with modular organization');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/brand-guidelines', 'official', 'anthropics', 'skills', 'anthropics/skills', 'brand-guidelines', 85097, 8974, 58, '2026-03-06T03:11:21Z', '2026-03-06T03:13:22.193Z', '1120b3769e2985cefb3d25be981b1f914abeba57ae079b83c20c666c164fa9fe', '{"id":"anthropics/skills/brand-guidelines","name":"brand-guidelines","description":{"en":"This AI Agent skill programmatically applies Anthropic''s official brand colors and typography to artifacts, ensuring compliance with corporate design standards. It is designed for developers and AI agents who need to generate on-brand visual content and formatted materials.","zh":"Anthropic品牌指南技能用于应用官方品牌颜色和字体样式，实现一致的视觉风格","ja":"Anthropicブランドガイドラインスキルは公式ブランドカラーとフォントスタイルを適用して一貫したビジュアルスタイルを実現","ko":"Anthropic 브랜드 가이드라인 스킬은 공식 브랜드 색상과 글꼴 스타일을 적용하여 일관된 시각적 스타일을 구현","es":"Esta skill de agente de IA aplica automáticamente las pautas de marca de Anthropic, incluyendo sus colores oficiales (como #141413 y #faf9f5) y tipografía, a cualquier artefacto que requiera el look-and-feel corporativo para un procesamiento visual consistente.","fr":"Cette compétence d''agent IA applique automatiquement les directives de marque d''Anthropic, y compris ses couleurs officielles (comme #141413 et #faf9f5) et sa typographie, à tout artefact nécessitant l''aspect corporate pour un traitement visuel cohérent.","de":"Diese KI-Agenten-Fähigkeit wendet automatisch die Markenrichtlinien von Anthropic an, einschließlich der offiziellen Farben (wie #141413 und #faf9f5) und Typografie, auf alle Artefakte, die das Corporate Look-and-Feel für eine konsistente visuelle Verarbeitung benötigen.","pt":"Este skill de agente de IA aplica automaticamente as diretrizes de marca da Anthropic, incluindo cores primárias (#141413, #faf9f5) e tipografia, a qualquer artefato que necessite da identidade visual corporativa. Ideal para padronização de design em projetos técnicos.","ru":"Этот навык ИИ агента автоматически применяет бренд-гайдлайны Anthropic, включая основные цвета (#141413, #faf9f5) и типографику, к любым артефактам, требующим корпоративной идентичности. Идеален для стандартизации дизайна в технических проектах.","ar":"تطبق مهارة وكيل الذكاء الاصطناعي هذه تلقائيًا إرشادات العلامة التجارية لـ Anthropic، بما في ذلك الألوان الأساسية (#141413, #faf9f5) وأنماط Typography، على أي قطعة أثرية تحتاج إلى هوية بصرية مؤسسية. مثالي لتوحيد التصميم في المشاريع التقنية."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"brand-guidelines","description":"Applies Anthropics official brand colors and typography to any sort of artifact that may benefit from having Anthropics look-and-feel. Use it when brand colors or style guidelines, visual formatting, or company design standards apply.","bodyPreview":"# Anthropic Brand Styling\n\n## Overview\n\nTo access Anthropic''s official brand identity and style resources, use this skill.\n\n**Keywords**: branding, corporate identity, visual identity, post-processing, styling, brand colors, typography, Anthropic brand, visual formatting, visual design\n\n## Brand Guidelines\n\n### Colors\n\n**Main Colors:**\n\n- Dark: `#141413` - Primary text and dark backgrounds\n- Light: `#faf9f5` - Light backgrounds and text on dark\n- Mid Gray: `#b0aea5` - Secondary elements\n- Light","body":"# Anthropic Brand Styling\n\n## Overview\n\nTo access Anthropic''s official brand identity and style resources, use this skill.\n\n**Keywords**: branding, corporate identity, visual identity, post-processing, styling, brand colors, typography, Anthropic brand, visual formatting, visual design\n\n## Brand Guidelines\n\n### Colors\n\n**Main Colors:**\n\n- Dark: `#141413` - Primary text and dark backgrounds\n- Light: `#faf9f5` - Light backgrounds and text on dark\n- Mid Gray: `#b0aea5` - Secondary elements\n- Light Gray: `#e8e6dc` - Subtle backgrounds\n\n**Accent Colors:**\n\n- Orange: `#d97757` - Primary accent\n- Blue: `#6a9bcc` - Secondary accent\n- Green: `#788c5d` - Tertiary accent\n\n### Typography\n\n- **Headings**: Poppins (with Arial fallback)\n- **Body Text**: Lora (with Georgia fallback)\n- **Note**: Fonts should be pre-installed in your environment for best results\n\n## Features\n\n### Smart Font Application\n\n- Applies Poppins font to headings (24pt and larger)\n- Applies Lora font to body text\n- Automatically falls back to Arial/Georgia if custom fonts unavailable\n- Preserves readability across all systems\n\n### Text Styling\n\n- Headings (24pt+): Poppins font\n- Body text: Lora font\n- Smart color selection based on background\n- Preserves text hierarchy and formatting\n\n### Shape and Accent Colors\n\n- Non-text shapes use accent colors\n- Cycles through orange, blue, and green accents\n- Maintains visual interest while staying on-brand\n\n## Technical Details\n\n### Font Management\n\n- Uses system-installed Poppins and Lora fonts when available\n- Provides automatic fallback to Arial (headings) and Georgia (body)\n- No font installation required - works with existing system fonts\n- For best results, pre-install Poppins and Lora fonts in your environment\n\n### Color Application\n\n- Uses RGB color values for precise brand matching\n- Applied via python-pptx''s RGBColor class\n- Maintains color fidelity across different systems\n"},"category":"official","lastSynced":"2026-03-06T03:13:22.193Z","seo":{"title":{"en":"brand-guidelines: Apply Official Anthropic Styling | AI A...","zh":"Anthropic品牌指南设置指南 - AI智能工具","ja":"Anthropicブランドガイドラインの設定方法 - AIエージェント","ko":"Anthropic 브랜드 가이드라인 설정 가이드 - AI 에이전트","es":"Anthropic Brand Guidelines: Guía de Implementación Técnica","fr":"Anthropic Brand Guidelines : Guide de Configuration Techn...","de":"Anthropic Brand Guidelines: Technische Einrichtungsanleitung","pt":"brand-guidelines: Guia de Implementação para Cores e Tipo...","ru":"brand-guidelines: Руководство по использованию фирменного...","ar":"brand-guidelines: دليل إرشادي لتطبيق ألوان وأنماط Typogra..."},"description":{"en":"Integrate Anthropic''s official brand identity into your projects. This AI Agent skill applies the exact #141413 dark color, #faf9f5 light color, and typograp...","zh":"实现Anthropic官方品牌身份和样式资源的访问，使用品牌指南技能实现一致的视觉风格","ja":"Anthropic公式ブランドアイデンティティとスタイルリソースへのアクセスを実現するブランドガイドラインスキル","ko":"Anthropic 공식 브랜드 아이덴티티와 스타일 리소스에 대한 액세스를 제공하는 브랜드 가이드라인 스킬","es":"Aplica la identidad visual oficial de Anthropic (#141413, #faf9f5) a tus artefactos. Herramienta de IA para automatizar el branding y el diseño visual con co...","fr":"Appliquez l''identité visuelle officielle d''Anthropic (#141413, #faf9f5) à vos artefacts. Outil d''IA pour automatiser le branding et le design visuel avec les...","de":"Wenden Sie die offizielle visuelle Identität von Anthropic (#141413, #faf9f5) auf Ihre Artefakte an. KI-Tool zur Automatisierung von Branding und visuellem D...","pt":"Aprenda a aplicar as cores oficiais da Anthropic (#141413, #faf9f5, #b0aea5) e diretrizes de tipografia em seus projetos. Este skill de agente de IA automati...","ru":"Научитесь применять официальные цвета Anthropic (#141413, #faf9f5, #b0aea5) и типографику в ваших проектах. Этот навык ИИ агента автоматизирует визуальное оф...","ar":"تعلم كيفية تطبيق الألوان الرسمية لـ Anthropic (#141413, #faf9f5, #b0aea5) وإرشادات Typography في مشاريعك. مهارة وكيل الذكاء الاصطناعي هذه تؤتمت الهوية البصري..."},"definition":{"en":"brand-guidelines is an AI Agent skill that provides access to and applies Anthropic''s official brand identity resources, including specific hex color codes and typography, to ensure visual artifacts conform to the company''s design standards.","zh":"Anthropic品牌指南是一种实现官方品牌身份和样式资源访问的技能","ja":"Anthropicブランドガイドラインは公式ブランドアイデンティティとスタイルリソースへのアクセスを実現するスキル","ko":"Anthropic 브랜드 가이드라인은 공식 브랜드 아이덴티티와 스타일 리소스에 대한 액세스를 제공하는 스킬","es":"La skill ''brand-guidelines'' es una herramienta de agente de IA que aplica la identidad visual oficial de Anthropic. Automatiza el uso de colores de marca específicos (p. ej., #141413), tipografía y estándares de diseño para garantizar un post-procesamiento visual coherente en diversos artefactos.","fr":"La compétence ''brand-guidelines'' est un outil d''agent IA qui applique l''identité visuelle officielle d''Anthropic. Elle automatise l''utilisation de couleurs de marque spécifiques (ex: #141413), de la typographie et des normes de conception pour assurer un post-traitement visuel cohérent sur divers artefacts.","de":"Die ''brand-guidelines''-Fähigkeit ist ein KI-Agenten-Tool, das die offizielle visuelle Identität von Anthropic anwendet. Es automatisiert die Verwendung spezifischer Markenfarben (z.B. #141413), Typografie und Designstandards, um eine konsistente visuelle Nachbearbeitung auf verschiedenen Artefakten zu gewährleisten.","pt":"brand-guidelines é um skill de agente de IA que aplica automaticamente a identidade visual oficial da Anthropic, incluindo cores corporativas específicas (#141413, #faf9f5, #b0aea5) e diretrizes de tipografia, para garantir conformidade com os padrões de design em artefatos técnicos.","ru":"brand-guidelines — это навык ИИ агента, который автоматически применяет официальный визуальный стиль Anthropic, включая корпоративные цвета (#141413, #faf9f5, #b0aea5) и руководства по типографике, для обеспечения соответствия стандартам дизайна в технических артефактах.","ar":"brand-guidelines هي مهارة لوكيل الذكاء الاصطناعي تطبق تلقائيًا الهوية البصرية الرسمية لـ Anthropic، بما في ذلك الألوان المؤسسية المحددة (#141413, #faf9f5, #b0aea5) وإرشادات Typography، لضمان الامتثال لمعايير التصميم في القطع الأثرية التقنية."},"features":{"en":["Applies the official Anthropic dark color (#141413) for primary text and dark backgrounds","Applies the official Anthropic light color (#faf9f5) for light backgrounds and text on dark","Uses mid gray (#b0aea5) for styling secondary visual elements","Enforces corporate brand identity and visual design standards on artifacts"],"zh":["支持Dark、Light、Mid Gray三种主要颜色","应用官方品牌字体样式","实现一致的视觉风格","支持Post-processing和Styling","提供Visual Formatting和Visual Design功能"],"ja":["Dark、Light、Mid Grayの3つのメインカラーをサポート","公式ブランドフォントスタイルを適用","一貫したビジュアルスタイルを実現","Post-processingとStylingをサポート","Visual FormattingとVisual Design機能を提供"],"ko":["Dark, Light, Mid Gray 3가지 주요 색상을 지원","공식 브랜드 글꼴 스타일을 적용","일관된 시각적 스타일을 구현","Post-processing과 Styling을 지원","Visual Formatting과 Visual Design 기능을 제공"],"es":["Aplica la paleta de colores oficial de Anthropic, incluyendo el Dark #141413 y Light #faf9f5.","Implementa automáticamente la tipografía corporativa definida en las directrices de marca.","Proporciona un post-procesamiento visual consistente para diversos artefactos.","Garantiza el cumplimiento de los estándares de identidad visual y diseño de Anthropic.","Automatiza la aplicación del look-and-feel de la marca para ahorrar tiempo en diseño."],"fr":["Applique la palette de couleurs officielle d''Anthropic, incluant le Dark #141413 et le Light #faf9f5.","Implémente automatiquement la typographie corporate définie dans les directives de marque.","Fournit un post-traitement visuel cohérent pour divers artefacts.","Garantit le respect des standards d''identité visuelle et de conception d''Anthropic.","Automatise l''application du look-and-feel de la marque pour gagner du temps en conception."],"de":["Wendet die offizielle Farbpalette von Anthropic an, einschließlich Dark #141413 und Light #faf9f5.","Implementiert automatisch die in den Markenrichtlinien definierte Corporate Typografie.","Ermöglicht eine konsistente visuelle Nachbearbeitung für verschiedene Artefakte.","Stellt die Einhaltung der visuellen Identitäts- und Designstandards von Anthropic sicher.","Automatisiert die Anwendung des Marken-Look-and-Feel, um Zeit beim Design zu sparen."],"pt":["Aplicação automática da cor primária escura da Anthropic (#141413) para texto e fundos","Implementação da cor de fundo clara oficial (#faf9f5) para elementos de interface","Uso do Mid Gray (#b0aea5) para elementos secundários e realces","Integração das diretrizes de tipografia corporativa da Anthropic","Processamento pós-produção para conformidade com identidade visual","Padronização de formatação visual em artefatos técnicos diversos"],"ru":["Автоматическое применение темного основного цвета Anthropic (#141413) для текста и фонов","Реализация официального светлого фона (#faf9f5) для элементов интерфейса","Использование Mid Gray (#b0aea5) для вторичных элементов и акцентов","Интеграция корпоративных руководств по типографике Anthropic","Пост-обработка для обеспечения соответствия визуальному стилю","Стандартизация визуального форматирования в различных технических артефактах"],"ar":["تطبيق تلقائي للون الأساسي الغامق لـ Anthropic (#141413) للنص والخلفيات","تنفيذ الخلفية الفاتحة الرسمية (#faf9f5) لعناصر الواجهة","استخدام الرمادي المتوسط (#b0aea5) للعناصر الثانوية والتأكيدات","دمج إرشادات Typography المؤسسية لـ Anthropic","معالجة لاحقة لضمان الامتثال للهوية البصرية","توحيد التنسيق المرئي في القطع الأثرية التقنية المختلفة"]},"keywords":{"en":["how to use anthropic brand guidelines","what is brand-guidelines ai skill","brand-guidelines vs manual styling","anthropic brand colors hex codes","brand-guidelines setup for AI agents","implement anthropic visual identity","brand-guidelines install guide","anthropic corporate identity standards"],"zh":["AI智能工具","品牌指南","Anthropic品牌","视觉风格","品牌身份","Post-processing","Styling","Visual Formatting","Visual Design"],"ja":["AIエージェント","ブランドガイドライン","Anthropicブランド","ビジュアルスタイル","ブランドアイデンティティ","Post-processing","Styling","Visual Formatting","Visual Design"],"ko":["AI 에이전트","브랜드 가이드라인","Anthropic 브랜드","시각적 스타일","브랜드 아이덴티티","Post-processing","Styling","Visual Formatting","Visual Design"],"es":["Anthropic brand guidelines skill","aplicar colores de marca Anthropic","automatizar identidad visual IA","post-procesamiento visual #141413","herramienta de agente de IA para branding","tipografía corporativa Anthropic","estándares de diseño Anthropic","look-and-feel Anthropic automático"],"fr":["compétence Anthropic brand guidelines","appliquer couleurs de marque Anthropic","automatiser identité visuelle IA","post-traitement visuel #141413","outil agent IA pour branding","typographie corporate Anthropic","normes de conception Anthropic","look-and-feel Anthropic automatique"],"de":["Anthropic brand guidelines Fähigkeit","Anthropic Markenfarben anwenden","visuelle Identität KI automatisieren","visuelle Nachbearbeitung #141413","KI-Agenten Tool für Branding","Corporate Typografie Anthropic","Designstandards Anthropic","automatisches Anthropic Look-and-Feel"],"pt":["skill agentes IA brand guidelines","cores Anthropic #141413 #faf9f5","tipografia marca Anthropic","identidade visual automática","post-processing styling AI","formatação visual corporativa","padrões design Anthropic","automação identidade visual"],"ru":["навык ИИ агенты бренд гайдлайны","цвета Anthropic #141413 #faf9f5","типографика бренд Anthropic","автоматическая визуальная идентичность","пост-обработка стилизация ИИ","корпоративное визуальное форматирование","стандарты дизайна Anthropic","автоматизация визуального стиля"],"ar":["مهارة وكلاء الذكاء الاصطناعي إرشادات العلامة التجارية","ألوان Anthropic #141413 #faf9f5","Typography العلامة التجارية Anthropic","هوية بصرية تلقائية","معالجة لاحقة للتنسيق بالذكاء الاصطناعي","تنسيق مرئي مؤسسي","معايير تصميم Anthropic","أتمتة الهوية البصرية"]}},"agentAnalysis":{"suitability":{"en":"Essential for Content Generation Agents that require strict adherence to Anthropic''s official visual identity standards.","zh":"对于需要严格遵守Anthropic官方视觉识别标准的Content Generation Agents至关重要。","ja":"Anthropicの公式ビジュアルアイデンティティ基準を厳密に遵守する必要があるContent Generation Agentsに不可欠です。","ko":"Anthropic의 공식 시각적 아이덴티티 기준을 엄격히 준수해야 하는 Content Generation Agents에 필수적입니다.","es":"Esencial para los Agentes de Generación de Contenido que requieren una adherencia estricta a los estándares oficiales de identidad visual de Anthropic.","fr":"Essentiel pour les Agents de Génération de Contenu qui nécessitent une adhésion stricte aux standards officiels d''identité visuelle d''Anthropic.","de":"Essenziell für Content-Generation-Agents, die eine strikte Einhaltung der offiziellen visuellen Identitätsstandards von Anthropic erfordern.","pt":"Essencial para Agentes de Geração de Conteúdo que requerem adesão estrita aos padrões oficiais de identidade visual da Anthropic.","ru":"Необходим для Агентов Генерации Контента, которые требуют строгого соблюдения официальных стандартов визуального стиля Anthropic.","ar":"أساسي لوكلاء توليد المحتوى الذين يتطلبون الالتزام الصارم بمعايير الهوية البصرية الرسمية لـ Anthropic."},"recommendation":{"en":"Applies Anthropic''s official brand colors (#141413, #faf9f5, #b0aea5) and typography to artifacts requiring corporate identity compliance, ensuring consistent visual formatting across all generated materials.","zh":"将Anthropic官方品牌颜色（#141413、#faf9f5、#b0aea5）和排版应用于需要企业身份合规的工件，确保所有生成材料具有一致的视觉格式。","ja":"企業アイデンティティ準拠が必要なアーティファクトにAnthropicの公式ブランドカラー（#141413、#faf9f5、#b0aea5）とタイポグラフィを適用し、生成されるすべての資料で一貫した視覚的フォーマットを保証します。","ko":"기업 아이덴티티 준수가 필요한 아티팩트에 Anthropic의 공식 브랜드 색상(#141413, #faf9f5, #b0aea5)과 타이포그래피를 적용하여 모든 생성 자료에서 일관된 시각적 형식을 보장합니다.","es":"Aplica los colores oficiales de la marca de Anthropic (#141413, #faf9f5, #b0aea5) y la tipografía a los artefactos que requieren cumplimiento de identidad corporativa, asegurando un formato visual consistente en todos los materiales generados.","fr":"Applique les couleurs officielles de la marque Anthropic (#141413, #faf9f5, #b0aea5) et la typographie aux artefacts nécessitant une conformité d''identité d''entreprise, garantissant un formatage visuel cohérent sur tous les matériaux générés.","de":"Wendet die offiziellen Markenfarben von Anthropic (#141413, #faf9f5, #b0aea5) und Typografie auf Artefakte an, die Corporate-Identity-Konformität erfordern, und gewährleistet so eine konsistente visuelle Formatierung über alle generierten Materialien hinweg.","pt":"Aplica as cores oficiais da marca Anthropic (#141413, #faf9f5, #b0aea5) e tipografia a artefatos que requerem conformidade com a identidade corporativa, garantindo formatação visual consistente em todos os materiais gerados.","ru":"Применяет официальные цвета бренда Anthropic (#141413, #faf9f5, #b0aea5) и типографику к артефактам, требующим соответствия корпоративному стилю, обеспечивая согласованное визуальное форматирование всех генерируемых материалов.","ar":"يطبق الألوان الرسمية لعلامة Anthropic التجارية (#141413, #faf9f5, #b0aea5) والطباعة على العناصر التي تتطلب الامتثال للهوية المؤسسية، مما يضمن تنسيقًا مرئيًا متسقًا عبر جميع المواد المُنشأة."},"useCases":{"en":["Styling documentation with official brand colors","Formatting presentations with corporate identity guidelines","Applying visual design standards to generated reports","Post-processing content with Anthropic''s look-and-feel"],"zh":["使用官方品牌颜色设置文档样式","按照企业身份指南格式化演示文稿","将视觉设计标准应用于生成的报告","使用Anthropic的外观进行内容后处理"],"ja":["公式ブランドカラーを使用したドキュメントのスタイリング","企業アイデンティティガイドラインに基づくプレゼンテーションのフォーマット","生成されたレポートへの視覚デザイン基準の適用","Anthropicのルックアンドフィールによるコンテンツの後処理"],"ko":["공식 브랜드 색상으로 문서 스타일링","기업 아이덴티티 가이드라인에 따른 프레젠테이션 서식 지정","생성된 보고서에 시각 디자인 기준 적용","Anthropic의 Look-and-Feel로 콘텐츠 후처리"],"es":["Aplicar estilos a la documentación con los colores oficiales de la marca","Dar formato a presentaciones con las directrices de identidad corporativa","Aplicar estándares de diseño visual a informes generados","Post-procesar contenido con el aspecto visual de Anthropic"],"fr":["Styliser la documentation avec les couleurs officielles de la marque","Formater des présentations selon les directives d''identité d''entreprise","Appliquer des standards de conception visuelle aux rapports générés","Post-traiter le contenu avec l''apparence et la sensation d''Anthropic"],"de":["Styling von Dokumentationen mit offiziellen Markenfarben","Formatieren von Präsentationen nach Corporate-Identity-Richtlinien","Anwenden von visuellen Designstandards auf generierte Berichte","Nachbearbeiten von Inhalten mit dem Look-and-Feel von Anthropic"],"pt":["Estilização de documentação com cores oficiais da marca","Formatação de apresentações com diretrizes de identidade corporativa","Aplicação de padrões de design visual a relatórios gerados","Pós-processamento de conteúdo com a aparência e sensação da Anthropic"],"ru":["Стилизация документации с использованием официальных цветов бренда","Форматирование презентаций в соответствии с руководством по корпоративному стилю","Применение стандартов визуального дизайна к генерируемым отчетам","Постобработка контента в соответствии с внешним видом Anthropic"],"ar":["تنسيق الوثائق بألوان العلامة التجارية الرسمية","تنسيق العروض التقديمية وفق إرشادات الهوية المؤسسية","تطبيق معايير التصميم المرئي على التقارير المُنشأة","معالجة المحتوى بعد إنشائه بمظهر وشعور Anthropic"]},"limitations":{"en":["Limited to Anthropic-specific brand guidelines","Requires artifacts to support visual formatting","Only provides predefined color and typography rules"],"zh":["仅限于Anthropic特定品牌指南","要求工件支持视觉格式","仅提供预定义的颜色和排版规则"],"ja":["Anthropic固有のブランドガイドラインに限定","視覚的フォーマットをサポートするアーティファクトが必要","事前定義された色とタイポグラフィルールのみを提供"],"ko":["Anthropic 전용 브랜드 가이드라인으로 제한됨","시각적 서식을 지원하는 아티팩트 필요","미리 정의된 색상 및 타이포그래피 규칙만 제공"],"es":["Limitado a las directrices de marca específicas de Anthropic","Requiere que los artefactos admitan formato visual","Solo proporciona reglas predefinidas de color y tipografía"],"fr":["Limité aux directives de marque spécifiques à Anthropic","Nécessite que les artefacts prennent en charge le formatage visuel","Fournit uniquement des règles prédéfinies de couleur et de typographie"],"de":["Beschränkt auf Anthropic-spezifische Markenrichtlinien","Erfordert, dass Artefakte visuelle Formatierung unterstützen","Bietet nur vordefinierte Farb- und Typografieregeln"],"pt":["Limitado às diretrizes de marca específicas da Anthropic","Requer que os artefatos suportem formatação visual","Fornece apenas regras predefinidas de cores e tipografia"],"ru":["Ограничено конкретными рекомендациями по бренду Anthropic","Требует, чтобы артефакты поддерживали визуальное форматирование","Предоставляет только предопределенные правила цветов и типографики"],"ar":["يقتصر على إرشادات العلامة التجارية المحددة لـ Anthropic","يتطلب أن تدعم العناصر التنسيق المرئي","يوفر فقط قواعد محددة مسبقًا للألوان والطباعة"]},"version":4},"contentHash":"1120b3769e2985cefb3d25be981b1f914abeba57ae079b83c20c666c164fa9fe","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":58}');
