INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/brand-guidelines', 'brand-guidelines', 'anthropics', 'skills', 'official', 'brand-guidelines anthropics skills official agent-skills This AI Agent skill programmatically applies Anthropic''s official brand colors and typography to artifacts, ensuring compliance with corporate design standards. It is designed for developers and AI agents who need to generate on-brand visual content and formatted materials. Anthropic品牌指南技能用于应用官方品牌颜色和字体样式，实现一致的视觉风格 Anthropicブランドガイドラインスキルは公式ブランドカラーとフォントスタイルを適用して一貫したビジュアルスタイルを実現 Anthropic 브랜드 가이드라인 스킬은 공식 브랜드 색상과 글꼴 스타일을 적용하여 일관된 시각적 스타일을 구현 Esta skill de agente de IA aplica automáticamente las pautas de marca de Anthropic, incluyendo sus colores oficiales (como #141413 y #faf9f5) y tipografía, a cualquier artefacto que requiera el look-and-feel corporativo para un procesamiento visual consistente. Cette compétence d''agent IA applique automatiquement les directives de marque d''Anthropic, y compris ses couleurs officielles (comme #141413 et #faf9f5) et sa typographie, à tout artefact nécessitant l''aspect corporate pour un traitement visuel cohérent. Diese KI-Agenten-Fähigkeit wendet automatisch die Markenrichtlinien von Anthropic an, einschließlich der offiziellen Farben (wie #141413 und #faf9f5) und Typografie, auf alle Artefakte, die das Corporate Look-and-Feel für eine konsistente visuelle Verarbeitung benötigen. Este skill de agente de IA aplica automaticamente as diretrizes de marca da Anthropic, incluindo cores primárias (#141413, #faf9f5) e tipografia, a qualquer artefato que necessite da identidade visual corporativa. Ideal para padronização de design em projetos técnicos. Этот навык ИИ агента автоматически применяет бренд-гайдлайны Anthropic, включая основные цвета (#141413, #faf9f5) и типографику, к любым артефактам, требующим корпоративной идентичности. Идеален для стандартизации дизайна в технических проектах. تطبق مهارة وكيل الذكاء الاصطناعي هذه تلقائيًا إرشادات العلامة التجارية لـ Anthropic، بما في ذلك الألوان الأساسية (#141413, #faf9f5) وأنماط Typography، على أي قطعة أثرية تحتاج إلى هوية بصرية مؤسسية. مثالي لتوحيد التصميم في المشاريع التقنية. how to use anthropic brand guidelines what is brand-guidelines ai skill brand-guidelines vs manual styling anthropic brand colors hex codes brand-guidelines setup for AI agents implement anthropic visual identity brand-guidelines install guide anthropic corporate identity standards AI智能工具 品牌指南 Anthropic品牌 视觉风格 品牌身份 Post-processing Styling Visual Formatting Visual Design Applies the official Anthropic dark color (#141413) for primary text and dark backgrounds Applies the official Anthropic light color (#faf9f5) for light backgrounds and text on dark Uses mid gray (#b0aea5) for styling secondary visual elements Enforces corporate brand identity and visual design standards on artifacts brand-guidelines is an AI Agent skill that provides access to and applies Anthropic''s official brand identity resources, including specific hex color codes and typography, to ensure visual artifacts conform to the company''s design standards.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/investor-materials', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'investor-materials', 61988, 7678, 58, '2026-03-06T03:39:20Z', '2026-03-06T04:15:28.331Z', '0541ac8ede8d39c59a646834481d0de86312e598331b86dc7027ece0def3c193', '{"id":"affaan-m/everything-claude-code/investor-materials","name":"investor-materials","description":{"en":"The investor-materials skill is an AI Agent tool that generates and updates consistent pitch decks, one-pagers, financial models, and use-of-funds tables. It benefits founders and developers by maintaining internal consistency across all fundraising assets.","zh":"Investor-Materials AI代理专门为开发者提供一致的投资材料创建功能，包括pitch deck、财务模型和里程碑计划。通过Claude Code确保所有 fundraising assets 保持单一事实来源。","ja":"Investor-Materials AIエージェントは、ピッチデッキ、財務モデル、マイルストン計画など、整合性のある資金調達資料を作成します。Claude Codeにより全ての資料を単一の情報源で管理。","ko":"Investor-Materials AI 에이전트는 피치덱, 재무 모델, 마일스톤 계획 등 일관된 투자 자료 생성 기능을 제공합니다. Claude Code로 모든 자료의 단일 정보源 관리를 보장합니다.","es":"Nuestra herramienta de materiales para inversores ayuda a crear y actualizar documentos consistentes y creíbles, como decks de presentación y memorandos","fr":"Notre outil de documents pour investisseurs aide à créer et à mettre à jour des documents cohérents et crédibles, tels que des decks de présentation et des memorandos","de":"Unser Investorenmaterialien-Tool hilft bei der Erstellung und Aktualisierung konsistenter und glaubwürdiger Dokumente wie Präsentationsdecks und Memoranden","pt":"O skill de materiais para investidores permite criar e atualizar documentos de investidores, incluindo pitch decks e modelos financeiros, de forma consistente e credível","ru":"Навык материалов для инвесторов позволяет создавать и обновлять документы для инвесторов, включая презентации и финансовые модели, последовательно и достоверно","ar":"تمكن مهارة مواد المستثمرين من إنشاء وتحديث مستندات المستثمرين، بما في ذلك عروض تقديمية ونماذج مالية، بطريقة متسقة وموثوقة"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"investor-materials","description":"Create and update pitch decks, one-pagers, investor memos, accelerator applications, financial models, and fundraising materials. Use when the user needs investor-facing documents, projections, use-of-funds tables, milestone plans, or materials that must stay internally consistent across multiple fundraising assets.","bodyPreview":"# Investor Materials\n\nBuild investor-facing materials that are consistent, credible, and easy to defend.\n\n## When to Activate\n\n- creating or revising a pitch deck\n- writing an investor memo or one-pager\n- building a financial model, milestone plan, or use-of-funds table\n- answering accelerator or incubator application questions\n- aligning multiple fundraising docs around one source of truth\n\n## Golden Rule\n\nAll investor materials must agree with each other.\n\nCreate or confirm a single source of","body":"# Investor Materials\n\nBuild investor-facing materials that are consistent, credible, and easy to defend.\n\n## When to Activate\n\n- creating or revising a pitch deck\n- writing an investor memo or one-pager\n- building a financial model, milestone plan, or use-of-funds table\n- answering accelerator or incubator application questions\n- aligning multiple fundraising docs around one source of truth\n\n## Golden Rule\n\nAll investor materials must agree with each other.\n\nCreate or confirm a single source of truth before writing:\n- traction metrics\n- pricing and revenue assumptions\n- raise size and instrument\n- use of funds\n- team bios and titles\n- milestones and timelines\n\nIf conflicting numbers appear, stop and resolve them before drafting.\n\n## Core Workflow\n\n1. inventory the canonical facts\n2. identify missing assumptions\n3. choose the asset type\n4. draft the asset with explicit logic\n5. cross-check every number against the source of truth\n\n## Asset Guidance\n\n### Pitch Deck\nRecommended flow:\n1. company + wedge\n2. problem\n3. solution\n4. product / demo\n5. market\n6. business model\n7. traction\n8. team\n9. competition / differentiation\n10. ask\n11. use of funds / milestones\n12. appendix\n\nIf the user wants a web-native deck, pair this skill with `frontend-slides`.\n\n### One-Pager / Memo\n- state what the company does in one clean sentence\n- show why now\n- include traction and proof points early\n- make the ask precise\n- keep claims easy to verify\n\n### Financial Model\nInclude:\n- explicit assumptions\n- bear / base / bull cases when useful\n- clean layer-by-layer revenue logic\n- milestone-linked spending\n- sensitivity analysis where the decision hinges on assumptions\n\n### Accelerator Applications\n- answer the exact question asked\n- prioritize traction, insight, and team advantage\n- avoid puffery\n- keep internal metrics consistent with the deck and model\n\n## Red Flags to Avoid\n\n- unverifiable claims\n- fuzzy market sizing without assumptions\n- inconsistent team roles or titles\n- revenue math that does not sum cleanly\n- inflated certainty where assumptions are fragile\n\n## Quality Gate\n\nBefore delivering:\n- every number matches the current source of truth\n- use of funds and revenue layers sum correctly\n- assumptions are visible, not buried\n- the story is clear without hype language\n- the final asset is defensible in a partner meeting\n"},"category":"official","lastSynced":"2026-03-06T04:15:28.331Z","seo":{"title":{"en":"investor-materials: Consistent Fundraising Docs | AI Agen...","zh":"Investor-Materials AI代理设置指南：创建一致的投资材料","ja":"Investor-Materials AIエージェント活用ガイド：資金調達資料作成","ko":"Investor-Materials AI 에이전트 설정 가이드: 투자 자료 일관성 유지","es":"Guía de configuración de materiales para inversores","fr":"Guide de mise en place de documents pour investisseurs","de":"Einrichtungsleitfaden für Investorenmaterialien","pt":"Guia de Configuração de Materiais para Investidores com A...","ru":"Настройка материалов для инвесторов с помощью ИИ Агентов","ar":"دليل إعداد مواد المستثمرين باستخدام وكلاء الذكاء الاصطناعي"},"description":{"en":"Eliminate conflicting numbers in your pitch deck, one-pager, and financial model. This MCP skill for Claude ensures all investor materials align to a single ...","zh":"使用Claude AI代理自动创建和更新pitch deck、财务模型、资金使用表。确保所有投资材料保持内部一致性，支持加速器申请和投资者备忘录。","ja":"Claude AIエージェントでピッチデッキ、財務モデル、資金使途表を自動生成。全ての資金調達資料の内部整合性を確保し、アクセラレーター申請をサポート。","ko":"Claude AI 에이전트로 피치덱, 재무 모델, 자금 사용 계획표 자동 생성. 모든 투자 자료의 내부 일관성 유지 및 액셀러레이터 지원 지원.","es":"Cree y actualice materiales para inversores como decks de presentación y memorandos con nuestra herramienta de AI Agents","fr":"Créez et mettez à jour des documents pour investisseurs tels que des decks de présentation et des memorandos avec notre outil d''AI Agents","de":"Erstellen und aktualisieren Sie Investorenmaterialien wie Präsentationsdecks und Memoranden mit unserem AI-Tool","pt":"Aprenda a criar e atualizar pitch decks, memorandos de investidores e modelos financeiros com o skill de materiais para investidores","ru":"Узнайте, как создавать и обновлять презентации, меморандумы инвесторов и финансовые модели с помощью навыка материалов для инвесторов","ar":"تعلم كيفية إنشاء وتحديث عروض تقديمية ومراسلات مستثمرين ونماذج مالية باستخدام مهارة مواد المستثمرين"},"definition":{"en":"investor-materials is an MCP skill for AI agents like Claude that creates and revises investor-facing documents. It ensures all fundraising materials, from pitch decks to financial models, remain internally consistent by aligning them to a single source of truth.","zh":"Investor-Materials是一种AI代理技能，专门用于创建和维护投资者面向文档，确保pitch deck、财务模型和资金使用表在所有 fundraising assets 中保持内部一致性。","ja":"Investor-Materialsは、ピッチデッキ、財務モデル、資金使途表など、全ての資金調達資料の整合性を保つために設計されたAIエージェント技能です。","ko":"Investor-Materials는 피치덱, 재무 모델, 자금 사용 계획표 등 모든 투자 자료의 내부 일관성을 유지하도록 설계된 AI 에이전트 기능입니다.","es":"Materiales para inversores son documentos que se utilizan para presentar y promocionar una empresa o proyecto a posibles inversores","fr":"Les documents pour investisseurs sont des documents utilisés pour présenter et promouvoir une entreprise ou un projet à des investisseurs potentiels","de":"Investorenmaterialien sind Dokumente, die verwendet werden, um ein Unternehmen oder ein Projekt potenziellen Investoren vorzustellen und zu bewerben","pt":"O que é o skill de materiais para investidores? É uma ferramenta que ajuda a criar e atualizar documentos de investidores de forma consistente","ru":"Что такое навык материалов для инвесторов? Это инструмент, помогающий создавать и обновлять документы для инвесторов последовательно","ar":"ما هي مهارة مواد المستثمرين؟ هي أداة تساعد في إنشاء وتحديث مستندات المستثمرين بطريقة متسقة"},"features":{"en":["Creates and revises pitch decks for investor presentations","Generates one-pagers and investor memos for fundraising outreach","Builds financial models including use-of-funds tables and projections","Aligns multiple documents to maintain a single source of truth","Answers accelerator and incubator application questions"],"zh":["跨文档一致性检查确保所有投资材料保持统一","自动生成资金使用表和财务预测模型","支持加速器和孵化器申请问题回答","基于单一事实来源维护多个 fundraising assets","集成Claude Code进行技术文档生成","里程碑计划和财务模型协同更新"],"ja":["複数資料の整合性チェック機能","資金使途表と財務予測モデルの自動生成","アクセラレーター申請質問への回答対応","単一情報源に基づく複数資料の管理","Claude Code連携による技術文書生成","マイルストン計画と財務モデルの連動更新"],"ko":["다중 문서 일관성 검증 기능","자금 사용 계획표 및 재무 예측 모델 자동 생성","액셀러레이터 지원 질문 응답 지원","단일 정보원 기반 다중 자료 관리","Claude Code 연동 기술 문서 생성","마일스톤 계획과 재무 모델 연동 업데이트"],"es":["Creación de decks de presentación y memorandos para inversores","Actualización de modelos financieros y planes de hitos","Generación de tablas de uso de fondos y planes de uso de fondos","Creación de aplicaciones para aceleradoras e incubadoras","Mantenimiento de la consistencia entre múltiples documentos de recaudación de fondos"],"fr":["Création de decks de présentation et de memorandos pour investisseurs","Mise à jour de modèles financiers et de plans de jalons","Génération de tableaux d''utilisation de fonds et de plans d''utilisation de fonds","Création de candidatures pour accélérateurs et incubateurs","Maintenance de la cohérence entre plusieurs documents de collecte de fonds"],"de":["Erstellung von Präsentationsdecks und Memoranden für Investoren","Aktualisierung von Finanzmodellen und Meilensteinplänen","Generierung von Mittelverwendungstabelle und Mittelverwendungsplänen","Erstellung von Bewerbungen für Acceleratoren und Inkubatoren","Aufrechterhaltung der Konsistenz zwischen mehreren Fundraising-Dokumenten"],"pt":["Criação e atualização de pitch decks","Desenvolvimento de memorandos de investidores e one-pagers","Construção de modelos financeiros e planos de uso de fundos","Alinhamento de múltiplos documentos de captação de recursos","Integração com aplicativos de aceleradoras e incubadoras"],"ru":["Создание и обновление презентаций","Разработка меморандумов инвесторов и одном страницах","Строительство финансовых моделей и планов использования средств","Согласование нескольких документов для привлечения ресурсов","Интеграция с приложениями ускорителей и инкубаторов"],"ar":["إنشاء وتحديث عروض تقديمية","تطوير مراسلات مستثمرين وصفحات واحدة","بناء نماذج مالية وخطط استخدام الأموال","مواءمة مستندات جمع الأموال المتعددة","التكامل مع تطبيقات معجل وحدائق أعمال"]},"keywords":{"en":["how to use investor-materials skill","what is investor-materials MCP","investor-materials vs manual deck creation","investor-materials alternative","install investor-materials MCP","investor-materials setup guide","claude-code investor materials","mcp financial model generation"],"zh":["investor-materials AI代理","pitch deck生成","财务模型创建","资金使用表AI","Claude Code投资材料","加速器申请自动化","投资文档一致性","fundraising assets管理"],"ja":["investor-materials AIエージェント","ピッチデッキ自動生成","財務モデル作成AI","資金使途表生成","Claude Code資金調達","アクセラレーター申請自動化","投資資料整合性","fundraising assets管理"],"ko":["investor-materials AI 에이전트","피치덱 자동 생성","재무 모델 작성 AI","자금 사용 계획표 생성","Claude Code 투자 자료","액셀러레이터 지원 자동화","투자 문서 일관성","fundraising assets 관리"],"es":["materiales para inversores","AI Agents","herramientas de productividad","desarrollo de aplicaciones","creación de decks de presentación","memorandos para inversores","modelos financieros","planes de hitos","tablas de uso de fondos"],"fr":["documents pour investisseurs","AI Agents","outils de productivité","développement d''applications","création de decks de présentation","memorandos pour investisseurs","modèles financiers","plans de jalons","tableaux d''utilisation de fonds"],"de":["Investorenmaterialien","AI-Tools","Produktivitätstools","Anwendungsentwicklung","Erstellung von Präsentationsdecks","Memoranden für Investoren","Finanzmodelle","Meilensteinpläne","Mittelverwendungstabellen"],"pt":["materiais para investidores","AI Agents","pitch decks","memorandos de investidores","modelos financeiros","captação de recursos","aceleradoras","incubadoras"],"ru":["материалы для инвесторов","ИИ Агенты","презентации","меморандумы инвесторов","финансовые модели","привлечение ресурсов","ускорители","инкубаторы"],"ar":["مواد المستثمرين","وكلاء الذكاء الاصطناعي","عروض تقديمية","مراسلات مستثمرين","نماذج مالية","جمع الأموال","معجل","حدائق أعمال"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Fundraising Agents needing to generate and maintain consistent investor-facing documentation.","zh":"非常适合需要生成和维护面向投资者的一致文档的Fundraising Agent。","ja":"投資家向けの一貫した文書を生成および維持する必要があるFundraising Agentに最適です。","ko":"투자자 대상의 일관된 문서를 생성 및 유지해야 하는 Fundraising Agent에 완벽합니다.","es":"Perfecto para agentes de recaudación de fondos que necesitan generar y mantener documentación coherente orientada a inversores.","fr":"Parfait pour les agents de collecte de fonds ayant besoin de générer et de maintenir une documentation cohérente destinée aux investisseurs.","de":"Perfekt für Fundraising-Agenten, die konsistente, an Investoren gerichtete Dokumentation erstellen und pflegen müssen.","pt":"Perfeito para Agentes de Fundraising que precisam gerar e manter documentação consistente voltada para investidores.","ru":"Идеально подходит для Агентов по привлечению финансирования (Fundraising Agents), которым необходимо создавать и поддерживать последовательную документацию для инвесторов.","ar":"مثالي لوكلاء جمع التبرعات الذين يحتاجون إلى إنشاء والحفاظ على وثائق متسقة موجهة للمستثمرين."},"recommendation":{"en":"Enables automated creation and synchronization of pitch decks, financial models, and investor memos while ensuring internal consistency across all fundraising assets. Maintains a single source of truth for projections, use-of-funds tables, and milestone plans.","zh":"支持自动创建和同步pitch decks、financial models和investor memos，同时确保所有fundraising资产间的内部一致性。为projections、use-of-funds tables和milestone plans维护单一事实来源。","ja":"ピッチデッキ、財務モデル、投資家メモの自動作成と同期を可能にし、全ての資金調達資産にわたる内部一貫性を確保します。予測、資金使途表、マイルストンプランの信頼できる単一情報源を維持します。","ko":"피치 데크, 재무 모델 및 투자자 메모의 자동 생성 및 동기화를 가능하게 하여 모든 펀드레이징 자산 전반의 내부 일관성을 보장합니다. 예측, 자금 사용 계획표 및 마일스톤 계획에 대한 단일 정보 소스를 유지합니다.","es":"Permite la creación y sincronización automatizadas de presentaciones, modelos financieros y memorandos para inversores, garantizando la coherencia interna en todos los activos de recaudación de fondos. Mantiene una sola fuente de verdad para proyecciones, tablas de uso de fondos y planes de hitos.","fr":"Permet la création et la synchronisation automatisées de présentations, de modèles financiers et de notes pour investisseurs, en garantissant la cohérence interne de tous les actifs de collecte de fonds. Maintient une seule source de vérité pour les projections, les tableaux d''utilisation des fonds et les plans de jalons.","de":"Ermöglicht die automatisierte Erstellung und Synchronisation von Präsentationen, Finanzmodellen und Investoren-Memos, während die interne Konsistenz aller Fundraising-Assets sichergestellt wird. Bewahrt eine einzige Wahrheitsquelle für Prognosen, Mittelverwendungstabellen und Meilensteinpläne auf.","pt":"Permite a criação e sincronização automatizada de pitch decks, modelos financeiros e memorandos para investidores, garantindo consistência interna em todos os ativos de fundraising. Mantém uma única fonte de verdade para projeções, tabelas de uso de fundos e planos de marcos.","ru":"Обеспечивает автоматизированное создание и синхронизацию презентаций (pitch decks), финансовых моделей и меморандумов для инвесторов, гарантируя внутреннюю согласованность всех активов для привлечения финансирования. Поддерживает единый источник истины для прогнозов, таблиц использования средств и планов по этапам (milestone plans).","ar":"يتيح الإنشاء الآلي ومزامنة عروض التقديم (pitch decks) والنماذج المالية ومذكرات المستثمرين مع ضمان الاتساق الداخلي عبر جميع أصول جمع التبرعات. يحافظ على مصدر واحد للحقيقة للتوقعات وجداول استخدام الأموال وخطط المراحل الأساسية (milestone plans)."},"useCases":{"en":["Generating pitch decks with aligned financial projections","Creating consistent use-of-funds tables across multiple documents","Updating investor memos to reflect revised milestone plans","Answering accelerator application questions with data-driven responses"],"zh":["生成具有一致financial projections的pitch decks","在多个文档中创建一致的use-of-funds tables","更新investor memos以反映修订后的milestone plans","使用数据驱动的回答来回应accelerator application问题"],"ja":["整合性のある財務予測を備えたピッチデッキの生成","複数の文書にわたる一貫した資金使途表の作成","改訂されたマイルストンプランを反映するための投資家メモの更新","データ駆動型の回答によるアクセラレーター申請質問への対応"],"ko":["일치된 재무 예측이 포함된 피치 데크 생성","여러 문서에 걸쳐 일관된 자금 사용 계획표 작성","수정된 마일스톤 계획을 반영하도록 투자자 메모 업데이트","데이터 기반 응답으로 액셀러레이터 지원 질문에 답변"],"es":["Generar presentaciones con proyecciones financieras alineadas","Crear tablas de uso de fondos coherentes en varios documentos","Actualizar memorandos para inversores para reflejar planes de hitos revisados","Responder a preguntas de solicitudes de aceleradora con respuestas impulsadas por datos"],"fr":["Générer des présentations avec des projections financières alignées","Créer des tableaux d''utilisation des fonds cohérents dans plusieurs documents","Mettre à jour les notes pour investisseurs pour refléter les plans de jalons révisés","Répondre aux questions de demande d''accélérateur avec des réponses pilotées par les données"],"de":["Erstellung von Präsentationen mit ausgerichteten Finanzprognosen","Erstellen konsistenter Mittelverwendungstabellen in mehreren Dokumenten","Aktualisieren von Investoren-Memos, um überarbeitete Meilensteinpläne widerzuspiegeln","Beantworten von Beschleunigerantragsfragen mit datengetriebenen Antworten"],"pt":["Geração de pitch decks com projeções financeiras alinhadas","Criação de tabelas de uso de fundos consistentes em vários documentos","Atualização de memorandos para investidores para refletir planos de marcos revisados","Resposta a perguntas de aplicação para aceleradoras com respostas baseadas em dados"],"ru":["Генерация презентаций (pitch decks) с согласованными финансовыми прогнозами","Создание последовательных таблиц использования средств в нескольких документах","Обновление меморандумов для инвесторов с учетом пересмотренных планов по этапам (milestone plans)","Ответы на вопросы заявок в акселераторы с помощью ответов, основанных на данных"],"ar":["إنشاء عروض تقديمية (pitch decks) مع توقعات مالية متوافقة","إنشاء جداول متسقة لاستخدام الأموال عبر مستندات متعددة","تحديث مذكرات المستثمرين لتعكس خطط المراحل الأساسية (milestone plans) المنقحة","الإجابة على أسئلة طلبات مسرعات الأعمال باستخدام ردود تعتمد على البيانات"]},"limitations":{"en":["Requires access to financial data sources","Needs document editing capabilities","Must maintain internal consistency across all materials"],"zh":["需要访问financial data sources","需要具备document editing capabilities","必须维护所有材料间的内部一致性"],"ja":["財務データソースへのアクセスが必要","文書編集機能が必要","全ての資料にわたる内部一貫性を維持しなければならない"],"ko":["재무 데이터 소스에 대한 액세스 필요","문서 편집 기능 필요","모든 자료 전반의 내부 일관성 유지 필요"],"es":["Requiere acceso a fuentes de datos financieros","Necesita capacidades de edición de documentos","Debe mantener la coherencia interna en todos los materiales"],"fr":["Nécessite un accès aux sources de données financières","A besoin de capacités d''édition de documents","Doit maintenir la cohérence interne de tous les matériaux"],"de":["Erfordert Zugriff auf Finanzdatenquellen","Benötigt Dokumentenbearbeitungsfunktionen","Muss die interne Konsistenz aller Materialien aufrechterhalten"],"pt":["Requer acesso a fontes de dados financeiros","Necessita de capacidades de edição de documentos","Deve manter a consistência interna em todos os materiais"],"ru":["Требует доступа к источникам финансовых данных","Нуждается в возможностях редактирования документов","Должен поддерживать внутреннюю согласованность всех материалов"],"ar":["يتطلب الوصول إلى مصادر البيانات المالية","يحتاج إلى قدرات تحرير المستندات","يجب الحفاظ على الاتساق الداخلي عبر جميع المواد"]},"version":4},"contentHash":"0541ac8ede8d39c59a646834481d0de86312e598331b86dc7027ece0def3c193","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":58}');
