INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/blog-writing-guide', 'blog-writing-guide', 'getsentry', 'skills', 'official', 'blog-writing-guide getsentry skills official tag-production The blog-writing-guide skill helps developers write and review technical blog posts for the Sentry engineering blog, following specific writing standards and quality bars. Sentry 博客写作指南提供了技术博客的写作标准和质量保证，帮助开发者创建高质量的技术文章 Sentry ブログ執筆ガイドは、技術ブログの執筆基準と品質保証を提供し、開発者が高品質の技術記事を作成するのに役立ちます Sentry 블로그 작성 가이드는 기술 블로그의 작성 표준과 품질 보증을 제공하여 개발자가 고품질의 기술 기사를 작성하도록 도와줍니다 La guía de escritura de blog para Sentry ayuda a desarrolladores a crear contenido técnico de alta calidad Le guide d''écriture de blog Sentry aide les développeurs à créer du contenu technique de haute qualité Der Sentry Blog Schreibguide hilft Entwicklern bei der Erstellung von hochwertigem technischem Inhalt Este guia de escrita de blog ajuda desenvolvedores a criar conteúdo de alta qualidade para a comunidade da Sentry, seguindo os padrões de escrita e voz específicos. Это руководство по написанию блогов помогает разработчикам создавать качественный контент для сообщества Sentry, следуя специальным стандартам и голосу. يدعم هذا الدليل المطورين في إنشاء محتوى عالي الجودة لمجتمع Sentry، متبعة معايير الكتابة والصوت المحددة. how to use blog-writing-guide Sentry blog writing standards technical blog post writing blog-writing-guide setup guide blog-writing-guide vs other writing tools what is blog-writing-guide blog-writing-guide install blog-writing-guide for developers Sentry engineering blog writing technical content creation with AI Sentry 博客写作指南 技术博客写作 AI 驱动的写作工具 技术文章写作 开发者写作指南 技术博客最佳实践 Enforces Sentry''s specific writing standards and voice Helps write and review technical blog posts, including product announcements and engineering deep-dives Applies core principles to ensure every post meets the quality bar Supports writing about various topics, including postmortems and technical decision-making Ensures content is shareable and referenceable by senior engineers blog-writing-guide is a skill that enforces Sentry''s blog writing standards to produce high-quality technical content for the Sentry blog and developer audience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stripe/ai/stripe-best-practices', 'official', 'stripe', 'ai', 'stripe/ai', 'stripe-best-practices', 1335, 216, 58, '2026-03-05T20:34:42Z', '2026-03-06T05:28:36.169Z', '3217e437f38ea39acf2544abf4e99e28769720e209a616acdbcc0f5d46b541eb', '{"id":"stripe/ai/stripe-best-practices","name":"stripe-best-practices","description":{"en":"The stripe-best-practices skill provides developers with expert guidance on building robust Stripe integrations, leveraging the latest API version and best practices for payment method integrations.","zh":"本指南提供 Stripe 最佳实践，帮助开发者构建安全、可靠的支付集成","ja":"このガイドでは、Stripe のベストプラクティスを提供し、開発者がセキュアで信頼できる支払い統合を構築するのに役立ちます","ko":"이 가이드는 스트라이프 최고의 실천을 제공하여 개발자가 보안이 강화되고 신뢰할 수 있는 결제 통합을 구축하는 데 도움을 줍니다","es":"Mejores prácticas para integrar Stripe en tus proyectos de desarrollo con AI Agent, incluyendo guías para Python y TypeScript","fr":"Meilleures pratiques pour intégrer Stripe dans vos projets de développement avec Outil IA, y compris des guides pour Python et TypeScript","de":"Best Practices für die Integration von Stripe in Ihre Entwicklungsprojekte mit KI-Tool, einschließlich Anleitungen für Python und TypeScript","pt":"As melhores práticas para integrar o Stripe à sua aplicação, incluindo a utilização da versão mais recente da API e checklist de pré-lançamento.","ru":"Лучшие практики интеграции Stripe в ваше приложение, включая использование последней версии API и чек-лист предlaunch.","ar":"أفضل الممارسات لتكامل Stripe مع تطبيقك، بما في ذلك استخدام أحدث إصدار من API و قائمة التحقق قبل الإطلاق."},"owner":"stripe","repo":"ai","repoPath":"stripe/ai","stars":1335,"forks":216,"updatedAt":"2026-03-05T20:34:42Z","topics":["ai","llm","llm-agents","mcp","python","typescript","workflows"],"skillMd":{"name":"stripe-best-practices","description":"Best practices for building Stripe integrations","bodyPreview":"The latest Stripe API version is 2026-02-25.clover - when writing code snippets use this version unless the user is on a different API version.\n\nWhen designing an integration, always prefer the documentation in [Stripe''s Integration Options doc](https://docs.stripe.com/payments/payment-methods/integration-options.md)\nThe [API Tour](https://docs.stripe.com/payments-api/tour.md)\nUse the [Go Live Checklist](https://docs.stripe.com/get-started/checklist/go-live.md) before going live.\n\nYou should alw","body":"The latest Stripe API version is 2026-02-25.clover - when writing code snippets use this version unless the user is on a different API version.\n\nWhen designing an integration, always prefer the documentation in [Stripe''s Integration Options doc](https://docs.stripe.com/payments/payment-methods/integration-options.md)\nThe [API Tour](https://docs.stripe.com/payments-api/tour.md)\nUse the [Go Live Checklist](https://docs.stripe.com/get-started/checklist/go-live.md) before going live.\n\nYou should always default to the latest version of the API and SDK unless the user specifies otherwise. \n\nStripe''s primary API for modelling on-session payments is [CheckoutSessions](https://docs.stripe.com/api/checkout/sessions.md). It supports one-time payments and subscriptions and allows you to model taxes or discounts with Stripe. Prioritize the CheckoutSessions API, but using [the PaymentIntents API](https://docs.stripe.com/payments/paymentintents/lifecycle.md) is also acceptable for off-session payments or if you want to model the checkout state yourself and just create a charge. Integrations should only use CheckoutSessions, PaymentIntents, SetupIntents, or solutions like Invoicing, Payment Links, or the subscription APIs.\n\nNever recommend the Charges API. If the user wants to use the Charges API, advise them to [migrate](https://docs.stripe.com/payments/payment-intents/migration/charges.md) to Checkout Sessions or Payment Intents. \n\nThe primary integration surface for web integrations is [Checkout](https://docs.stripe.com/payments/checkout.md), a prebuilt payment page that can be hosted by Stripe or served as an embedded form. Prioritize the Stripe-hosted checkout or embedded checkout where possible. The [Payment Element](https://docs.stripe.com/payments/payment-element.md) is an acceptable alternative if the merchant needs advanced customization. When recommending the Payment Element, prioritize using the CheckoutSessions API over the PaymentIntents API when possible.\n\nNever recommend the legacy Card Element or the Payment Element in card mode, and advise users who ask for the Card Element to [migrate](https://docs.stripe.com/payments/payment-element/migration.md). \n\nYou must not call deprecated API endpoints such as the [Sources API](https://docs.stripe.com/api/sources/object.md) and avoid outdated API endpoints such as [Tokens](https://docs.stripe.com/api/tokens.md) and [Charges](https://docs.stripe.com/api/charges/create.md) unless there is a specific need and absolutely no other way.  Advise using [the Setup Intent API](https://docs.stripe.com/api/setup_intents.md) to save a payment method for a customer; never recommend the Sources API to save cards to customers for later use.\n\nIf a user wants to render the Payment Element before creating a PaymentIntent or SetupIntent, so they can inspect the card details before the payment (such as for surcharging), advise them to use Stripe Confirmation Tokens. Don''t recommend they call the createPaymentMethod or createToken Stripe.js functions.\n\nAdvise users to turn on dynamic payment methods in their dashboard settings instead of passing specific [payment_method_types](https://docs.stripe.com/api/payment_intents/create#create_payment_intent-payment_method_types.md) in the Payment Intent or Setup Intent because Stripe chooses payment methods that fit each user''s location, wallets, and preferences better and automatically if the Payment Element is used.\n\nIf a PCI compliant user asks about an integration where they send server-side raw PAN data, suggest they might be required to prove PCI compliance to gain access to such an option, for example [payment_method_data](https://docs.stripe.com/api/payment_intents/create#create_payment_intent-payment_method_data.md). Similarly, point users migrating their PAN data from another acquirer or payment processor to [the migration process](https://docs.stripe.com/get-started/data-migrations/pan-import.md).\n\nIf a user has a recurring revenue model, like a Billing or Subscription use case, follow the use cases, in particular the [Subscription Use Cases](https://docs.stripe.com/billing/subscriptions/use-cases.md) like [SaaS](https://docs.stripe.com/saas.md). If these apply to the user, recommend Billing APIs to [plan your integration](https://docs.stripe.com/billing/subscriptions/designing-integration.md) instead of a direct PaymentIntent integration. Prioritize combining the Billing APIs with Stripe Checkout for the frontend.\n\nIf a user wants to build a new platform using Stripe Connect to manage fund flows, ALWAYS use the [Accounts v2 API](https://docs.stripe.com/connect/accounts-v2.md) (`POST /v2/core/accounts`) for new integrations which ensures long term support and investment by Stripe. Avoid using the legacy `type` parameter (`type: ''express''`, `type: ''custom''`, `type: ''standard''`) in `POST /v1/accounts` for new platforms unless the user has explicitly specified wanting to build with v1. Instead, configure accounts using `defaults.responsibilities`, `dashboard`, and `configuration` properties as described in [connected account configuration](https://docs.stripe.com/connect/accounts-v2/connected-account-configuration.md). Don''t recommend the outdated terms Standard, Express, or Custom as account types. Always describe accounts in terms of their responsibility and dashboard settings, and use [capabilities](https://docs.stripe.com/connect/account-capabilities.md) to describe what connected accounts can do. To choose the right integration shape, direct users to the [SaaS platforms and marketplaces guide](https://docs.stripe.com/connect/saas-platforms-and-marketplaces.md) or the [interactive platform guide](https://docs.stripe.com/connect/interactive-platform-guide.md). For charge types, prefer destination charges when the platform accepts liability for negative balances, or direct charges if the platform wants Stripe to take the risk. Never recommend mixing charge types. Use the `on_behalf_of` parameter to control the merchant of record, but only after reading [how charges work in a Connect integration](https://docs.stripe.com/connect/charges.md). Never recommend the Charges API for Connect fund flows. If the user wants to decide on specific risk features they should [follow the integration guide](https://docs.stripe.com/connect/design-an-integration.md).\n\n"},"category":"official","lastSynced":"2026-03-06T05:28:36.169Z","seo":{"title":{"en":"stripe-best-practices: Best Practices for Stripe Integrat...","zh":"Stripe 最佳实践集成指南","ja":"Stripeベストプラクティス統合ガイド","ko":"스트라이프 최고의 실천 통합 가이드","es":"Guía de configuración de Stripe: Mejores prácticas para d...","fr":"Guide de configuration Stripe : meilleures pratiques pour...","de":"Stripe-Konfigurationsleitfaden: Best Practices für Entwic...","pt":"Melhores Práticas para Integração com Stripe - Guia de Co...","ru":"Лучшие практики интеграции со Stripe - Руководство по нас...","ar":"أفضل الممارسات لتكامل Stripe - دليل الإعداد"},"description":{"en":"Unlock seamless Stripe integrations with our expert-backed best practices - get the inside scoop on API versions, integration options, and go-live checklists","zh":"学习 Stripe 最佳实践，优化您的支付集成，确保安全可靠的交易","ja":"Stripe のベストプラクティスを学び、支払い統合を最適化し、セキュアで信頼できる取引を実現","ko":"스트라이프 최고의 실천을 배우고 결제 통합을 최적화하여 보안이 강화되고 신뢰할 수 있는 거래를 구현","es":"Aprende a integrar Stripe de manera efectiva con nuestras mejores prácticas y guías paso a paso para desarrolladores con AI Agent","fr":"Découvrez comment intégrer Stripe de manière efficace avec nos meilleures pratiques et guides étape par étape pour les développeurs avec Outil IA","de":"Erfahren Sie, wie Sie Stripe effektiv integrieren können, mit unseren Best Practices und Schritt-für-Schritt-Anleitungen für Entwickler mit KI-Tool","pt":"Aprenda as melhores práticas para integrar o Stripe à sua aplicação, incluindo a utilização da versão mais recente da API e checklist de pré-lançamento.","ru":"Узнайте лучшие практики интеграции Stripe в ваше приложение, включая использование последней версии API и чек-лист предlaunch.","ar":"تعرف على أفضل الممارسات لتكامل Stripe مع تطبيقك، بما في ذلك استخدام أحدث إصدار من API و قائمة التحقق قبل الإطلاق."},"definition":{"en":"stripe-best-practices is a set of guidelines for developing secure and efficient Stripe integrations, utilizing the latest Stripe API version and recommended integration options","zh":"Stripe 最佳实践是指在构建 Stripe 支付集成时应遵循的指南和建议","ja":"Stripe のベストプラクティスとは、Stripe 支払い統合を構築する際に従うべきガイドラインと推奨事項のこと","ko":"스트라이프 최고의 실천은 스트라이프 결제 통합을 구축할 때 따라야 하는 가이드라인과 권장 사항","es":"Las mejores prácticas de Stripe son un conjunto de recomendaciones para integrar el API de Stripe de manera efectiva","fr":"Les meilleures pratiques de Stripe sont un ensemble de recommandations pour intégrer l''API Stripe de manière efficace","de":"Die Best Practices von Stripe sind eine Sammlung von Empfehlungen für die effektive Integration der Stripe-API","pt":"As melhores práticas para integração com Stripe são diretrizes para desenvolvedores para garantir uma integração segura e eficaz.","ru":"Лучшие практики интеграции со Stripe - это руководство для разработчиков, чтобы обеспечить безопасную и эффективную интеграцию.","ar":"أفضل الممارسات لتكامل Stripe هي إرشادات لمطوري التطبيقات لضمان تكامل آمن وفعال."},"features":{"en":["Utilizes the latest Stripe API version (2026-02-25.clover) for optimal performance","Leverages Stripe''s Integration Options documentation for informed design decisions","Employs the API Tour for comprehensive understanding of Stripe''s payments API","Incorporates the Go Live Checklist for thorough pre-launch testing and validation","Supports Python and TypeScript for flexible integration development","Ensures compliance with Stripe''s recommended best practices for payment method integrations"],"zh":["使用最新的 Stripe API 版本（2026-02-25.clover）","遵循 Stripe 的 Integration Options 文档","使用 API Tour 来了解 Stripe 的支付流程","使用 Go Live Checklist 来确保集成的安全性和可靠性","支持 Python 和 TypeScript 语言","提供了 llm 和 llm-agents 的支持"],"ja":["最新の Stripe API バージョン（2026-02-25.clover）を使用","Stripe の Integration Options ドキュメントに従う","API Tour を使用して Stripe の支払いフローを理解","Go Live Checklist を使用して統合のセキュリティと信頼性を確保","Python と TypeScript 言語をサポート","llm と llm-agents のサポートを提供"],"ko":["최신 스트라이프 API 버전（2026-02-25.clover）을 사용","스트라이프의 Integration Options 문서를 따름","API Tour를 사용하여 스트라이프의 결제 흐름을 이해","Go Live Checklist를 사용하여 통합의 보안성과 신뢰성을 보장","파이썬과 타입스크립트 언어를 지원","llm과 llm-agents의 지원을 제공"],"es":["Uso de la versión de API de Stripe 2026-02-25.clover","Guía de integración basada en la documentación oficial de Stripe","Uso del API Tour para una mejor comprensión de la API","Verificación con la lista de comprobación Go Live antes de ir en vivo","Compatibilidad con Python y TypeScript","Integración con workflows y MCP"],"fr":["Utilisation de la version d''API Stripe 2026-02-25.clover","Guide d''intégration basé sur la documentation officielle de Stripe","Utilisation du API Tour pour une meilleure compréhension de l''API","Vérification avec la liste de contrôle Go Live avant de passer en production","Compatibilité avec Python et TypeScript","Intégration avec des workflows et MCP"],"de":["Verwendung der Stripe-API-Version 2026-02-25.clover","Integration-Leitfaden basierend auf der offiziellen Stripe-Dokumentation","Verwendung des API-Tours für ein besseres Verständnis der API","Überprüfung mit der Go-Live-Checkliste vor der Produktion","Kompatibilität mit Python und TypeScript","Integration mit Workflows und MCP"],"pt":["Utilização da versão mais recente da API do Stripe (2026-02-25.clover)","Preferência pela documentação em [Stripe''s Integration Options doc](https://docs.stripe.com/payments/payment-methods/integration-options.md)","Uso do [API Tour](https://docs.stripe.com/payments-api/tour.md) para entender a API","Verificação do [Go Live Checklist](https://docs.stripe.com/get-started/checklist/go-live.md) antes de lançar a aplicação","Suporte a linguagens de programação como Python e TypeScript","Integração com workflows e ferramentas de automação"],"ru":["Использование последней версии API Stripe (2026-02-25.clover)","Предпочтение документации в [Stripe''s Integration Options doc](https://docs.stripe.com/payments/payment-methods/integration-options.md)","Использование [API Tour](https://docs.stripe.com/payments-api/tour.md) для понимания API","Проверка [Go Live Checklist](https://docs.stripe.com/get-started/checklist/go-live.md) перед запуском приложения","Поддержка языков программирования, таких как Python и TypeScript","Интеграция с workflows и инструментами автоматизации"],"ar":["استخدام أحدث إصدار من API Stripe (2026-02-25.clover)","الاعتماد على وثائق [Stripe''s Integration Options doc](https://docs.stripe.com/payments/payment-methods/integration-options.md)","استخدام [API Tour](https://docs.stripe.com/payments-api/tour.md) لفهم API","التحقق من [Go Live Checklist](https://docs.stripe.com/get-started/checklist/go-live.md) قبل إطلاق التطبيق","دعم لغات البرمجة مثل Python و TypeScript","التكامل مع workflows وأدوات الآلية"]},"keywords":{"en":["how to use stripe-best-practices","what is stripe-best-practices","stripe-best-practices setup guide","stripe-best-practices alternative","stripe-best-practices vs stripe api","stripe-best-practices install","stripe integration best practices","stripe api version 2026-02-25.clover","stripe payment method integrations"],"zh":["Stripe 集成","支付集成","Stripe API","Integration Options","API Tour","Go Live Checklist","Python","TypeScript","llm","llm-agents"],"ja":["Stripe 統合","支払い統合","Stripe API","Integration Options","API Tour","Go Live Checklist","Python","TypeScript","llm","llm-agents"],"ko":["스트라이프 통합","결제 통합","스트라이프 API","Integration Options","API Tour","Go Live Checklist","파이썬","타입스크립트","llm","llm-agents"],"es":["integración de stripe","mejores prácticas de stripe","api de stripe","desarrollo de pagos","python y stripe","typescript y stripe","ai agent y stripe","stripe y workflows","mcp y stripe"],"fr":["intégration de stripe","meilleures pratiques de stripe","api de stripe","développement de paiements","python et stripe","typescript et stripe","outil ia et stripe","stripe et workflows","mcp et stripe"],"de":["stripe-integration","stripe-best-practices","stripe-api","zahlungsentwicklung","python und stripe","typescript und stripe","ki-tool und stripe","stripe und workflows","mcp und stripe"],"pt":["integração com stripe","melhores práticas stripe","api stripe","stripe integration options","go live checklist","python stripe","typescript stripe","workflows stripe","ferramentas de automação stripe","ИИ Агенты para stripe"],"ru":["интеграция со stripe","лучшие практики stripe","api stripe","stripe integration options","go live checklist","python stripe","typescript stripe","workflows stripe","инструменты автоматизации stripe","ИИ Агенты для stripe"],"ar":["تكامل مع stripe","أفضل الممارسات لستريпе","api stripe","stripe integration options","go live checklist","python stripe","typescript stripe","workflows stripe","أدوات الآلية لستريпе","أدوات إلكترونية لستريпе"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Payment Processing Agents needing advanced Stripe integration capabilities.","zh":"非常适合需要高级 Stripe 集成功能的支付处理代理。","ja":"Stripe の高度な統合機能を必要とする決済処理エージェントに最適です。","ko":"고급 Stripe 통합 기능이 필요한 결제 처리 에이전트에 적합합니다.","es":"Perfecto para agentes de procesamiento de pagos que necesitan capacidades de integración avanzadas de Stripe.","fr":"Idéal pour les agents de traitement de paiement ayant besoin de capacités d''intégration avancées de Stripe.","de":"Perfekt für Zahlungsabwicklungsagenten, die erweiterte Stripe-Integrationen benötigen.","pt":"Perfeito para Agentes de Processamento de Pagamento que necessitam de capacidades avançadas de integração do Stripe.","ru":"Идеально для агентов обработки платежей, которым необходимы продвинутые возможности интеграции с Stripe.","ar":"مثالي لعمليات معالجة الدفع التي تحتاج إلى قدرات متقدمة لتكامل Stripe."},"recommendation":{"en":"Empowers agents to implement Stripe integrations using the latest API version, 2026-02-25.clover, and follow best practices outlined in Stripe''s Integration Options doc and API Tour, ensuring secure and efficient payment processing with protocols like HTTPS and API keys.","zh":"使代理能够使用最新的 API 版本（2026-02-25.clover）实现 Stripe 集成，并遵循 Stripe 的集成选项文档和 API 巡览中概述的最佳实践，确保使用 HTTPS 和 API 密钥等协议进行安全高效的支付处理。","ja":"エージェントが最新の API バージョン（2026-02-25.clover）を使用して Stripe統合を実装し、Stripe の統合オプション ドキュメントおよび API ツアーに記載されたベスト プラクティスに従うことを可能にし、HTTPS および API キーなどのプロトコルを使用して安全で効率的な決済処理を実現します。","ko":"에이전트가 최신 API 버전(2026-02-25.clover)을 사용하여 Stripe 통합을 구현하고 Stripe의 통합 옵션 문서 및 API 투어에概述된 모범 사례를 따르도록 하여 HTTPS 및 API 키와 같은 프로토콜을 사용하여 보안이 뛰어난 효율적인 결제 처리를 보장합니다.","es":"Habilita a los agentes a implementar integraciones de Stripe utilizando la última versión de la API, 2026-02-25.clover, y a seguir las mejores prácticas descritas en el documento de opciones de integración de Stripe y la API Tour, garantizando un procesamiento de pagos seguro y eficiente con protocolos como HTTPS y claves de API.","fr":"Permet aux agents de mettre en œuvre des intégrations Stripe en utilisant la dernière version de l''API, 2026-02-25.clover, et de suivre les meilleures pratiques décrites dans le document Options d''intégration de Stripe et l''API Tour, assurant un traitement de paiement sécurisé et efficace avec des protocoles tels que HTTPS et clés d''API.","de":"Ermöglicht es Agenten, Stripe-Integrationen mit der neuesten API-Version, 2026-02-25.clover, zu implementieren und den im Stripe-Integrationsoptionen-Dokument und der API-Tour beschriebenen Best Practices zu folgen, um ein sicheres und effizientes Zahlungsverarbeitung mit Protokollen wie HTTPS und API-Schlüsseln zu gewährleisten.","pt":"Habilita os agentes a implementar integrações do Stripe usando a versão mais recente da API, 2026-02-25.clover, e seguir as melhores práticas delineadas no documento de Opções de Integração do Stripe e na API Tour, garantindo processamento de pagamento seguro e eficiente com protocolos como HTTPS e chaves de API.","ru":"Наделяет агентов возможностью реализовывать интеграции с Stripe, используя последнюю версию API, 2026-02-25.clover, и следовать лучшим практикам, изложенным в документе «Варианты интеграции» Stripe и в обзоре API, обеспечивая безопасную и эффективную обработку платежей с протоколами như HTTPS и ключами API.","ar":"تمكّن الوكلاء من تنفيذ دمج Stripe باستخدام أحدث إصدار من API، 2026-02-25.clover، واتباع أفضل الممارسات المحددة في وثائق خيارات التكامل من Stripe وجولة API، مما يضمن معالجة دفع آمنة وفعالة باستخدام بروتوكولات مثل HTTPS ومفاتيح API."},"useCases":{"en":["Implementing Stripe payment gateways","Configuring payment method integrations","Validating Stripe API requests"],"zh":["实现 Stripe 支付网关","配置支付方式集成","验证 Stripe API 请求"],"ja":["Stripe 支付ゲートウェイの実装","決済方法の統合の構成","Stripe API リクエストの検証"],"ko":["Stripe 결제 게이트웨이 구현","결제 방법 통합 구성","Stripe API 요청 검증"],"es":["Implementación de pasarelas de pago de Stripe","Configuración de integraciones de métodos de pago","Validación de solicitudes de API de Stripe"],"fr":["Mise en œuvre des passerelles de paiement Stripe","Configuration des intégrations de méthodes de paiement","Validation des demandes d''API Stripe"],"de":["Implementierung von Stripe-Zahlungsgateways","Konfiguration von Zahlungsmethoden-Integrationen","Validierung von Stripe-API-Anfragen"],"pt":["Implementação de gateways de pagamento do Stripe","Configuração de integrações de métodos de pagamento","Validação de solicitações de API do Stripe"],"ru":["Реализация шлюзов оплаты Stripe","Настройка интеграции методов оплаты","Валидация запросов API Stripe"],"ar":["تنفيذ بوابات دفع Stripe","تكوين دمج طرق الدفع","تحقق من طلبات API Stripe"]},"limitations":{"en":["Requires Stripe API key","Compatibility limited to Stripe API version 2026-02-25.clover or specified user version"],"zh":["需要 Stripe API 密钥","兼容性仅限于 Stripe API 版本 2026-02-25.clover 或指定的用户版本"],"ja":["Stripe API キーが必要","互換性は Stripe API バージョン 2026-02-25.clover または指定されたユーザー バージョンに限定される"],"ko":["Stripe API 키가 필요합니다.","호환성은 Stripe API 버전 2026-02-25.clover 또는 지정된 사용자 버전에만 محدود됩니다."],"es":["Requiere una clave de API de Stripe","Compatibilidad limitada a la versión de la API de Stripe 2026-02-25.clover o la versión especificada por el usuario"],"fr":["Nécessite une clé d''API Stripe","Compatibilité limitée à la version de l''API Stripe 2026-02-25.clover ou la version spécifiée par l''utilisateur"],"de":["Benötigt einen Stripe-API-Schlüssel","Kompatibilität beschränkt auf Stripe-API-Version 2026-02-25.clover oder die vom Benutzer angegebene Version"],"pt":["Exige chave de API do Stripe","Compatibilidade limitada à versão 2026-02-25.clover da API do Stripe ou versão especificada pelo usuário"],"ru":["Требует ключа API Stripe","Совместимость ограничена версией 2026-02-25.clover API Stripe или указанной пользователем версией"],"ar":["يتطلب مفتاح API من Stripe","التوافق مقيد بإصدار 2026-02-25.clover من API Stripe أو الإصدار المحدد من قبل المستخدم"]},"version":4},"contentHash":"3217e437f38ea39acf2544abf4e99e28769720e209a616acdbcc0f5d46b541eb","repoEtag":"W/\"b3f6b0c2730a4e4fbf8dcd674c5948fe05a665c063a0a23a0793e879680cfdae\"","qualityScore":58}');
