INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stripe/ai/stripe-best-practices', 'stripe-best-practices', 'stripe', 'ai', 'official', 'stripe-best-practices stripe ai official ai llm llm-agents mcp python typescript workflows The stripe-best-practices skill provides developers with expert guidance on building robust Stripe integrations, leveraging the latest API version and best practices for payment method integrations. 本指南提供 Stripe 最佳实践，帮助开发者构建安全、可靠的支付集成 このガイドでは、Stripe のベストプラクティスを提供し、開発者がセキュアで信頼できる支払い統合を構築するのに役立ちます 이 가이드는 스트라이프 최고의 실천을 제공하여 개발자가 보안이 강화되고 신뢰할 수 있는 결제 통합을 구축하는 데 도움을 줍니다 Mejores prácticas para integrar Stripe en tus proyectos de desarrollo con AI Agent, incluyendo guías para Python y TypeScript Meilleures pratiques pour intégrer Stripe dans vos projets de développement avec Outil IA, y compris des guides pour Python et TypeScript Best Practices für die Integration von Stripe in Ihre Entwicklungsprojekte mit KI-Tool, einschließlich Anleitungen für Python und TypeScript As melhores práticas para integrar o Stripe à sua aplicação, incluindo a utilização da versão mais recente da API e checklist de pré-lançamento. Лучшие практики интеграции Stripe в ваше приложение, включая использование последней версии API и чек-лист предlaunch. أفضل الممارسات لتكامل Stripe مع تطبيقك، بما في ذلك استخدام أحدث إصدار من API و قائمة التحقق قبل الإطلاق. how to use stripe-best-practices what is stripe-best-practices stripe-best-practices setup guide stripe-best-practices alternative stripe-best-practices vs stripe api stripe-best-practices install stripe integration best practices stripe api version 2026-02-25.clover stripe payment method integrations Stripe 集成 支付集成 Stripe API Integration Options API Tour Go Live Checklist Python TypeScript llm llm-agents Utilizes the latest Stripe API version (2026-02-25.clover) for optimal performance Leverages Stripe''s Integration Options documentation for informed design decisions Employs the API Tour for comprehensive understanding of Stripe''s payments API Incorporates the Go Live Checklist for thorough pre-launch testing and validation Supports Python and TypeScript for flexible integration development Ensures compliance with Stripe''s recommended best practices for payment method integrations stripe-best-practices is a set of guidelines for developing secure and efficient Stripe integrations, utilizing the latest Stripe API version and recommended integration options');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/enterprise-agent-ops', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'enterprise-agent-ops', 61988, 7678, 58, '2026-03-06T03:39:20Z', '2026-03-06T04:08:27.502Z', '27edc796df2bf30b611b05ca443434bf65bfc6fde18c94cd16ec41357f4c8ac5', '{"id":"affaan-m/everything-claude-code/enterprise-agent-ops","name":"enterprise-agent-ops","description":{"en":"The enterprise-agent-ops skill provides operational controls for cloud-hosted or continuously running AI agent systems. It enables developers to manage runtime lifecycle, observability, safety controls, and change management for long-lived agent workloads.","zh":"企业级AI代理运营技能提供长期运行的AI代理系统的可观察性、安全边界和生命周期管理","ja":"エンタープライズAIエージェントの運用スキルは、長期間実行されるAIエージェントシステムの可観測性、セキュリティ境界、ライフサイクル管理を提供","ko":"엔터프라이즈 AI 에이전트 작동 가이드는 장기간 작동하는 AI 에이전트 시스템의 관찰 가능성, 보안 경계, 수명주기 관리를 제공","pt":"O Enterprise Agent Ops permite operar cargas de trabalho de agentes de longa duração com controles operacionais avançados","ru":"ИИ Агенты: Enterprise Agent Ops позволяет работать с долгоживущими рабочими нагрузками с расширенными операционными контролями","ar":"يعمل Enterprise Agent Ops على تشغيل أحمال عمل وكلاء المؤسسة على المدى الطويل مع سيطرة تشغيلية متقدمة"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"enterprise-agent-ops","description":"Operate long-lived agent workloads with observability, security boundaries, and lifecycle management.","bodyPreview":"# Enterprise Agent Ops\n\nUse this skill for cloud-hosted or continuously running agent systems that need operational controls beyond single CLI sessions.\n\n## Operational Domains\n\n1. runtime lifecycle (start, pause, stop, restart)\n2. observability (logs, metrics, traces)\n3. safety controls (scopes, permissions, kill switches)\n4. change management (rollout, rollback, audit)\n\n## Baseline Controls\n\n- immutable deployment artifacts\n- least-privilege credentials\n- environment-level secret injection\n- h","body":"# Enterprise Agent Ops\n\nUse this skill for cloud-hosted or continuously running agent systems that need operational controls beyond single CLI sessions.\n\n## Operational Domains\n\n1. runtime lifecycle (start, pause, stop, restart)\n2. observability (logs, metrics, traces)\n3. safety controls (scopes, permissions, kill switches)\n4. change management (rollout, rollback, audit)\n\n## Baseline Controls\n\n- immutable deployment artifacts\n- least-privilege credentials\n- environment-level secret injection\n- hard timeout and retry budgets\n- audit log for high-risk actions\n\n## Metrics to Track\n\n- success rate\n- mean retries per task\n- time to recovery\n- cost per successful task\n- failure class distribution\n\n## Incident Pattern\n\nWhen failure spikes:\n1. freeze new rollout\n2. capture representative traces\n3. isolate failing route\n4. patch with smallest safe change\n5. run regression + security checks\n6. resume gradually\n\n## Deployment Integrations\n\nThis skill pairs with:\n- PM2 workflows\n- systemd services\n- container orchestrators\n- CI/CD gates\n"},"category":"official","lastSynced":"2026-03-06T04:08:27.502Z","seo":{"title":{"en":"enterprise-agent-ops: Setup Guide for Long-Lived AI Agent...","zh":"企业级AI代理运营设置指南","ja":"エンタープライズAIエージェントの運用ベストプラクティス","ko":"엔터프라이즈 AI 에이전트 작동 가이드","pt":"Guia de Configuração de Operações de Agentes Empresariais","ru":"Настройка ИИ Агентов: Руководство по Enterprise Agent Ops","ar":"دليل إعداد عمليات وكلاء المؤسسة"},"description":{"en":"Deploy & manage persistent AI agents with enterprise-grade controls. Learn how to implement observability, lifecycle management, and security boundaries for ...","zh":"了解如何使用企业级AI代理运营技能，实现长期运行的AI代理系统的可观察性、安全边界和生命周期管理","ja":"エンタープライズAIエージェントの運用を効率化するためのスキル。可観測性、セキュリティ境界、ライフサイクル管理を実現","ko":"엔터프라이즈 AI 에이전트 작동을 위한 운용 가이드. 관찰 가능성, 보안 경계, 수명주기 관리를 실현","pt":"Aprenda a operar cargas de trabalho de agentes de longa duração com observabilidade, segurança e gerenciamento de ciclo de vida","ru":"Узнайте, как работать с долгоживущими рабочими нагрузками ИИ Агентов с наблюдаемостью, безопасностью и управлением жизненного цикла","ar":"تعلم تشغيل أحمال عمل وكلاء المؤسسة على المدى الطويل مع القدرة على الرصد والأمان وإدارة دورة الحياة"},"definition":{"en":"enterprise-agent-ops is a skill for operating long-lived AI agent workloads with enterprise-grade operational controls. It provides capabilities for runtime lifecycle management, observability (logs, metrics, traces), safety controls, and change management beyond single CLI sessions.","zh":"企业级AI代理运营是指为长期运行的AI代理系统提供可观察性、安全边界和生命周期管理的运营技能","ja":"エンタープライズAIエージェントの運用とは、長期間実行されるAIエージェントシステムの可観測性、セキュリティ境界、ライフサイクル管理を提供する運用スキルのこと","ko":"엔터프라이즈 AI 에이전트 작동은 장기간 작동하는 AI 에이전트 시스템의 관찰 가능성, 보안 경계, 수명주기 관리를 제공하는 운용 가이드","pt":"O que é Enterprise Agent Ops? É uma habilidade para operar agentes de longa duração com observabilidade e segurança","ru":"Что такое Enterprise Agent Ops? Это навык для работы с долгоживущими ИИ Агентами с наблюдаемостью и безопасностью","ar":"ما هو Enterprise Agent Ops؟ إنه مهارة لتشغيل وكلاء المؤسسة على المدى الطويل مع القدرة على الرصد والأمان"},"features":{"en":["Runtime lifecycle management (start, pause, stop, restart commands)","Comprehensive observability with logs, metrics, and traces","Safety controls including scopes, permissions, and kill switches","Change management for rollout, rollback, and audit processes","Immutable deployment artifacts for consistent operations","Environment-level secret injection with least-privilege credentials"],"zh":["运行时生命周期管理（启动、暂停、停止、重启）","可观察性（日志、指标、跟踪）","安全控制（范围、权限、杀死开关）","变更管理（滚动更新、回滚、审计）"],"ja":["ランタイムライフサイクル管理（起動、暂停、停止、再起動）","可観測性（ログ、メトリクス、トレース）","セキュリティコントロール（スコープ、パーミッション、キルスイッチ）","変更管理（ロールアウト、ロールバック、監査）"],"ko":["실행 시간 수명주기 관리（시작、暂停、중지、다시 시작）","관찰 가능성（로그、메트릭、추적）","보안 제어（범위、권한、킬 스위치）","변경 관리（롤아웃、롤백、감사）"],"pt":["Gerenciamento de ciclo de vida de runtime","Observabilidade com logs, métricas e rastreios","Controles de segurança com escopos e permissões","Gerenciamento de mudanças com rollout e rollback"],"ru":["Управление жизненным циклом runtime","Наблюдаемость с логами, метриками и трассировками","Контроли безопасности с областями и разрешениями","Управление изменениями с rollout и rollback"],"ar":["إدارة دورة الحياة للتشغيل","القدرة على الرصد مع سجلات وقياسات وتتبع","ضوابط الأمان مع نطاقات وتصريحات","إدارة التغييرات مع التوزيع والتراجع"]},"keywords":{"en":["how to use enterprise-agent-ops","what is enterprise-agent-ops","enterprise-agent-ops vs crewai","enterprise-agent-ops alternative","enterprise-agent-ops install","enterprise-agent-ops setup guide","long-lived AI agent management","claude agent observability","MCP agent security controls","AI agent lifecycle management"],"zh":["企业级AI代理运营","AI代理系统","可观察性","安全边界","生命周期管理","运用技能","AIエージェント","Anthropic","Claude"],"ja":["エンタープライズAIエージェントの運用","AIエージェントシステム","可観測性","セキュリティ境界","ライフサイクル管理","運用スキル","AIエージェント","Anthropic","Claude"],"ko":["엔터프라이즈 AI 에이전트 작동","AI 에이전트 시스템","관찰 가능성","보안 경계","수명주기 관리","운용 가이드","AI 에이전트","Anthropic","Claude"],"pt":["operacoes de agentes empresariais","ia agentes","desenvolvimento de agentes","gerenciamento de ciclo de vida","observabilidade de agentes","segurança de agentes"],"ru":["ИИ Агенты","операции ИИ Агентов","разработка ИИ Агентов","управление жизненным циклом","наблюдаемость ИИ Агентов","безопасность ИИ Агентов"],"ar":["عمليات وكلاء المؤسسة","وكلاء الذكاء الاصطناعي","تطوير وكلاء","إدارة دورة الحياة","القدرة على الرصد لوكلاء","أمان وكلاء"]}},"agentAnalysis":{"suitability":{"en":"Essential for Production Agents requiring secure, observable, and long-running operation in enterprise environments.","zh":"对于需要在企业环境中安全、可观测且长期运行的Production Agent而言至关重要。","ja":"企業環境における安全で観測可能、かつ長時間稼働するProduction Agentの運用に不可欠です。","ko":"엔터프라이즈 환경에서 안전하고, 관찰 가능하며, 장기간 운영되는 Production Agent에 필수적입니다.","es":"Esencial para Production Agents que requieren operación segura, observable y de larga duración en entornos empresariales.","fr":"Essentiel pour les Production Agents nécessitant une opération sécurisée, observable et de longue durée dans des environnements d''entreprise.","de":"Essenziell für Production Agents, die einen sicheren, beobachtbaren und langlaufenden Betrieb in Unternehmensumgebungen erfordern.","pt":"Essencial para Production Agents que exigem operação segura, observável e de longa duração em ambientes empresariais.","ru":"Необходимо для Production Agents, требующих безопасной, наблюдаемой и длительной работы в корпоративных средах.","ar":"أساسي لـ Production Agents التي تتطلب تشغيلًا آمنًا ويمكن مراقبته ويعمل لفترات طويلة في بيئات المؤسسات."},"recommendation":{"en":"Enables operation of persistent agent workloads with immutable deployment artifacts, least-privilege credentials, and environment-level secret injection. Provides critical runtime lifecycle management, observability (logs, metrics, traces), and safety controls including scopes and kill switches.","zh":"能够以不可变的部署工件、最小权限凭证和环境级密钥注入来操作持久性Agent工作负载。提供关键的运行时生命周期管理、可观测性（日志、指标、追踪）以及包括作用域和紧急停止开关在内的安全控制。","ja":"不変のデプロイメントアーティファクト、最小権限の資格情報、環境レベルのシークレットインジェクションを用いた永続的なAgentワークロードの操作を可能にします。重要なランタイムライフサイクル管理、観測可能性（ログ、メトリクス、トレース）、およびスコープとキルスイッチを含む安全制御を提供します。","ko":"불변의 배포 아티팩트, 최소 권한 자격 증명 및 환경 수준의 비밀 주입을 통해 지속적인 Agent 워크로드 운영을 가능하게 합니다. 중요한 런타임 생명주기 관리, 관찰 가능성(로그, 메트릭, 트레이스) 및 범위(scope)와 킬 스위치(kill switch)를 포함한 안전 컨트롤을 제공합니다.","es":"Permite la operación de cargas de trabajo de agentes persistentes con artefactos de despliegue inmutables, credenciales de mínimo privilegio e inyección de secretos a nivel de entorno. Proporciona gestión crítica del ciclo de vida en tiempo de ejecución, observabilidad (logs, metrics, traces) y controles de seguridad que incluyen scopes y kill switches.","fr":"Permet le fonctionnement de charges de travail d''agents persistants avec des artefacts de déploiement immuables, des identifiants à privilèges minimum et l''injection de secrets au niveau de l''environnement. Fournit une gestion critique du cycle de vie d''exécution, une observabilité (logs, metrics, traces) et des contrôles de sécurité incluant des scopes et des kill switches.","de":"Ermöglicht den Betrieb von persistenten Agent-Workloads mit unveränderlichen Deployment-Artefakten, Berechtigungen nach dem Prinzip des geringsten Privilegs und der Injection von Secrets auf Umgebungsebene. Bietet kritisches Runtime-Lifecycle-Management, Observability (Logs, Metrics, Traces) und Safety-Controls, einschließlich Scopes und Kill Switches.","pt":"Permite a operação de cargas de trabalho de agentes persistentes com artefatos de implantação imutáveis, credenciais de privilégio mínimo e injeção de segredos em nível de ambiente. Fornece gerenciamento crítico do ciclo de vida de runtime, observabilidade (logs, métricas, traces) e controles de segurança, incluindo escopos e kill switches.","ru":"Обеспечивает работу постоянных нагрузок агентов с неизменяемыми артефактами развертывания, учетными данными с минимальными привилегиями и внедрением секретов на уровне среды. Предоставляет критически важное управление жизненным циклом runtime, наблюдаемость (логи, метрики, трассировки) и средства контроля безопасности, включая области действия и аварийные выключатели.","ar":"يتيح تشغيل أحمال عمل الوكيل المستمرة مع مواد النشر الثابتة، وأcredentials ذات least-privilege، وحقن الأسرار على مستوى البيئة. يوفر إدارة دورة حياة التشغيل الحرجة، وإمكانية المراقبة (logs, metrics, traces)، وضوابط السلامة بما في ذلك النطاقات وkill switches."},"useCases":{"en":["Managing long-lived agent lifecycle (start, pause, stop, restart)","Implementing safety boundaries and kill switches for security","Deploying immutable artifacts with rollout/rollback change management","Injecting environment-level secrets securely","Monitoring agent performance through logs, metrics, and traces"],"zh":["管理长生命周期Agent的生命周期（启动、暂停、停止、重启）","为实现安全性而实施安全边界和紧急停止开关","通过推出/回滚变更管理来部署不可变工件","安全地注入环境级密钥","通过日志、指标和追踪来监控Agent性能"],"ja":["長寿命なAgentのライフサイクル管理（開始、一時停止、停止、再起動）","セキュリティのための安全境界とキルスイッチの実装","ロールアウト/ロールバック変更管理を用いた不変アーティファクトのデプロイ","環境レベルのシークレットを安全に注入","ログ、メトリクス、トレースを通じたAgentパフォーマンスの監視"],"ko":["장수명 Agent의 생명주기 관리(시작, 일시중지, 중지, 재시작)","보안을 위한 안전 경계 및 킬 스위치(kill switch) 구현","롤아웃/롤백 변경 관리로 불변 아티팩트 배포","환경 수준의 비밀을 안전하게 주입","로그, 메트릭, 트레이스를 통한 Agent 성능 모니터링"],"es":["Gestion del ciclo de vida de agentes de larga duración (inicio, pausa, parada, reinicio)","Implementación de límites de seguridad y kill switches para la seguridad","Despliegue de artefactos inmutables con gestión de cambios rollout/rollback","Inyección segura de secretos a nivel de entorno","Monitorización del rendimiento del agente mediante logs, metrics y traces"],"fr":["Gestion du cycle de vie des agents de longue durée (démarrage, pause, arrêt, redémarrage)","Mise en œuvre de limites de sécurité et de kill switches pour la sécurité","Déploiement d''artefacts immuables avec une gestion des changements rollout/rollback","Injection sécurisée de secrets au niveau de l''environnement","Surveillance des performances de l''agent via les logs, metrics et traces"],"de":["Verwaltung des Lebenszyklus von langlebigen Agents (starten, pausieren, stoppen, neu starten)","Implementierung von Safety-Boundaries und Kill Switches für die Sicherheit","Deployment von unveränderlichen Artefakten mit Rollout/Rollback-Change-Management","Sichere Injection von Secrets auf Umgebungsebene","Überwachung der Agentenleistung durch Logs, Metrics und Traces"],"pt":["Gerenciamento do ciclo de vida de agentes de longa duração (iniciar, pausar, parar, reiniciar)","Implementação de limites de segurança e kill switches para segurança","Implante artefatos imutáveis com gerenciamento de alterações de rollout/rollback","Injetar segredos em nível de ambiente com segurança","Monitoramento do desempenho do agente por meio de logs, métricas e traces"],"ru":["Управление жизненным циклом долгоживущих агентов (запуск, приостановка, остановка, перезапуск)","Реализация границ безопасности и аварийных выключателей для обеспечения безопасности","Развертывание неизменяемых артефактов с управлением изменениями rollout/rollback","Безопасное внедрение секретов на уровне среды","Мониторинг производительности агента с помощью логов, метрик и трассировок"],"ar":["إدارة دورة حياة الوكيل طويل الأمد (بدء، إيقاف مؤقت، إيقاف، إعادة تشغيل)","تنفيذ حدود السلامة وkill switches للأمان","نشر مواد النشر الثابتة مع إدارة التغيير rollout/rollback","حقن الأسرار على مستوى البيئة بأمان","مراقبة أداء الوكيل من خلال logs وmetrics وtraces"]},"limitations":{"en":["Designed for cloud-hosted/continuously running systems only","Requires infrastructure for observability stack implementation","Needs credential management system for least-privilege access"],"zh":["仅设计用于云托管/持续运行的系统","需要基础设施来实现可观测性技术栈","需要凭证管理系统来实现最小权限访问"],"ja":["クラウドホスト型/継続的稼働システム専用に設計されています","観測可能性スタックを実装するためのインフラストラクチャが必要です","最小権限アクセスのための資格情報管理システムが必要です"],"ko":["클라우드 호스팅/지속적으로 실행되는 시스템만을 위해 설계됨","관찰 가능성 스택 구현을 위한 인프라가 필요함","최소 권한 접근을 위한 자격 증명 관리 시스템이 필요함"],"es":["Diseñado únicamente para sistemas alojados en la nube/en ejecución continua","Requiere infraestructura para la implementación de la pila de observabilidad","Necesita un sistema de gestión de credenciales para el acceso de mínimo privilegio"],"fr":["Conçu uniquement pour les systèmes hébergés dans le cloud/fonctionnant en continu","Nécessite une infrastructure pour la mise en œuvre de la stack d''observabilité","Requiert un système de gestion des identifiants pour un accès à privilèges minimum"],"de":["Nur für cloud-gehostete/kontinuierlich laufende Systeme konzipiert","Erfordert Infrastruktur für die Implementierung des Observability-Stacks","Benötigt ein Credential-Management-System für den Zugriff nach dem Prinzip des geringsten Privilegs"],"pt":["Projetado apenas para sistemas hospedados em nuvem/em execução contínua","Requer infraestrutura para implementação da pilha de observabilidade","Necessita de um sistema de gerenciamento de credenciais para acesso de privilégio mínimo"],"ru":["Предназначен только для облачных/постоянно работающих систем","Требует инфраструктуры для реализации стека наблюдаемости","Требуется система управления учетными данными для доступа с минимальными привилегиями"],"ar":["مصمم لأنظمة الاستضافة السحابية/التشغيل المستمر فقط","يتطلب بنية تحتية لتنفيذ مجموعة أدوات المراقبة","يحتاج إلى نظام إدارة credentials للوصول بـ least-privilege"]},"version":4},"contentHash":"27edc796df2bf30b611b05ca443434bf65bfc6fde18c94cd16ec41357f4c8ac5","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":58}');
