INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/enterprise-agent-ops', 'enterprise-agent-ops', 'affaan-m', 'everything-claude-code', 'official', 'enterprise-agent-ops affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The enterprise-agent-ops skill provides operational controls for cloud-hosted or continuously running AI agent systems. It enables developers to manage runtime lifecycle, observability, safety controls, and change management for long-lived agent workloads. 企业级AI代理运营技能提供长期运行的AI代理系统的可观察性、安全边界和生命周期管理 エンタープライズAIエージェントの運用スキルは、長期間実行されるAIエージェントシステムの可観測性、セキュリティ境界、ライフサイクル管理を提供 엔터프라이즈 AI 에이전트 작동 가이드는 장기간 작동하는 AI 에이전트 시스템의 관찰 가능성, 보안 경계, 수명주기 관리를 제공 O Enterprise Agent Ops permite operar cargas de trabalho de agentes de longa duração com controles operacionais avançados ИИ Агенты: Enterprise Agent Ops позволяет работать с долгоживущими рабочими нагрузками с расширенными операционными контролями يعمل Enterprise Agent Ops على تشغيل أحمال عمل وكلاء المؤسسة على المدى الطويل مع سيطرة تشغيلية متقدمة how to use enterprise-agent-ops what is enterprise-agent-ops enterprise-agent-ops vs crewai enterprise-agent-ops alternative enterprise-agent-ops install enterprise-agent-ops setup guide long-lived AI agent management claude agent observability MCP agent security controls AI agent lifecycle management 企业级AI代理运营 AI代理系统 可观察性 安全边界 生命周期管理 运用技能 AIエージェント Anthropic Claude Runtime lifecycle management (start, pause, stop, restart commands) Comprehensive observability with logs, metrics, and traces Safety controls including scopes, permissions, and kill switches Change management for rollout, rollback, and audit processes Immutable deployment artifacts for consistent operations Environment-level secret injection with least-privilege credentials enterprise-agent-ops is a skill for operating long-lived AI agent workloads with enterprise-grade operational controls. It provides capabilities for runtime lifecycle management, observability (logs, metrics, traces), safety controls, and change management beyond single CLI sessions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ParadeTo/vue-tree-list/openspec-explore', 'community', 'ParadeTo', 'vue-tree-list', 'ParadeTo/vue-tree-list', 'openspec-explore', 686, 125, 57, '2026-02-22T07:18:50Z', '2026-03-06T06:27:16.887Z', '64ded43c11f45d9be10670202659bbbb81bb70e4fd67d3579ae31f1a1f693911', '{"id":"ParadeTo/vue-tree-list/openspec-explore","name":"openspec-explore","description":{"en":"openspec-explore is a Vue component for visualizing tree structures, allowing developers to think deeply and investigate codebases. It enables exploration and creation of OpenSpec artifacts.","zh":"openspec-explore是一个Vue组件，用于创建树结构。它允许您探索和可视化复杂的数据结构","ja":"openspec-exploreは、Vueコンポーネントのツリ構造を作成するために使用されます。複雑なデータ構造を探索して視覚化することができます","ko":"openspec-explore는 Vue 컴포넌트의 트리 구조를 생성하는 데 사용됩니다. 복잡한 데이터 구조를 탐색하고 시각화할 수 있습니다","es":"openspec-explore es un componente Vue para visualizar estructuras de árbol, permitiendo la exploración y creación de artefactos OpenSpec","fr":"openspec-explore est un composant Vue pour visualiser les structures d''arbre, permettant l''exploration et la création d''artefacts OpenSpec","de":"openspec-explore ist ein Vue-Komponente für die Visualisierung von Baumstrukturen, ermöglicht die Exploration und Erstellung von OpenSpec-Artefakten","pt":"O openspec-explore é um componente Vue para estruturas de árvore, permitindo explorar e visualizar dados de forma livre.","ru":"openspec-explore - это компонент Vue для древовидных структур, позволяющий исследовать и визуализировать данные свободно.","ar":"openspec-explore هو مكون Vue للهياكل الشجرية، مما يسمح بالاستكشاف والتصور البيانات بحرية."},"seo":{"title":{"en":"openspec-explore: Vue Component Setup Guide | AI Agent Skill","zh":"openspec-explore.setup Vue组件树结构指南","ja":"openspec-explore.Vueコンポーネントツリ構造設定ガイド","ko":"openspec-explore.Vue 컴포넌트 트리 구조 설정 가이드","es":"Guía de configuración de openspec-explore para estructura...","fr":"Mode d''exploration openspec-explore pour les structures d...","de":"Einrichtung von openspec-explore für Baumstrukturen mit Vue","pt":"Guia de Configuração do openspec-explore: Explorando Estr...","ru":"Руководство по настройке openspec-explore: Изучение древо...","ar":"دليل إعداد openspec-explore: استكشاف الهياكل الشجرية باست..."},"description":{"en":"Discover how to use openspec-explore, a Vue component for tree structure visualization. Learn how to enter explore mode and create OpenSpec artifacts with th...","zh":"了解openspec-explore的功能和特点，学习如何在Vue项目中使用此组件树结构","ja":"openspec-exploreの機能と特徴をご紹介。Vueプロジェクトでこのコンポーネントツリ構造を使用する方法を学びましょう","ko":"openspec-explore의 기능과 특징을 알아보세요. Vue 프로젝트에서 이 컴포넌트 트리 구조를 사용하는 방법을 배우세요","es":"Descubre cómo utilizar openspec-explore para visualizar estructuras de árbol en Vue, con características de exploración y creación de artefactos OpenSpec","fr":"Découvrez comment utiliser openspec-explore pour visualiser les structures d''arbre dans Vue, avec des fonctionnalités d''exploration et de création d''artefact...","de":"Erfahren Sie, wie Sie openspec-explore verwenden können, um Baumstrukturen in Vue zu visualisieren, mit Funktionen zur Exploration und Erstellung von OpenSpe...","pt":"Aprenda a configurar o componente Vue openspec-explore para visualizar estruturas de árvore de forma eficaz. Descubra como explorar e criar artefatos OpenSpec","ru":"Узнайте, как настроить компонент Vue openspec-explore для эффективной визуализации древовидных структур. Откройте для себя, как исследовать и создавать артеф...","ar":"تعرف على كيفية تكوين مكون Vue openspec-explore لتصور الهياكل الشجرية بفعالية. اكتشف كيفية استكشاف وإنشاء مكونات OpenSpec"},"definition":{"en":"openspec-explore is a Vue component facilitating tree structure visualization and exploration, ideal for developers and AI agents.","zh":"openspec-explore是一种Vue组件，用于创建树结构，以便于数据探索和可视化","ja":"openspec-exploreは、Vueコンポーネントのツリ構造を作成するために使用されるコンポーネントで、データの探索と視覚化を容易にします","ko":"openspec-explore는 Vue 컴포넌트의 트리 구조를 생성하는 데 사용되는 컴포넌트로 데이터 탐색과 시각화를 쉽게 합니다","es":"openspec-explore es un componente de software para la visualización de estructuras de árbol en aplicaciones Vue","fr":"openspec-explore est un composant logiciel pour la visualisation des structures d''arbre dans les applications Vue","de":"openspec-explore ist ein Software-Komponente für die Visualisierung von Baumstrukturen in Vue-Anwendungen","pt":"O openspec-explore é um componente Vue que permite explorar e visualizar estruturas de árvore","ru":"openspec-explore - это компонент Vue, который позволяет исследовать и визуализировать древовидные структуры","ar":"openspec-explore هو مكون Vue الذي يسمح بالاستكشاف والتصور الهياكل الشجرية"},"features":{"en":["Enters explore mode for deep thinking and investigation","Supports reading files and searching code","Enables creation of OpenSpec artifacts, such as proposals and specs","Reminds users to exit explore mode before implementing changes","Compatible with commands like /opsx:new and /opsx:ff"],"zh":["支持树结构创建","允许探索和可视化复杂数据结构","适用于Vue项目","支持OpenSpec文档创建","探索模式下可以读取文件和搜索代码"],"ja":["ツリ構造の作成をサポート","複雑なデータ構造の探索と視覚化を可能に","Vueプロジェクト向け","OpenSpecドキュメントの作成をサポート","探索モードでファイルの読み取りとコードの検索が可能"],"ko":["트리 구조 생성 지원","복잡한 데이터 구조의 탐색과 시각화 지원","Vue 프로젝트용","OpenSpec 문서 생성 지원","탐색 모드에서 파일 읽기와 코드 검색이 가능"],"es":["Exploración de estructuras de árbol","Creación de artefactos OpenSpec","Visualización de datos en forma de árbol","Integración con Vue","Modo de exploración para pensamiento y diseño"],"fr":["Exploration des structures d''arbre","Création d''artefacts OpenSpec","Visualisation des données sous forme d''arbre","Intégration avec Vue","Mode d''exploration pour la réflexion et la conception"],"de":["Exploration von Baumstrukturen","Erstellung von OpenSpec-Artefakten","Visualisierung von Daten in Baumform","Integration mit Vue","Explorationsmodus für Denken und Design"],"pt":["Exploração de estruturas de árvore com Vue","Criação de artefatos OpenSpec","Leitura de arquivos e busca de código","Investigação do código-base","Modo de exploração para pensamento e design"],"ru":["Изучение древовидных структур с помощью Vue","Создание артефактов OpenSpec","Чтение файлов и поиск кода","Исследование кодовой базы","Режим исследования для мышления и проектирования"],"ar":["استكشاف الهياكل الشجرية باستخدام Vue","إنشاء مكونات OpenSpec","قراءة الملفات و البحث عن الكود","التحقيق في قاعدة الكود","وضع الاستكشاف للتفكير والتصميم"]},"keywords":{"en":["how to use openspec-explore","openspec-explore alternative","openspec-explore setup guide","what is openspec-explore","openspec-explore vs other Vue components","openspec-explore install","Vue component for tree structure","openspec-explore documentation","openspec-explore tutorial"],"zh":["openspec-explore","Vue组件","树结构","数据探索","可视化","OpenSpec","Vue项目","AIエージェント","Vue树结构组件"],"ja":["openspec-explore","Vueコンポーネント","ツリ構造","データ探索","視覚化","OpenSpec","Vueプロジェクト","AIエージェント","Vueツリ構造コンポーネント"],"ko":["openspec-explore","Vue 컴포넌트","트리 구조","데이터 탐색","시각화","OpenSpec","Vue 프로젝트","AI 에이전트","Vue 트리 구조 컴포넌트"],"es":["openspec-explore","estructuras de árbol","Vue","visualización de datos","creación de artefactos OpenSpec","modo de exploración","herramientas de desarrollo","componentes de software","desarrollo de aplicaciones"],"fr":["openspec-explore","structures d''arbre","Vue","visualisation de données","création d''artefacts OpenSpec","mode d''exploration","outils de développement","composants logiciels","développement d''applications"],"de":["openspec-explore","Baumstrukturen","Vue","Datenvisualisierung","Erstellung von OpenSpec-Artefakten","Explorationsmodus","Entwicklertools","Software-Komponenten","Anwendungsentwicklung"],"pt":["openspec-explore","Vue","estruturas de árvore","arteefatos OpenSpec","exploração de código","desenvolvimento de software","ferramentas de desenvolvimento","componentes Vue","visualização de dados"],"ru":["openspec-explore","Vue","древовидные структуры","артефакты OpenSpec","исследование кода","разработка программного обеспечения","инструменты разработки","компоненты Vue","визуализация данных"],"ar":["openspec-explore","Vue","هياكل شجرية","مكونات OpenSpec","استكشاف الكود","تطوير البرمجيات","أدوات التطوير","مكونات Vue","تصور البيانات"]}},"owner":"ParadeTo","repo":"vue-tree-list","repoPath":"ParadeTo/vue-tree-list","stars":686,"forks":125,"updatedAt":"2026-02-22T07:18:50Z","topics":[],"category":"community","skillMd":{"name":"openspec-explore","description":"Enter explore mode - a thinking partner for exploring ideas, investigating problems, and clarifying requirements. Use when the user wants to think through something before or during a change.","version":"1.0","bodyPreview":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s c","body":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s capturing thinking, not implementing.\n\n**This is a stance, not a workflow.** There are no fixed steps, no required sequence, no mandatory outputs. You''re a thinking partner helping the user explore.\n\n---\n\n## The Stance\n\n- **Curious, not prescriptive** - Ask questions that emerge naturally, don''t follow a script\n- **Open threads, not interrogations** - Surface multiple interesting directions and let the user follow what resonates. Don''t funnel them through a single path of questions.\n- **Visual** - Use ASCII diagrams liberally when they''d help clarify thinking\n- **Adaptive** - Follow interesting threads, pivot when new information emerges\n- **Patient** - Don''t rush to conclusions, let the shape of the problem emerge\n- **Grounded** - Explore the actual codebase when relevant, don''t just theorize\n\n---\n\n## What You Might Do\n\nDepending on what the user brings, you might:\n\n**Explore the problem space**\n- Ask clarifying questions that emerge from what they said\n- Challenge assumptions\n- Reframe the problem\n- Find analogies\n\n**Investigate the codebase**\n- Map existing architecture relevant to the discussion\n- Find integration points\n- Identify patterns already in use\n- Surface hidden complexity\n\n**Compare options**\n- Brainstorm multiple approaches\n- Build comparison tables\n- Sketch tradeoffs\n- Recommend a path (if asked)\n\n**Visualize**\n```\n┌─────────────────────────────────────────┐\n│     Use ASCII diagrams liberally        │\n├─────────────────────────────────────────┤\n│                                         │\n│   ┌────────┐         ┌────────┐        │\n│   │ State  │────────▶│ State  │        │\n│   │   A    │         │   B    │        │\n│   └────────┘         └────────┘        │\n│                                         │\n│   System diagrams, state machines,      │\n│   data flows, architecture sketches,    │\n│   dependency graphs, comparison tables  │\n│                                         │\n└─────────────────────────────────────────┘\n```\n\n**Surface risks and unknowns**\n- Identify what could go wrong\n- Find gaps in understanding\n- Suggest spikes or investigations\n\n---\n\n## OpenSpec Awareness\n\nYou have full context of the OpenSpec system. Use it naturally, don''t force it.\n\n### Check for context\n\nAt the start, quickly check what exists:\n```bash\nopenspec list --json\n```\n\nThis tells you:\n- If there are active changes\n- Their names, schemas, and status\n- What the user might be working on\n\n### When no change exists\n\nThink freely. When insights crystallize, you might offer:\n\n- \"This feels solid enough to start a change. Want me to create one?\"\n  → Can transition to `/opsx:new` or `/opsx:ff`\n- Or keep exploring - no pressure to formalize\n\n### When a change exists\n\nIf the user mentions a change or you detect one is relevant:\n\n1. **Read existing artifacts for context**\n   - `openspec/changes/<name>/proposal.md`\n   - `openspec/changes/<name>/design.md`\n   - `openspec/changes/<name>/tasks.md`\n   - etc.\n\n2. **Reference them naturally in conversation**\n   - \"Your design mentions using Redis, but we just realized SQLite fits better...\"\n   - \"The proposal scopes this to premium users, but we''re now thinking everyone...\"\n\n3. **Offer to capture when decisions are made**\n\n   | Insight Type | Where to Capture |\n   |--------------|------------------|\n   | New requirement discovered | `specs/<capability>/spec.md` |\n   | Requirement changed | `specs/<capability>/spec.md` |\n   | Design decision made | `design.md` |\n   | Scope changed | `proposal.md` |\n   | New work identified | `tasks.md` |\n   | Assumption invalidated | Relevant artifact |\n\n   Example offers:\n   - \"That''s a design decision. Capture it in design.md?\"\n   - \"This is a new requirement. Add it to specs?\"\n   - \"This changes scope. Update the proposal?\"\n\n4. **The user decides** - Offer and move on. Don''t pressure. Don''t auto-capture.\n\n---\n\n## What You Don''t Have To Do\n\n- Follow a script\n- Ask the same questions every time\n- Produce a specific artifact\n- Reach a conclusion\n- Stay on topic if a tangent is valuable\n- Be brief (this is thinking time)\n\n---\n\n## Handling Different Entry Points\n\n**User brings a vague idea:**\n```\nUser: I''m thinking about adding real-time collaboration\n\nYou: Real-time collab is a big space. Let me think about this...\n\n      COLLABORATION SPECTRUM\n      ════════════════════════════════════════════\n\n      Awareness          Coordination         Sync\n          │                   │                 │\n          ▼                   ▼                 ▼\n      ┌────────┐         ┌────────┐        ┌────────┐\n      │Presence│         │Cursors │        │  CRDT  │\n      │  \"3    │         │ Multi  │        │Conflict│\n      │online\" │         │ select │        │  free  │\n      └────────┘         └────────┘        └────────┘\n          │                   │                 │\n       trivial            moderate           complex\n\n      Where''s your head at?\n```\n\n**User brings a specific problem:**\n```\nUser: The auth system is a mess\n\nYou: [reads codebase]\n\n     ┌─────────────────────────────────────────────┐\n     │              CURRENT AUTH FLOW              │\n     └─────────────────────────────────────────────┘\n                        │\n          ┌─────────────┼─────────────┐\n          ▼             ▼             ▼\n     ┌─────────┐  ┌─────────┐  ┌─────────┐\n     │ Google  │  │  GitHub │  │  Email  │\n     │  OAuth  │  │  OAuth  │  │  Magic  │\n     └────┬────┘  └────┬────┘  └────┬────┘\n          │             │             │\n          └─────────────┼─────────────┘\n                        ▼\n                  ┌───────────┐\n                  │  Session  │\n                  └─────┬─────┘\n                        │\n                        ▼\n                  ┌───────────┐\n                  │   Perms   │\n                  └───────────┘\n\n     I see three tangles. Which one''s burning?\n```\n\n**User is stuck mid-implementation:**\n```\nUser: /opsx:explore add-auth-system\n      The OAuth integration is more complex than expected\n\nYou: [reads change artifacts]\n\n     You''re on task 4: \"Implement OAuth flow\"\n\n     Let me trace what''s involved...\n\n     [draws diagram, explores options, suggests paths]\n\n     Want to update the design to reflect this?\n     Or add a spike task to investigate?\n```\n\n**User wants to compare options:**\n```\nUser: Should we use Postgres or SQLite?\n\nYou: Generic answer is boring. What''s the context?\n\nUser: A CLI tool that tracks local dev environments\n\nYou: That changes everything.\n\n     ┌─────────────────────────────────────────────────┐\n     │         CLI TOOL DATA STORAGE                  │\n     └─────────────────────────────────────────────────┘\n\n     Key constraints:\n     • No daemon running\n     • Must work offline\n     • Single user\n\n                  SQLite          Postgres\n     Deployment   embedded ✓      needs server ✗\n     Offline      yes ✓           no ✗\n     Single file  yes ✓           no ✗\n\n     SQLite. Not even close.\n\n     Unless... is there a sync component?\n```\n\n---\n\n## Ending Discovery\n\nThere''s no required ending. Discovery might:\n\n- **Flow into action**: \"Ready to start? /opsx:new or /opsx:ff\"\n- **Result in artifact updates**: \"Updated design.md with these decisions\"\n- **Just provide clarity**: User has what they need, moves on\n- **Continue later**: \"We can pick this up anytime\"\n\nWhen it feels like things are crystallizing, you might summarize:\n\n```\n## What We Figured Out\n\n**The problem**: [crystallized understanding]\n\n**The approach**: [if one emerged]\n\n**Open questions**: [if any remain]\n\n**Next steps** (if ready):\n- Create a change: /opsx:new <name>\n- Fast-forward to tasks: /opsx:ff <name>\n- Keep exploring: just keep talking\n```\n\nBut this summary is optional. Sometimes the thinking IS the value.\n\n---\n\n## Guardrails\n\n- **Don''t implement** - Never write code or implement features. Creating OpenSpec artifacts is fine, writing application code is not.\n- **Don''t fake understanding** - If something is unclear, dig deeper\n- **Don''t rush** - Discovery is thinking time, not task time\n- **Don''t force structure** - Let patterns emerge naturally\n- **Don''t auto-capture** - Offer to save insights, don''t just do it\n- **Do visualize** - A good diagram is worth many paragraphs\n- **Do explore the codebase** - Ground discussions in reality\n- **Do question assumptions** - Including the user''s and your own\n"},"lastSynced":"2026-03-06T06:27:16.887Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced tree structure visualization and OpenSpec artifact creation capabilities.","zh":"非常适合需要高级树结构可视化和 OpenSpec 文档创建能力的代码分析代理。","ja":"コード分析エージェントが高度な木構造の可視化と OpenSpec アーティファクトの作成機能を必要とする場合に最適です。","ko":"고급 트리 구조 시각화 및 OpenSpec 아티팩트 생성 기능이 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan visualización avanzada de estructuras de árbol y capacidades de creación de artefactos OpenSpec.","fr":"Parfait pour les agents d''analyse de code nécessitant une visualisation avancée de structures d''arbre et des capacités de création d''artéfacts OpenSpec.","de":"Perfekt für Code-Analyse-Agents, die eine erweiterte Baumstruktur-Visualisierung und OpenSpec-Artefakt-Erstellungs-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de visualização avançada de estrutura de árvore e capacidades de criação de artefatos OpenSpec.","ru":"Идеально подходит для агентов анализа кода, которым требуются продвинутые возможности визуализации структуры дерева и создания артефактов OpenSpec.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى تمثيل هيكل شجري متقدم وإنشاء مواصفات مفتوحة OpenSpec."},"recommendation":{"en":"Empowers agents to deeply investigate codebases, visualize tree structures, and create OpenSpec artifacts such as proposals, designs, and specs, utilizing Vue components and exploring codebases without implementing changes, while leveraging OpenSpec protocols.","zh":"赋予代理深入调查代码库、可视化树结构、创建 OpenSpec 文档（如提案、设计和规格）等能力，利用 Vue 组件探索代码库而无需实施更改，同时利用 OpenSpec 协议。","ja":"エージェントがコードベースを深く調査し、木構造を可視化し、Vue コンポーネントを使用してコードベースを変更せずに調査し、OpenSpec プロトコルを利用して OpenSpec アーティファクト（提案、設計、仕様など）を作成する機能を提供します。","ko":"에이전트가 코드베이스를 심층적으로 조사하고 트리 구조를 시각화하며 Vue 컴포넌트를 사용하여 코드베이스를 수정하지 않고 탐색하고 OpenSpec 프로토콜을 활용하여 OpenSpec 아티팩트(제안, 설계, 사양 등)를 생성하는 기능을 제공합니다.","es":"Habilita a los agentes a investigar profundamente las bases de código, visualizar estructuras de árbol y crear artefactos OpenSpec como propuestas, diseños y especificaciones, utilizando componentes Vue y explorando las bases de código sin implementar cambios, mientras aprovecha los protocolos OpenSpec.","fr":"Permet aux agents d''enquêter en profondeur sur les bases de code, de visualiser les structures d''arbre et de créer des artéfacts OpenSpec tels que des propositions, des conceptions et des spécifications, en utilisant des composants Vue et en explorant les bases de code sans apporter de modifications, tout en exploitant les protocoles OpenSpec.","de":"Ermächtigt die Agents, Codebasen tief zu untersuchen, Baumstrukturen zu visualisieren und OpenSpec-Artikel wie Vorschläge, Entwürfe und Spezifikationen zu erstellen, indem sie Vue-Komponenten verwenden und Codebasen ohne Änderungen zu implementieren, während sie die OpenSpec-Protokolle nutzen.","pt":"Habilita os agentes a investigar profundamente as bases de código, visualizar estruturas de árvore e criar artefatos OpenSpec, como propostas, designs e especificações, utilizando componentes Vue e explorando bases de código sem implementar alterações, aproveitando os protocolos OpenSpec.","ru":"Наделяет агентов возможностью глубоко исследовать кодовые базы, визуализировать структуры дерева и создавать артефакты OpenSpec, такие как предложения, дизайны и спецификации, используя компоненты Vue и исследуя кодовые базы без реализации изменений, используя протоколы OpenSpec.","ar":"يمنح الوكيل القدرة على التحقيق العميق في قواعد البيانات ، وتصور الهياكل الشجرية ، وإنشاء مواصفات مفتوحة OpenSpec مثل المقترحات والتصاميم والمواصفات ، باستخدام مكونات Vue والاستكشاف قواعد البيانات دون تنفيذ التغييرات ، واستخدام بروتوكولات OpenSpec."},"useCases":{"en":["Investigating complex codebases","Creating OpenSpec proposals and designs","Visualizing tree structures for deep analysis"],"zh":["调查复杂的代码库","创建 OpenSpec 提案和设计","可视化树结构以进行深入分析"],"ja":["複雑なコードベースの調査","OpenSpec 提案と設計の作成","木構造の可視化による深い分析"],"ko":["복잡한 코드베이스 조사","OpenSpec 제안 및 설계 생성","트리 구조 시각화를 통한 심층 분석"],"es":["Investigación de bases de código complejas","Creación de propuestas y diseños OpenSpec","Visualización de estructuras de árbol para un análisis profundo"],"fr":["Enquête sur des bases de code complexes","Création de propositions et de conceptions OpenSpec","Visualisation de structures d''arbre pour une analyse approfondie"],"de":["Untersuchung komplexer Codebasen","Erstellung von OpenSpec-Vorschlägen und -Entwürfen","Visualisierung von Baumstrukturen für eine tiefe Analyse"],"pt":["Investigação de bases de código complexas","Criação de propostas e designs OpenSpec","Visualização de estruturas de árvore para análise profunda"],"ru":["Исследование сложных кодовых баз","Создание предложений и дизайнов OpenSpec","Визуализация структур дерева для глубокого анализа"],"ar":["تحقيق قواعد بيانات معقدة","إنشاء مقترحات وتصاميم مواصفات مفتوحة OpenSpec","تصور هياكل شجرية للتحليل العميق"]},"limitations":{"en":["Must not write code or implement features in explore mode","Requires exit from explore mode for implementation using /opsx:new or /opsx:ff"],"zh":["探索模式下不能编写代码或实现功能","需要退出探索模式以使用 /opsx:new 或 /opsx:ff 进行实现"],"ja":["探索モードではコードを書いたり機能を実装したりできない","実装するには /opsx:new または /opsx:ff を使用して探索モードから退出する必要がある"],"ko":["탐색 모드에서 코드를 작성하거나 기능을 구현할 수 없음","구현하려면 /opsx:new 또는 /opsx:ff를 사용하여 탐색 모드를 종료해야 함"],"es":["No debe escribir código ni implementar características en el modo de exploración","Requiere salir del modo de exploración para la implementación utilizando /opsx:new o /opsx:ff"],"fr":["Ne doit pas écrire de code ni implémenter de fonctionnalités en mode d''exploration","Nécessite de sortir du mode d''exploration pour l''implémentation en utilisant /opsx:new ou /opsx:ff"],"de":["Darf keinen Code schreiben oder Funktionen im Explorationsmodus implementieren","Erfordert das Verlassen des Explorationsmodus für die Implementierung unter Verwendung von /opsx:new oder /opsx:ff"],"pt":["Não deve escrever código ou implementar recursos no modo de exploração","Requer saída do modo de exploração para implementação usando /opsx:new ou /opsx:ff"],"ru":["Не должен писать код или реализовывать функции в режиме исследования","Требует выхода из режима исследования для реализации с использованием /opsx:new или /opsx:ff"],"ar":["لا يجب كتابة التعليمات البرمجية أو تنفيذ الميزات في режим الاستكشاف","يتطلب الخروج من وضع الاستكشاف للتطبيق باستخدام /opsx:new أو /opsx:ff"]},"version":4},"contentHash":"64ded43c11f45d9be10670202659bbbb81bb70e4fd67d3579ae31f1a1f693911","qualityScore":57}');
