INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ParadeTo/vue-tree-list/openspec-explore', 'openspec-explore', 'ParadeTo', 'vue-tree-list', 'community', 'openspec-explore ParadeTo vue-tree-list community openspec-explore is a Vue component for visualizing tree structures, allowing developers to think deeply and investigate codebases. It enables exploration and creation of OpenSpec artifacts. openspec-explore是一个Vue组件，用于创建树结构。它允许您探索和可视化复杂的数据结构 openspec-exploreは、Vueコンポーネントのツリ構造を作成するために使用されます。複雑なデータ構造を探索して視覚化することができます openspec-explore는 Vue 컴포넌트의 트리 구조를 생성하는 데 사용됩니다. 복잡한 데이터 구조를 탐색하고 시각화할 수 있습니다 openspec-explore es un componente Vue para visualizar estructuras de árbol, permitiendo la exploración y creación de artefactos OpenSpec openspec-explore est un composant Vue pour visualiser les structures d''arbre, permettant l''exploration et la création d''artefacts OpenSpec openspec-explore ist ein Vue-Komponente für die Visualisierung von Baumstrukturen, ermöglicht die Exploration und Erstellung von OpenSpec-Artefakten O openspec-explore é um componente Vue para estruturas de árvore, permitindo explorar e visualizar dados de forma livre. openspec-explore - это компонент Vue для древовидных структур, позволяющий исследовать и визуализировать данные свободно. openspec-explore هو مكون Vue للهياكل الشجرية، مما يسمح بالاستكشاف والتصور البيانات بحرية. how to use openspec-explore openspec-explore alternative openspec-explore setup guide what is openspec-explore openspec-explore vs other Vue components openspec-explore install Vue component for tree structure openspec-explore documentation openspec-explore tutorial openspec-explore Vue组件 树结构 数据探索 可视化 OpenSpec Vue项目 AIエージェント Vue树结构组件 Enters explore mode for deep thinking and investigation Supports reading files and searching code Enables creation of OpenSpec artifacts, such as proposals and specs Reminds users to exit explore mode before implementing changes Compatible with commands like /opsx:new and /opsx:ff openspec-explore is a Vue component facilitating tree structure visualization and exploration, ideal for developers and AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('beavermoney/beavermoney/relay-pagination', 'community', 'beavermoney', 'beavermoney', 'beavermoney/beavermoney', 'relay-pagination', 0, 0, 57, '2026-03-07T01:49:01.507Z', '2026-03-07T01:58:35.696Z', '64136f876946c97ea39ec2fdb5b7901f3b79052ce785cd487c20475f06064c55', '{"id":"beavermoney/beavermoney/relay-pagination","name":"relay-pagination","description":{"en":"relay-pagination enables efficient loading and displaying of large datasets using cursor-based pagination. It benefits developers working with GraphQL and infinite scroll/load more patterns.","zh":"Relay 分页是基于 GraphQL Cursor Connections Specification 的一种高效的数据加载方式，提供自动缓存更新和连接管理","ja":"Relay Pagination は、GraphQL Cursor Connections Specification を実装した効率的なデータ読み込み方法で、自動キャッシュ更新と接続管理を提供します","ko":"릴레이 페이징은 GraphQL Cursor Connections Specification을 기반으로 하는 효율적인 데이터 로딩 방식으로, 자동 캐시 업데이트와 커넥션 관리를 제공합니다","es":"Relay Pagination es una técnica para cargar y mostrar grandes conjuntos de datos de manera eficiente. Implementa la especificación de conexiones de cursores de GraphQL para la paginación.","fr":"Relay Pagination est une technique pour charger et afficher de grands ensembles de données de manière efficace. Il met en œuvre la spécification de connexion de curseur GraphQL pour la pagination.","de":"Relay Pagination ist eine Technik zum effizienten Laden und Anzeigen großer Datenmengen. Es implementiert die GraphQL-Cursor-Connections-Spezifikation für die Paginierung.","pt":"O Relay-Pagination é uma ferramenta para carregar grandes conjuntos de dados de forma eficiente, utilizando a especificação de conexões de cursor do GraphQL","ru":"Relay-Pagination - это инструмент для эффективной загрузки больших наборов данных, использующий спецификацию курсорных подключений GraphQL","ar":"relay-pagination هو أداة لتحميل مجموعات البيانات الكبيرة بفعالية، باستخدام مواصفات الاتصال القائم على المؤشر لGraphQL"},"seo":{"title":{"en":"relay-pagination: Mastering Cursor-Based Pagination | AI ...","zh":"Relay 分页设置指南 - 优化大数据加载","ja":"Relay Pagination のベストプラクティス - AIエージェントを使用した効率的なデータ読み込み","ko":"릴레이 페이징 설정 가이드 - 대용량 데이터 로딩 최적화","es":"Guía de configuración de Relay Pagination para desarrolla...","fr":"Configurer Relay Pagination pour les développeurs : meill...","de":"Relay Pagination Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do Relay-Pagination para Desenvolved...","ru":"Руководство по настройке Relay-Pagination для ИИ Агентов","ar":"دليل الإعداد لrelay-pagination لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient data loading with relay-pagination! Learn how to implement cursor-based pagination for infinite scroll and load more patterns","zh":"了解 Relay 分页的工作原理，并使用 GraphQL Cursor Connections Specification 实现高效的数据加载","ja":"Relay Pagination を使用して大容量のデータを効率的に読み込み、AIエージェントの能力を最大限に活用する","ko":"릴레이 페이징을 사용하여 대용량 데이터를 효율적으로 로딩하고, GraphQL Cursor Connections Specification을 사용하여 캐시 업데이트를 자동화하십시오","es":"Aprende a implementar Relay Pagination para cargar y mostrar grandes conjuntos de datos de manera eficiente con infinite scroll y patrones de carga adicional","fr":"Découvrez comment mettre en œuvre Relay Pagination pour charger et afficher de grands ensembles de données de manière efficace avec un défilement infini et d...","de":"Erfahren Sie, wie Sie Relay Pagination implementieren, um große Datenmengen effizient zu laden und anzuzeigen, mit Endlosscrolling und Lade-Mehr-Mustern","pt":"Aprenda a implementar a paginação baseada em cursor do Relay para carregar grandes conjuntos de dados de forma eficiente","ru":"Узнайте, как реализовать курсорную пагинацию Relay для эффективной загрузки больших наборов данных","ar":"تعلم كيفية تنفيذ نظام التصفح القائم على المؤشر لrelay لتحميل مجموعات البيانات الكبيرة بفعالية"},"definition":{"en":"relay-pagination is a skill that implements the GraphQL Cursor Connections Specification for efficient pagination","zh":"Relay 分页是一种高效的数据加载方式，使用 GraphQL Cursor Connections Specification 实现自动缓存更新和连接管理","ja":"Relay Pagination は、GraphQL Cursor Connections Specification を使用した自動キャッシュ更新と接続管理を提供する効率的なデータ読み込み方法です","ko":"릴레이 페이징은 GraphQL Cursor Connections Specification을 사용하여 자동 캐시 업데이트와 커넥션 관리를 제공하는 효율적인 데이터 로딩 방식입니다","es":"Relay Pagination es una técnica de paginación basada en cursores que permite cargar y mostrar grandes conjuntos de datos de manera eficiente","fr":"Relay Pagination est une technique de pagination basée sur les curseurs qui permet de charger et d''afficher de grands ensembles de données de manière efficace","de":"Relay Pagination ist eine cursorbasierte Paginierungstechnik, die das effiziente Laden und Anzeigen großer Datenmengen ermöglicht","pt":"O que é Relay-Pagination? É uma ferramenta de paginação baseada em cursor para carregar grandes conjuntos de dados","ru":"Что такое Relay-Pagination? Это инструмент курсорной пагинации для загрузки больших наборов данных","ar":"ما هو relay-pagination؟ هو أداة تصفح قائم على المؤشر لتحميل مجموعات البيانات الكبيرة"},"features":{"en":["Implements GraphQL Cursor Connections Specification","Provides hooks like usePaginationFragment for declarative pagination","Supports automatic cache updates and connection management","Enables infinite scroll and load more patterns","Uses GraphQL query structure for pagination","Includes installation and setup guide"],"zh":["基于 GraphQL Cursor Connections Specification 的分页实现","自动缓存更新和连接管理","使用 usePaginationFragment 实现声明式分页","支持无限滚动和加载更多模式","高效加载和显示大数据集"],"ja":["GraphQL Cursor Connections Specification を使用した分页実装","自動キャッシュ更新と接続管理","usePaginationFragment を使用した宣言的分页","無限スクロールと読み込み更多モードのサポート","大容量データの効率的な読み込みと表示"],"ko":["GraphQL Cursor Connections Specification을 기반으로 하는 페이징 实现","자동 캐시 업데이트와 커넥션 관리","usePaginationFragment을 사용한 선언적 페이징","무한 스크롤과 로딩更多 모드 지원","대용량 데이터의 효율적인 로딩과 표시"],"es":["Implementación de la especificación de conexiones de cursores de GraphQL","Carga eficiente de grandes conjuntos de datos con infinite scroll","Patrones de carga adicional para una mejor experiencia del usuario","Uso de hooks como usePaginationFragment para la paginación declarativa","Actualizaciones automáticas de caché y administración de conexiones"],"fr":["Mise en œuvre de la spécification de connexion de curseur GraphQL","Chargement efficace de grands ensembles de données avec un défilement infini","Modèles de chargement supplémentaire pour une meilleure expérience utilisateur","Utilisation de hooks tels que usePaginationFragment pour la pagination déclarative","Mises à jour automatiques du cache et gestion des connexions"],"de":["Implementierung der GraphQL-Cursor-Connections-Spezifikation","Effizientes Laden großer Datenmengen mit Endlosscrolling","Lade-Mehr-Muster für eine bessere Benutzererfahrung","Verwendung von Hooks wie usePaginationFragment für die deklarative Paginierung","Automatische Cache-Aktualisierungen und Verbindungsbetrieb"],"pt":["Implementação da especificação de conexões de cursor do GraphQL","Uso de hooks como usePaginationFragment para paginação declarativa","Cache automático e gerenciamento de conexões","Suporte a padrões de rolagem infinita e carregamento de mais","Integração com o Relay para carregar grandes conjuntos de dados"],"ru":["Реализация спецификации курсорных подключений GraphQL","Использование хуков, таких как usePaginationFragment, для декларативной пагинации","Автоматическое кэширование и управление подключениями","Поддержка шаблонов бесконечной прокрутки и загрузки еще","Интеграция с Relay для загрузки больших наборов данных"],"ar":["تنفيذ مواصفات الاتصال القائم على المؤشر لGraphQL","استخدام Hooks مثل usePaginationFragment للتصفح اللفظي","التخزين المؤقت التلقائي وإدارة الاتصالات","دعم أنماط التمرير اللانهائي و تحميل المزيد","التكامل مع relay لتحميل مجموعات البيانات الكبيرة"]},"keywords":{"en":["how to use relay-pagination","relay-pagination setup guide","graphql cursor connections specification","relay-pagination vs other pagination methods","install relay-pagination","relay-pagination infinite scroll","what is relay-pagination","relay-pagination alternative","relay-pagination tutorial"],"zh":["Relay 分页","GraphQL Cursor Connections Specification","自动缓存更新","连接管理","usePaginationFragment","无限滚动","加载更多","大数据加载","AI工具"," Relay 分页设置"],"ja":["Relay Pagination","GraphQL Cursor Connections Specification","自動キャッシュ更新","接続管理","usePaginationFragment","無限スクロール","読み込み更多","大容量データ読み込み","AIエージェント","Relay Pagination のベストプラクティス"],"ko":["릴레이 페이징","GraphQL Cursor Connections Specification","자동 캐시 업데이트","커넥션 관리","usePaginationFragment","무한 스크롤","로딩更多","대용량 데이터 로딩","AI 툴","릴레이 페이징 설정 가이드"],"es":["relay pagination","paginación basada en cursores","carga eficiente de datos","infinite scroll","patrones de carga adicional","graphql","usepaginationfragment","desarrollo de aplicaciones","tecnologías de desarrollo web"],"fr":["relay pagination","pagination basée sur les curseurs","chargement efficace de données","défilement infini","modèles de chargement supplémentaire","graphql","usepaginationfragment","développement d''applications","technologies de développement web"],"de":["relay pagination","cursorbasierte paginierung","effizientes datenladen","endlosscrolling","lade-mehr-muster","graphql","usepaginationfragment","anwendungsentwicklung","webentwicklungstechnologien"],"pt":["relay pagination","paginação baseada em cursor","graphql cursor connections","usepaginationfragment","carregar grandes conjuntos de dados","rolagem infinita","carregamento de mais","desenvolvedores de software","ferramentas de ai"],"ru":["relay пагинация","курсорная пагинация","graphql курсорные подключения","usepaginationfragment","загрузка больших наборов данных","бесконечная прокрутка","загрузка еще","разработчики программного обеспечения","инструменты ИИ"],"ar":["relay-تصفح","نظام التصفح القائم على المؤشر","اتصال المؤشر لGraphQL","usepaginationfragment","تحميل مجموعات البيانات الكبيرة","التمرير اللانهائي","تحميل المزيد","مطورو البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"beavermoney","repo":"beavermoney","repoPath":"beavermoney/beavermoney","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.507Z","topics":[],"category":"community","skillMd":{"name":"relay-pagination","description":"Use when relay pagination with cursor-based pagination, infinite scroll, load more patterns, and connection protocols.","bodyPreview":"# Relay Pagination\n\nMaster Relay''s cursor-based pagination for efficiently loading and displaying\nlarge datasets with infinite scroll and load more patterns.\n\n## Overview\n\nRelay implements the GraphQL Cursor Connections Specification for efficient\npagination. It provides hooks like usePaginationFragment for declarative\npagination with automatic cache updates and connection management.\n\n## Installation and Setup\n\n### Pagination Query Structure\n\n```graphql\n# schema.graphql\ntype Query {\n  posts(","body":"# Relay Pagination\n\nMaster Relay''s cursor-based pagination for efficiently loading and displaying\nlarge datasets with infinite scroll and load more patterns.\n\n## Overview\n\nRelay implements the GraphQL Cursor Connections Specification for efficient\npagination. It provides hooks like usePaginationFragment for declarative\npagination with automatic cache updates and connection management.\n\n## Installation and Setup\n\n### Pagination Query Structure\n\n```graphql\n# schema.graphql\ntype Query {\n  posts(\n    first: Int\n    after: String\n    last: Int\n    before: String\n  ): PostConnection!\n}\n\ntype PostConnection {\n  edges: [PostEdge!]!\n  pageInfo: PageInfo!\n  totalCount: Int\n}\n\ntype PostEdge {\n  cursor: String!\n  node: Post!\n}\n\ntype PageInfo {\n  hasNextPage: Boolean!\n  hasPreviousPage: Boolean!\n  startCursor: String\n  endCursor: String\n}\n\ntype Post {\n  id: ID!\n  title: String!\n  body: String!\n}\n```\n\n## Core Patterns\n\n### 1. Basic Pagination\n\n```javascript\n// PostsList.jsx\nimport { graphql, usePaginationFragment } from ''react-relay'';\n\nconst PostsListFragment = graphql`\n  fragment PostsList_query on Query\n  @refetchable(queryName: \"PostsListPaginationQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 10 }\n    after: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after)\n    @connection(key: \"PostsList_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n    }\n  }\n`;\n\nfunction PostsList({ query }) {\n  const {\n    data,\n    loadNext,\n    loadPrevious,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious,\n    refetch\n  } = usePaginationFragment(PostsListFragment, query);\n\n  return (\n    <div>\n      <button\n        onClick={() => refetch({ first: 10 })}\n        disabled={isLoadingNext}\n      >\n        Refresh\n      </button>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button\n          onClick={() => loadNext(10)}\n          disabled={isLoadingNext}\n        >\n          {isLoadingNext ? ''Loading...'' : ''Load More''}\n        </button>\n      )}\n    </div>\n  );\n}\n\nexport default PostsList;\n```\n\n### 2. Infinite Scroll\n\n```javascript\n// InfiniteScrollPosts.jsx\nimport { useEffect, useRef } from ''react'';\nimport { graphql, usePaginationFragment } from ''react-relay'';\n\nconst InfiniteScrollFragment = graphql`\n  fragment InfiniteScrollPosts_query on Query\n  @refetchable(queryName: \"InfiniteScrollPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 20 }\n    after: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after)\n    @connection(key: \"InfiniteScroll_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction InfiniteScrollPosts({ query }) {\n  const { data, loadNext, hasNext, isLoadingNext } = usePaginationFragment(\n    InfiniteScrollFragment,\n    query\n  );\n\n  const observerRef = useRef();\n  const loadMoreRef = useRef();\n\n  useEffect(() => {\n    const observer = new IntersectionObserver(\n      (entries) => {\n        if (entries[0].isIntersecting && hasNext && !isLoadingNext) {\n          loadNext(20);\n        }\n      },\n      { threshold: 0.5 }\n    );\n\n    const currentRef = loadMoreRef.current;\n    if (currentRef) {\n      observer.observe(currentRef);\n    }\n\n    observerRef.current = observer;\n\n    return () => {\n      if (currentRef) {\n        observer.unobserve(currentRef);\n      }\n    };\n  }, [hasNext, isLoadingNext, loadNext]);\n\n  return (\n    <div>\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <div ref={loadMoreRef} className=\"load-more-trigger\">\n          {isLoadingNext && <Spinner />}\n        </div>\n      )}\n\n      {!hasNext && <div>No more posts</div>}\n    </div>\n  );\n}\n```\n\n### 3. Bidirectional Pagination\n\n```javascript\n// BidirectionalPosts.jsx\nconst BidirectionalFragment = graphql`\n  fragment BidirectionalPosts_query on Query\n  @refetchable(queryName: \"BidirectionalPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\" }\n    after: { type: \"String\" }\n    last: { type: \"Int\" }\n    before: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after, last: $last, before: $before)\n    @connection(key: \"Bidirectional_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n      pageInfo {\n        hasNextPage\n        hasPreviousPage\n        startCursor\n        endCursor\n      }\n    }\n  }\n`;\n\nfunction BidirectionalPosts({ query }) {\n  const {\n    data,\n    loadNext,\n    loadPrevious,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious\n  } = usePaginationFragment(BidirectionalFragment, query);\n\n  return (\n    <div>\n      {hasPrevious && (\n        <button\n          onClick={() => loadPrevious(10)}\n          disabled={isLoadingPrevious}\n        >\n          {isLoadingPrevious ? ''Loading...'' : ''Load Previous''}\n        </button>\n      )}\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button\n          onClick={() => loadNext(10)}\n          disabled={isLoadingNext}\n        >\n          {isLoadingNext ? ''Loading...'' : ''Load Next''}\n        </button>\n      )}\n    </div>\n  );\n}\n```\n\n### 4. Filtered Pagination\n\n```javascript\n// FilteredPosts.jsx\nconst FilteredPostsFragment = graphql`\n  fragment FilteredPosts_query on Query\n  @refetchable(queryName: \"FilteredPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 10 }\n    after: { type: \"String\" }\n    status: { type: \"PostStatus\" }\n    authorId: { type: \"ID\" }\n  ) {\n    posts(\n      first: $first\n      after: $after\n      status: $status\n      authorId: $authorId\n    )\n    @connection(key: \"FilteredPosts_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction FilteredPosts({ query }) {\n  const [status, setStatus] = useState(''PUBLISHED'');\n  const [authorId, setAuthorId] = useState(null);\n\n  const { data, loadNext, hasNext, refetch } = usePaginationFragment(\n    FilteredPostsFragment,\n    query\n  );\n\n  const handleFilterChange = (newStatus, newAuthorId) => {\n    setStatus(newStatus);\n    setAuthorId(newAuthorId);\n\n    refetch({\n      first: 10,\n      after: null,\n      status: newStatus,\n      authorId: newAuthorId\n    });\n  };\n\n  return (\n    <div>\n      <FilterControls\n        status={status}\n        authorId={authorId}\n        onChange={handleFilterChange}\n      />\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button onClick={() => loadNext(10)}>Load More</button>\n      )}\n    </div>\n  );\n}\n```\n\n### 5. Pagination with Search\n\n```javascript\n// SearchablePosts.jsx\nconst SearchablePostsFragment = graphql`\n  fragment SearchablePosts_query on Query\n  @refetchable(queryName: \"SearchablePostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 10 }\n    after: { type: \"String\" }\n    searchTerm: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after, searchTerm: $searchTerm)\n    @connection(key: \"SearchablePosts_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n      totalCount\n    }\n  }\n`;\n\nfunction SearchablePosts({ query }) {\n  const [searchTerm, setSearchTerm] = useState('''');\n  const { data, loadNext, hasNext, refetch, isLoadingNext } =\n    usePaginationFragment(SearchablePostsFragment, query);\n\n  const handleSearch = (term) => {\n    setSearchTerm(term);\n    refetch({\n      first: 10,\n      after: null,\n      searchTerm: term\n    });\n  };\n\n  return (\n    <div>\n      <SearchInput\n        value={searchTerm}\n        onChange={handleSearch}\n        placeholder=\"Search posts...\"\n      />\n\n      <div>\n        Showing {data.posts.edges.length} of {data.posts.totalCount} posts\n      </div>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button onClick={() => loadNext(10)} disabled={isLoadingNext}>\n          {isLoadingNext ? ''Loading...'' : ''Load More''}\n        </button>\n      )}\n    </div>\n  );\n}\n```\n\n### 6. Optimistic Pagination Updates\n\n```javascript\n// OptimisticPaginationPosts.jsx\nconst CreatePostMutation = graphql`\n  mutation OptimisticPaginationCreatePostMutation(\n    $input: CreatePostInput!\n    $connections: [ID!]!\n  ) {\n    createPost(input: $input) {\n      postEdge @prependEdge(connections: $connections) {\n        cursor\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction OptimisticPaginationPosts({ query }) {\n  const { data } = usePaginationFragment(PostsFragment, query);\n  const [commit] = useMutation(CreatePostMutation);\n\n  const connectionID = ConnectionHandler.getConnectionID(\n    ''client:root'',\n    ''Posts_posts''\n  );\n\n  const handleCreate = (title, body) => {\n    commit({\n      variables: {\n        input: { title, body },\n        connections: [connectionID]\n      },\n\n      optimisticResponse: {\n        createPost: {\n          postEdge: {\n            cursor: ''temp-cursor'',\n            node: {\n              id: `temp-${Date.now()}`,\n              title,\n              body,\n              createdAt: new Date().toISOString(),\n              author: {\n                id: currentUser.id,\n                name: currentUser.name\n              }\n            }\n          }\n        }\n      }\n    });\n  };\n\n  return (\n    <div>\n      <CreatePostForm onSubmit={handleCreate} />\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n    </div>\n  );\n}\n```\n\n### 7. Paginated Tabs\n\n```javascript\n// TabbedPosts.jsx\nconst TabbedPostsFragment = graphql`\n  fragment TabbedPosts_user on User\n  @refetchable(queryName: \"TabbedPostsQuery\")\n  @argumentDefinitions(\n    draftsFirst: { type: \"Int\", defaultValue: 10 }\n    draftsAfter: { type: \"String\" }\n    publishedFirst: { type: \"Int\", defaultValue: 10 }\n    publishedAfter: { type: \"String\" }\n  ) {\n    draftPosts: posts(\n      first: $draftsFirst\n      after: $draftsAfter\n      status: DRAFT\n    )\n    @connection(key: \"TabbedPosts_draftPosts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n\n    publishedPosts: posts(\n      first: $publishedFirst\n      after: $publishedAfter\n      status: PUBLISHED\n    )\n    @connection(key: \"TabbedPosts_publishedPosts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction TabbedPosts({ user }) {\n  const [activeTab, setActiveTab] = useState(''published'');\n  const { data } = usePaginationFragment(TabbedPostsFragment, user);\n\n  const posts =\n    activeTab === ''draft'' ? data.draftPosts : data.publishedPosts;\n\n  return (\n    <div>\n      <Tabs value={activeTab} onChange={setActiveTab}>\n        <Tab value=\"published\">Published</Tab>\n        <Tab value=\"draft\">Drafts</Tab>\n      </Tabs>\n\n      {posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n    </div>\n  );\n}\n```\n\n### 8. Virtual Scrolling with Pagination\n\n```javascript\n// VirtualizedPosts.jsx\nimport { useVirtualizer } from ''@tanstack/react-virtual'';\nimport { graphql, usePaginationFragment } from ''react-relay'';\n\nconst VirtualizedPostsFragment = graphql`\n  fragment VirtualizedPosts_query on Query\n  @refetchable(queryName: \"VirtualizedPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 50 }\n    after: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after)\n    @connection(key: \"VirtualizedPosts_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction VirtualizedPosts({ query }) {\n  const { data, loadNext, hasNext, isLoadingNext } = usePaginationFragment(\n    VirtualizedPostsFragment,\n    query\n  );\n\n  const parentRef = useRef();\n  const posts = data.posts.edges.map(e => e.node);\n\n  const virtualizer = useVirtualizer({\n    count: posts.length,\n    getScrollElement: () => parentRef.current,\n    estimateSize: () => 200,\n    overscan: 5\n  });\n\n  useEffect(() => {\n    const [lastItem] = [...virtualizer.getVirtualItems()].reverse();\n\n    if (!lastItem) return;\n\n    if (\n      lastItem.index >= posts.length - 1 &&\n      hasNext &&\n      !isLoadingNext\n    ) {\n      loadNext(50);\n    }\n  }, [\n    hasNext,\n    loadNext,\n    isLoadingNext,\n    posts.length,\n    virtualizer.getVirtualItems()\n  ]);\n\n  return (\n    <div ref={parentRef} style={{ height: ''600px'', overflow: ''auto'' }}>\n      <div\n        style={{\n          height: `${virtualizer.getTotalSize()}px`,\n          position: ''relative''\n        }}\n      >\n        {virtualizer.getVirtualItems().map(virtualItem => (\n          <div\n            key={virtualItem.key}\n            style={{\n              position: ''absolute'',\n              top: 0,\n              left: 0,\n              width: ''100%'',\n              transform: `translateY(${virtualItem.start}px)`\n            }}\n          >\n            <PostCard post={posts[virtualItem.index]} />\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n```\n\n### 9. Pagination State Management\n\n```javascript\n// PaginationStateManager.jsx\nfunction PaginationStateManager({ query }) {\n  const {\n    data,\n    loadNext,\n    hasNext,\n    isLoadingNext,\n    refetch\n  } = usePaginationFragment(PostsFragment, query);\n\n  const [paginationState, setPaginationState] = useState({\n    currentPage: 1,\n    itemsPerPage: 10,\n    totalLoaded: 0\n  });\n\n  const handleLoadMore = () => {\n    const itemsToLoad = paginationState.itemsPerPage;\n    loadNext(itemsToLoad);\n\n    setPaginationState(prev => ({\n      ...prev,\n      currentPage: prev.currentPage + 1,\n      totalLoaded: prev.totalLoaded + itemsToLoad\n    }));\n  };\n\n  const handleChangePageSize = (newSize) => {\n    setPaginationState(prev => ({\n      ...prev,\n      itemsPerPage: newSize\n    }));\n\n    refetch({\n      first: newSize,\n      after: null\n    });\n  };\n\n  return (\n    <div>\n      <div>\n        Page {paginationState.currentPage} -\n        Loaded {paginationState.totalLoaded} items\n      </div>\n\n      <select\n        value={paginationState.itemsPerPage}\n        onChange={(e) => handleChangePageSize(Number(e.target.value))}\n      >\n        <option value={10}>10 per page</option>\n        <option value={25}>25 per page</option>\n        <option value={50}>50 per page</option>\n      </select>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button onClick={handleLoadMore} disabled={isLoadingNext}>\n          Load More\n        </button>\n      )}\n    </div>\n  );\n}\n```\n\n### 10. Custom Pagination Hook\n\n```javascript\n// hooks/usePagination.js\nimport { useState, useCallback } from ''react'';\nimport { usePaginationFragment } from ''react-relay'';\n\nexport function usePagination(fragment, fragmentRef, options = {}) {\n  const {\n    onLoadMore,\n    onLoadPrevious,\n    onRefetch,\n    pageSize = 10\n  } = options;\n\n  const {\n    data,\n    loadNext,\n    loadPrevious,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious,\n    refetch\n  } = usePaginationFragment(fragment, fragmentRef);\n\n  const [page, setPage] = useState(1);\n\n  const handleLoadNext = useCallback(() => {\n    loadNext(pageSize);\n    setPage(p => p + 1);\n    onLoadMore?.();\n  }, [loadNext, pageSize, onLoadMore]);\n\n  const handleLoadPrevious = useCallback(() => {\n    loadPrevious(pageSize);\n    setPage(p => Math.max(1, p - 1));\n    onLoadPrevious?.();\n  }, [loadPrevious, pageSize, onLoadPrevious]);\n\n  const handleRefetch = useCallback((variables) => {\n    refetch(variables);\n    setPage(1);\n    onRefetch?.();\n  }, [refetch, onRefetch]);\n\n  return {\n    data,\n    page,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious,\n    loadNext: handleLoadNext,\n    loadPrevious: handleLoadPrevious,\n    refetch: handleRefetch\n  };\n}\n\n// Usage\nfunction PostsList({ query }) {\n  const {\n    data,\n    page,\n    hasNext,\n    loadNext,\n    refetch\n  } = usePagination(PostsFragment, query, {\n    pageSize: 20,\n    onLoadMore: () => console.log(''Loaded more''),\n    onRefetch: () => console.log(''Refetched'')\n  });\n\n  return (\n    <div>\n      <div>Page {page}</div>\n      <button onClick={() => refetch({ first: 20 })}>Refresh</button>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && <button onClick={loadNext}>Load More</button>}\n    </div>\n  );\n}\n```\n\n## Best Practices\n\n1. **Use @connection directive** - Ensure proper cache updates\n2. **Implement loading states** - Show feedback during pagination\n3. **Handle edge cases** - Empty states, no more data\n4. **Optimize page size** - Balance UX and performance\n5. **Use infinite scroll wisely** - Consider virtual scrolling for large lists\n6. **Implement search/filter** - Allow users to narrow results\n7. **Cache pagination state** - Preserve scroll position\n8. **Handle errors gracefully** - Retry failed pagination requests\n9. **Test pagination thoroughly** - Edge cases, network failures\n10. **Monitor performance** - Track pagination metrics\n\n## Common Pitfalls\n\n1. **Missing @connection directive** - Cache updates fail\n2. **Incorrect cursor management** - Duplicate or missing items\n3. **No loading states** - Poor user experience\n4. **Over-fetching** - Requesting too many items per page\n5. **Memory leaks** - Not cleaning up observers\n6. **Missing error handling** - Failed requests break pagination\n7. **Inconsistent page sizes** - Confusing user experience\n8. **Not handling empty states** - Poor UX for no results\n9. **Race conditions** - Multiple concurrent pagination requests\n10. **Missing accessibility** - Keyboard navigation, screen readers\n\n## When to Use\n\n- Displaying large lists of data\n- Building infinite scroll interfaces\n- Creating feed-based applications\n- Implementing search results\n- Building e-commerce product listings\n- Creating social media timelines\n- Developing comment threads\n- Building admin dashboards\n- Creating data tables\n- Implementing file browsers\n\n## Resources\n\n- [Relay Pagination](https://relay.dev/docs/guided-tour/list-data/pagination/)\n- [Connection Specification](https://relay.dev/graphql/connections.htm)\n- [usePaginationFragment](https://relay.dev/docs/api-reference/use-pagination-fragment/)\n- [Cursor Connections](https://graphql.org/learn/pagination/)\n- [Relay Examples](https://github.com/relayjs/relay-examples)\n"},"lastSynced":"2026-03-07T01:58:35.696Z","agentAnalysis":{"suitability":{"en":"Perfect for GraphQL Agents needing efficient data pagination and caching capabilities.","zh":"非常适合需要高效数据分页和缓存功能的 GraphQL 代理。","ja":"GraphQL エージェントが効率的なデータのページネーションとキャッシング機能を必要とする場合に最適です。","ko":"효율적인 데이터 페이지네이션 및 캐싱 기능이 필요한 GraphQL 에이전트에 적합합니다.","es":"Perfecto para agentes GraphQL que necesitan capacidades de paginación de datos eficientes y caché.","fr":"Parfait pour les agents GraphQL ayant besoin de capacités de pagination de données efficaces et de mise en cache.","de":"Perfekt für GraphQL-Agents, die effiziente Datenpaginierung und Cachefunktionen benötigen.","pt":"Perfeito para agentes GraphQL que necessitam de paginação de dados eficiente e capacidades de cache.","ru":"Идеально подходит для агентов GraphQL, которым необходима эффективная постраничная навигация и возможности кэширования.","ar":"مثالي لعميل GraphQL الذي يحتاج إلى تنسيق بيانات فعال وتخزين مؤقت"},"recommendation":{"en":"Empowers agents to manage large datasets with cursor-based pagination, automatic cache updates, and connection management using the GraphQL Cursor Connections Specification and hooks like usePaginationFragment.","zh":"通过 GraphQL Cursor Connections Specification 和诸如 usePaginationFragment 的钩子，赋予代理管理大型数据集的能力，具有基于游标的分页、自动缓存更新和连接管理。","ja":"GraphQL Cursor Connections Specification と usePaginationFragment などのフックを使用して、エージェントがカーソルベースのページネーション、自動キャッシュ更新、接続管理を使用して大規模なデータセットを管理できるようにします。","ko":"GraphQL Cursor Connections Specification 및 usePaginationFragment와 같은 훅을 사용하여 에이전트가 커서 기반 페이지네이션, 자동 캐시 업데이트 및 커넥션 관리를 사용하여 대규모 데이터 세트를 관리할 수 있도록 합니다.","es":"Habilita a los agentes a gestionar grandes conjuntos de datos con paginación basada en cursor, actualizaciones de caché automáticas y gestión de conexiones utilizando la especificación de conexiones de cursor GraphQL y ganchos como usePaginationFragment.","fr":"Permet aux agents de gérer de grands ensembles de données avec une pagination basée sur le curseur, des mises à jour de cache automatiques et une gestion de connexions en utilisant la spécification de connexions de curseur GraphQL et des crochets comme usePaginationFragment.","de":"Ermächtigt die Agenten, große Datensätze mit cursorbasierter Paginierung, automatischen Cache-Aktualisierungen und Verbindungsnutzung über die GraphQL-Cursor-Connections-Spezifikation und Haken wie usePaginationFragment zu verwalten.","pt":"Habilita os agentes a gerenciar grandes conjuntos de dados com paginação baseada em cursor, atualizações de cache automáticas e gerenciamento de conexões usando a Especificação de Conexões de Cursor GraphQL e ganchos como usePaginationFragment.","ru":"Наделяет агентов возможностью управлять большими наборами данных с помощью курсорной постраничной навигации, автоматического обновления кэша и управления соединениями с использованием Спецификации соединений курсора GraphQL и крючков, таких как usePaginationFragment.","ar":"يمنح الوكلاء إمكانية إدارة مجموعات بيانات كبيرة باستخدام نظام التمرير القائم على المؤشر وتحديثات الذاكرة المؤقتة الآلية وإدارة الاتصال باستخدام مواصفات اتصال المؤشر GraphQL وأدوات مثل usePaginationFragment"},"useCases":{"en":["Implementing infinite scroll and load more patterns","Optimizing data loading for large datasets","Managing cache updates for efficient data retrieval"],"zh":["实施无限滚动和加载更多模式","优化大型数据集的数据加载","管理缓存更新以实现高效的数据检索"],"ja":["無限スクロールと読み込みの追加パターンの実装","大規模なデータセットのデータ読み込みの最適化","効率的なデータの取得のためにキャッシュの更新を管理する"],"ko":["무한 스크롤 및 더 많은 항목 로드 패턴 구현","대규모 데이터 세트에 대한 데이터 로드 최적화","효율적인 데이터 조회를 위한 캐시 업데이트 관리"],"es":["Implementar patrones de desplazamiento infinito y carga adicional","Optimizar la carga de datos para grandes conjuntos de datos","Gestionar actualizaciones de caché para una recuperación de datos eficiente"],"fr":["Mettre en œuvre des modèles de défilement infini et de chargement supplémentaire","Optimiser le chargement de données pour les grands ensembles de données","Gérer les mises à jour de cache pour une récupération de données efficace"],"de":["Implementierung von Mustern für unendliches Scrollen und Laden von mehr","Optimierung der Datenladung für große Datensätze","Verwaltung von Cache-Aktualisierungen für eine effiziente Datenabruf"],"pt":["Implementar padrões de rolagem infinita e carregar mais","Otimizar o carregamento de dados para grandes conjuntos de dados","Gerenciar atualizações de cache para recuperação de dados eficiente"],"ru":["Реализация паттернов бесконечной прокрутки и загрузки еще","Оптимизация загрузки данных для больших наборов данных","Управление обновлениями кэша для эффективного извлечения данных"],"ar":["تنفيذ أنماط التمرير اللانهائي وتحميل المزيد","تحسين تحميل البيانات لمجموعات البيانات الكبيرة","إدارة تحديثات الذاكرة المؤقتة لاسترجاع البيانات الفعال"]},"limitations":{"en":["Requires GraphQL schema setup","Relay environment setup needed"],"zh":["需要 GraphQL 模式设置","需要 Relay 环境设置"],"ja":["GraphQL スキーマの設定が必要","Relay 環境の設定が必要"],"ko":["GraphQL 스키마 설정이 필요합니다","Relay 환경 설정이 필요합니다"],"es":["Requiere configuración de esquema GraphQL","Entorno de Relay necesario"],"fr":["Nécessite une configuration de schéma GraphQL","Environnement Relay nécessaire"],"de":["Benötigt GraphQL-Schema-Setup","Relay-Umgebung erforderlich"],"pt":["Requer configuração do schema GraphQL","Configuração do ambiente Relay necessária"],"ru":["Требуется настройка схемы GraphQL","Необходима настройка среды Relay"],"ar":["يتطلب إعداد مخطط GraphQL","مطلوب إعداد بيئة Relay"]},"version":4},"contentHash":"64136f876946c97ea39ec2fdb5b7901f3b79052ce785cd487c20475f06064c55","qualityScore":57}');
