INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('beavermoney/beavermoney/relay-pagination', 'relay-pagination', 'beavermoney', 'beavermoney', 'community', 'relay-pagination beavermoney beavermoney community relay-pagination enables efficient loading and displaying of large datasets using cursor-based pagination. It benefits developers working with GraphQL and infinite scroll/load more patterns. Relay 分页是基于 GraphQL Cursor Connections Specification 的一种高效的数据加载方式，提供自动缓存更新和连接管理 Relay Pagination は、GraphQL Cursor Connections Specification を実装した効率的なデータ読み込み方法で、自動キャッシュ更新と接続管理を提供します 릴레이 페이징은 GraphQL Cursor Connections Specification을 기반으로 하는 효율적인 데이터 로딩 방식으로, 자동 캐시 업데이트와 커넥션 관리를 제공합니다 Relay Pagination es una técnica para cargar y mostrar grandes conjuntos de datos de manera eficiente. Implementa la especificación de conexiones de cursores de GraphQL para la paginación. Relay Pagination est une technique pour charger et afficher de grands ensembles de données de manière efficace. Il met en œuvre la spécification de connexion de curseur GraphQL pour la pagination. Relay Pagination ist eine Technik zum effizienten Laden und Anzeigen großer Datenmengen. Es implementiert die GraphQL-Cursor-Connections-Spezifikation für die Paginierung. O Relay-Pagination é uma ferramenta para carregar grandes conjuntos de dados de forma eficiente, utilizando a especificação de conexões de cursor do GraphQL Relay-Pagination - это инструмент для эффективной загрузки больших наборов данных, использующий спецификацию курсорных подключений GraphQL relay-pagination هو أداة لتحميل مجموعات البيانات الكبيرة بفعالية، باستخدام مواصفات الاتصال القائم على المؤشر لGraphQL how to use relay-pagination relay-pagination setup guide graphql cursor connections specification relay-pagination vs other pagination methods install relay-pagination relay-pagination infinite scroll what is relay-pagination relay-pagination alternative relay-pagination tutorial Relay 分页 GraphQL Cursor Connections Specification 自动缓存更新 连接管理 usePaginationFragment 无限滚动 加载更多 大数据加载 AI工具 Relay 分页设置 Implements GraphQL Cursor Connections Specification Provides hooks like usePaginationFragment for declarative pagination Supports automatic cache updates and connection management Enables infinite scroll and load more patterns Uses GraphQL query structure for pagination Includes installation and setup guide relay-pagination is a skill that implements the GraphQL Cursor Connections Specification for efficient pagination');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RosyGameStudio/forge-gpu/forge-mesh-loading', 'community', 'RosyGameStudio', 'forge-gpu', 'RosyGameStudio/forge-gpu', 'forge-mesh-loading', 20, 0, 57, '2026-03-02T00:33:19Z', '2026-03-06T06:41:46.472Z', 'd51cc4235885ba5ca680317b887bd7d7858dc9cd904a2a277f3b6f6453c202db', '{"id":"RosyGameStudio/forge-gpu/forge-mesh-loading","name":"forge-mesh-loading","description":{"en":"forge-mesh-loading teaches real-time graphics programming with SDL''s GPU API, enabling developers to load and render 3D models from Wavefront OBJ files.","zh":"本技能教你如何使用SDL的GPU API加载和渲染3D模型，包括OBJ文件解析和纹理渲染","ja":"このスキルでは、SDLのGPU APIを使用して3Dモデルをロードしてレンダリングする方法を学び、OBJファイルの解析とテクスチャレンダリングを実践します","ko":"본 스킬은 SDL의 GPU API를 사용하여 3D 모델을 로드하고 렌더링하는 방법을 학습하고, OBJ 파일 파싱과 텍스처 렌더링을 실践합니다","es":"El skill forge-mesh-loading enseña a cargar y renderizar modelos 3D desde archivos OBJ con SDL''s GPU API","fr":"Le skill forge-mesh-loading apprend à charger et à afficher des modèles 3D à partir de fichiers OBJ avec l''API GPU de SDL","de":"Das Skill forge-mesh-loading lehrt, 3D-Modelle aus OBJ-Dateien mit der SDL-GPU-API zu laden und zu rendern","pt":"O forge-mesh-loading é uma habilidade que ensina a carregar e renderizar malhas 3D de arquivos OBJ, incluindo parsing de vértices, normais e coordenadas UV","ru":"Forge-mesh-loading - это навык, который учит загружать и отображать 3D-мши из файлов OBJ, включая парсинг вершин, нормалей и координат UV","ar":"forge-mesh-loading هو مهارة تعليمية لتحميل وتصيير الشبكات ثلاثية الأبعاد من ملفات OBJ، بما في ذلك تحليل الرأس والتوازي والتنسيق UV"},"seo":{"title":{"en":"forge-mesh-loading: Real-Time Graphics Setup Guide | AI A...","zh":"forge-mesh-loading Setup Guide - 3D 模型加载和渲染","ja":"forge-mesh-loading セットアップガイド - 3D モデルローディングとレンダリング","ko":"forge-mesh-loading 설정 가이드 - 3D 모델 로딩과 렌더링","es":"Guía de configuración de forge-mesh-loading para gráficos...","fr":"Guide de mise en place de forge-mesh-loading pour la prog...","de":"Einrichtungsleitfaden für forge-mesh-loading zur Echtzeit...","pt":"Guia de Configuração do forge-mesh-loading para Carregame...","ru":"Настройка ИИ Агентов: Руководство по загрузке мешей с пом...","ar":"دليل الإعداد لتحميل الشبكات ثلاثية الأبعاد باستخدام forge..."},"description":{"en":"Unlock 3D model rendering with forge-mesh-loading. Learn OBJ parsing, textured rendering, and camera setup. Get started with tutorials and code examples now!","zh":"学习使用SDL的GPU API进行实时图形编程和游戏开发，包括OBJ文件解析和纹理渲染","ja":"SDLのGPU APIを使用したリアルタイムグラフィックスプログラミングとゲーム開発を学び、OBJファイルの解析とテクスチャレンダリングを実践","ko":"SDL의 GPU API를 사용한 실시간 그래픽스 프로그래밍과 게임 개발을 학습하고, OBJ 파일 파싱과 텍스처 렌더링을 실践합니다","es":"Aprende a cargar y renderizar modelos 3D con SDL''s GPU API y descubre los mejores trucos para una experiencia de juego óptima","fr":"Découvrez comment charger et afficher des modèles 3D avec l''API GPU de SDL et améliorez votre expérience de jeu","de":"Erfahren Sie, wie Sie 3D-Modelle mit der SDL-GPU-API laden und rendern und verbessern Sie Ihre Spiel-Erfahrung","pt":"Aprenda a carregar e renderizar malhas 3D com o forge-mesh-loading, incluindo parsing de arquivos OBJ e renderização texturizada","ru":"Узнайте, как загружать и отображать 3D-мши с помощью forge-mesh-loading, включая парсинг файлов OBJ и текстурированное рендеринг","ar":"تعلم كيفية تحميل وتصيير الشبكات ثلاثية الأبعاد باستخدام forge-mesh-loading، بما في ذلك تحليل ملفات OBJ وتصيير متوافق"},"definition":{"en":"forge-mesh-loading is a skill that enables loading and rendering of 3D models from Wavefront OBJ files using SDL''s GPU API.","zh":"forge-mesh-loading是一种使用SDL的GPU API加载和渲染3D模型的技术","ja":"forge-mesh-loadingは、SDLのGPU APIを使用して3Dモデルをロードしてレンダリングする技術です","ko":"forge-mesh-loading은 SDL의 GPU API를 사용하여 3D 모델을 로드하고 렌더링하는 기술입니다","es":"Forge-mesh-loading es una habilidad que permite cargar y renderizar modelos 3D con texturas y cámaras","fr":"Forge-mesh-loading est une compétence qui permet de charger et d''afficher des modèles 3D avec des textures et des caméras","de":"Forge-mesh-loading ist eine Fähigkeit, die das Laden und Rendern von 3D-Modellen mit Texturen und Kameras ermöglicht","pt":"O que é forge-mesh-loading? É uma habilidade de programação gráfica em tempo real que carrega e renderiza malhas 3D de arquivos OBJ","ru":"Что такое forge-mesh-loading? Это навык реального времени графики, который загружает и отображает 3D-мши из файлов OBJ","ar":"ما هو forge-mesh-loading؟ هو مهارة برمجة رسومات الوقت الحقيقي التي تحمل وتصيير الشبكات ثلاثية الأبعاد من ملفات OBJ"},"features":{"en":["Loads and renders 3D models from Wavefront OBJ files","Supports textured rendering with SDL''s GPU API","Parses vertex positions, normals, and UV coordinates from files","Sets up non-indexed rendering (de-indexed vertices)","Builds on `textures-and-samplers`, `mipmaps`, `depth-and-3d`, and `camera-and-input` lessons"],"zh":["使用SDL的GPU API加载和渲染3D模型","OBJ文件解析和纹理渲染","设置非索引化渲染（去索引化顶点）","相机和输入处理","支持Wavefront OBJ文件"],"ja":["SDLのGPU APIを使用して3Dモデルをロードしてレンダリング","OBJファイルの解析とテクスチャレンダリング","非索引化レンダリング（デインデックス化頂点）の設定","カメラと入力処理","Wavefront OBJファイルのサポート"],"ko":["SDL의 GPU API를 사용하여 3D 모델을 로드하고 렌더링","OBJ 파일 파싱과 텍스처 렌더링","비인덱스화 렌더링（디인덱스화頂点）的 설정","카메라와 입력 처리","Wavefront OBJ 파일 지원"],"es":["Carga de modelos 3D desde archivos OBJ","Renderizado de mallas texturizadas con cámaras","Análisis de posiciones de vértices, normales y coordenadas UV desde archivos","Configuración de renderizado no indexado (vértices desindexados)","Compatibilidad con la API GPU de SDL"],"fr":["Chargement de modèles 3D à partir de fichiers OBJ","Affichage de maillages texturisées avec des caméras","Analyse de positions de sommets, de normales et de coordonnées UV à partir de fichiers","Configuration de l''affichage non indexé (sommets désindexés)","Compatibilité avec l''API GPU de SDL"],"de":["Laden von 3D-Modellen aus OBJ-Dateien","Rendern von texturierten Netzen mit Kameras","Analyse von Vertex-Positionen, Normalen und UV-Koordinaten aus Dateien","Einrichtung von nicht-indexiertem Rendering (desindexierte Vertices)","Kompatibilität mit der SDL-GPU-API"],"pt":["Carregamento de malhas 3D de arquivos OBJ","Parsing de vértices, normais e coordenadas UV","Renderização texturizada com câmera","Configuração de renderização não indexada","Combinação de malhas e texturas"],"ru":["Загрузка 3D-мшей из файлов OBJ","Парсинг вершин, нормалей и координат UV","Текстурированное рендеринг с камерой","Настройка нераспределённого рендеринга","Объединение мешей и текстур"],"ar":["تحميل الشبكات ثلاثية الأبعاد من ملفات OBJ","تحليل الرأس والتوازي والتنسيق UV","تصيير متوافق مع الكاميرا","إعداد تصيير غير مصنف","دمج الشبكات والتنسيقات"]},"keywords":{"en":["how to use forge-mesh-loading","forge-mesh-loading tutorial","SDL GPU API","OBJ file parsing","3D model rendering","forge-mesh-loading setup guide","forge-mesh-loading alternative","real-time graphics programming"],"zh":["forge-mesh-loading","SDL","GPU API","3D模型加载","OBJ文件解析","纹理渲染","实时图形编程","游戏开发","AIエージェント"],"ja":["forge-mesh-loading","SDL","GPU API","3Dモデルローディング","OBJファイル解析","テクスチャレンダリング","リアルタイムグラフィックスプログラミング","ゲーム開発","AIエージェント"],"ko":["forge-mesh-loading","SDL","GPU API","3D 모델 로딩","OBJ 파일 파싱","텍스처 렌더링","실시간 그래픽스 프로그래밍","게임 개발","AI 에이전트"],"es":["carga de modelos 3D","renderizado de mallas texturizadas","SDL GPU API","programación de gráficos en tiempo real","juegos con gráficos 3D","tutoriales de SDL","carga de archivos OBJ"],"fr":["chargement de modèles 3D","affichage de maillages texturisées","API GPU de SDL","programmation graphique en temps réel","jeux avec des graphiques 3D","tutoriels de SDL","chargement de fichiers OBJ"],"de":["Laden von 3D-Modellen","Rendern von texturierten Netzen","SDL-GPU-API","Echtzeit-Grafikprogrammierung","Spiele mit 3D-Grafiken","SDL-Tutorials","Laden von OBJ-Dateien"],"pt":["carregamento de malhas 3D","parsing de arquivos OBJ","renderização texturizada","câmera e input","SDL GPU API","programação gráfica em tempo real","desenvolvimento de jogos"],"ru":["загрузка 3D-мшей","парсинг файлов OBJ","текстурированное рендеринг","камера и ввод","SDL GPU API","реальное время графики","разработка игр"],"ar":["تحميل الشبكات ثلاثية الأبعاد","تحليل ملفات OBJ","تصيير متوافق","الكاميرا والمدخلات","SDL GPU API","برمجة رسومات الوقت الحقيقي","تطوير الألعاب"]}},"owner":"RosyGameStudio","repo":"forge-gpu","repoPath":"RosyGameStudio/forge-gpu","stars":20,"forks":0,"updatedAt":"2026-03-02T00:33:19Z","topics":["c","gamedev","graphics-programming","learn","sdl","sdl-gpu","sdl-gpu-tutorial","sdl3","tutorial"],"category":"community","skillMd":{"name":"forge-mesh-loading","description":"Load a 3D model from an OBJ file, create a textured mesh with mipmaps, and render with a fly-around camera. Use when someone needs to load geometry from a file, parse OBJ models, or render textured 3D meshes in SDL3 GPU.","bodyPreview":"# Mesh Loading — OBJ Parsing, Textured Rendering, Camera\n\nThis skill teaches how to load and render 3D models from Wavefront OBJ files.\nIt builds on `textures-and-samplers` (Lesson 04), `mipmaps` (Lesson 05),\n`depth-and-3d` (Lesson 06), and `camera-and-input` (Lesson 07).\n\n## When to use\n\n- Loading 3D models from OBJ files\n- Rendering textured meshes with a camera\n- Parsing vertex positions, normals, and UV coordinates from files\n- Setting up non-indexed rendering (de-indexed vertices)\n- Combini","body":"# Mesh Loading — OBJ Parsing, Textured Rendering, Camera\n\nThis skill teaches how to load and render 3D models from Wavefront OBJ files.\nIt builds on `textures-and-samplers` (Lesson 04), `mipmaps` (Lesson 05),\n`depth-and-3d` (Lesson 06), and `camera-and-input` (Lesson 07).\n\n## When to use\n\n- Loading 3D models from OBJ files\n- Rendering textured meshes with a camera\n- Parsing vertex positions, normals, and UV coordinates from files\n- Setting up non-indexed rendering (de-indexed vertices)\n- Combining texture loading + mipmaps + depth testing + camera in one app\n\n## Key API calls (ordered)\n\n1. `forge_obj_load(path, &mesh)` — parse OBJ into de-indexed vertex array\n2. `SDL_CreateGPUBuffer` + transfer upload — upload vertices to GPU\n3. `SDL_LoadSurface` + `SDL_ConvertSurface` — load PNG texture\n4. `SDL_CreateGPUTexture` with `SAMPLER | COLOR_TARGET` — mipmapped texture\n5. `SDL_GenerateMipmapsForGPUTexture` — auto-generate mip chain\n6. `SDL_CreateGPUSampler` — trilinear, REPEAT address mode\n7. `SDL_CreateGPUGraphicsPipeline` — 3 vertex attributes, depth test, back-face cull\n8. `SDL_BindGPUFragmentSamplers` — bind diffuse texture + sampler\n9. `SDL_DrawGPUPrimitives` — non-indexed draw (de-indexed vertices)\n\n## Libraries\n\n```c\n#include \"obj/forge_obj.h\"     /* OBJ parser */\n#include \"math/forge_math.h\"   /* vectors, matrices, quaternions */\n```\n\n## Code template\n\n### Loading the mesh\n\n```c\n/* Build path relative to executable */\nconst char *base_path = SDL_GetBasePath();\nchar obj_path[512];\nSDL_snprintf(obj_path, sizeof(obj_path), \"%smodels/model.obj\", base_path);\n\nForgeObjMesh mesh;\nif (!forge_obj_load(obj_path, &mesh)) {\n    SDL_Log(\"Failed to load model\");\n    return SDL_APP_FAILURE;\n}\n\n/* Upload to GPU vertex buffer via transfer buffer */\nUint32 vertex_data_size = mesh.vertex_count * (Uint32)sizeof(ForgeObjVertex);\n/* ... standard transfer buffer pattern from Lesson 02 ... */\n\nUint32 mesh_vertex_count = mesh.vertex_count;\nforge_obj_free(&mesh);  /* CPU-side data no longer needed */\n```\n\n### Loading texture with mipmaps\n\n```c\nSDL_Surface *surface = SDL_LoadSurface(tex_path);\nSDL_Surface *converted = SDL_ConvertSurface(surface, SDL_PIXELFORMAT_ABGR8888);\nSDL_DestroySurface(surface);\n\nint num_levels = (int)forge_log2f((float)converted->w) + 1;\n\nSDL_GPUTextureCreateInfo tex_info;\nSDL_zero(tex_info);\ntex_info.type     = SDL_GPU_TEXTURETYPE_2D;\ntex_info.format   = SDL_GPU_TEXTUREFORMAT_R8G8B8A8_UNORM_SRGB;\ntex_info.usage    = SDL_GPU_TEXTUREUSAGE_SAMPLER | SDL_GPU_TEXTUREUSAGE_COLOR_TARGET;\ntex_info.width    = converted->w;\ntex_info.height   = converted->h;\ntex_info.num_levels = num_levels;\n/* ... upload base level, then: */\nSDL_GenerateMipmapsForGPUTexture(cmd, texture);\n```\n\n### Vertex layout (3 attributes)\n\n```c\n/* ForgeObjVertex: position (float3) + normal (float3) + uv (float2) */\n\nvertex_attributes[0].location = 0;  /* TEXCOORD0 = position */\nvertex_attributes[0].format   = SDL_GPU_VERTEXELEMENTFORMAT_FLOAT3;\nvertex_attributes[0].offset   = offsetof(ForgeObjVertex, position);\n\nvertex_attributes[1].location = 1;  /* TEXCOORD1 = normal */\nvertex_attributes[1].format   = SDL_GPU_VERTEXELEMENTFORMAT_FLOAT3;\nvertex_attributes[1].offset   = offsetof(ForgeObjVertex, normal);\n\nvertex_attributes[2].location = 2;  /* TEXCOORD2 = uv */\nvertex_attributes[2].format   = SDL_GPU_VERTEXELEMENTFORMAT_FLOAT2;\nvertex_attributes[2].offset   = offsetof(ForgeObjVertex, uv);\n```\n\n### Rendering (non-indexed)\n\n```c\nSDL_BindGPUVertexBuffers(pass, 0, &vertex_binding, 1);\n\nSDL_GPUTextureSamplerBinding tex_binding;\nSDL_zero(tex_binding);\ntex_binding.texture = diffuse_texture;\ntex_binding.sampler = sampler;\nSDL_BindGPUFragmentSamplers(pass, 0, &tex_binding, 1);\n\n/* Non-indexed draw — de-indexed vertices, every 3 form a triangle */\nSDL_DrawGPUPrimitives(pass, mesh_vertex_count, 1, 0, 0);\n```\n\n### HLSL shaders\n\n**Vertex shader:**\n\n```hlsl\ncbuffer Uniforms : register(b0, space1) { column_major float4x4 mvp; };\n\nstruct VSInput {\n    float3 position : TEXCOORD0;\n    float3 normal   : TEXCOORD1;\n    float2 uv       : TEXCOORD2;\n};\n\nstruct VSOutput {\n    float4 position : SV_Position;\n    float2 uv       : TEXCOORD0;\n};\n\nVSOutput main(VSInput input) {\n    VSOutput output;\n    output.position = mul(mvp, float4(input.position, 1.0));\n    output.uv = input.uv;\n    return output;\n}\n```\n\n**Fragment shader:**\n\n```hlsl\nTexture2D    diffuse_tex : register(t0, space2);\nSamplerState smp         : register(s0, space2);\n\nfloat4 main(float4 pos : SV_Position, float2 uv : TEXCOORD0) : SV_Target {\n    return diffuse_tex.Sample(smp, uv);\n}\n```\n\n## Common mistakes\n\n1. **Forgetting UV flip** — OBJ uses V=0 at bottom; GPU uses V=0 at top.\n   The `forge_obj.h` parser handles this automatically (`1.0 - v`).\n\n2. **Using indexed draw for de-indexed mesh** — Use `SDL_DrawGPUPrimitives`,\n   not `SDL_DrawGPUIndexedPrimitives`, since vertices are already expanded.\n\n3. **Wrong pixel format** — `SDL_LoadSurface` may return any format.\n   Always convert to `SDL_PIXELFORMAT_ABGR8888` for GPU `R8G8B8A8`.\n\n4. **Missing `COLOR_TARGET` usage** — Required for mipmap generation.\n   Without it, `SDL_GenerateMipmapsForGPUTexture` silently fails.\n\n5. **Not copying model files in CMake** — The OBJ and texture must be next\n   to the executable. Use `add_custom_command(POST_BUILD ...)` to copy them.\n\n6. **Loading JPG** — `SDL_LoadSurface` only supports BMP and PNG.\n   Convert JPG textures to PNG first (e.g. with Python Pillow).\n\n## CMakeLists.txt pattern\n\n```cmake\n# Copy model files next to executable\nadd_custom_command(TARGET my-target POST_BUILD\n    COMMAND ${CMAKE_COMMAND} -E make_directory\n        $<TARGET_FILE_DIR:my-target>/models/model-name\n    COMMAND ${CMAKE_COMMAND} -E copy_if_different\n        ${CMAKE_CURRENT_SOURCE_DIR}/models/model-name/model.obj\n        $<TARGET_FILE_DIR:my-target>/models/model-name/model.obj\n    COMMAND ${CMAKE_COMMAND} -E copy_if_different\n        ${CMAKE_CURRENT_SOURCE_DIR}/models/model-name/texture.png\n        $<TARGET_FILE_DIR:my-target>/models/model-name/texture.png\n)\n```\n\n## References\n\n- [GPU Lesson 08 — Loading a Mesh](../../../lessons/gpu/08-mesh-loading/)\n- [GPU Lesson 04 — Textures & Samplers](../../../lessons/gpu/04-textures-and-samplers/)\n- [GPU Lesson 05 — Mipmaps](../../../lessons/gpu/05-mipmaps/)\n- [GPU Lesson 07 — Camera & Input](../../../lessons/gpu/07-camera-and-input/)\n- [OBJ Parser Library](../../../common/obj/forge_obj.h)\n"},"lastSynced":"2026-03-06T06:41:46.472Z","agentAnalysis":{"suitability":{"en":"Perfect for Graphics Agents needing real-time 3D model rendering capabilities with SDL''s GPU API","zh":"非常适合需要实时 3D 模型渲染功能的 Graphics Agents，使用 SDL 的 GPU API","ja":"リアルタイム 3D モデルレンダリング機能が必要な Graphics エージェントに最適で、SDL の GPU API を使用","ko":"실시간 3D 모델 렌더링 기능이 필요한 Graphics 에이전트에게 적합하며, SDL의 GPU API를 사용","es":"Perfecto para agentes gráficos que necesitan capacidades de renderizado de modelos 3D en tiempo real con la API de GPU de SDL","fr":"Parfait pour les agents graphiques nécessitant des capacités de rendu de modèles 3D en temps réel avec l''API GPU de SDL","de":"Perfekt für Grafikagenten, die Echtzeit-3D-Modell-Renderfunktionen mit SDLs GPU-API benötigen","pt":"Perfeito para Agentes Gráficos que necessitam de capacidades de renderização de modelos 3D em tempo real com a API de GPU da SDL","ru":"Идеально подходит для Графических Агентов, требующих возможностей рендеринга 3D-моделей в реальном времени с помощью API GPU от SDL","ar":"مثالي لوكلاء الرسومات الذين يحتاجون إلى إمكانيات تحديث نماذج 3D في الوقت الفعلي باستخدام واجهة برمجة تطبيقات GPU من SDL"},"recommendation":{"en":"Empowers agents to load and render 3D models from Wavefront OBJ files, enabling textured rendering with camera control using SDL''s GPU API, and parsing vertex positions, normals, and UV coordinates from files","zh":"赋予代理加载和渲染 Wavefront OBJ 文件中的 3D 模型的能力，实现使用 SDL 的 GPU API 进行纹理渲染和摄像头控制，并从文件中解析顶点位置、法线和 UV 坐标","ja":"エージェントが Wavefront OBJ ファイルから 3D モデルを読み込み、SDL の GPU API を使用してテクスチャレンダリングとカメラ制御を実行し、ファイルから頂点位置、法線、UV 座標を解析する機能を提供","ko":"에이전트가 Wavefront OBJ 파일에서 3D 모델을 로드하고 렌더링할 수 있는 기능을 제공하며, SDL의 GPU API를 사용하여 텍스처 렌더링과 카메라 제어를 가능하게 하며, 파일에서 꼭지점 위치, 법선 및 UV 좌표를 구문 분석","es":"Habilita a los agentes a cargar y renderizar modelos 3D desde archivos Wavefront OBJ, permitiendo renderizado texturizado con control de cámara utilizando la API de GPU de SDL, y analizar posiciones de vértices, normales y coordenadas UV desde archivos","fr":"Permet aux agents de charger et de rendre des modèles 3D à partir de fichiers Wavefront OBJ, permettant un rendu texturé avec contrôle de caméra en utilisant l''API GPU de SDL, et analyser les positions de sommets, les normales et les coordonnées UV à partir de fichiers","de":"Ermächtigt Agenten, 3D-Modelle aus Wavefront-OBJ-Dateien zu laden und zu rendern, ermöglicht texturiertes Rendern mit Kamera-Steuerung unter Verwendung von SDLs GPU-API und Parsen von Vertex-Positionen, Normalen und UV-Koordinaten aus Dateien","pt":"Habilita os agentes a carregar e renderizar modelos 3D a partir de arquivos Wavefront OBJ, permitindo renderização texturizada com controle de câmera usando a API de GPU da SDL, e análise de posições de vértices, normais e coordenadas UV a partir de arquivos","ru":"Наделяет агентов возможностью загружать и рендерить 3D-модели из файлов Wavefront OBJ, обеспечивая текстурированное рендеринг с контролем камеры с помощью API GPU от SDL, и разбор позиций вершин, нормалей и координат UV из файлов","ar":"تمكين الوكلاء من تحميل وتصيير نماذج 3D من ملفات Wavefront OBJ، وتوفير تصيير محسن مع تحكم الكاميرا باستخدام واجهة برمجة تطبيقات GPU من SDL، وتحليل مواقع الرأس والاعتيان والتنسيق UV من الملفات"},"useCases":{"en":["Loading 3D models from OBJ files for interactive simulations","Rendering textured meshes with camera control for immersive experiences","Parsing 3D model data from Wavefront OBJ files for further processing"],"zh":["从 OBJ 文件加载 3D 模型用于交互式模拟","使用摄像头控制渲染纹理网格以实现身临其境的体验","从 Wavefront OBJ 文件解析 3D 模型数据以进行进一步处理"],"ja":["OBJ ファイルから 3D モデルを読み込み、インタラクティブなシミュレーションに使用","カメラ制御を使用してテクスチャ化されたメッシュをレンダリングし、臨場感のある体験を実現","Wavefront OBJ ファイルから 3D モデルデータを解析してさらに処理"],"ko":["OBJ 파일에서 3D 모델을 로드하여 상호작용 시뮬레이션에 사용","카메라 제어를 사용하여 텍스처화된 메쉬를 렌더링하여 몰입감 있는 경험을 제공","Wavefront OBJ 파일에서 3D 모델 데이터를 구문 분석하여 추가 처리"],"es":["Carga de modelos 3D desde archivos OBJ para simulaciones interactivas","Renderizado de mallas texturizadas con control de cámara para experiencias inmersivas","Análisis de datos de modelos 3D desde archivos Wavefront OBJ para un procesamiento posterior"],"fr":["Chargement de modèles 3D à partir de fichiers OBJ pour des simulations interactives","Rendu de maillages texturés avec contrôle de caméra pour des expériences immersives","Analyse de données de modèles 3D à partir de fichiers Wavefront OBJ pour un traitement ultérieur"],"de":["Laden von 3D-Modellen aus OBJ-Dateien für interaktive Simulationen","Rendern von texturierten Netzen mit Kamera-Steuerung für immersive Erfahrungen","Auswertung von 3D-Modell-Daten aus Wavefront-OBJ-Dateien für eine weitere Verarbeitung"],"pt":["Carregando modelos 3D a partir de arquivos OBJ para simulações interativas","Renderizando malhas texturizadas com controle de câmera para experiências imersivas","Analisando dados de modelos 3D a partir de arquivos Wavefront OBJ para processamento adicional"],"ru":["Загрузка 3D-моделей из файлов OBJ для интерактивных симуляций","Рендеринг текстурированных сеток с контролем камеры для погружающих опытов","Разбор данных 3D-моделей из файлов Wavefront OBJ для дальнейшей обработки"],"ar":["تحميل نماذج 3D من ملفات OBJ للتحاكي التفاعلي","تصيير شبكات محسنة مع تحكم الكاميرا لتجارب غامرة","تحليل بيانات نماذج 3D من ملفات Wavefront OBJ للمعالجة الإضافية"]},"limitations":{"en":["Requires SDL''s GPU API compatibility","Limited to Wavefront OBJ file format","Builds on prior knowledge of textures, mipmaps, depth, and camera concepts"],"zh":["需要 SDL 的 GPU API 兼容性","仅限 Wavefront OBJ 文件格式","需要对纹理、mipmaps、深度和摄像头概念有先前的知识"],"ja":["SDL の GPU API の互換性が必要","Wavefront OBJ ファイル形式のみ","テクスチャ、ミップマップ、深度、カメラの概念に関する事前の知識が必要"],"ko":["SDL의 GPU API 호환성이 필요","Wavefront OBJ 파일 형식만 해당","텍스처, 미ップ맵, 깊이 및 카메라 개념에 대한 이전 지식이 필요"],"es":["Requiere compatibilidad con la API de GPU de SDL","Limitado al formato de archivo Wavefront OBJ","Se basa en conocimientos previos de texturas, mipmaps, profundidad y conceptos de cámara"],"fr":["Nécessite la compatibilité avec l''API GPU de SDL","Limité au format de fichier Wavefront OBJ","Repose sur des connaissances antérieures en matière de textures, de mipmaps, de profondeur et de concepts de caméra"],"de":["Benötigt Kompatibilität mit SDLs GPU-API","Begrenzt auf das Wavefront-OBJ-Dateiformat","Baut auf Vorkenntnissen von Texturen, Mipmaps, Tiefe und Kamera-Konzepten auf"],"pt":["Exige compatibilidade com a API de GPU da SDL","Limitado ao formato de arquivo Wavefront OBJ","Constrói sobre conhecimento prévio de texturas, mipmaps, profundidade e conceitos de câmera"],"ru":["Требует совместимости с API GPU от SDL","Ограничен форматом файла Wavefront OBJ","Строится на предварительных знаниях текстур, mipmaps, глубины и концепций камеры"],"ar":["يتطلب توافقًا مع واجهة برمجة تطبيقات GPU من SDL","محدود بتنسيق ملف Wavefront OBJ","يبني على معرفة سابقة لأنسجة المياب، والعمق، ومفاهيم الكاميرا"]},"version":4},"contentHash":"d51cc4235885ba5ca680317b887bd7d7858dc9cd904a2a277f3b6f6453c202db","qualityScore":57}');
