INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cooldaemon/dotfiles/git-workflow', 'git-workflow', 'cooldaemon', 'dotfiles', 'community', 'git-workflow cooldaemon dotfiles community The git-workflow skill streamlines Git workflow by enforcing a standardized commit message format, benefiting developers and teams through improved code organization and readability. Git 工作流是一种优化代码提交和管理的方法，包括特定的提交消息格式和类型 Git ワークフローは、コードを効率的に管理するための方法論で、特定のコミットメッセージ形式やタイプが含まれています Git 워크플로우는 코드를 효율적으로 관리하기 위한 방법으로, 특정한 커밋 메시지 형식과 유형을 포함합니다 El flujo de trabajo Git es una forma de organizar y estructurar tus cambios en el código. Utiliza patrones como feat, fix y docs para mejorar la colaboración Le flux de travail Git est un moyen d''organiser et de structurer vos modifications de code. Utilisez des modèles tels que feat, fix et docs pour améliorer la collaboration Der Git-Workflow ist eine Möglichkeit, Ihre Code-Änderungen zu organisieren und zu strukturieren. Verwenden Sie Muster wie feat, fix und docs, um die Zusammenarbeit zu verbessern O fluxo de trabalho Git é um padrão de commits que ajuda a manter a organização e a clareza no código Поток работы Git - это шаблон коммитов, который помогает поддерживать организацию и ясность в коде Fluxo de Trabalho Git هو نمط إلتزامات يساعد في الحفاظ على التنظيم والوضوح في الكود git-workflow setup guide commit message format best practices git workflow management tools standardized commit messages git-workflow vs git-flow how to use git-workflow git-workflow installation git workflow automation git commit message conventions improving code readability with git-workflow Git 工作流 代码管理 提交消息格式 提交类型 代码优化 效率提升 标准化提交消息 AI工具 代码管理工具 Enforces a consistent commit message format using type, scope, subject, body, and footer Supports multiple commit types, including feat, fix, docs, style, refactor, perf, test, and chore Improves code readability through clear and descriptive commit messages Enhances team collaboration by establishing a shared understanding of commit message conventions Facilitates the use of automated tools and scripts to parse and analyze commit messages git-workflow is a standardized approach to managing Git commits through a specific message format, enhancing code maintainability and team collaboration');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('taucad/tau/pr-review-coordinator', 'community', 'taucad', 'tau', 'taucad/tau', 'pr-review-coordinator', 12, 1, 57, '2026-02-23T01:15:11Z', '2026-03-06T06:45:29.713Z', '19a19fb906dc17ab5c7d83f4b558d9b600436d4b0080a22ffe66663dbef44239', '{"id":"taucad/tau/pr-review-coordinator","name":"pr-review-coordinator","description":{"en":"The pr-review-coordinator skill automates PR review feedback parsing and dispatches issues to subagents for resolution, benefiting developers and teams working with CodeRabbit, Claude bot, and Cursor bot.","zh":"PR审查协调器是一种AI原生CAD平台，用于解析PR审查反馈并分配问题给子代理进行解决","ja":"PRレビューコーディネーターは、AIネイティブCADプラットフォームであり、PRレビューのフィードバックを解析してサブエージェントに問題を割り当てる","ko":"PR 리뷰 코디네이터는 AI 네이티브 CAD 플랫폼으로 PR 리뷰 피드백을 파싱하여 서브 에이전트에 문제를 할당","es":"El Coordinador de Revisión de PR es una herramienta que parsea la retroalimentación de revisión y envía problemas al subagente pr-issue-fixer para su resolución","fr":"Le Coordinateur de Revue de PR est un outil qui analyse les commentaires de révision et envoie les problèmes au sous-agent pr-issue-fixer pour résolution","de":"Der PR-Review-Koordinator ist ein Tool, das die Rückmeldung zur Überprüfung analysiert und Probleme an den Subagenten pr-issue-fixer zur Lösung sendet","pt":"O pr-review-coordinator é uma ferramenta de análise de código que extrai issues de revisões de código e as dispatcha para resolução","ru":"Пр-review-coordinator - это инструмент для анализа кода, который извлекает проблемы из обзоров кода и отправляет их на решение","ar":"pr-review-coordinator هو أداة لتحليل الكود التي تستخرج القضايا من مراجعات الكود وتوجهها إلى الإصلاح"},"seo":{"title":{"en":"pr-review-coordinator: Automated PR Review Setup Guide | ...","zh":"PR审查协调器_setup指南 - AIエージェント工具","ja":"PRレビューコーディネーター設定ガイド - AIエージェント","ko":"PR 리뷰 코디네이터 설정 가이드 - AI 에이전트","es":"Configuración del Coordinador de Revisión de PR: Guía par...","fr":"Mise en place du Coordinateur de Revue de PR: Guide pour ...","de":"Einrichtung des PR-Review- Koordinators: Anleitung für En...","pt":"Guia de Configuração do pr-review-coordinator: Ferramenta...","ru":"Настройка пр-review-coordinator: Инструмент для анализа к...","ar":"دليل إعداد pr-review-coordinator: أداة تحليل الكود الذكية"},"description":{"en":"Streamline your PR review process with pr-review-coordinator. Discover how to automate issue parsing and dispatching with this AI-native CAD platform.","zh":"了解PR审查协调器的工作原理，如何解析PR审查反馈并分配问题给子代理进行解决","ja":"PRレビューコーディネーターのしくみを学び、PRレビューのフィードバックを解析してサブエージェントに問題を割り当てる","ko":"PR 리뷰 코디네이터의 작동 원리를 알아보고 PR 리뷰 피드백을 파싱하여 서브 에이전트에 문제를 할당하는 방법","es":"Aprenda a configurar el Coordinador de Revisión de PR para agilizar su flujo de trabajo de desarrollo con tecnologías como CodeRabbit y Claude bot","fr":"Découvrez comment configurer le Coordinateur de Revue de PR pour accélérer votre flux de travail de développement avec des technologies comme CodeRabbit et C...","de":"Erfahren Sie, wie Sie den PR-Review-Koordinator einrichten, um Ihren Entwicklungsworkflow mit Technologien wie CodeRabbit und Claude bot zu optimieren","pt":"Aprenda a configurar o pr-review-coordinator para analisar comentários de revisão de código e dispatchar issues para resolução","ru":"Узнайте, как настроить пр-review-coordinator для анализа комментариев к коду и отправки задач на решение ИИ Агентов","ar":"تعرف على كيفية إعداد pr-review-coordinator لتحليل التعليقات على الكود وتوجيه القضايا إلى الإصلاح"},"definition":{"en":"pr-review-coordinator is a skill that parses PR review feedback and dispatches issues to subagents for resolution, integrating with tools like CodeRabbit and Claude bot.","zh":"PR审查协调器是一种工具，用于解析PR审查反馈并自动分配问题给子代理进行解决","ja":"PRレビューコーディネーターは、PRレビューのフィードバックを解析してサブエージェントに問題を割り当てるツール","ko":"PR 리뷰 코디네이터는 PR 리뷰 피드백을 파싱하여 서브 에이전트에 문제를 할당하는 도구","es":"El Coordinador de Revisión de PR es una herramienta de desarrollo que automatiza la revisión de código","fr":"Le Coordinateur de Revue de PR est un outil de développement qui automatise la révision de code","de":"Der PR-Review-Koordinator ist ein Entwicklungstool, das die Code-Überprüfung automatisiert","pt":"O pr-review-coordinator é uma ferramenta de análise de código que automatiza a revisão de código","ru":"Пр-review-coordinator - это инструмент для анализа кода, который автоматизирует обзор кода ИИ Агенты","ar":"pr-review-coordinator هو أداة لتحليل الكود التي تautomatiza مراجعة الكود"},"features":{"en":["Parses issues from CodeRabbit using actionable comments and severity badges","Extracts priority sections from Claude bot reviews, including Critical/High/Medium/Low sections","Dispatches issues to pr-issue-fixer subagents for automated resolution","Supports manual issue extraction using bull syntax","Integrates with Cursor bot for numbered suggestions with code snippets"],"zh":["解析CodeRabbit的行动点和严重性徽章","支持Claude bot的优先级部分","识别Cursor bot的编号建议","手动问题识别"],"ja":["CodeRabbitのアクションポイントとシバリティバッジの解析","Claude botの優先度セクションのサポート","Cursor botの番号付き提案の識別","手動問題の識別"],"ko":["CodeRabbit의 액션 포인트와 심각성 배지 파싱","Claude bot의 우선 순위 섹션 지원","Cursor bot의 번호付き 제안 식별","수동 문제 식별"],"es":["Análisis de comentarios de revisión de CodeRabbit","Detección de secciones de prioridad de Claude bot","Procesamiento de sugerencias numeradas de Cursor bot","Compatibilidad con comentarios manuales"],"fr":["Analyse des commentaires de révision de CodeRabbit","Détection des sections de priorité de Claude bot","Traitement des suggestions numérotées de Cursor bot","Compatibilité avec les commentaires manuels"],"de":["Analyse von CodeRabbit-Überprüfungskommentaren","Erkennung von Prioritätsabschnitten von Claude bot","Verarbeitung von nummerierten Vorschlägen von Cursor bot","Kompatibilität mit manuellen Kommentaren"],"pt":["Análise de comentários de revisão de código","Extração de issues de revisões de código","Dispatch de issues para resolução","Integração com CodeRabbit, Claude bot e Cursor bot","Suporte a análise de código manual"],"ru":["Анализ комментариев к коду","Извлечение проблем из обзоров кода","Отправка задач на решение","Интеграция с CodeRabbit, Claude bot и Cursor bot","Поддержка ручного анализа кода ИИ Агенты"],"ar":["تحليل التعليقات على الكود","استخراج القضايا من مراجعات الكود","توجيه القضايا إلى الإصلاح","التكامل مع CodeRabbit، Claude bot و Cursor bot","دعم تحليل الكود اليدوي"]},"keywords":{"en":["how to use pr-review-coordinator","pr-review-coordinator setup guide","pr-review-coordinator vs manual review","pr-review-coordinator install","what is pr-review-coordinator","pr-review-coordinator alternative","automated pr review tools","pr-review-coordinator and CodeRabbit integration","pr-review-coordinator tutorial"],"zh":["PR审查协调器","AIエージェント工具","CAD平台","PR审查反馈","子代理","CodeRabbit","Claude bot","Cursor bot"],"ja":["PRレビューコーディネーター","AIエージェント","CADプラットフォーム","PRレビューのフィードバック","サブエージェント","CodeRabbit","Claude bot","Cursor bot"],"ko":["PR 리뷰 코디네이터","AI 에이전트","CAD 플랫폼","PR 리뷰 피드백","서브 에이전트","CodeRabbit","Claude bot","Cursor bot"],"es":["Herramientas de desarrollo de AI","Coordinador de Revisión de PR","CodeRabbit","Claude bot","Cursor bot","Automatización de revisión de código"],"fr":["Outils de développement d''IA","Coordinateur de Revue de PR","CodeRabbit","Claude bot","Cursor bot","Automatisation de la révision de code"],"de":["Entwicklungstools für KI","PR-Review-Koordinator","CodeRabbit","Claude bot","Cursor bot","Automatisierung der Code-Überprüfung"],"pt":["pr-review-coordinator","análise de código","revisão de código","ferramenta de análise de código","automatização de revisão de código","CodeRabbit","Claude bot","Cursor bot"],"ru":["пр-review-coordinator","анализ кода","обзор кода","инструмент для анализа кода","автоматизация обзора кода ИИ Агенты","CodeRabbit","Claude bot","Cursor bot"],"ar":["pr-review-coordinator","تحليل الكود","مراجعة الكود","أداة لتحليل الكود","تأتمتة مراجعة الكود","CodeRabbit","Claude bot","Cursor bot"]}},"owner":"taucad","repo":"tau","repoPath":"taucad/tau","stars":12,"forks":1,"updatedAt":"2026-02-23T01:15:11Z","topics":[],"category":"community","skillMd":{"name":"pr-review-coordinator","description":"Orchestrates PR review issue resolution by parsing review comments and dispatching to pr-issue-fixer subagents. Use when given a PR review summary, list of issues to fix, or when the user pastes review comments from CodeRabbit, Claude, Cursor, or similar tools.","bodyPreview":"# PR Review Coordinator\n\nParses PR review feedback and dispatches issues to `pr-issue-fixer` subagents for resolution.\n\n## Workflow\n\n### Step 1: Parse Issues\n\nExtract issues from the review. Look for:\n\n| Source | Patterns to Find |\n|--------|------------------|\n| CodeRabbit | \"Actionable comments\", severity badges, file paths with line numbers |\n| Claude bot | Priority sections (Critical/High/Medium/Low), code suggestions |\n| Cursor bot | Numbered suggestions with code snippets |\n| Manual | Bull","body":"# PR Review Coordinator\n\nParses PR review feedback and dispatches issues to `pr-issue-fixer` subagents for resolution.\n\n## Workflow\n\n### Step 1: Parse Issues\n\nExtract issues from the review. Look for:\n\n| Source | Patterns to Find |\n|--------|------------------|\n| CodeRabbit | \"Actionable comments\", severity badges, file paths with line numbers |\n| Claude bot | Priority sections (Critical/High/Medium/Low), code suggestions |\n| Cursor bot | Numbered suggestions with code snippets |\n| Manual | Bulleted/numbered issues with descriptions |\n\nFor each issue, extract:\n\n```\n- File: (required) path/to/file.ts\n- Lines: (optional) 45-50 or 123\n- Priority: Critical > High > Medium > Low\n- Category: cache-management | error-handling | performance | code-style | testing | documentation | security | architecture\n- Problem: What''s wrong\n- Suggestion: The fix (preserve code snippets!)\n```\n\n### Step 2: Group and Prioritize\n\n1. Sort by priority (Critical first)\n2. Group by file (same-file issues run sequentially)\n3. Flag conflicts (multiple issues on same lines)\n\n### Step 3: Dispatch to Fixers\n\nUse the Task tool with `subagent_type=\"pr-issue-fixer\"`:\n\n```\nUse Task tool:\n- subagent_type: \"pr-issue-fixer\"\n- prompt: |\n    Fix this PR review issue:\n    - File: [path]\n    - Lines: [numbers]\n    - Priority: [level]\n    - Category: [category]\n    - Problem: [description]\n    - Suggestion: [fix with code snippets]\n    - Context: [relevant architecture info]\n    \n    After fixing, run verification and report status.\n```\n\n**Parallelization:**\n- PARALLEL: Issues in different files\n- SEQUENTIAL: Issues in the same file\n\n### Step 4: Compile Results\n\nAfter all fixers complete:\n\n```markdown\n## PR Review Resolution Summary\n\n### Processed: X issues\n\n| Status | File | Issue |\n|--------|------|-------|\n| ✅ | path/file.ts | Brief description |\n| ⚠️ | path/other.ts | Partial - [what remains] |\n| ❌ | path/broken.ts | [reason] |\n\n### Verification\n- Typecheck: ✅/❌\n- Tests: N passed, M failed\n\n### Follow-up\n- [ ] Items needing human review\n```\n\n### Step 5: Final Verification\n\nRun after all issues addressed:\n\n```bash\npnpm nx typecheck <project>\npnpm nx test <project> --watch=false\n```\n\n## Example\n\n**Input:**\n```\nCodeRabbit review:\n1. [High] apps/ui/utils/cache.ts:45 - Cache unbounded, add LRU\n2. [Medium] apps/ui/worker.ts:123 - Memory leak in cleanup\n```\n\n**Actions:**\n1. Parse → 2 issues, 2 different files\n2. Dispatch in parallel (different files)\n3. Collect results\n4. Run final verification\n5. Report summary\n\n## Guidelines\n\n- Preserve code snippets from suggestions\n- Skip \"nitpick\" or \"optional\" issues unless requested\n- For vague issues, include surrounding review context\n- Flag conflicting suggestions for human decision\n"},"lastSynced":"2026-03-06T06:45:29.713Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing automated PR review feedback parsing and issue dispatching capabilities.","zh":"适用于需要自动化PR审查反馈解析和问题派发能力的代码审查代理。","ja":"コードレビューエージェントが自動化されたPRレビューフィードバックの解析と問題の派遣機能を必要とする場合に最適です。","ko":"코드 리뷰 에이전트가 자동화된 PR 리뷰 피드백 파싱 및 문제 배포 기능을 필요로 할 때 적합합니다.","es":"Ideal para agentes de revisión de código que necesitan comentarios de revisión de PR automatizados y capacidades de envío de problemas.","fr":"Idéal pour les agents de révision de code ayant besoin d''une rétroaction de révision de PR automatisée et de capacités d''envoi de problèmes.","de":"Ideal für Code-Review-Agents, die automatisierte PR-Review-Feedback-Parsing und Issue-Dispatching-Funktionen benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de feedback de revisão de PR automatizado e capacidades de despacho de problemas.","ru":"Идеально для Агентов обзора кода, которым требуются автоматизированные отзывы об обзоре PR и возможности отправки проблем.","ar":"مثالي للوكلاء المراجعة الكود الذين يحتاجون إلى ملاحظات مراجعة.PR آليّة وقدرات إرسال المشكلات."},"recommendation":{"en":"Empowers agents to parse PR review feedback from CodeRabbit, Claude bot, and Cursor bot, and dispatch issues to subagents like `pr-issue-fixer` for resolution, utilizing severity badges, priority sections, and code suggestions.","zh":"赋予代理解析来自CodeRabbit、Claude bot和Cursor bot的PR审查反馈的能力，并将问题派遣给像`pr-issue-fixer`这样的子代理进行解决，利用严重性徽章、优先级部分和代码建议。","ja":"エージェントがCodeRabbit、Claude bot、Cursor botからのPRレビューフィードバックを解析し、`pr-issue-fixer`などのサブエージェントに解決のために問題を派遣することを可能にします。セバリティバッジ、優先度セクション、コードの提案を利用します。","ko":"에이전트가 CodeRabbit, Claude bot, Cursor bot의 PR 리뷰 피드백을 파싱하고 `pr-issue-fixer`와 같은 하위 에이전트에 해결을 위해 문제를 디스패치하는 것을 가능하게 합니다. 심각성 배지, 우선 순위 섹션 및 코드 제안을 사용합니다.","es":"Habilita a los agentes para analizar comentarios de revisión de PR de CodeRabbit, Claude bot y Cursor bot, y enviar problemas a subagentes como `pr-issue-fixer` para resolución, utilizando insignias de gravedad, secciones de prioridad y sugerencias de código.","fr":"Permet aux agents d''analyser les commentaires de révision de PR de CodeRabbit, Claude bot et Cursor bot, et d''envoyer des problèmes à des sous-agents comme `pr-issue-fixer` pour résolution, en utilisant des badges de gravité, des sections de priorité et des suggestions de code.","de":"Ermächtigt Agenten, PR-Review-Feedback von CodeRabbit, Claude bot und Cursor bot zu parsen und Probleme an Subagenten wie `pr-issue-fixer` zur Lösung zu senden, unter Verwendung von Schweregrad-Abzeichen, Prioritätsabschnitten und Code-Vorschlägen.","pt":"Habilita agentes a analisar feedback de revisão de PR do CodeRabbit, Claude bot e Cursor bot, e despachar problemas para subagentes como `pr-issue-fixer` para resolução, utilizando badges de gravidade, seções de prioridade e sugestões de código.","ru":"Наделяет агентов возможностью анализировать отзывы об обзоре PR от CodeRabbit, Claude bot и Cursor bot, и отправлять проблемы подагентам, таким как `pr-issue-fixer`, для решения, используя значки серьезности, разделы приоритета и предложения кода.","ar":"يمكّن الوكلاء من تحليل ملاحظات مراجعة.PR من CodeRabbit و Claude bot و Cursor bot ، وإرسال المشكلات إلى وكلاء فرعيين مثل `pr-issue-fixer` لحلها ، باستخدام شارات الجدية وأقسام الأولوية ومقترحات الكود."},"useCases":{"en":["Automating PR review feedback parsing for CodeRabbit","Dispatching issues to subagents for resolution with Claude bot","Parsing numbered suggestions with code snippets from Cursor bot"],"zh":["为CodeRabbit自动化PR审查反馈解析","使用Claude bot将问题派遣给子代理进行解决","使用Cursor bot解析带有代码片段的编号建议"],"ja":["CodeRabbitのPRレビューフィードバックの自動化","Claude botを使用してサブエージェントに問題を派遣して解決","Cursor botを使用してコードスニペットを含む番号付きの提案を解析"],"ko":["CodeRabbit의 PR 리뷰 피드백 자동화","Claude bot를 사용하여 하위 에이전트에 문제를 디스패치하여 해결","Cursor bot를 사용하여 코드 스니펫을 포함한 번호가 있는 제안을 파싱"],"es":["Automatización del análisis de comentarios de revisión de PR para CodeRabbit","Envío de problemas a subagentes para resolución con Claude bot","Análisis de sugerencias numeradas con fragmentos de código de Cursor bot"],"fr":["Automatisation de l''analyse des commentaires de révision de PR pour CodeRabbit","Envoi de problèmes à des sous-agents pour résolution avec Claude bot","Analyse de suggestions numérotées avec des extraits de code de Cursor bot"],"de":["Automatisierung der Analyse von PR-Review-Feedback für CodeRabbit","Senden von Problemen an Subagenten zur Lösung mit Claude bot","Analyse von nummerierten Vorschlägen mit Code-Snippets von Cursor bot"],"pt":["Automatizar a análise de feedback de revisão de PR para CodeRabbit","Despachar problemas para subagentes para resolução com Claude bot","Analizar sugestões numeradas com trechos de código de Cursor bot"],"ru":["Автоматизировать анализ отзывов об обзоре PR для CodeRabbit","Отправлять проблемы подагентам для решения с Claude bot","Анализировать пронумерованные предложения с фрагментами кода от Cursor bot"],"ar":["تحليل ملاحظات مراجعة.PR آليّة لـ CodeRabbit","إرسال المشكلات إلى وكلاء فرعيين لحلها مع Claude bot","تحليل الاقتراحات المرقمة مع شذرات من الكود من Cursor bot"]},"limitations":{"en":["Requires integration with CodeRabbit, Claude bot, or Cursor bot","Limited to parsing specific patterns and formats"],"zh":["需要与CodeRabbit、Claude bot或Cursor bot集成","仅限于解析特定模式和格式"],"ja":["CodeRabbit、Claude bot、またはCursor botとの統合が必要","特定のパターンと形式の解析のみに限定"],"ko":["CodeRabbit, Claude bot 또는 Cursor bot와의 통합이 필요","특정 패턴 및 형식의 파싱만으로 제한"],"es":["Requiere integración con CodeRabbit, Claude bot o Cursor bot","Limitado al análisis de patrones y formatos específicos"],"fr":["Nécessite une intégration avec CodeRabbit, Claude bot ou Cursor bot","Limité à l''analyse de modèles et de formats spécifiques"],"de":["Erfordert Integration mit CodeRabbit, Claude bot oder Cursor bot","Begrenzt auf die Analyse spezifischer Muster und Formate"],"pt":["Requer integração com CodeRabbit, Claude bot ou Cursor bot","Limitado à análise de padrões e formatos específicos"],"ru":["Требует интеграции с CodeRabbit, Claude bot или Cursor bot","Ограничен анализом определенных шаблонов и форматов"],"ar":["يتطلب التكامل مع CodeRabbit و Claude bot و Cursor bot","محدود بتحليل أنماط وتنسيقات محددة"]},"version":4},"contentHash":"19a19fb906dc17ab5c7d83f4b558d9b600436d4b0080a22ffe66663dbef44239","qualityScore":57}');
