INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('taucad/tau/pr-review-coordinator', 'pr-review-coordinator', 'taucad', 'tau', 'community', 'pr-review-coordinator taucad tau community The pr-review-coordinator skill automates PR review feedback parsing and dispatches issues to subagents for resolution, benefiting developers and teams working with CodeRabbit, Claude bot, and Cursor bot. PR审查协调器是一种AI原生CAD平台，用于解析PR审查反馈并分配问题给子代理进行解决 PRレビューコーディネーターは、AIネイティブCADプラットフォームであり、PRレビューのフィードバックを解析してサブエージェントに問題を割り当てる PR 리뷰 코디네이터는 AI 네이티브 CAD 플랫폼으로 PR 리뷰 피드백을 파싱하여 서브 에이전트에 문제를 할당 El Coordinador de Revisión de PR es una herramienta que parsea la retroalimentación de revisión y envía problemas al subagente pr-issue-fixer para su resolución Le Coordinateur de Revue de PR est un outil qui analyse les commentaires de révision et envoie les problèmes au sous-agent pr-issue-fixer pour résolution Der PR-Review-Koordinator ist ein Tool, das die Rückmeldung zur Überprüfung analysiert und Probleme an den Subagenten pr-issue-fixer zur Lösung sendet O pr-review-coordinator é uma ferramenta de análise de código que extrai issues de revisões de código e as dispatcha para resolução Пр-review-coordinator - это инструмент для анализа кода, который извлекает проблемы из обзоров кода и отправляет их на решение pr-review-coordinator هو أداة لتحليل الكود التي تستخرج القضايا من مراجعات الكود وتوجهها إلى الإصلاح how to use pr-review-coordinator pr-review-coordinator setup guide pr-review-coordinator vs manual review pr-review-coordinator install what is pr-review-coordinator pr-review-coordinator alternative automated pr review tools pr-review-coordinator and CodeRabbit integration pr-review-coordinator tutorial PR审查协调器 AIエージェント工具 CAD平台 PR审查反馈 子代理 CodeRabbit Claude bot Cursor bot Parses issues from CodeRabbit using actionable comments and severity badges Extracts priority sections from Claude bot reviews, including Critical/High/Medium/Low sections Dispatches issues to pr-issue-fixer subagents for automated resolution Supports manual issue extraction using bull syntax Integrates with Cursor bot for numbered suggestions with code snippets pr-review-coordinator is a skill that parses PR review feedback and dispatches issues to subagents for resolution, integrating with tools like CodeRabbit and Claude bot.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cmd-llm/cllm/adr', 'community', 'cmd-llm', 'cllm', 'cmd-llm/cllm', 'adr', 8, 3, 57, '2026-02-23T09:57:54Z', '2026-03-06T06:49:20.917Z', '4adfff1b3b7d858415fa66e36fc6c8769248fa2fe26d091ede06e4242140df08', '{"id":"cmd-llm/cllm/adr","name":"adr","description":{"en":"The adr skill helps developers create comprehensive Architecture Decision Records using the MADR template. It assists in documenting architectural decisions, problems, and solutions.","zh":"ADR 创建指南使用 MADR 模板帮助开发者创建全面的架构决策记录。该工具提供了创建 ADR 的步骤指南","ja":"ADR 作成ガイドは、MADR テンプレートを使用して包括的なアーキテクチャ決定レコードを作成するためのステップバイステップガイドを提供する","ko":"ADR 생성 가이드는 MADR 템플릿을 사용하여 포괄적인 아키텍처 결정 기록을 생성하는 데 필요한 단계별 가이드를 제공합니다","es":"ADR es una herramienta de línea de comandos que ayuda a crear registros de decisiones de arquitectura con la plantilla MADR de o3-cloud","fr":"ADR est un outil de ligne de commande qui aide à créer des enregistrements de décisions d''architecture avec le modèle MADR de o3-cloud","de":"ADR ist ein Kommandozeilen-Tool, das dabei hilft, Architekturentscheidungsprotokolle mit der MADR-Vorlage von o3-cloud zu erstellen","pt":"A ferramenta ADR ajuda a criar registros de decisão de arquitetura com o modelo MADR da o3-cloud. Ela fornece uma estrutura para documentar decisões arquiteturais.","ru":"ИИ Агент ADR помогает создавать Architecture Decision Records с помощью шаблона MADR от o3-cloud. Он предоставляет структуру для документирования решений по архитектуре","ar":"أداة ADR تساعد في إنشاء سجلات قرارات Архитектур باستخدام نموذج MADR من o3-cloud. توفر هيكلاً لتوثيق القرارات المعمارية"},"seo":{"title":{"en":"adr: Comprehensive ADR Creator Setup Guide | AI Agent Skill","zh":"ADR 创建指南：使用 MADR 模板的 CLI 工具","ja":"ADR 作成ガイド：MADR テンプレートを使用した AI エージェント","ko":"ADR 생성 가이드: MADR 템플릿을 사용하는 AI 에이전트","es":"ADR Setup Guide: Herramientas de Línea de Comandos para R...","f