INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cmd-llm/cllm/adr', 'adr', 'cmd-llm', 'cllm', 'community', 'adr cmd-llm cllm community The adr skill helps developers create comprehensive Architecture Decision Records using the MADR template. It assists in documenting architectural decisions, problems, and solutions. ADR 创建指南使用 MADR 模板帮助开发者创建全面的架构决策记录。该工具提供了创建 ADR 的步骤指南 ADR 作成ガイドは、MADR テンプレートを使用して包括的なアーキテクチャ決定レコードを作成するためのステップバイステップガイドを提供する ADR 생성 가이드는 MADR 템플릿을 사용하여 포괄적인 아키텍처 결정 기록을 생성하는 데 필요한 단계별 가이드를 제공합니다 ADR es una herramienta de línea de comandos que ayuda a crear registros de decisiones de arquitectura con la plantilla MADR de o3-cloud ADR est un outil de ligne de commande qui aide à créer des enregistrements de décisions d''architecture avec le modèle MADR de o3-cloud ADR ist ein Kommandozeilen-Tool, das dabei hilft, Architekturentscheidungsprotokolle mit der MADR-Vorlage von o3-cloud zu erstellen A ferramenta ADR ajuda a criar registros de decisão de arquitetura com o modelo MADR da o3-cloud. Ela fornece uma estrutura para documentar decisões arquiteturais. ИИ Агент ADR помогает создавать Architecture Decision Records с помощью шаблона MADR от o3-cloud. Он предоставляет структуру для документирования решений по архитектуре أداة ADR تساعد في إنشاء سجلات قرارات Архитектур باستخدام نموذج MADR من o3-cloud. توفر هيكلاً لتوثيق القرارات المعمارية how to use adr what is adr adr setup guide adr alternative adr vs madr adr install adr template architecture decision record madr template ADR 创建 MADR 模板 架构决策记录 CLI 工具 AI 에이전트 开发者工具 Generates comprehensive Architecture Decision Records using the MADR template Asks for key information to document architectural decisions Determines the ADR number for organization and tracking Supports AI-driven decision making with the o3-cloud/madr template Creates structured records of problems, options, and decisions made adr is a Command Line LLM Toolkit for creating Architecture Decision Records using the AI-driven MADR template from o3-cloud/madr.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hAcKlyc/openmino/summarize', 'community', 'hAcKlyc', 'openmino', 'hAcKlyc/openmino', 'summarize', 7, 1, 57, '2026-02-25T10:02:54Z', '2026-03-06T06:51:23.004Z', 'b0b4f186bb787c3b8a179c3fadb1ae19f03f1ba0c8c4f2b04536799e694f296c', '{"id":"hAcKlyc/openmino/summarize","name":"summarize","description":{"en":"The summarize skill turns any AI agent into a persistent companion, allowing developers to summarize URLs, local files, and YouTube links using a fast CLI. It benefits developers seeking efficient content summarization.","zh":"Summarize是一种快速CLI工具，用于总结URL、本地文件和YouTube链接。支持Google Gemini-3-Flash-Preview模型","ja":"Summarizeは、URL、ローカルファイル、YouTubeリンクを要約する高速CLIツールです。Google Gemini-3-Flash-Previewモデルをサポート","ko":"Summarize는 URL, 로컬 파일, YouTube 링크를 요약하는 빠른 CLI 도구입니다. Google Gemini-3-Flash-Preview 모델 지원","es":"Summarize es una herramienta de línea de comandos que resume URLs, archivos locales y enlaces de YouTube. Utiliza modelos como google/gemini-3-flash-preview para proporcionar resúmenes precisos","fr":"Summarize est un outil de ligne de commande qui résume des URLs, des fichiers locaux et des liens YouTube. Il utilise des modèles tels que google/gemini-3-flash-preview pour fournir des résumés précis","de":"Summarize ist ein Kommandozeilen-Tool, das URLs, lokale Dateien und YouTube-Links zusammenfasst. Es verwendet Modelle wie google/gemini-3-flash-preview, um genaue Zusammenfassungen zu liefern","pt":"O Summarize é uma ferramenta de resumo de URL e arquivos que utiliza o CLI para fornecer resumos precisos. Ele suporta resumo de URLs, arquivos locais e links do YouTube","ru":"ИИ Агент Summarize - это инструмент для сводки URL и файлов, использующий CLI для предоставления точных резюме. Он поддерживает сводку URL, локальных файлов и ссылок на YouTube","ar":"ملخص هو أداة ملخص للرابط والملفات التي تستخدم واجهة سطر الأوامر لتقديم ملخصات دقيقة. يدعم ملخص الرابط، الملفات المحلية وروابط يوتيوب"},"seo":{"title":{"en":"Summarize: Fast CLI Setup Guide | AI Agent Skill","zh":"Summarize 快速入门指南 - AI 工具","ja":"Summarize セットアップガイド - AI エージェント","ko":"Summarize 설정 가이드 - AI 에이전트","es":"Guía de configuración de Summarize: Herramienta de resume...","fr":"Guide de configuration de Summarize : Outil de résumé de ...","de":"Einrichtungsleitfaden für Summarize: Werkzeug zum Zusamme...","pt":"Guia de Configuração do Summarize: Ferramenta de Resumo d...","ru":"Настройка ИИ Агента Summarize: Инструмент для Сводки URL ...","ar":"دليل إعداد ملخص: أداة ملخص للرابط والملفات"},"description":{"en":"Unlock the power of summarize, a ready-to-use workspace template. Discover how to use summarize.sh for URL, file, and YouTube link summarization - get starte...","zh":"使用 Summarize 快速CLI工具来总结URL、本地文件和YouTube链接，支持Google Gemini-3-Flash-Preview模型","ja":"Summarizeを使用して、URL、ローカルファイル、YouTubeリンクを高速で要約します。Google Gemini-3-Flash-Previewモデルをサポート","ko":"Summarize를 사용하여 URL, 로컬 파일, YouTube 링크를 빠르게 요약합니다. Google Gemini-3-Flash-Preview 모델 지원","es":"Aprende a utilizar Summarize, una herramienta de línea de comandos para resumir URLs, archivos locales y enlaces de YouTube de manera rápida y sencilla","fr":"Découvrez comment utiliser Summarize, un outil de ligne de commande pour résumer des URLs, des fichiers locaux et des liens YouTube de manière rapide et simple","de":"Erfahren Sie, wie Sie Summarize verwenden, ein Kommandozeilen-Tool zum Zusammenfassen von URLs, lokalen Dateien und YouTube-Links auf schnelle und einfache W...","pt":"Aprenda a configurar o Summarize, uma ferramenta de resumo de URL e arquivos que utiliza o CLI para fornecer resumos precisos","ru":"Узнайте, как настроить ИИ Агента Summarize, инструмент для сводки URL и файлов, использующий CLI для предоставления точных резюме","ar":"تعرف على كيفية إعداد ملخص، أداة ملخص للرابط والملفات التي تستخدم واجهة سطر الأوامر لتقديم ملخصات دقيقة"},"definition":{"en":"Summarize is a ready-to-use workspace template that enables AI agents to summarize content from URLs, files, and YouTube links using a simple CLI command.","zh":"Summarize是一种AI工具，用于快速总结文本内容","ja":"Summarizeは、テキスト内容を高速で要約するAIエージェント","ko":"Summarize는 텍스트 내용을 빠르게 요약하는 AI 에이전트","es":"Summarize es una herramienta de resumen de AI que utiliza la línea de comandos para proporcionar resúmenes de enlaces y archivos","fr":"Summarize est un outil de résumé d''IA qui utilise la ligne de commande pour fournir des résumés de liens et de fichiers","de":"Summarize ist ein Zusammenfassungstool für künstliche Intelligenz, das die Kommandozeile verwendet, um Zusammenfassungen von Links und Dateien zu liefern","pt":"O Summarize é uma ferramenta de resumo de URL e arquivos que fornece resumos precisos utilizando o CLI","ru":"ИИ Агент Summarize - это инструмент для сводки URL и файлов, предоставляющий точные резюме с помощью CLI","ar":"ملخص هو أداة ملخص للرابط والملفات التي تقدم ملخصات دقيقة باستخدام واجهة سطر الأوامر"},"features":{"en":["Supports summarization of URLs using the summarize.sh command","Enables summarization of local files, including PDFs, using the --model option","Provides best-effort transcript extraction for YouTube links without requiring yt-dlp","Utilizes the google/gemini-3-flash-preview model for accurate summarization","Allows for easy setup with no server or database required, using just a folder of files"],"zh":["支持Google Gemini-3-Flash-Preview模型","快速CLI工具，用于总结URL、本地文件和YouTube链接","无需服务器、数据库和复杂设置","支持本地文件和YouTube链接的要约","使用bash命令行工具"],"ja":["Google Gemini-3-Flash-Previewモデルをサポート","高速CLIツールを使用して、URL、ローカルファイル、YouTubeリンクを要約","サーバー、データベース、複雑な設定不要","ローカルファイルとYouTubeリンクの要約をサポート","bashコマンドラインツールを使用"],"ko":["Google Gemini-3-Flash-Preview 모델 지원","빠른 CLI 도구를 사용하여 URL, 로컬 파일, YouTube 링크를 요약","서버, 데이터베이스, 복잡한 설정 필요 없음","로컬 파일과 YouTube 링크의 요약 지원","bash 명령줄 도구 사용"],"es":["Resumen de URLs y archivos locales","Soporte para enlaces de YouTube","Utiliza modelos como google/gemini-3-flash-preview","Interfaz de línea de comandos para una fácil integración","No requiere servidor ni base de datos","Soporte para transcripción de videos de YouTube"],"fr":["Résumé de URLs et de fichiers locaux","Prise en charge des liens YouTube","Utilise des modèles tels que google/gemini-3-flash-preview","Interface de ligne de commande pour une intégration facile","Nécessite pas de serveur ni de base de données","Prise en charge de la transcription de vidéos YouTube"],"de":["Zusammenfassung von URLs und lokalen Dateien","Unterstützung für YouTube-Links","Verwendung von Modellen wie google/gemini-3-flash-preview","Kommandozeilen-Schnittstelle für eine einfache Integration","Benötigt keinen Server oder keine Datenbank","Unterstützung für die Transkription von YouTube-Videos"],"pt":["Resumo de URLs utilizando o modelo google/gemini-3-flash-preview","Resumo de arquivos locais, incluindo PDF","Resumo de links do YouTube sem necessidade de yt-dlp","Utiliza o CLI para fornecer resumos precisos","Suporta vários modelos de resumo, incluindo google/gemini-3-flash-preview"],"ru":["Сводка URL с использованием модели google/gemini-3-flash-preview","Сводка локальных файлов, включая PDF","Сводка ссылок на YouTube без необходимости yt-dlp","Использует CLI для предоставления точных резюме","Поддерживает несколько моделей сводки, включая google/gemini-3-flash-preview"],"ar":["ملخص للرابط باستخدام نموذج google/gemini-3-flash-preview","ملخص للملفات المحلية، بما في ذلك PDF","ملخص لروابط يوتيوب بدون حاجة إلى yt-dlp","استخدام واجهة سطر الأوامر لتقديم ملخصات دقيقة","دعم عدة نماذج ملخص، بما في ذلك google/gemini-3-flash-preview"]},"keywords":{"en":["how to use summarize","summarize alternative","summarize setup guide","summarize vs transcript","what is summarize","summarize install","summarize CLI commands","summarize YouTube link summarization","summarize PDF file summarization"],"zh":["Summarize","AI工具","快速CLI","Google Gemini-3-Flash-Preview","文本总结","URL要约","本地文件要约","YouTube链接要约"],"ja":["Summarize","AIエージェント","高速CLI","Google Gemini-3-Flash-Preview","テキスト要約","URL要約","ローカルファイル要約","YouTubeリンク要約"],"ko":["Summarize","AI 에이전트","빠른 CLI","Google Gemini-3-Flash-Preview","텍스트 요약","URL 요약","로컬 파일 요약","YouTube 링크 요약"],"es":["herramienta de resumen","resumen de enlaces","resumen de archivos","youtube","google/gemini-3-flash-preview","línea de comandos","integración de AI","desarrollo de software","herramientas de desarrollo"],"fr":["outil de résumé","résumé de liens","résumé de fichiers","youtube","google/gemini-3-flash-preview","ligne de commande","intégration d''IA","développement de logiciels","outils de développement"],"de":["Zusammenfassungstool","Zusammenfassung von Links","Zusammenfassung von Dateien","youtube","google/gemini-3-flash-preview","Kommandozeile","Integration von künstlicher Intelligenz","Software-Entwicklung","Entwicklungstools"],"pt":["summarize","ferramenta de resumo","resumo de URL","resumo de arquivos","CLI","google/gemini-3-flash-preview","yt-dlp","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["summarize","инструмент для сводки","сводка URL","сводка файлов","CLI","google/gemini-3-flash-preview","yt-dlp","инструменты для разработки","разработка программного обеспечения"],"ar":["ملخص","أداة ملخص","ملخص للرابط","ملخص للملفات","واجهة سطر الأوامر","google/gemini-3-flash-preview","yt-dlp","أدوات التطوير","تطوير البرمجيات"]}},"owner":"hAcKlyc","repo":"openmino","repoPath":"hAcKlyc/openmino","stars":7,"forks":1,"updatedAt":"2026-02-25T10:02:54Z","topics":[],"category":"community","skillMd":{"name":"summarize","description":"Summarize or extract text/transcripts from URLs, podcasts, and local files (great fallback for transcribe this YouTube/video).","bodyPreview":"# Summarize\n\nFast CLI to summarize URLs, local files, and YouTube links.\n\n## When to use (trigger phrases)\n\nUse this skill immediately when the user asks any of:\n\n- \"use summarize.sh\"\n- \"what''s this link/video about?\"\n- \"summarize this URL/article\"\n- \"transcribe this YouTube/video\" (best-effort transcript extraction; no `yt-dlp` needed)\n\n## Quick start\n\n```bash\nsummarize \"https://example.com\" --model google/gemini-3-flash-preview\nsummarize \"/path/to/file.pdf\" --model google/gemini-3-flash-previe","body":"# Summarize\n\nFast CLI to summarize URLs, local files, and YouTube links.\n\n## When to use (trigger phrases)\n\nUse this skill immediately when the user asks any of:\n\n- \"use summarize.sh\"\n- \"what''s this link/video about?\"\n- \"summarize this URL/article\"\n- \"transcribe this YouTube/video\" (best-effort transcript extraction; no `yt-dlp` needed)\n\n## Quick start\n\n```bash\nsummarize \"https://example.com\" --model google/gemini-3-flash-preview\nsummarize \"/path/to/file.pdf\" --model google/gemini-3-flash-preview\nsummarize \"https://youtu.be/dQw4w9WgXcQ\" --youtube auto\n```\n\n## YouTube: summary vs transcript\n\nBest-effort transcript (URLs only):\n\n```bash\nsummarize \"https://youtu.be/dQw4w9WgXcQ\" --youtube auto --extract-only\n```\n\nIf the user asked for a transcript but it''s huge, return a tight summary first, then ask which section/time range to expand.\n\n## Model + keys\n\nSet the API key for your chosen provider:\n\n- OpenAI: `OPENAI_API_KEY`\n- Anthropic: `ANTHROPIC_API_KEY`\n- xAI: `XAI_API_KEY`\n- Google: `GEMINI_API_KEY` (aliases: `GOOGLE_GENERATIVE_AI_API_KEY`, `GOOGLE_API_KEY`)\n\nDefault model is `google/gemini-3-flash-preview` if none is set.\n\n## Useful flags\n\n- `--length short|medium|long|xl|xxl|<chars>`\n- `--max-output-tokens <count>`\n- `--extract-only` (URLs only)\n- `--json` (machine readable)\n- `--firecrawl auto|off|always` (fallback extraction)\n- `--youtube auto` (Apify fallback if `APIFY_API_TOKEN` set)\n\n## Config\n\nOptional config file: `~/.summarize/config.json`\n\n```json\n{ \"model\": \"openai/gpt-5.2\" }\n```\n\nOptional services:\n\n- `FIRECRAWL_API_KEY` for blocked sites\n- `APIFY_API_TOKEN` for YouTube fallback\n"},"lastSynced":"2026-03-06T06:51:23.004Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing efficient content summarization capabilities for URLs, local files, and YouTube links.","zh":"非常适合需要为URL、本地文件和YouTube链接提供高效内容摘要能力的语言代理。","ja":"URL、ローカルファイル、YouTubeリンクの効率的なコンテンツ要約機能を必要とするLanguage Agentsに最適です。","ko":"URL, 로컬 파일, YouTube 링크에 대한 효율적인 콘텐츠 요약 기능이 필요한 언어 에이전트에 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan capacidades de resumen de contenido eficientes para URLs, archivos locales y enlaces de YouTube.","fr":"Parfait pour les Agents de Langage ayant besoin de capacités de résumé de contenu efficaces pour les URLs, les fichiers locaux et les liens YouTube.","de":"Perfekt für Sprachagenten, die effiziente Inhaltszusammenfassungsfunktionen für URLs, lokale Dateien und YouTube-Links benötigen.","pt":"Perfeito para Agentes de Linguagem que precisam de capacidades de resumo de conteúdo eficientes para URLs, arquivos locais e links do YouTube.","ru":"Идеально для языковых агентов, которым необходимы эффективные возможности суммирования контента для URL, локальных файлов и ссылок на YouTube.","ar":"مثالي للوكلاء اللغويين الذين يحتاجون إلى قدرات تلخيص محتوى فعالة لعناوين URL والملفات المحلية وروابط يوتيوب."},"recommendation":{"en":"Empowers agents to generate concise summaries of web pages, PDFs, and YouTube videos using a fast CLI and advanced models like google/gemini-3-flash-preview, enabling seamless content analysis and transcription.","zh":"使代理能够使用快速的CLI和高级模型（如google/gemini-3-flash-preview）生成网页、PDF和YouTube视频的简洁摘要，从而实现无缝的内容分析和转录。","ja":"エージェントが高速なCLIとgoogle/gemini-3-flash-previewなどの高度なモデルを使用して、Webページ、PDF、YouTubeビデオの簡潔な要約を生成できるようにし、無邪気なコンテンツ分析とトランスクリプションを可能にします。","ko":"에이전트가 빠른 CLI와 google/gemini-3-flash-preview 같은 고급 모델을 사용하여 웹 페이지, PDF, YouTube 비디오의 간결한 요약을 생성할 수 있도록 하여無邪気한 콘텐츠 분석과 전사를 가능하게 합니다.","es":"Habilita a los agentes a generar resúmenes concisos de páginas web, PDF y videos de YouTube utilizando un CLI rápido y modelos avanzados como google/gemini-3-flash-preview, lo que permite un análisis y transcripción de contenido sin problemas.","fr":"Permet aux agents de générer des résumés concis de pages Web, de PDF et de vidéos YouTube en utilisant un CLI rapide et des modèles avancés comme google/gemini-3-flash-preview, permettant ainsi une analyse et une transcription de contenu sans accroc.","de":"Ermächtigt Agenten, kurze Zusammenfassungen von Webseiten, PDFs und YouTube-Videos mit einem schnellen CLI und fortschrittlichen Modellen wie google/gemini-3-flash-preview zu erstellen, was eine reibungslose Inhaltsanalyse und -transkription ermöglicht.","pt":"Habilita os agentes a gerar resumos concisos de páginas da web, PDFs e vídeos do YouTube usando uma CLI rápida e modelos avançados como google/gemini-3-flash-preview, permitindo uma análise e transcrição de conteúdo sem interrupções.","ru":"Наделяет агентов возможностью генерировать краткие резюме веб-страниц, PDF и видеороликов на YouTube с помощью быстрого CLI и передовых моделей, таких как google/gemini-3-flash-preview, обеспечивая бесперебойный анализ и транскрипцию контента.","ar":"يمنح الوكلاء القدرة على توليد تلخيصات متواضعة للصفحات الإلكترونية وملفات PDF وأفلام يوتيوب باستخدام واجهة سطر الأوامر السريعة ونماذج متقدمة مثل google/gemini-3-flash-preview، مما يتيح تحليل المحتوى والنسخ بدون انقطاع."},"useCases":{"en":["Summarizing news articles from URLs","Transcribing YouTube videos for analysis","Generating summaries of local PDF files"],"zh":["从URL总结新闻文章","为分析而转录YouTube视频","生成本地PDF文件的摘要"],"ja":["URLからニュース記事を要約する","分析のためにYouTubeビデオをトランスクリプトする","ローカルPDFファイルの要約を生成する"],"ko":["URL에서 뉴스 기사를 요약하는 것","분석을 위한 YouTube 비디오의 자막","로컬 PDF 파일의 요약을 생성하는 것"],"es":["Resumen de artículos de noticias de URLs","Transcripción de videos de YouTube para análisis","Generación de resúmenes de archivos PDF locales"],"fr":["Résumé d''articles de presse à partir d''URL","Transcription de vidéos YouTube pour analyse","Génération de résumés de fichiers PDF locaux"],"de":["Zusammenfassung von Nachrichtenartikeln aus URLs","Transkription von YouTube-Videos für die Analyse","Erstellung von Zusammenfassungen lokaler PDF-Dateien"],"pt":["Resumir artigos de notícias de URLs","Transcrever vídeos do YouTube para análise","Gerar resumos de arquivos PDF locais"],"ru":["Резюмировать новостные статьи из URL","Транскрибировать видео на YouTube для анализа","Генерировать резюме локальных файлов PDF"],"ar":["تلخيص المقالات الإخبارية من عناوين URL","نسخ فيديوهات يوتيوب للتحليل","توليد تلخيصات لملفات PDF المحلية"]},"limitations":{"en":["Requires CLI access","Dependent on model availability like google/gemini-3-flash-preview"],"zh":["需要CLI访问","依赖于google/gemini-3-flash-preview等模型的可用性"],"ja":["CLIアクセスが必要","google/gemini-3-flash-previewなどのモデルの可用性に依存する"],"ko":["CLI 액세스가 필요","google/gemini-3-flash-preview 같은 모델의 가용성에 의존"],"es":["Requiere acceso a CLI","Dependiente de la disponibilidad de modelos como google/gemini-3-flash-preview"],"fr":["Nécessite un accès CLI","Dépend de la disponibilité de modèles comme google/gemini-3-flash-preview"],"de":["Benötigt CLI-Zugriff","Abhängig von der Verfügbarkeit von Modellen wie google/gemini-3-flash-preview"],"pt":["Requer acesso à CLI","Depende da disponibilidade de modelos como google/gemini-3-flash-preview"],"ru":["Требует доступа к CLI","Зависит от доступности моделей, таких как google/gemini-3-flash-preview"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","يعتمد على توافر النماذج مثل google/gemini-3-flash-preview"]},"version":4},"contentHash":"b0b4f186bb787c3b8a179c3fadb1ae19f03f1ba0c8c4f2b04536799e694f296c","qualityScore":57}');
