INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hAcKlyc/openmino/summarize', 'summarize', 'hAcKlyc', 'openmino', 'community', 'summarize hAcKlyc openmino community The summarize skill turns any AI agent into a persistent companion, allowing developers to summarize URLs, local files, and YouTube links using a fast CLI. It benefits developers seeking efficient content summarization. Summarize是一种快速CLI工具，用于总结URL、本地文件和YouTube链接。支持Google Gemini-3-Flash-Preview模型 Summarizeは、URL、ローカルファイル、YouTubeリンクを要約する高速CLIツールです。Google Gemini-3-Flash-Previewモデルをサポート Summarize는 URL, 로컬 파일, YouTube 링크를 요약하는 빠른 CLI 도구입니다. Google Gemini-3-Flash-Preview 모델 지원 Summarize es una herramienta de línea de comandos que resume URLs, archivos locales y enlaces de YouTube. Utiliza modelos como google/gemini-3-flash-preview para proporcionar resúmenes precisos Summarize est un outil de ligne de commande qui résume des URLs, des fichiers locaux et des liens YouTube. Il utilise des modèles tels que google/gemini-3-flash-preview pour fournir des résumés précis Summarize ist ein Kommandozeilen-Tool, das URLs, lokale Dateien und YouTube-Links zusammenfasst. Es verwendet Modelle wie google/gemini-3-flash-preview, um genaue Zusammenfassungen zu liefern O Summarize é uma ferramenta de resumo de URL e arquivos que utiliza o CLI para fornecer resumos precisos. Ele suporta resumo de URLs, arquivos locais e links do YouTube ИИ Агент Summarize - это инструмент для сводки URL и файлов, использующий CLI для предоставления точных резюме. Он поддерживает сводку URL, локальных файлов и ссылок на YouTube ملخص هو أداة ملخص للرابط والملفات التي تستخدم واجهة سطر الأوامر لتقديم ملخصات دقيقة. يدعم ملخص الرابط، الملفات المحلية وروابط يوتيوب how to use summarize summarize alternative summarize setup guide summarize vs transcript what is summarize summarize install summarize CLI commands summarize YouTube link summarization summarize PDF file summarization Summarize AI工具 快速CLI Google Gemini-3-Flash-Preview 文本总结 URL要约 本地文件要约 YouTube链接要约 Supports summarization of URLs using the summarize.sh command Enables summarization of local files, including PDFs, using the --model option Provides best-effort transcript extraction for YouTube links without requiring yt-dlp Utilizes the google/gemini-3-flash-preview model for accurate summarization Allows for easy setup with no server or database required, using just a folder of files Summarize is a ready-to-use workspace template that enables AI agents to summarize content from URLs, files, and YouTube links using a simple CLI command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jhd3197/CachiBot/review-fix', 'community', 'jhd3197', 'CachiBot', 'jhd3197/CachiBot', 'review-fix', 6, 0, 57, '2026-02-25T20:46:18Z', '2026-03-06T06:52:50.723Z', 'e92ccf01fd6b23257fc3e02dce31811c12101c3668f482818e17baf792e22a81', '{"id":"jhd3197/CachiBot/review-fix","name":"review-fix","description":{"en":"The review-fix skill automates the review and fix process for AI agents, benefiting developers by planning and executing fixes from the last review. It supports multi-provider LLM and produces review-plan and review-execution logs.","zh":"Review Fix 是一种 AI 驱动的代码修复工具，使用 Python 和 LLM 支持","ja":"Review Fix は、Python と LLM を使用した AI ドリブンのコード修正ツールです","ko":"Review Fix 는 Python 및 LLM 을 사용하는 AI 기반 코드 자동화 툴입니다","es":"Review Fix es una habilidad que ejecuta correcciones automatizadas en función de la última revisión. Soporta múltiples proveedores LLM y ejecución sandbox","fr":"Review Fix est une compétence qui exécute des corrections automatiques en fonction de la dernière revue. Il prend en charge plusieurs fournisseurs LLM et l''exécution sandbox","de":"Review Fix ist eine Fähigkeit, die automatisierte Korrekturen auf der Grundlage der letzten Überprüfung ausführt. Sie unterstützt mehrere LLM-Anbieter und die Sandbox-Ausführung","pt":"O Review-Fix é uma ferramenta que planeja e executa correções em seu código com base em revisões recentes","ru":"Review-Fix - это инструмент, который планирует и выполняет исправления в вашем коде на основе последних обзоров для ИИ Агентов","ar":"Review-Fix هو أداة لتخطيط وتنفيذ تصحيح العيوب في رمزك بناءً على المراجعات الأخيرة ل وكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"review-fix: Automated Review and Fix Setup Guide | AI Age...","zh":"Review Fix Setup Guide - AIエージェント自动化修复","ja":"Review Fix ベストプラクティス - AIエージェントによるコード修正","ko":"Review Fix 구현 방법 - AI 에이전트를 이용한 코드 자동화","es":"Guía de Configuración de Review Fix - Ejecución de Correc...","fr":"Guide de Configuration de Review Fix - Exécution des Corr...","de":"Konfigurationsleitfaden für Review Fix - Ausführung von K...","pt":"Guia de Configuração do Review-Fix: Planejamento e Execuç...","ru":"Настройка Review-Fix: Планирование и Выполнение Исправлен...","ar":"دليل إعداد Review-Fix: التخطيط والتنفيذ لتصحيح العيوب في ..."},"description":{"en":"Discover how review-fix streamlines your AI agent workflow by planning and executing fixes from the last review. Get started now and optimize your developmen...","zh":"了解 Review Fix 的技术细节和实现方法，自动化代码修复和优化","ja":"Review Fix を使用してコードの修正と最適化を自動化する方法を学ぶ","ko":"Review Fix 를 사용하여 코드 자동화와 최적화를 구현하는 방법에 대해 알아보세요","es":"Aprende a configurar Review Fix para ejecutar correcciones automatizadas. Descubre cómo funciona con soporte multi-proveedor LLM y ejecución sandbox","fr":"Découvrez comment configurer Review Fix pour exécuter des corrections automatiques. Apprenez à utiliser le support multi-fournisseur LLM et l''exécution sandbox","de":"Erfahren Sie, wie Sie Review Fix konfigurieren, um automatisierte Korrekturen auszuführen. Entdecken Sie, wie es mit dem Multi-Anbieter-LLM-Support und der S...","pt":"Aprenda a configurar o Review-Fix para planejar e executar correções em seu código com atomic commits e logs de execução","ru":"Узнайте, как настроить Review-Fix для планирования и выполнения исправлений в вашем коде с атомарными коммитами и журналами выполнения для ИИ Агентов","ar":"تعرف على كيفية إعداد Review-Fix لتنفيذ تصحيح العيوب في رمزك مع التزامات ذرية وسجلات التنفيذ ل وكلاء الذكاء الاصطناعي"},"definition":{"en":"review-fix is a skill that automates the review and fix process for AI agents, parsing findings from review files and executing planned fixes with atomic commits.","zh":"Review Fix 是一种自动化代码修复工具，使用 AI 技术分析和修正代码","ja":"Review Fix は、AI 技術を使用してコードを分析し修正する自動化ツールです","ko":"Review Fix 는 AI 기술을 이용하여 코드를 분석하고 자동으로 수정하는 툴입니다","es":"Review Fix es una herramienta de AI que ejecuta correcciones automatizadas en función de la última revisión, utilizando soporte multi-proveedor LLM","fr":"Review Fix est un outil d''IA qui exécute des corrections automatiques en fonction de la dernière revue, en utilisant le support multi-fournisseur LLM","de":"Review Fix ist ein AI-Tool, das automatisierte Korrekturen auf der Grundlage der letzten Überprüfung ausführt, unter Verwendung des Multi-Anbieter-LLM-Supports","pt":"O Review-Fix é uma ferramenta de revisão de código que planeja e executa correções com base em revisões recentes","ru":"Review-Fix - это инструмент обзора кода, который планирует и выполняет исправления на основе последних обзоров для ИИ Агентов","ar":"Review-Fix هو أداة مراجعة رمز تقوم بتخطيط وتنفيذ تصحيح العيوب بناءً على المراجعات الأخيرة ل وكلاء الذكاء الاصطناعي"},"features":{"en":["Reads the most recent .reviews/YYYY-MM-DD-review.md file and parses findings into a list","Plans fixes for all findings grouped by priority","Executes every planned fix with atomic commits","Produces review-plan and review-execution logs","Supports multi-provider LLM","Globs for .reviews/*-review.md files to find the latest review"],"zh":["支持多个 LLM 提供商","使用 Python 实现自动化修复","生成 review-plan 和 review-execution 日志","支持 atomic commits","自动化代码优化和修复"],"ja":["複数の LLM 提供商をサポート","Python を使用した自動化修正","review-plan と review-execution ログを生成","atomic commits をサポート","コードの自動化最適化と修正"],"ko":["다수의 LLM 제공사를 지원","Python 을 사용한 자동화 修复","review-plan 과 review-execution 로그를 생성","atomic commits 를 지원","코드 자동화 최적화와 修复"],"es":["Soporte multi-proveedor LLM","Ejecución sandbox para pruebas seguras","Análisis de la última revisión para planificar correcciones","Ejecución de correcciones automatizadas con commits atómicos","Generación de un plan de revisión y un registro de ejecución"],"fr":["Support multi-fournisseur LLM","Exécution sandbox pour des tests sécurisés","Analyse de la dernière revue pour planifier des corrections","Exécution de corrections automatiques avec des commits atomiques","Génération d''un plan de revue et d''un journal d''exécution"],"de":["Multi-Anbieter-LLM-Support","Sandbox-Ausführung für sichere Tests","Analyse der letzten Überprüfung zur Planung von Korrekturen","Ausführung von automatisierten Korrekturen mit atomaren Commits","Erzeugung eines Überprüfungsplans und eines Ausführungsprotokolls"],"pt":["Leitura da revisão mais recente em `.reviews/YYYY-MM-DD-review.md`","Planejamento de correções com base em prioridade","Execução de correções com atomic commits","Geração de logs de execução","Suporte a multi-provedores de LLM","Integração com Python"],"ru":["Чтение последнего обзора в `.reviews/YYYY-MM-DD-review.md`","Планирование исправлений на основе приоритета","Выполнение исправлений с атомарными коммитами","Генерация журналов выполнения","Поддержка нескольких поставщиков LLM для ИИ Агентов","Интеграция с Python"],"ar":["قراءة المراجعة الأخيرة في `.reviews/YYYY-MM-DD-review.md`","تخطيط تصحيح العيوب بناءً على الأهمية","تنفيذ تصحيح العيوب مع التزامات ذرية","توليد سجلات التنفيذ","دعم عدة مزودين ل LLM ل وكلاء الذكاء الاصطناعي","التكامل مع Python"]},"keywords":{"en":["how to use review-fix","review-fix setup guide","review-fix alternative","review-fix vs claude","review-fix install","what is review-fix","review-fix for AI agents","review-fix and LLM","review-fix automated review","review-fix execution logs"],"zh":["AIエージェント","代码自动化","Review Fix","Python","LLM","代码优化","自动化修复","AI工具","代码分析"],"ja":["AIエージェント","コード自動化","Review Fix","Python","LLM","コード最適化","自動化修正","AIツール","コード分析"],"ko":["AI 에이전트","코드 자동화","Review Fix","Python","LLM","코드 최적화","자동화 修复","AI 툴","코드 분석"],"es":["review fix","ai agents","llm","soporte multi-proveedor","ejecución sandbox","correcciones automatizadas","plan de revisión","registro de ejecución"],"fr":["review fix","agents d''ia","llm","support multi-fournisseur","exécution sandbox","corrections automatiques","plan de revue","journal d''exécution"],"de":["review fix","ai-agenten","llm","multi-anbieter-support","sandbox-ausführung","automatisierte korrekturen","überprüfungsplan","ausführungsprotokoll"],"pt":["review-fix","planejamento de correções","execução de correções","atomic commits","logs de execução","LLM","Python","revisão de código","ferramentas de desenvolvimento"],"ru":["review-fix","планирование исправлений","выполнение исправлений","атомарные коммиты","журналы выполнения","LLM","Python","обзор кода","инструменты разработки для ИИ Агентов"],"ar":["review-fix","تخطيط تصحيح العيوب","تنفيذ تصحيح العيوب","التزامات ذرية","سجلات التنفيذ","LLM","Python","مراجعة رمز","أدوات تطوير ل وكلاء الذكاء الاصطناعي"]}},"owner":"jhd3197","repo":"CachiBot","repoPath":"jhd3197/CachiBot","stars":6,"forks":0,"updatedAt":"2026-02-25T20:46:18Z","topics":["ai","ai-agents","chatbot","claude","discord-bot","llm","prompture","python","telegram-bot"],"category":"community","skillMd":{"name":"review-fix","description":"Read the latest code review, plan fixes for all findings, then execute the fixes — all in one command. Produces a dated plan and execution log in .reviews/.","bodyPreview":"# Review Fix — Plan & Execute from Last Review\n\nRead the most recent `.reviews/YYYY-MM-DD-review.md`, plan fixes for all findings\ngrouped by priority, then execute every planned fix with atomic commits. Produces\ntwo artifacts: a **review-plan** and a **review-execution** log.\n\n## Instructions\n\n### Phase 0 — Find the Latest Review\n\n1. Glob for `.reviews/*-review.md` and pick the most recent file by date.\n2. Read the full review file. Parse every finding into a list of\n   `{ severity, reviewer, fi","body":"# Review Fix — Plan & Execute from Last Review\n\nRead the most recent `.reviews/YYYY-MM-DD-review.md`, plan fixes for all findings\ngrouped by priority, then execute every planned fix with atomic commits. Produces\ntwo artifacts: a **review-plan** and a **review-execution** log.\n\n## Instructions\n\n### Phase 0 — Find the Latest Review\n\n1. Glob for `.reviews/*-review.md` and pick the most recent file by date.\n2. Read the full review file. Parse every finding into a list of\n   `{ severity, reviewer, file, line, description }` entries.\n3. If no review file exists, tell the user to run `/code-review` first and stop.\n\n### Phase 1 — Plan\n\nSpawn **4 parallel planning agents** (Task tool, `subagent_type: Plan`) that each\nreceive the full findings list filtered to their scope. Each agent returns a\nstructured list of fix actions.\n\n#### Agent scopes\n\n| Agent         | Scope                                                  |\n|---------------|--------------------------------------------------------|\n| **backend**   | Findings from Tina, Marcus, Priya, Carlos, Oscar that touch `cachibot/` |\n| **frontend**  | Findings from Tina, Zoe, Luna that touch `frontend/src/` |\n| **data**      | Findings from Carlos (storage/db layer)                |\n| **tests**     | Findings from Derek (test coverage gaps)               |\n\n> Findings that span multiple scopes go to every relevant agent.\n\nEach planning agent must:\n\n- Group related findings that can be fixed together (same file, same pattern).\n- For each group, produce:\n  - **What**: one-line summary of the change\n  - **Files**: list of files to modify\n  - **How**: 2-3 sentence implementation approach\n  - **Severity**: highest severity in the group (Fix > Improve > Note)\n  - **Risk**: Low / Medium / High (does this change behavior or just style?)\n  - **Depends on**: other group IDs this group must wait for (if any)\n- Order groups by: Fix severity first, then by dependency order.\n- Skip any finding rated **Note** — notes are informational only.\n\nAfter all 4 agents return, compile results into `.reviews/YYYY-MM-DD-review-plan.md`:\n\n```markdown\n# Review Fix Plan — YYYY-MM-DD\n\n**Source review:** `.reviews/YYYY-MM-DD-review.md`\n**Generated:** YYYY-MM-DD HH:MM\n\n## Stats\n\n| Severity | Findings | Planned groups |\n|----------|----------|----------------|\n| Fix      | N        | N              |\n| Improve  | N        | N              |\n| Note     | N        | (skipped)      |\n\n## Execution Waves\n\nWave 1 (no dependencies):\n- [B1] Backend: <summary>\n- [F1] Frontend: <summary>\n\nWave 2 (depends on wave 1):\n- [B2] Backend: <summary> (depends on B1)\n\n...\n\n## Detailed Plan\n\n### [B1] <Summary>\n- **Severity:** Fix\n- **Risk:** Low\n- **Files:** `path/to/file.py`\n- **How:** Description of the fix approach\n- **Findings addressed:**\n  - Tina: `path/to/file.py:42` — original finding text\n  - Marcus: `path/to/file.py:50` — original finding text\n```\n\nPrint the plan summary (wave count, group count, severity breakdown) to the user,\nthen **immediately proceed to Phase 2** without waiting for approval.\n\n### Phase 2 — Execute\n\nRead the plan file. Execute fixes **wave by wave** — all groups in a wave run in\nparallel, but waves run sequentially (wave 2 waits for wave 1 to finish).\n\nFor each group, spawn a Task agent (`subagent_type: general-purpose`) with:\n\n- The group''s detailed plan (What, Files, How)\n- The original finding text for context\n- Instruction to read each file before editing\n- Instruction to make the minimal change that addresses the finding\n- Instruction to run `ruff check --fix` and `ruff format` on any modified Python file\n- Instruction to run `npm run lint -- --fix` on any modified TypeScript file (from `frontend/`)\n- Instruction to NOT create new files unless the plan explicitly says to\n- Instruction to NOT add tests (Derek findings are tracked but test writing is a separate task)\n\nAfter each wave completes:\n\n1. Verify no lint errors remain (`ruff check cachibot/` and `cd frontend && npm run lint`).\n2. If lint fails, spawn a fix agent for the failing files before continuing.\n3. Stage all changed files and create one commit per wave:\n   ```\n   Review fixes wave N: <comma-separated group IDs>\n\n   Addresses findings from YYYY-MM-DD code review.\n   Groups: [B1] summary, [F2] summary, ...\n\n   Co-Authored-By: Claude Opus 4.6 <noreply@anthropic.com>\n   ```\n\nAfter all waves complete, write `.reviews/YYYY-MM-DD-review-execution.md`:\n\n```markdown\n# Review Fix Execution — YYYY-MM-DD\n\n**Plan:** `.reviews/YYYY-MM-DD-review-plan.md`\n**Source review:** `.reviews/YYYY-MM-DD-review.md`\n\n## Results\n\n| Wave | Groups | Status  | Commit  |\n|------|--------|---------|---------|\n| 1    | B1, F1 | Done    | abc1234 |\n| 2    | B2     | Done    | def5678 |\n\n## Findings Addressed\n\n| Severity | Planned | Fixed | Skipped | Reason          |\n|----------|---------|-------|---------|-----------------|\n| Fix      | N       | N     | N       |                 |\n| Improve  | N       | N     | N       |                 |\n\n## Group Details\n\n### [B1] <Summary> — Done\n- **Commit:** abc1234\n- **Files changed:** `path/to/file.py`\n- **Findings fixed:**\n  - Tina: `path/to/file.py:42` — fixed\n  - Marcus: `path/to/file.py:50` — fixed\n\n### [F1] <Summary> — Skipped\n- **Reason:** File was recently refactored, finding no longer applies\n- **Findings skipped:**\n  - Zoe: `frontend/src/Component.tsx:100` — N/A after refactor\n\n## Remaining Work\n\n- Derek''s test coverage findings were not addressed (test writing is separate)\n- N findings skipped due to: ...\n```\n\n### Phase 3 — Summary\n\nPrint a final summary to the user:\n\n```\nReview fix complete.\n\nWaves executed: N\nCommits created: N\nFindings fixed: N / M planned (X Fix, Y Improve)\nSkipped: N (reasons listed in execution log)\n\nPlan:      .reviews/YYYY-MM-DD-review-plan.md\nExecution: .reviews/YYYY-MM-DD-review-execution.md\n```\n\n## Important Rules\n\n- **Never skip a Fix-severity finding** without logging a clear reason.\n- **Read before edit** — every agent must read the target file before modifying it.\n- **Minimal changes** — fix exactly what the finding describes, nothing more.\n- **No new features** — this is a fix pass, not a feature pass.\n- **No test writing** — Derek''s findings are logged as \"remaining work\" but not executed\n  here. Test creation deserves its own focused session.\n- **Preserve behavior** — if a fix would change external API behavior, mark it as\n  Risk: High in the plan and add a note in the execution log.\n- If the review file has a \"Previous Reviews\" section noting still-open findings from\n  prior reviews, include those in the plan too.\n"},"lastSynced":"2026-03-06T06:52:50.723Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing automated review and fix processes with multi-provider LLM support.","zh":"适用于需要自动化审查和修复过程的代码审查代理，并支持多提供商LLM。","ja":"コードレビューエージェントが自動化されたレビューと修正プロセスを必要とする場合に最適で、マルチプロバイダのLLMをサポートしています。","ko":"코드 리뷰 에이전트가 자동화된 리뷰 및 수정 프로세스를 필요로 할 때 적합하며, 다중 제공자 LLM을 지원합니다.","es":"Ideal para agentes de revisión de código que necesitan procesos de revisión y corrección automatizados con soporte para varios proveedores de LLM.","fr":"Idéal pour les agents de révision de code nécessitant des processus de révision et de correction automatisés avec une prise en charge de plusieurs fournisseurs de LLM.","de":"Ideal für Code-Review-Agenten, die automatisierte Review- und Fixprozesse mit Unterstützung für mehrere LLM-Anbieter benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de processos de revisão e fix automática com suporte a vários provedores de LLM.","ru":"Идеально для агентов кодового обзора, требующих автоматизированных процессов обзора и исправления с поддержкой нескольких поставщиков LLM.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى عمليات مراجعة وتصحيح آلي مع دعم لموفري LLM متعددين."},"recommendation":{"en":"Empowers agents to plan and execute fixes from the last review, producing review-plan and review-execution logs, while supporting atomic commits and parsing findings into severity-based lists.","zh":"赋予代理规划和执行上次审查的修复，生成审查计划和审查执行日志，同时支持原子提交和将发现结果解析为基于严重程度的列表。","ja":"エージェントに、最後のレビューからの修正を計画して実行することを可能にし、レビュープランとレビュー実行ログを生成しながら、原子コミットと発見結果を严重度ベースのリストに解析することをサポートします。","ko":"에이전트가 마지막 리뷰에서 수정을 계획하고 실행할 수 있도록 하며, 리뷰 계획과 리뷰 실행 로그를 생성하면서 원자적 커밋과 발견 결과를 심각도 기반 목록으로 phân析하는 것을 지원합니다.","es":"Permite a los agentes planificar y ejecutar correcciones desde la última revisión, produciendo registros de planificación de revisión y ejecución de revisión, mientras admite commits atómicos y analiza los resultados en listas basadas en la gravedad.","fr":"Permet aux agents de planifier et d''exécuter des corrections à partir de la dernière révision, produisant des journaux de planification de révision et d''exécution de révision, tout en supportant les commits atomiques et en analysant les résultats en listes basées sur la gravité.","de":"Ermöglicht es Agenten, Korrekturen vom letzten Review zu planen und auszuführen, indem Review-Plan- und Review-Ausführungsprotokolle erstellt werden, während atomare Commits unterstützt und Ergebnisse in schweregradbasierte Listen aufgeteilt werden.","pt":"Permite que os agentes planejem e executem correções da última revisão, produzindo planos de revisão e logs de execução de revisão, ao mesmo tempo em que suporta commits atômicos e analisa as descobertas em listas baseadas em gravidade.","ru":"Позволяет агентам планировать и выполнять исправления с последнего обзора, производя планы обзора и журналы выполнения обзора, а также поддерживает атомарные коммиты и парсит результаты в списки на основе тяжести.","ar":"تمكن العملاء من تخطيط وتنفيذ الإصلاحات من آخر مراجعة ، وإنتاج خطط المراجعة وسجلات تنفيذ المراجعة ، مع دعم الإلتزامات الذرية وتحليل النتائج في قوائم基于 الشدة."},"useCases":{"en":["Automating review and fix processes for AI-generated code","Generating review plans based on priority and severity","Executing fixes with atomic commits for version control"],"zh":["自动化AI生成代码的审查和修复过程","根据优先级和严重程度生成审查计划","执行修复以原子提交用于版本控制"],"ja":["AI生成コードのレビューと修正プロセスの自動化","優先度と严重度に基づいてレビュープランを生成する","原子コミットを使用して修正を実行する"],"ko":["AI 생성 코드의 리뷰 및 수정 프로세스를 자동화하는 것","우선순위 및 심각도에 따라 리뷰 계획을 생성하는 것","버전 관리를 위해 원자적 커밋으로 수정을 실행하는 것"],"es":["Automatización de procesos de revisión y corrección para código generado por IA","Generación de planes de revisión basados en prioridad y gravedad","Ejecución de correcciones con commits atómicos para el control de versiones"],"fr":["Automatisation des processus de révision et de correction pour le code généré par l''IA","Génération de plans de révision basés sur la priorité et la gravité","Exécution de corrections avec des commits atomiques pour le contrôle de version"],"de":["Automatisierung von Review- und Fixprozessen für von KI generierten Code","Erstellung von Reviewplänen basierend auf Priorität und Schweregrad","Ausführung von Korrekturen mit atomaren Commits für die Versionskontrolle"],"pt":["Automatizar processos de revisão e fix para código gerado por IA","Gerar planos de revisão com base em prioridade e gravidade","Executar correções com commits atômicos para controle de versão"],"ru":["Автоматизировать процессы обзора и исправления для кода, сгенерированного ИИ","Генерировать планы обзора на основе приоритета и тяжести","Выполнять исправления с атомарными коммитами для контроля версий"],"ar":["تأتمتة عمليات المراجعة والإصلاح للكود المتولد بواسطة الذكاء الاصطناعي","توليد خطط المراجعة بناءً على الأهمية والشدة","تنفيذ الإصلاحات بإلتزامات ذرية للسيطرة على الإصدارات"]},"limitations":{"en":["Requires access to .reviews directory with review files in Markdown format","Limited to file-based review storage and execution"],"zh":["需要访问.reviews目录，且审查文件必须为Markdown格式","仅限于文件 기반的审查存储和执行"],"ja":[".reviewsディレクトリへのアクセスが必要であり、レビューファイルはMarkdown形式でなければならない","ファイルベースのレビューストレージと実行に限定される"],"ko":["리뷰 파일이 Markdown 형식인 .reviews 디렉토리에 대한 액세스가 필요함","파일 기반의 리뷰 저장 및 실행에만限定됨"],"es":["Requiere acceso al directorio .reviews con archivos de revisión en formato Markdown","Limitado al almacenamiento y ejecución de revisiones basadas en archivos"],"fr":["Nécessite un accès au répertoire .reviews avec des fichiers de révision au format Markdown","Limité au stockage et à l''exécution de révisions basés sur des fichiers"],"de":["Erfordert Zugriff auf das Verzeichnis .reviews mit Review-Dateien im Markdown-Format","Begrenzt auf dateibasierten Review-Speicher und -Ausführung"],"pt":["Requer acesso ao diretório .reviews com arquivos de revisão no formato Markdown","Limitado ao armazenamento e execução de revisão baseada em arquivos"],"ru":["Требует доступа к каталогу .reviews с файлами обзора в формате Markdown","Ограничен хранением и выполнением обзора на основе файлов"],"ar":["يتطلب الوصول إلى الدليل .reviews مع ملفات المراجعة بصيغة Markdown","محدود بالتخزين والتنفيذ المرتبط بالملفات"]},"version":4},"contentHash":"e92ccf01fd6b23257fc3e02dce31811c12101c3668f482818e17baf792e22a81","qualityScore":57}');
